CONTROL_HZ = 30.0


def _set_background_thread_nice(
    env_name: str,
    *,
    default: int = 19,
) -> None:
    """Lower an archival worker without changing the evaluator thread.

    Linux exposes nice values per native thread.  The current priority is read
    before applying the delta so this helper is monotonic and cannot
    accidentally promote a worker when a deployment overrides the setting.
    """

    raw = os.environ.get(env_name, str(default)).strip()
    try:
        target = int(raw)
    except (TypeError, ValueError):
        target = int(default)
    if target < 0 or target > 19:
        target = int(default)
    try:
        getpriority = getattr(os, "getpriority", None)
        if callable(getpriority):
            current = int(
                getpriority(getattr(os, "PRIO_PROCESS", 0), 0)
            )
            if target <= current:
                return
            os.nice(target - current)
            return
        os.nice(target)
    except (AttributeError, OSError, TypeError, ValueError):
        pass


def _capture_artifact_thread_initializer() -> None:
    """Keep the restricted thread fallback below the evaluator priority."""

    _set_background_thread_nice(
        "BEHAVIOR_OFFICIAL_CAPTURE_NICE",
        default=19,
    )
    try:
        cv2.setNumThreads(1)
    except Exception:
        pass


# A reload transaction is only admitted while no normal skill is running, so
# an executor from the previous generation can be retired without abandoning a
# user-visible capture.  Keeping this cleanup here prevents one child process
# per hot reload from accumulating in a long-lived interface.
_previous_capture_process_executor = globals().get(
    "_CAPTURE_ARTIFACT_PROCESS_EXECUTOR"
)
if _previous_capture_process_executor is not None:
    try:
        _previous_capture_process_executor.shutdown(
            wait=False,
            cancel_futures=True,
        )
    except Exception:
        pass
_previous_capture_thread_executor = globals().get("_CAPTURE_ARTIFACT_EXECUTOR")
if _previous_capture_thread_executor is not None:
    try:
        _previous_capture_thread_executor.shutdown(
            wait=False,
            cancel_futures=True,
        )
    except Exception:
        pass
_CAPTURE_ARTIFACT_EXECUTOR = concurrent.futures.ThreadPoolExecutor(
    max_workers=1,
    thread_name_prefix="official-capture-artifacts",
    initializer=_capture_artifact_thread_initializer,
)
_CAPTURE_ARTIFACT_PROCESS_EXECUTOR = None
_CAPTURE_ARTIFACT_PROCESS_LOCK = threading.Lock()

# Agent-monitor cards are presentation telemetry.  Their thumbnail encoding
# and durable NAS writes must not sit on the HTTP response's critical path:
# the same Python process also owns the evaluator websocket callback.  Keep a
# single FIFO worker so card ids/order remain identical to the synchronous
# implementation while allowing the response and evaluator action loop to
# continue immediately.  The executor survives tool hot reloads because the
# monitor store itself is owned by the long-lived web app.
_AGENT_MONITOR_FINISH_EXECUTOR = globals().get(
    "_AGENT_MONITOR_FINISH_EXECUTOR"
)
_AGENT_MONITOR_FINISH_LOCK = globals().get(
    "_AGENT_MONITOR_FINISH_LOCK"
) or threading.Lock()
_AGENT_MONITOR_FINISH_MARKER = "_official_async_finish_card"
_previous_agent_monitor_finish_version = globals().get(
    "_AGENT_MONITOR_FINISH_VERSION"
)
_AGENT_MONITOR_FINISH_VERSION = 3
if (
    _previous_agent_monitor_finish_version is not None
    and _previous_agent_monitor_finish_version != _AGENT_MONITOR_FINISH_VERSION
    and _AGENT_MONITOR_FINISH_EXECUTOR is not None
):
    # Let an in-flight telemetry write finish, but prevent the old executor
    # from receiving any new cards after a transactional tool reload.
    try:
        _AGENT_MONITOR_FINISH_EXECUTOR.shutdown(
            wait=False,
            cancel_futures=False,
        )
    except Exception:
        pass
    _AGENT_MONITOR_FINISH_EXECUTOR = None


@dataclass
class _PendingCaptureArtifact:
    """One detached capture result owned by the HTTP waiter.

    The evaluator callback only keeps the immutable worker inputs and this
    small record.  It never waits for the media/geometry renderer.  ``finalize``
    is intentionally called by the waiting request thread so the existing
    ``ctx.set_result`` callback remains on a normal interface thread.
    """

    future: Any
    isolated: bool
    worker: Callable[[], dict[str, Any]]
    tool_name: str
    finalize: Callable[[dict[str, Any]], Any]
    created_mono: float
    lock: Any = field(default_factory=threading.RLock, repr=False)
    final_result: dict[str, Any] | None = None
    final_error: BaseException | None = None
    cancelled: bool = False


_CAPTURE_ARTIFACT_PENDING_LOCK = threading.RLock()
_CAPTURE_ARTIFACT_PENDING: dict[str, _PendingCaptureArtifact] = {}
_CAPTURE_ARTIFACT_PENDING_TTL_S = 15.0 * 60.0

# The official policy coordinator normally installs this bridge when its
# runtime is constructed.  Keep the same marker in the tool module as a
# compatibility fallback: a long-lived interface can reload the tool stack
# without re-running the coordinator constructor, and a later capture is the
# first point at which we can prove that the server still needs the bridge.
_CAPTURE_WAIT_BRIDGE_ATTR = "_official_capture_wait_bridge"
_CAPTURE_WAIT_BRIDGE_SOURCE_ATTR = "_official_capture_wait_bridge_source"

# Optional local diagnostic.  It is deliberately off in normal operation so
# a capture never adds a filesystem write of its own.
_CAPTURE_TRACE_ENABLED = (
    os.environ.get("BEHAVIOR_OFFICIAL_CAPTURE_TRACE", "0")
    .strip()
    .lower()
    in {"1", "true", "yes", "on"}
)


def _capture_trace(stage: str, **fields: Any) -> None:
    if not _CAPTURE_TRACE_ENABLED:
        return
    record = {
        "ts": time.time(),
        "pid": os.getpid(),
        "thread": threading.get_native_id(),
        "module": "tools",
        "stage": str(stage),
        **fields,
    }
    try:
        with open(
            f"/tmp/official_capture_trace_{os.getpid()}.jsonl",
            "a",
            encoding="utf-8",
        ) as stream:
            stream.write(json.dumps(record, separators=(",", ":")) + "\n")
    except OSError:
        pass


_NAVIGATION_TRACE_SENTINEL = "/tmp/behavior_navigation_trace.enabled"


def _navigation_trace(stage: str, **fields: Any) -> None:
    """Write an opt-in, observation-only trace for live navigation diagnosis."""

    if not os.path.isfile(_NAVIGATION_TRACE_SENTINEL):
        return
    record = {
        "ts": time.time(),
        "pid": os.getpid(),
        "thread": threading.get_native_id(),
        "module": "tools",
        "stage": str(stage),
        **fields,
    }
    try:
        with open(
            f"/tmp/official_navigation_trace_{os.getpid()}.jsonl",
            "a",
            encoding="utf-8",
        ) as stream:
            stream.write(
                json.dumps(
                    _json_ready(record),
                    separators=(",", ":"),
                    ensure_ascii=True,
                    allow_nan=False,
                )
                + "\n"
            )
    except (OSError, TypeError, ValueError):
        pass


def _capture_artifact_process_initializer() -> None:
    """Keep the isolated media worker from starting a CPU thread fan-out."""

    # interface 被 setsid 拉起、停机只杀组长时，spawn worker 会被 init 收养
    # 并继续占着 CUDA context。父进程一死就让子进程跟着退出。
    try:
        import ctypes
        import signal as signal_mod

        parent_pid = os.getppid()
        libc = ctypes.CDLL(None, use_errno=True)
        if int(libc.prctl(1, int(signal_mod.SIGTERM), 0, 0, 0)) == 0:
            if os.getppid() != parent_pid:
                os.kill(os.getpid(), signal_mod.SIGTERM)
    except Exception:
        pass
    _set_background_thread_nice(
        "BEHAVIOR_OFFICIAL_CAPTURE_NICE",
        default=19,
    )
    try:
        cv2.setNumThreads(1)
    except Exception:
        pass


def _agent_monitor_finish_initializer() -> None:
    """Give presentation-only card work a lower scheduling priority."""

    _set_background_thread_nice(
        "BEHAVIOR_OFFICIAL_MONITOR_NICE",
        default=19,
    )


def _agent_monitor_finish_executor():
    global _AGENT_MONITOR_FINISH_EXECUTOR
    with _AGENT_MONITOR_FINISH_LOCK:
        executor = _AGENT_MONITOR_FINISH_EXECUTOR
        if executor is None:
            executor = concurrent.futures.ThreadPoolExecutor(
                max_workers=1,
                thread_name_prefix="official-agent-monitor",
                initializer=_agent_monitor_finish_initializer,
            )
            _AGENT_MONITOR_FINISH_EXECUTOR = executor
        return executor


def _install_async_agent_monitor_finish() -> bool:
    """Defer external-agent monitor cards without changing card semantics.

    The web app is intentionally long-lived across official-v2 transactions,
    while this tool module is reloadable.  Installing the tiny wrapper here
    lets a hot reload upgrade an already-created ``AgentMonitorStore`` class.
    Direct/unit-test calls have no Flask request context and therefore retain
    the original synchronous behavior.
    """

    try:
        from behavior_interface.agent_monitor import AgentMonitorStore
    except Exception:
        return False
    current = getattr(AgentMonitorStore, "finish_card", None)
    if not callable(current):
        return False
    if (
        bool(getattr(current, _AGENT_MONITOR_FINISH_MARKER, False))
        and getattr(current, "_official_async_finish_card_version", None)
        == _AGENT_MONITOR_FINISH_VERSION
    ):
        return True
    original = getattr(current, "_official_async_finish_card_base", None)
    if not callable(original):
        original = current

    def finish_card_async(store, context, response, sim_tick=None):
        if context is None:
            return original(store, context, response, sim_tick)
        # Only Flask's response/teardown hooks are deferred.  Keeping direct
        # calls synchronous preserves the monitor store's public API and all
        # existing tests/tools that inspect the returned card immediately.
        try:
            from flask import has_request_context

            if not has_request_context():
                return original(store, context, response, sim_tick)
        except Exception:
            return original(store, context, response, sim_tick)
        try:
            _agent_monitor_finish_executor().submit(
                original,
                store,
                context,
                response,
                sim_tick,
            )
            return None
        except Exception:
            # A saturated/shutdown telemetry worker must never change the
            # user-visible tool result.  Fall back to the exact old behavior.
            return original(store, context, response, sim_tick)

    finish_card_async.__name__ = "finish_card"
    setattr(finish_card_async, _AGENT_MONITOR_FINISH_MARKER, True)
    setattr(
        finish_card_async,
        "_official_async_finish_card_version",
        _AGENT_MONITOR_FINISH_VERSION,
    )
    setattr(finish_card_async, "_official_async_finish_card_base", original)
    AgentMonitorStore.finish_card = finish_card_async
    return True


def _capture_server_from_context(ctx: Any) -> Any | None:
    """Find the owning compatibility server without changing SkillContext.

    Older interface processes do not expose ``ctx.server``.  Their setter is
    the server's ``_set_result_for_job`` closure, whose cells contain the
    exact server instance.  This read-only lookup lets a reloaded tool stack
    repair the HTTP bridge in-place while ordinary unit-test contexts simply
    return ``None``.
    """

    candidate = getattr(ctx, "server", None)
    if callable(getattr(candidate, "wait_for_skill_result", None)) and hasattr(
        candidate, "_last_skill_results"
    ):
        return candidate
    setter = getattr(ctx, "_set_result", None)
    for cell in getattr(setter, "__closure__", ()) or ():
        try:
            value = cell.cell_contents
        except ValueError:
            continue
        if callable(getattr(value, "wait_for_skill_result", None)) and hasattr(
            value, "_last_skill_results"
        ):
            return value
    return None


def _install_capture_wait_bridge(server: Any) -> bool:
    """Install one idempotent waiter that resolves detached capture tokens."""

    previous = getattr(server, "wait_for_skill_result", None)
    if not callable(previous):
        return False
    if (
        bool(getattr(previous, _CAPTURE_WAIT_BRIDGE_ATTR, False))
        and getattr(previous, _CAPTURE_WAIT_BRIDGE_SOURCE_ATTR, None)
        == __name__
    ):
        return True

    # A previous coordinator generation may have wrapped the waiter already.
    # Peel those compatibility layers back to the policy wait closure before
    # installing the current resolver, otherwise an old layer can look up a
    # token in a retired module registry and return the private marker.
    base = previous
    seen: set[int] = set()
    while bool(getattr(base, _CAPTURE_WAIT_BRIDGE_ATTR, False)):
        marker = id(base)
        if marker in seen:
            break
        seen.add(marker)
        candidate = getattr(base, "_official_capture_wait_bridge_base", None)
        if not callable(candidate):
            break
        base = candidate
    previous = base

    def wait_for_skill_result_with_capture(
        skill_name: str,
        timeout_s: float = 180.0,
        poll_s: float = 0.25,
        request_id: str | None = None,
    ):
        started = time.monotonic()
        result = previous(
            skill_name,
            timeout_s=timeout_s,
            poll_s=poll_s,
            request_id=request_id,
        )
        if not isinstance(result, Mapping):
            return result
        token = str(result.get("_official_capture_pending_token") or "").strip()
        if not token:
            return result
        resolver = globals().get("wait_for_capture_artifact")
        if not callable(resolver):
            raise RuntimeError("official capture result resolver is unavailable")
        try:
            remaining = max(
                0.0,
                float(timeout_s) - (time.monotonic() - started),
            )
            final = resolver(token, timeout_s=remaining)
        except TimeoutError:
            cancel = globals().get("cancel_capture_artifact")
            if callable(cancel):
                cancel(token)
            raise
        if isinstance(final, Mapping):
            final = dict(final)
            final.pop("_official_capture_pending_token", None)
        return final

    wait_for_skill_result_with_capture.__name__ = (
        "wait_for_skill_result_with_capture"
    )
    setattr(wait_for_skill_result_with_capture, _CAPTURE_WAIT_BRIDGE_ATTR, True)
    setattr(
        wait_for_skill_result_with_capture,
        _CAPTURE_WAIT_BRIDGE_SOURCE_ATTR,
        __name__,
    )
    setattr(
        wait_for_skill_result_with_capture,
        "_official_capture_wait_bridge_base",
        previous,
    )
    server.wait_for_skill_result = wait_for_skill_result_with_capture
    return True


def _ensure_capture_wait_bridge(ctx: Any) -> bool:
    server = _capture_server_from_context(ctx)
    return bool(server is not None and _install_capture_wait_bridge(server))


def _get_capture_artifact_process_executor():
    global _CAPTURE_ARTIFACT_PROCESS_EXECUTOR
    with _CAPTURE_ARTIFACT_PROCESS_LOCK:
        if _CAPTURE_ARTIFACT_PROCESS_EXECUTOR is None:
            _CAPTURE_ARTIFACT_PROCESS_EXECUTOR = (
                concurrent.futures.ProcessPoolExecutor(
                    max_workers=1,
                    mp_context=multiprocessing.get_context("spawn"),
                    initializer=_capture_artifact_process_initializer,
                )
            )
        return _CAPTURE_ARTIFACT_PROCESS_EXECUTOR
