@dataclass
class _FrozenCapture:
    session_id: str
    image_id: str
    role: str
    depth: np.ndarray
    camera: dict[str, Any]
    rgb: np.ndarray | None = None
    robot: dict[str, Any] | None = None
    evaluator_sequence: int | None = None


def _check_cancelled(ctx, where: str) -> None:
    fn = getattr(ctx, "raise_if_cancelled", None)
    if callable(fn):
        fn(where)


def _smoothstep(value: float) -> float:
    value = float(np.clip(value, 0.0, 1.0))
    return value * value * (3.0 - 2.0 * value)


def _set_result(ctx, tool_name: str, payload: dict[str, Any]) -> dict[str, Any]:
    _capture_trace(
        "set_result_start",
        tool=tool_name,
        keys=len(payload) if isinstance(payload, Mapping) else -1,
        image_id=str(payload.get("image_id") or "") if isinstance(payload, Mapping) else "",
        rgb_chars=(
            len(str(payload.get("rgb_main") or ""))
            if isinstance(payload, Mapping)
            else 0
        ),
    )
    result = dict(payload)
    if (
        str(result.get("image_id") or "").strip()
        and any(result.get(key) for key in ("rgb_main", "rgb_main_path", "rgb_path"))
        and "track_object_distance_binding" not in result
    ):
        feed = str(result.get("feed") or "").strip().lower()
        reason = (
            "unsupported_camera_role"
            if feed and feed not in ("head", "main")
            else "binding_not_registered"
        )
        result["track_object_distance_binding"] = {
            "ok": False,
            "trackable": False,
            "reason": reason,
            "image_id": str(result.get("image_id") or "").strip(),
            "error": (
                "track_object_distance accepts only an exactly bound frozen "
                "head RGB-D capture"
            ),
        }
    result["tool"] = str(tool_name)
    result["tool_version"] = TOOL_VERSION
    # Tool diagnostics may use +/-inf internally to rank unavailable or
    # unobserved candidates.  Public results cross a strict JSON boundary,
    # where non-finite numbers are invalid and break browser JSON.parse().
    result = _json_ready(result)
    record_compliant_grasp_prediction(tool_name, result)
    # Returning the normalized payload is useful to the detached capture
    # waiter.  Existing callers ignore the return value, so this is a strictly
    # additive extension of the old result callback contract.
    installed = ctx.set_result(result)
    _capture_trace(
        "set_result_done",
        tool=tool_name,
        elapsed_ms=0.0,
        installed_mapping=isinstance(installed, Mapping),
    )
    if isinstance(installed, Mapping):
        return dict(installed)
    return result


_LEGACY_RUNS_ROOT = "/tmp/behavior_agent_runs"


def _runs_root() -> str:
    return os.environ.get(
        "BEHAVIOR_AGENT_RUNS", os.path.expanduser("~/.local/share/roboharness/recordings")
    )


def _run_dir(session_id: str) -> str:
    # A changed default must not split a live session's captures, plans and
    # counters. Explicit deployment overrides still take precedence.
    session = _validated_session_id(session_id)
    if "BEHAVIOR_AGENT_RUNS" not in os.environ:
        legacy = os.path.join(_LEGACY_RUNS_ROOT, session)
        if os.path.isfile(os.path.join(legacy, "session.json")):
            return legacy
    return os.path.join(_runs_root(), session)


def _images_dir(session_id: str) -> str:
    return os.path.join(_run_dir(session_id), "images")


def _plans_dir(session_id: str) -> str:
    return os.path.join(_run_dir(session_id), "plans")


def _validated_session_id(session_id: str) -> str:
    session = str(session_id or "").strip()
    if not _SESSION_ID_RE.fullmatch(session):
        raise ValueError(
            "session_id must contain only letters, digits, '_', '-', or '.'"
        )
    return session


def _validated_plan_id(plan_id: str) -> str:
    plan = str(plan_id or "").strip()
    if not _PLAN_ID_RE.fullmatch(plan):
        raise ValueError("plan_id must match plan_<letters-or-digits>")
    return plan


def _plan_record_path(session_id: str, plan_id: str) -> str:
    session = _validated_session_id(session_id)
    plan = _validated_plan_id(plan_id)
    root = os.path.realpath(_plans_dir(session))
    path = os.path.abspath(os.path.join(root, f"{plan}.json"))
    if os.path.commonpath((root, path)) != root:
        raise ValueError("plan path escapes the policy-owned plans directory")
    return path


def _canonical_json_bytes(payload: Any) -> bytes:
    return json.dumps(
        payload,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        allow_nan=False,
    ).encode("ascii")


def _trajectory_digest(trajectory: dict[str, Any]) -> str:
    unsigned = dict(trajectory)
    unsigned.pop("integrity", None)
    return hmac.new(
        _PLAN_INTEGRITY_KEY,
        _canonical_json_bytes(unsigned),
        hashlib.sha256,
    ).hexdigest()


def _write_plan_record(path: str, record: dict[str, Any]) -> None:
    directory = os.path.dirname(path)
    os.makedirs(directory, exist_ok=True)
    temp_path = f"{path}.tmp-{os.getpid()}-{threading.get_ident()}"
    encoded = _canonical_json_bytes(_json_ready(record))
    if not 1 <= len(encoded) <= MAX_PLAN_RECORD_BYTES:
        raise ValueError(
            "plan record size must be in "
            f"1..{MAX_PLAN_RECORD_BYTES} bytes (encoded size: {len(encoded)} bytes)"
        )
    try:
        with open(temp_path, "xb") as stream:
            stream.write(encoded)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temp_path, path)
    finally:
        if os.path.exists(temp_path):
            os.unlink(temp_path)


def _session_meta_path(session_id: str) -> str:
    return os.path.join(_run_dir(session_id), "session.json")


def _load_session_meta(session_id: str) -> dict[str, Any]:
    path = _session_meta_path(session_id)
    if os.path.isfile(path):
        with open(path, encoding="utf-8") as stream:
            return json.load(stream)
    return {
        "session_id": str(session_id),
        "image_counter": 0,
        "plan_counter": 0,
    }


def _save_session_meta(session_id: str, meta: dict[str, Any]) -> None:
    os.makedirs(_run_dir(session_id), exist_ok=True)
    with open(_session_meta_path(session_id), "w", encoding="utf-8") as stream:
        json.dump(meta, stream, indent=2, ensure_ascii=False)


def _ensure_session(session_id: str) -> None:
    with _SESSION_LOCK:
        os.makedirs(_images_dir(session_id), exist_ok=True)
        os.makedirs(_plans_dir(session_id), exist_ok=True)
        _save_session_meta(session_id, _load_session_meta(session_id))


def _next_image_id(session_id: str) -> str:
    with _SESSION_LOCK:
        meta = _load_session_meta(session_id)
        meta["image_counter"] = int(meta.get("image_counter", 0)) + 1
        _save_session_meta(session_id, meta)
        return f"img_{meta['image_counter']:04d}"


def _next_plan_id(session_id: str) -> str:
    with _SESSION_LOCK:
        meta = _load_session_meta(session_id)
        meta["plan_counter"] = int(meta.get("plan_counter", 0)) + 1
        _save_session_meta(session_id, meta)
        return f"plan_{meta['plan_counter']:04d}"


def _json_ready(value: Any) -> Any:
    if isinstance(value, Mapping):
        return {str(key): _json_ready(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_ready(item) for item in value]
    if isinstance(value, np.ndarray):
        return _json_ready(value.tolist())
    if isinstance(value, np.generic):
        return _json_ready(value.item())
    if isinstance(value, float) and not math.isfinite(value):
        return None
    return value


def _arm_vector(value: Any, *, label: str) -> np.ndarray:
    vector = np.asarray(value, dtype=np.float64).reshape(-1)
    if vector.size != ARM_DOF:
        raise ValueError(
            f"{label} must contain {ARM_DOF} arm values, got {vector.size}"
        )
    if not np.all(np.isfinite(vector)):
        raise ValueError(f"{label} contains non-finite values")
    return vector


def _j8_locked_copy(value: Any, *, label: str) -> np.ndarray:
    vector = _arm_vector(value, label=label).copy()
    if LOCKED_J8_INDEX is not None:
        vector[LOCKED_J8_INDEX] = LOCKED_J8_VALUE_RAD
    return vector


def _require_serialized_j8_zero(value: Any, *, label: str) -> np.ndarray:
    vector = _arm_vector(value, label=label)
    if (
        LOCKED_J8_INDEX is not None
        and abs(float(vector[LOCKED_J8_INDEX]) - LOCKED_J8_VALUE_RAD)
        > LOCKED_J8_SERIALIZED_TOLERANCE_RAD
    ):
        raise ValueError(
            f"{label} contains non-zero locked J8; re-plan after episode initialization"
        )
    return vector


def _normalize_arm_q_to_joint_limits(
    value: Any,
    *,
    arm: str,
    label: str,
    point: str,
    recover_observed_overshoot: bool = False,
) -> tuple[np.ndarray, list[dict[str, Any]]]:
    """把关节角收到本地位，并拒绝规划点上的真实越界。

    recover_observed_overshoot=True 只给 evaluator 实时观测值使用：观测值
    可能因控制残差轻微越过静态限位，但 action 仍必须严格位于限位内。
    规划得到的 safe_q / final_q 必须继续严格拒绝真实越界。
    """
    q = _arm_vector(value, label=label).copy()
    limits = _ARM_LIMITS[arm][:ARM_DOF]
    below = limits[:, 0] - q
    above = q - limits[:, 1]
    violation = np.maximum(np.maximum(below, above), 0.0)
    if (
        bool(np.any(violation > TRAJECTORY_JOINT_LIMIT_NUMERIC_TOLERANCE_RAD))
        and not recover_observed_overshoot
    ):
        joint_index = int(np.argmax(violation))
        raise ValueError(
            f"{label} exceeds local arm joint limits: arm={arm} "
            f"J{joint_index + 1}={q[joint_index]:.12g}rad outside "
            f"[{limits[joint_index, 0]:.12g},"
            f"{limits[joint_index, 1]:.12g}] by "
            f"{violation[joint_index]:.12g}rad; numeric tolerance is "
            f"{TRAJECTORY_JOINT_LIMIT_NUMERIC_TOLERANCE_RAD:.12g}rad"
        )

    clipped = np.clip(q, limits[:, 0], limits[:, 1])
    normalizations = []
    for joint_index in np.flatnonzero(clipped != q):
        index = int(joint_index)
        item = {
            "point": str(point),
            "joint": f"J{index + 1}",
            "before_rad": float(q[index]),
            "after_rad": float(clipped[index]),
            "correction_rad": float(clipped[index] - q[index]),
        }
        if (
            recover_observed_overshoot
            and float(violation[index])
            > TRAJECTORY_JOINT_LIMIT_NUMERIC_TOLERANCE_RAD
        ):
            item["recovered_observed_overshoot"] = True
        normalizations.append(item)
    return clipped, normalizations


def _normalize_trunk_q_to_joint_limits(
    value: Any,
    *,
    label: str,
    point: str,
    recover_observed_overshoot: bool = False,
) -> tuple[np.ndarray, list[dict[str, Any]]]:
    """Normalize the four trunk joints without accepting an invalid plan.

    Evaluator proprioception can contain float32-scale residuals at a static
    limit, including the locked fourth trunk joint. Planned values only get
    the shared numeric serialization tolerance; live observations may be
    recovered by callers after they enforce their bounded-action limit.
    """

    try:
        q = np.asarray(value, dtype=np.float64).reshape(-1)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{label} must contain 4 trunk values") from exc
    if q.size != 4:
        raise ValueError(f"{label} must contain 4 trunk values, got {q.size}")
    if not np.all(np.isfinite(q)):
        raise ValueError(f"{label} contains non-finite values")
    q = q.copy()
    limits = np.asarray(TRUNK_LIMITS, dtype=np.float64).reshape(4, 2)
    below = limits[:, 0] - q
    above = q - limits[:, 1]
    violation = np.maximum(np.maximum(below, above), 0.0)
    if (
        bool(np.any(violation > TRAJECTORY_JOINT_LIMIT_NUMERIC_TOLERANCE_RAD))
        and not recover_observed_overshoot
    ):
        joint_index = int(np.argmax(violation))
        raise ValueError(
            f"{label} exceeds local trunk joint limits: "
            f"J{joint_index + 1}={q[joint_index]:.12g}rad outside "
            f"[{limits[joint_index, 0]:.12g},"
            f"{limits[joint_index, 1]:.12g}] by "
            f"{violation[joint_index]:.12g}rad; numeric tolerance is "
            f"{TRAJECTORY_JOINT_LIMIT_NUMERIC_TOLERANCE_RAD:.12g}rad"
        )

    clipped = np.clip(q, limits[:, 0], limits[:, 1])
    normalizations = []
    for joint_index in np.flatnonzero(clipped != q):
        index = int(joint_index)
        item = {
            "point": str(point),
            "joint": f"J{index + 1}",
            "before_rad": float(q[index]),
            "after_rad": float(clipped[index]),
            "correction_rad": float(clipped[index] - q[index]),
        }
        if (
            recover_observed_overshoot
            and float(violation[index])
            > TRAJECTORY_JOINT_LIMIT_NUMERIC_TOLERANCE_RAD
        ):
            item["recovered_observed_overshoot"] = True
        normalizations.append(item)
    return clipped, normalizations


def _require_signed_trunk_q(
    value: Any,
    *,
    label: str,
    point: str,
) -> np.ndarray:
    """签名轨迹里的躯干只收 1e-6 数值残差，真越界仍拒绝。"""

    trunk, _normalizations = _normalize_trunk_q_to_joint_limits(
        value,
        label=label,
        point=point,
        recover_observed_overshoot=False,
    )
    return trunk


def _require_episode_initialized(ctx, operation: str) -> None:
    initialized = getattr(ctx.world, "episode_initialized", None)
    if callable(initialized) and not bool(initialized()):
        raise ValueError(
            f"episode grasp-prep initialization is incomplete; {operation} is blocked"
        )


def _interpolate_joint_segment(
    start_q: np.ndarray,
    target_q: np.ndarray,
    *,
    max_step_rad: float = DEFAULT_TRAJECTORY_STEP_RAD,
) -> list[list[float]]:
    start = _arm_vector(start_q, label="segment start")
    target = _arm_vector(target_q, label="segment target")
    max_step = float(max_step_rad)
    if not math.isfinite(max_step) or max_step <= 0.0:
        raise ValueError("max_step_rad must be positive and finite")
    distance = float(np.linalg.norm(target - start, ord=np.inf))
    # Smoothstep's maximum derivative is 1.5, so its midpoint samples move
    # faster than linear interpolation.
    steps = max(1, int(math.ceil(1.5 * distance / max_step)))
    return [
        (
            start
            + _smoothstep(index / steps) * (target - start)
        ).astype(float).tolist()
        for index in range(1, steps + 1)
    ]


def _compile_exec_arm_segments(
    start_q: Sequence[float],
    safe_q: Sequence[float],
    final_q: Sequence[float],
) -> list[dict[str, Any]]:
    """Build the one canonical arm-only current/safe/final exec trajectory."""

    start = _require_serialized_j8_zero(start_q, label="exec segment start_q")
    safe = _require_serialized_j8_zero(safe_q, label="exec segment safe_q")
    final = _require_serialized_j8_zero(final_q, label="exec segment final_q")
    segment_specs = (
        ("tool_roll_reset", start, start),
        ("current_to_safe", start, safe),
        ("safe_to_final", safe, final),
    )
    segments: list[dict[str, Any]] = []
    for name, segment_start, segment_target in segment_specs:
        segments.append(
            {
                "name": name,
                "waypoints": _interpolate_joint_segment(
                    segment_start,
                    segment_target,
                ),
                "endpoint_q": segment_target.astype(float).tolist(),
            }
        )
    return segments


def _selected_safe_q(payload: dict[str, Any], arm: str) -> tuple[np.ndarray, float]:
    candidates = payload.get("candidates")
    if not isinstance(candidates, list) or not candidates:
        raise ValueError("planner payload has no selected candidate list")
    candidate = candidates[0]
    if not isinstance(candidate, dict):
        raise ValueError("planner selected candidate is invalid")
    candidate_arm = str(candidate.get("arm", "")).strip().lower()
    if candidate_arm != arm:
        raise ValueError(
            f"planner selected candidate arm {candidate_arm!r} "
            f"does not match recommended arm {arm!r}"
        )
    planned_safe = dict((candidate.get("meta") or {}).get("planned_safe") or {})
    if not bool(planned_safe.get("ok")):
        raise ValueError(f"planner selected candidate has no validated safe_q")
    safe_q = _j8_locked_copy(
        planned_safe.get("safe_q"),
        label=f"{arm} planned safe_q",
    )
    planned_safe["safe_q"] = safe_q.astype(float).tolist()
    candidate_meta = dict(candidate.get("meta") or {})
    candidate_meta["planned_safe"] = planned_safe
    candidate["meta"] = candidate_meta
    back_m = float(
        planned_safe.get(
            "active_back_m",
            planned_safe.get("requested_back_m", 0.10),
        )
    )
    if not math.isfinite(back_m) or back_m < 0.0:
        raise ValueError("planned safe back_m is invalid")
    return safe_q, back_m


def _plan_start_local_state(start_state: dict[str, Any]) -> LocalRobotState:
    arm_qpos = dict(start_state.get("arm_qpos") or {})
    gripper_qpos = dict(start_state.get("gripper_qpos") or {})
    return local_robot_state(
        trunk_q=start_state.get("trunk_qpos"),
        arm_left_q=arm_qpos.get("left"),
        arm_right_q=arm_qpos.get("right"),
        gripper_left_q=gripper_qpos.get("left"),
        gripper_right_q=gripper_qpos.get("right"),
    )


def _validate_exec_final_q_for_arm(
    *,
    trajectory: dict[str, Any],
    arm: str,
    raw_q: Any,
    source: str,
) -> tuple[np.ndarray, dict[str, Any]]:
    """Verify a stored arm branch reaches the plan's immutable final target."""
    requested_arm = str(arm).strip().lower()
    planned_arm = str(trajectory["active_arm"])
    if requested_arm not in ("left", "right"):
        raise ValueError("requested execution arm must be left or right")
    candidate_q = _require_serialized_j8_zero(
        raw_q,
        label=f"{source} {requested_arm} final_q",
    )
    candidate_q, normalizations = _normalize_arm_q_to_joint_limits(
        candidate_q,
        arm=requested_arm,
        label=f"{source} {requested_arm} final_q",
        point="exec_final_q",
    )
    planned_q = _require_serialized_j8_zero(
        trajectory["segments"][2]["endpoint_q"],
        label=f"signed {planned_arm} final endpoint_q",
    )
    state = _plan_start_local_state(dict(trajectory["start_state"]))
    planned_position, planned_quaternion = _local_eef_pose(
        state,
        planned_arm,
        planned_q,
    )
    candidate_position, candidate_quaternion = _local_eef_pose(
        state,
        requested_arm,
        candidate_q,
    )
    pair_position_error = float(
        np.linalg.norm(candidate_position - planned_position)
    )
    pair_orientation_error = float(
        orientation_error_deg(candidate_quaternion, planned_quaternion)
    )
    if (
        pair_position_error > EXEC_FINAL_PAIR_POS_TOL_M
        or pair_orientation_error > EXEC_FINAL_PAIR_ORI_TOL_DEG
    ):
        raise ValueError(
            f"stored {requested_arm} final_q does not reach the planned final "
            f"EEF pose: pair position error {pair_position_error:.4f}m "
            f"(limit {EXEC_FINAL_PAIR_POS_TOL_M:.4f}m), orientation error "
            f"{pair_orientation_error:.3f}deg "
            f"(limit {EXEC_FINAL_PAIR_ORI_TOL_DEG:.3f}deg)"
        )

    return candidate_q, {
        "source": str(source),
        "planned_arm": planned_arm,
        "execution_arm": requested_arm,
        "arm_switched": requested_arm != planned_arm,
        "pair_pos_err_m": pair_position_error,
        "pair_ori_err_deg": pair_orientation_error,
        "pair_pos_tol_m": EXEC_FINAL_PAIR_POS_TOL_M,
        "pair_ori_tol_deg": EXEC_FINAL_PAIR_ORI_TOL_DEG,
        "target_comparison_frame": "submission_local_robot_base",
        "joint_limit_normalizations": normalizations,
        "submission_local_fk_checked": True,
        "j8_locked": LOCKED_J8_INDEX is not None,
    }


def _compile_joint_trajectory(
    *,
    ctx,
    plan_id: str,
    session_id: str,
    image_id: str,
    capture: _FrozenCapture,
    payload: dict[str, Any],
) -> dict[str, Any]:
    _require_episode_initialized(ctx, "trajectory compilation")
    active_arm = str(payload.get("recommended_arm", "")).strip().lower()
    if active_arm not in ("left", "right"):
        raise ValueError("planner did not select a valid execution arm")
    final_q_map = payload.get("selected_pose_ik_q")
    if not isinstance(final_q_map, dict):
        raise ValueError("planner payload has no selected_pose_ik_q")
    final_q = _j8_locked_copy(
        final_q_map.get(active_arm),
        label=f"{active_arm} selected final_q",
    )
    safe_q, back_m = _selected_safe_q(payload, active_arm)

    robot = dict(capture.robot or {})
    start_arms = {}
    for side in ("left", "right"):
        observed_start = _arm_vector(
            robot.get(f"arm_{side}_qpos"),
            label=f"capture {side} arm_qpos",
        )
        if (
            LOCKED_J8_INDEX is not None
            and abs(float(observed_start[LOCKED_J8_INDEX]))
            > LOCKED_J8_CAPTURE_TOLERANCE_RAD
        ):
            raise ValueError(
                f"capture {side} arm J8={observed_start[LOCKED_J8_INDEX]:.6f}rad "
                "is outside the locked-joint initialization tolerance; recapture"
            )
        start_arms[side] = _j8_locked_copy(
            observed_start,
            label=f"capture {side} normalized arm_qpos",
        )
    # 对齐 v2：冻结起点只记录、必要时回收到限位，不因物理穿透判规划失败。
    joint_limit_normalizations: list[dict[str, Any]] = []
    for side in ("left", "right"):
        recovered, normalized = _normalize_arm_q_to_joint_limits(
            start_arms[side],
            arm=side,
            label=f"capture {side} start_q",
            point="start_q" if side == active_arm else f"{side}_start_q",
            recover_observed_overshoot=True,
        )
        start_arms[side] = recovered
        joint_limit_normalizations.extend(normalized)
    start_q = start_arms[active_arm]
    captured_start_recovered = bool(
        any(
            item.get("recovered_observed_overshoot")
            for item in joint_limit_normalizations
        )
    )
    safe_q, normalized = _normalize_arm_q_to_joint_limits(
        safe_q,
        arm=active_arm,
        label=f"{active_arm} planned safe_q",
        point="safe_q",
    )
    joint_limit_normalizations.extend(normalized)
    final_q, normalized = _normalize_arm_q_to_joint_limits(
        final_q,
        arm=active_arm,
        label=f"{active_arm} selected final_q",
        point="final_q",
    )
    joint_limit_normalizations.extend(normalized)
    start_arms[active_arm] = start_q
    final_q_map[active_arm] = final_q.astype(float).tolist()
    payload["candidates"][0]["meta"]["planned_safe"]["safe_q"] = (
        safe_q.astype(float).tolist()
    )
    trunk_q = np.asarray(
        robot.get("trunk_qpos"),
        dtype=np.float64,
    ).reshape(-1)
    if trunk_q.size != 4 or not np.all(np.isfinite(trunk_q)):
        raise ValueError("capture trunk_qpos must contain four finite values")
    # 冻结观测与 start arm 对齐：ULP/float32 残差回收到限位后再签名。
    trunk_q, trunk_normalized = _normalize_trunk_q_to_joint_limits(
        trunk_q,
        label="capture trunk_qpos",
        point="start_trunk",
        recover_observed_overshoot=True,
    )
    joint_limit_normalizations.extend(trunk_normalized)
    capture_motion_epoch = robot.get("motion_epoch")
    if not isinstance(capture_motion_epoch, int) or capture_motion_epoch < 0:
        raise ValueError("capture has no valid policy motion_epoch")
    capture_episode_id = str(robot.get("episode_id", "")).strip()
    if not capture_episode_id:
        raise ValueError("capture has no valid evaluator episode_id")
    if str(ctx.world.episode_id()) != capture_episode_id:
        raise ValueError("capture belongs to a different evaluator episode")

    segments = _compile_exec_arm_segments(start_q, safe_q, final_q)
    waypoint_count = sum(len(segment["waypoints"]) for segment in segments)
    if waypoint_count > MAX_TRAJECTORY_WAYPOINTS:
        raise ValueError(
            f"compiled trajectory has {waypoint_count} waypoints; "
            f"limit is {MAX_TRAJECTORY_WAYPOINTS}"
        )

    limits = _ARM_LIMITS[active_arm][:ARM_DOF]
    all_waypoints = []
    for segment in segments:
        segment_name = str(segment["name"])
        for waypoint_index, raw_q in enumerate(segment["waypoints"]):
            q = _arm_vector(raw_q, label=f"{segment_name} waypoint")
            below = limits[:, 0] - q
            above = q - limits[:, 1]
            violation = np.maximum(below, above)
            if bool(np.any(violation > 0.0)):
                joint_index = int(np.argmax(violation))
                raise ValueError(
                    "compiled trajectory exceeds local arm joint limits: "
                    f"segment={segment_name} waypoint={waypoint_index + 1} "
                    f"arm={active_arm} J{joint_index + 1}="
                    f"{q[joint_index]:.12g}rad outside "
                    f"[{limits[joint_index, 0]:.12g},"
                    f"{limits[joint_index, 1]:.12g}] by "
                    f"{violation[joint_index]:.12g}rad"
                )
            all_waypoints.append(q)
    fk_positions = [
        _r1pro_arm_fk_robot(active_arm, trunk_q, q)[0]
        for q in all_waypoints
    ]
    if not all(np.all(np.isfinite(pos)) for pos in fk_positions):
        raise ValueError("local FK validation produced a non-finite pose")

    start_state = {
        "motion_epoch": int(capture_motion_epoch),
        "episode_id": capture_episode_id,
        "arm_qpos": {
            side: start_arms[side].astype(float).tolist()
            for side in ("left", "right")
        },
        "arm_qvel": {
            side: _arm_vector(
                robot.get(f"arm_{side}_qvel", [0.0] * ARM_DOF),
                label=f"capture {side} arm_qvel",
            ).astype(float).tolist()
            for side in ("left", "right")
        },
        "trunk_qpos": trunk_q.astype(float).tolist(),
        "gripper_qpos": {
            side: _json_ready(robot.get(f"gripper_{side}_qpos"))
            for side in ("left", "right")
        },
    }
    signed_final_q_by_arm = {
        active_arm: final_q.astype(float).tolist(),
    }
    for side in ("left", "right"):
        if side == active_arm or final_q_map.get(side) is None:
            continue
        alternate_q = _require_serialized_j8_zero(
            final_q_map[side],
            label=f"planner {side} selected final_q",
        )
        alternate_q, normalized = _normalize_arm_q_to_joint_limits(
            alternate_q,
            arm=side,
            label=f"planner {side} selected final_q",
            point=f"{side}_final_q",
        )
        joint_limit_normalizations.extend(normalized)
        signed_final_q_by_arm[side] = alternate_q.astype(float).tolist()
    trajectory: dict[str, Any] = {
        "schema": JOINT_TRAJECTORY_SCHEMA,
        "schema_version": JOINT_TRAJECTORY_SCHEMA_VERSION,
        "plan_id": str(plan_id),
        "session_id": str(session_id),
        "tool_version": TOOL_VERSION,
        "source_tool": "plan_grasp_point_filter_rgbd_lite",
        "source_image_id": str(image_id),
        "robot_profile": ROBOT_PROFILE,
        "arm_dof": int(ARM_DOF),
        "action_dim": int(ACTION_DIM),
        "active_arm": active_arm,
        "final_q_by_arm": signed_final_q_by_arm,
        "locked_arm_joints": (
            {"J8": LOCKED_J8_VALUE_RAD}
            if LOCKED_J8_INDEX is not None
            else {}
        ),
        "start_state": start_state,
        "parameters": {
            "back_m": float(back_m),
            "reset_tool_roll_at_start": True,
        },
        "tracking": {
            "start_arm_tolerance_rad": DEFAULT_START_ARM_TOLERANCE_RAD,
            "start_trunk_tolerance_rad": DEFAULT_START_TRUNK_TOLERANCE_RAD,
            "start_gripper_tolerance_rad": (
                DEFAULT_START_GRIPPER_TOLERANCE_RAD
            ),
            "stationary_qvel_tolerance_rad_s": 0.35,
            "settle_tolerance_rad": DEFAULT_WAYPOINT_SETTLE_TOLERANCE_RAD,
            "max_tracking_error_rad": DEFAULT_WAYPOINT_MAX_TRACKING_ERROR_RAD,
            "waypoint_timeout_s": DEFAULT_WAYPOINT_TIMEOUT_S,
            "stall_steps": DEFAULT_TRACKING_STALL_STEPS,
        },
        "segments": segments,
        "safety_validation": {
            "status": "conditional",
            "joint_limits_checked": True,
            "joint_limit_numeric_tolerance_rad": (
                TRAJECTORY_JOINT_LIMIT_NUMERIC_TOLERANCE_RAD
            ),
            "joint_limit_normalizations": joint_limit_normalizations,
            "captured_start_joint_limits_enforced": False,
            "captured_start_recovered_to_local_limits": (
                captured_start_recovered
            ),
            "local_fk_finite_checked": True,
            "safe_final_pair_validated_by_planner": True,
            "frozen_rgbd_collision_checked": False,
            "self_collision_checked": False,
            "runtime_may_recompute_kinematics": False,
        },
    }
    final_q_validation_by_arm = {
        active_arm: {
            "source": "signed_active_trajectory_endpoint",
            "planned_arm": active_arm,
            "execution_arm": active_arm,
            "arm_switched": False,
            "pair_pos_err_m": 0.0,
            "pair_ori_err_deg": 0.0,
            "submission_local_fk_checked": True,
            "j8_locked": LOCKED_J8_INDEX is not None,
        }
    }
    for side, raw_q in signed_final_q_by_arm.items():
        if side == active_arm:
            continue
        validated_q, validation = _validate_exec_final_q_for_arm(
            trajectory=trajectory,
            arm=side,
            raw_q=raw_q,
            source="planner_selected_pose_ik_q",
        )
        signed_final_q_by_arm[side] = validated_q.astype(float).tolist()
        final_q_validation_by_arm[side] = validation
    trajectory["final_q_validation_by_arm"] = final_q_validation_by_arm
    trajectory["integrity"] = {
        "algorithm": "hmac-sha256",
        "digest": _trajectory_digest(trajectory),
    }
    return trajectory


def _reject_duplicate_json_keys(pairs):
    payload = {}
    for key, value in pairs:
        if key in payload:
            raise ValueError(f"duplicate JSON key {key!r}")
        payload[key] = value
    return payload


def _load_plan_trajectory(
    session_id: str,
    plan_id: str,
    *,
    include_record: bool = False,
):
    path = _plan_record_path(session_id, plan_id)
    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    descriptor = os.open(path, flags)
    try:
        stat = os.fstat(descriptor)
        if stat.st_size <= 0 or stat.st_size > MAX_PLAN_RECORD_BYTES:
            raise ValueError(
                f"plan record size must be in 1..{MAX_PLAN_RECORD_BYTES} bytes"
            )
        raw = os.read(descriptor, stat.st_size + 1)
    finally:
        os.close(descriptor)
    if len(raw) != stat.st_size:
        raise ValueError("plan record changed while it was being read")
    record = json.loads(
        raw.decode("utf-8"),
        object_pairs_hook=_reject_duplicate_json_keys,
        parse_constant=lambda value: (_ for _ in ()).throw(
            ValueError(f"non-standard JSON constant {value!r}")
        ),
    )
    if not isinstance(record, dict):
        raise ValueError("plan record must be a JSON object")
    if str(record.get("plan_id")) != str(plan_id):
        raise ValueError("plan record plan_id does not match the request")
    if str(record.get("session_id")) != str(session_id):
        raise ValueError("plan record session_id does not match the request")
    record_tool = str(record.get("tool") or "")
    supported_source_tools = {
        "plan_grasp_point_filter_rgbd_lite",
        "move_tracked_point",
    }
    if record_tool not in supported_source_tools:
        raise ValueError(
            "plan record was not created by a supported official_v2 planner"
        )

    trajectory = record.get("trajectory")
    if not isinstance(trajectory, dict):
        raise ValueError(
            "plan record has no immutable joint trajectory; re-plan with official_v2"
        )
    expected_scalars = {
        "schema": JOINT_TRAJECTORY_SCHEMA,
        "schema_version": JOINT_TRAJECTORY_SCHEMA_VERSION,
        "plan_id": str(plan_id),
        "session_id": str(session_id),
        "tool_version": TOOL_VERSION,
        "source_tool": record_tool,
        "robot_profile": ROBOT_PROFILE,
        "arm_dof": int(ARM_DOF),
        "action_dim": int(ACTION_DIM),
    }
    for key, expected in expected_scalars.items():
        if trajectory.get(key) != expected:
            raise ValueError(
                f"trajectory {key}={trajectory.get(key)!r} "
                f"does not match {expected!r}"
            )
    active_arm = str(trajectory.get("active_arm", "")).strip().lower()
    if active_arm not in ("left", "right"):
        raise ValueError("trajectory active_arm is invalid")
    if not str(trajectory.get("source_image_id", "")).strip():
        raise ValueError("trajectory source_image_id is missing")
    expected_locked_joints = (
        {"J8": LOCKED_J8_VALUE_RAD}
        if LOCKED_J8_INDEX is not None
        else {}
    )
    if trajectory.get("locked_arm_joints") != expected_locked_joints:
        raise ValueError("trajectory locked-arm-joint contract is invalid")

    integrity = trajectory.get("integrity")
    if (
        not isinstance(integrity, dict)
        or integrity.get("algorithm") != "hmac-sha256"
    ):
        raise ValueError("trajectory integrity metadata is invalid")
    expected_digest = _trajectory_digest(trajectory)
    if not hmac.compare_digest(
        str(integrity.get("digest", "")),
        expected_digest,
    ):
        raise ValueError("trajectory digest mismatch")

    if record_tool == "move_tracked_point":
        move_source = record.get("move_tracked_trajectory")
        if not isinstance(move_source, dict):
            raise ValueError("move-tracked source trajectory is missing; re-plan")
        source_digest = str((move_source.get("integrity") or {}).get("digest", ""))
        bound_digest = str((trajectory.get("safety_validation") or {}).get(
            "source_move_trajectory_digest", ""
        ))
        if not (hmac.compare_digest(source_digest, _trajectory_digest(move_source))
                and hmac.compare_digest(source_digest, bound_digest)):
            raise ValueError("move-tracked source trajectory digest mismatch")
        _validate_move_tracked_endpoint_order(move_source["target"])

    safety = trajectory.get("safety_validation")
    if not isinstance(safety, dict):
        raise ValueError("trajectory safety_validation is missing")
    required_checks = (
        "joint_limits_checked",
        "local_fk_finite_checked",
        "safe_final_pair_validated_by_planner",
    )
    if not all(safety.get(key) is True for key in required_checks):
        raise ValueError("trajectory planner safety validation is incomplete")
    if safety.get("runtime_may_recompute_kinematics") is not False:
        raise ValueError("trajectory permits forbidden runtime kinematics")

    start_state = trajectory.get("start_state")
    if not isinstance(start_state, dict):
        raise ValueError("trajectory start_state is missing")
    motion_epoch = start_state.get("motion_epoch")
    if not isinstance(motion_epoch, int) or motion_epoch < 0:
        raise ValueError("trajectory motion_epoch is invalid")
    if not str(start_state.get("episode_id", "")).strip():
        raise ValueError("trajectory episode_id is invalid")
    arm_qpos = start_state.get("arm_qpos")
    arm_qvel = start_state.get("arm_qvel")
    if not isinstance(arm_qpos, dict) or not isinstance(arm_qvel, dict):
        raise ValueError("trajectory start arm proprioception is invalid")
    for side in ("left", "right"):
        _require_serialized_j8_zero(
            arm_qpos.get(side),
            label=f"start {side} arm_qpos",
        )
        _arm_vector(arm_qvel.get(side), label=f"start {side} arm_qvel")
    gripper_qpos = start_state.get("gripper_qpos")
    if not isinstance(gripper_qpos, dict):
        raise ValueError("trajectory start gripper proprioception is invalid")
    for side in ("left", "right"):
        gripper = np.asarray(
            gripper_qpos.get(side),
            dtype=np.float64,
        ).reshape(-1)
        if gripper.size == 0 or not np.all(np.isfinite(gripper)):
            raise ValueError(
                f"trajectory start {side} gripper_qpos is invalid"
            )
    trunk = np.asarray(start_state.get("trunk_qpos"), dtype=np.float64).reshape(-1)
    if trunk.size != 4 or not np.all(np.isfinite(trunk)):
        raise ValueError("trajectory start trunk_qpos is invalid")

    parameters = trajectory.get("parameters")
    tracking = trajectory.get("tracking")
    if not isinstance(parameters, dict) or not isinstance(tracking, dict):
        raise ValueError("trajectory parameters or tracking metadata is missing")
    back_m = float(parameters.get("back_m"))
    if not math.isfinite(back_m) or back_m < 0.0:
        raise ValueError("trajectory back_m is invalid")
    if not isinstance(parameters.get("reset_tool_roll_at_start"), bool):
        raise ValueError("trajectory tool-roll parameter is invalid")
    for key in (
        "start_arm_tolerance_rad",
        "start_trunk_tolerance_rad",
        "start_gripper_tolerance_rad",
        "stationary_qvel_tolerance_rad_s",
        "settle_tolerance_rad",
        "max_tracking_error_rad",
        "waypoint_timeout_s",
        "stall_steps",
    ):
        value = float(tracking.get(key))
        if not math.isfinite(value) or value <= 0.0:
            raise ValueError(f"trajectory tracking field {key} is invalid")
    raw_trunk_assisted = tracking.get("trunk_assisted", False)
    if not isinstance(raw_trunk_assisted, bool):
        raise ValueError("trajectory trunk-assisted flag is invalid")
    if raw_trunk_assisted:
        raise ValueError(
            "exec_plan_pose accepts arm-only plans; re-plan this legacy "
            "whole-body move-tracked target"
        )
    # 已签名 start trunk 只收 1e-6 残差；不要改磁盘 JSON，HMAC 仍对原字节。
    trunk = _require_signed_trunk_q(
        trunk,
        label="trajectory start trunk_qpos",
        point="signed_start_trunk",
    )
    if trajectory.get("final_trunk_q") is not None:
        raise ValueError("arm-only trajectory contains a final trunk target")

    segments = trajectory.get("segments")
    expected_names = (
        "tool_roll_reset",
        "current_to_safe",
        "safe_to_final",
    )
    if (
        not isinstance(segments, list)
        or len(segments) != len(expected_names)
        or not all(isinstance(segment, dict) for segment in segments)
        or tuple(str(segment.get("name", "")) for segment in segments)
        != expected_names
    ):
        raise ValueError("trajectory segment order is invalid")
    waypoint_count = 0
    limits = _ARM_LIMITS[active_arm][:ARM_DOF]
    previous_q = _require_serialized_j8_zero(
        start_state["arm_qpos"][active_arm],
        label="trajectory start arm_qpos",
    )
    for segment in segments:
        waypoints = segment.get("waypoints")
        if not isinstance(waypoints, list) or not waypoints:
            raise ValueError(f"trajectory segment {segment['name']} is empty")
        endpoint_q = _require_serialized_j8_zero(
            segment.get("endpoint_q"),
            label=f"trajectory {segment['name']} endpoint_q",
        )
        if (
            segment.get("trunk_waypoints") is not None
            or segment.get("endpoint_trunk_q") is not None
        ):
            raise ValueError("arm-only trajectory segment contains trunk motion")
        for raw_q in waypoints:
            q = _require_serialized_j8_zero(
                raw_q,
                label=f"trajectory {segment['name']} waypoint",
            )
            if np.any(q < limits[:, 0]) or np.any(q > limits[:, 1]):
                raise ValueError("trajectory waypoint exceeds arm joint limits")
            if (
                float(np.linalg.norm(q - previous_q, ord=np.inf))
                > DEFAULT_TRAJECTORY_STEP_RAD
                + TRAJECTORY_STEP_VALIDATION_EPS_RAD
            ):
                raise ValueError("trajectory waypoint step exceeds the compiled limit")
            previous_q = q
            waypoint_count += 1
        if not np.allclose(
            previous_q,
            endpoint_q,
            rtol=0.0,
            atol=LOCKED_J8_SERIALIZED_TOLERANCE_RAD,
        ):
            raise ValueError(
                f"trajectory {segment['name']} endpoint does not match its last waypoint"
            )
    if waypoint_count > MAX_TRAJECTORY_WAYPOINTS:
        raise ValueError("trajectory contains too many waypoints")
    final_q_by_arm = trajectory.get("final_q_by_arm")
    if final_q_by_arm is not None:
        if (
            not isinstance(final_q_by_arm, dict)
            or active_arm not in final_q_by_arm
            or any(side not in ("left", "right") for side in final_q_by_arm)
        ):
            raise ValueError("trajectory final_q_by_arm contract is invalid")
        active_final_q = _require_serialized_j8_zero(
            final_q_by_arm[active_arm],
            label=f"signed {active_arm} final_q_by_arm",
        )
        if not np.allclose(
            active_final_q,
            trajectory["segments"][2]["endpoint_q"],
            rtol=0.0,
            atol=LOCKED_J8_SERIALIZED_TOLERANCE_RAD,
        ):
            raise ValueError(
                "trajectory active final_q_by_arm does not match final endpoint"
            )
        for side, raw_q in final_q_by_arm.items():
            if side == active_arm:
                continue
            validated_q, _validation = _validate_exec_final_q_for_arm(
                trajectory=trajectory,
                arm=side,
                raw_q=raw_q,
                source="signed_final_q_by_arm",
            )
            if not np.allclose(
                validated_q,
                raw_q,
                rtol=0.0,
                atol=LOCKED_J8_SERIALIZED_TOLERANCE_RAD,
            ):
                raise ValueError(
                    f"trajectory {side} final_q_by_arm requires normalization"
                )
    if include_record:
        return trajectory, path, record
    return trajectory, path


def _stored_record_final_q_for_arm(
    record: dict[str, Any],
    arm: str,
) -> tuple[Any, str] | tuple[None, None]:
    """Find the plan-filter final IK branch using the same v2 record fields."""
    payload = record.get("payload")
    if not isinstance(payload, dict):
        return None, None
    locations: list[tuple[str, dict[str, Any]]] = [("payload", payload)]
    candidates = payload.get("candidates")
    if isinstance(candidates, list) and candidates and isinstance(candidates[0], dict):
        candidate = candidates[0]
        locations.append(("payload.candidates[0]", candidate))
        candidate_meta = candidate.get("meta")
        if isinstance(candidate_meta, dict):
            locations.append(("payload.candidates[0].meta", candidate_meta))
    plan_audit = payload.get("plan_audit")
    if isinstance(plan_audit, dict):
        locations.append(("payload.plan_audit", plan_audit))
        pick = plan_audit.get("pick")
        if isinstance(pick, dict):
            locations.append(("payload.plan_audit.pick", pick))

    for location_name, location in locations:
        q_map = location.get("selected_pose_ik_q")
        if isinstance(q_map, dict) and q_map.get(arm) is not None:
            return q_map[arm], f"{location_name}.selected_pose_ik_q"
        ik_summary = location.get("selected_pose_ik")
        if isinstance(ik_summary, dict):
            raw_q = ik_summary.get(f"{arm}_q_arm")
            if raw_q is None and str(location.get("arm", "")) == arm:
                raw_q = ik_summary.get("q_arm")
            if raw_q is not None:
                return raw_q, f"{location_name}.selected_pose_ik"
        ik_filter = location.get("ik_filter")
        if isinstance(ik_filter, dict):
            arm_info = ik_filter.get(arm)
            if isinstance(arm_info, dict) and arm_info.get("q_arm") is not None:
                return arm_info["q_arm"], f"{location_name}.ik_filter"
    return None, None


def _resolve_exec_final_q(
    *,
    trajectory: dict[str, Any],
    record: dict[str, Any],
    execution_arm: str,
) -> tuple[np.ndarray, dict[str, Any]]:
    planned_arm = str(trajectory["active_arm"])
    if execution_arm == planned_arm:
        final_q = _require_serialized_j8_zero(
            trajectory["segments"][2]["endpoint_q"],
            label=f"signed {planned_arm} final endpoint_q",
        )
        return final_q, {
            "source": "signed_active_trajectory_endpoint",
            "planned_arm": planned_arm,
            "execution_arm": execution_arm,
            "arm_switched": False,
            "submission_local_fk_checked": True,
            "j8_locked": LOCKED_J8_INDEX is not None,
        }

    signed_by_arm = trajectory.get("final_q_by_arm")
    if isinstance(signed_by_arm, dict) and signed_by_arm.get(execution_arm) is not None:
        raw_q = signed_by_arm[execution_arm]
        source = "signed_final_q_by_arm"
    else:
        raw_q, record_location = _stored_record_final_q_for_arm(
            record,
            execution_arm,
        )
        if raw_q is None:
            raise ValueError(
                f"plan has no stored final joint solution for requested arm "
                f"{execution_arm!r}"
            )
        source = f"legacy_plan_record_locally_verified:{record_location}"

    return _validate_exec_final_q_for_arm(
        trajectory=trajectory,
        arm=execution_arm,
        raw_q=raw_q,
        source=source,
    )


def _prepare_exec_segments(
    *,
    trajectory: dict[str, Any],
    current_q: np.ndarray,
    current_trunk: np.ndarray,
    stop_after_safe: bool,
    execution_arm: str | None = None,
    runtime_safe_q: np.ndarray | None = None,
    runtime_final_q: np.ndarray | None = None,
    back_m_resolution: dict[str, Any] | None = None,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Build a fresh observed-start bridge to the signed safe pose."""
    active_arm = str(execution_arm or trajectory["active_arm"])
    start_state = dict(trajectory["start_state"])
    observed_q = _j8_locked_copy(
        current_q,
        label=f"current {active_arm} arm_qpos",
    )
    planned_start = _require_serialized_j8_zero(
        start_state["arm_qpos"][active_arm],
        label=f"planned {active_arm} arm_qpos",
    )
    limits = _ARM_LIMITS[active_arm][:ARM_DOF]
    if runtime_safe_q is None and active_arm != str(trajectory["active_arm"]):
        raise ValueError("arm-switched execution requires a locally resolved safe_q")
    start_error = float(np.linalg.norm(observed_q - planned_start, ord=np.inf))
    safe_q = (
        _require_serialized_j8_zero(
            trajectory["segments"][1]["endpoint_q"],
            label="signed safe endpoint_q",
        )
        if runtime_safe_q is None
        else _j8_locked_copy(
            runtime_safe_q,
            label="runtime replanned safe endpoint_q",
        )
    )
    bridge_waypoints = _interpolate_joint_segment(observed_q, safe_q)
    if runtime_safe_q is None and runtime_final_q is None:
        final_segment = trajectory["segments"][2]
    else:
        final_q = _require_serialized_j8_zero(
            (
                trajectory["segments"][2]["endpoint_q"]
                if runtime_final_q is None
                else runtime_final_q
            ),
            label=f"resolved {active_arm} final endpoint_q",
        )
        if np.any(final_q < limits[:, 0]) or np.any(final_q > limits[:, 1]):
            raise ValueError("resolved final_q exceeds local arm joint limits")
        final_segment = {
            "name": "safe_to_final",
            "waypoints": _interpolate_joint_segment(safe_q, final_q),
            "endpoint_q": final_q.astype(float).tolist(),
        }
    signed_final_count = (
        0 if stop_after_safe else len(final_segment["waypoints"])
    )
    if len(bridge_waypoints) + signed_final_count > MAX_TRAJECTORY_WAYPOINTS:
        raise ValueError("runtime bridge produces too many waypoints")

    def local_limit_violation(q: np.ndarray) -> np.ndarray:
        return np.maximum(
            np.maximum(limits[:, 0] - q, q - limits[:, 1]),
            0.0,
        )

    observed_limit_violation = local_limit_violation(observed_q)
    previous_limit_violation = observed_limit_violation
    previous_q = observed_q
    previous_remaining = np.abs(safe_q - observed_q)
    envelope_lower = np.minimum(observed_q, safe_q)
    envelope_upper = np.maximum(observed_q, safe_q)
    fk_samples = [observed_q]
    for raw_q in bridge_waypoints:
        q = _require_serialized_j8_zero(
            raw_q,
            label="runtime current_to_safe waypoint",
        )
        step = float(np.linalg.norm(q - previous_q, ord=np.inf))
        if step > DEFAULT_TRAJECTORY_STEP_RAD + TRAJECTORY_STEP_VALIDATION_EPS_RAD:
            raise ValueError("runtime current-to-safe bridge exceeds the step limit")
        if np.any(q < envelope_lower - TRAJECTORY_STEP_VALIDATION_EPS_RAD) or np.any(
            q > envelope_upper + TRAJECTORY_STEP_VALIDATION_EPS_RAD
        ):
            raise ValueError("runtime current-to-safe bridge leaves its endpoint envelope")
        remaining = np.abs(safe_q - q)
        if np.any(
            remaining
            > previous_remaining + TRAJECTORY_STEP_VALIDATION_EPS_RAD
        ):
            raise ValueError("runtime current-to-safe bridge does not move toward safe_q")
        limit_violation = local_limit_violation(q)
        if np.any(
            limit_violation
            > previous_limit_violation + TRAJECTORY_STEP_VALIDATION_EPS_RAD
        ):
            raise ValueError(
                "runtime current-to-safe bridge moves farther outside local joint limits"
            )
        fk_samples.append(q)
        previous_q = q
        previous_remaining = remaining
        previous_limit_violation = limit_violation
    if not np.allclose(
        previous_q,
        safe_q,
        rtol=0.0,
        atol=LOCKED_J8_SERIALIZED_TOLERANCE_RAD,
    ):
        raise ValueError("runtime current-to-safe bridge does not end at safe_q")
    for q in fk_samples:
        position, rotation = _r1pro_arm_fk_robot(
            active_arm,
            current_trunk,
            q,
        )
        if not np.all(np.isfinite(position)) or not np.all(np.isfinite(rotation)):
            raise ValueError("runtime bridge local FK produced a non-finite pose")

    prepared_segments = [
        {
            "name": "runtime_current_to_safe",
            "waypoints": bridge_waypoints,
            "endpoint_q": safe_q.astype(float).tolist(),
        }
    ]
    if not stop_after_safe:
        prepared_segments.append(final_segment)
        if runtime_safe_q is not None:
            fk_samples.extend(
                _require_serialized_j8_zero(
                    raw_q,
                    label="runtime safe_to_final waypoint",
                )
                for raw_q in final_segment["waypoints"]
            )
            for q in fk_samples[len(bridge_waypoints) + 1 :]:
                position, rotation = _r1pro_arm_fk_robot(
                    active_arm,
                    current_trunk,
                    q,
                )
                if not np.all(np.isfinite(position)) or not np.all(
                    np.isfinite(rotation)
                ):
                    raise ValueError(
                        "runtime safe-to-final local FK produced a non-finite pose"
                    )
    outside_joint_indices = np.flatnonzero(
        observed_limit_violation
        > TRAJECTORY_JOINT_LIMIT_NUMERIC_TOLERANCE_RAD
    )
    return prepared_segments, {
        "mode": "fresh_current_to_safe",
        "planned_start_error_rad": start_error,
        "start_source": "evaluator_proprioception",
        "signed_prefix_replay": False,
        "signed_waypoint_resume": False,
        "runtime_bridge": {
            "waypoint_count": int(len(bridge_waypoints)),
            "current_start_joint_limits_enforced": False,
            "current_start_within_local_limits": not bool(
                outside_joint_indices.size
            ),
            "current_start_max_local_limit_violation_rad": float(
                np.max(observed_limit_violation)
            ),
            "current_start_outside_local_limit_joints": [
                f"J{int(index) + 1}" for index in outside_joint_indices
            ],
            "signed_safe_joint_limits_checked": True,
            "endpoint_envelope_checked": True,
            "monotonic_to_safe_checked": True,
            "monotonic_local_limit_recovery_checked": True,
            "max_step_checked": True,
            "local_fk_finite_checked": True,
            "j8_locked": LOCKED_J8_INDEX is not None,
            "frozen_rgbd_collision_checked": False,
            "self_collision_checked": False,
            "safe_to_final_recomputed": (
                runtime_safe_q is not None or runtime_final_q is not None
            ),
            "final_arm_trajectory_recomputed": runtime_final_q is not None,
        },
        "back_m_resolution": _json_ready(back_m_resolution or {}),
    }


def _exec_safe_back_m_candidates(
    requested_back_m: float,
    *,
    fallback_back_m: float | None = None,
) -> list[float]:
    """Match v2's stored-final safe retreat search order."""
    requested = float(
        np.clip(
            float(requested_back_m),
            EXEC_SAFE_BACK_MIN_M,
            EXEC_SAFE_BACK_MAX_M,
        )
    )
    values = [requested]
    requested_cm = int(round(requested * 100.0))
    values.extend(
        centimetres / 100.0
        for centimetres in sorted(
            range(5, int(EXEC_SAFE_BACK_MAX_M * 100.0) + 1),
            key=lambda value: (
                abs(value - requested_cm),
                value > requested_cm,
                abs(value),
            ),
        )
    )
    if fallback_back_m is not None and math.isfinite(float(fallback_back_m)):
        values.append(
            float(
                np.clip(
                    float(fallback_back_m),
                    EXEC_SAFE_BACK_MIN_M,
                    EXEC_SAFE_BACK_MAX_M,
                )
            )
        )
    result: list[float] = []
    for value in values:
        if all(abs(float(value) - old) > 1e-4 for old in result):
            result.append(float(value))
    return result


def _recompute_exec_safe_q(
    *,
    ctx,
    execution_arm: str,
    final_q: np.ndarray,
    current_arms: dict[str, np.ndarray],
    current_trunk: np.ndarray,
    current_grippers: dict[str, np.ndarray],
    requested_back_m: float,
    fallback_back_m: float | None,
    final_q_source: str,
) -> tuple[np.ndarray, dict[str, Any]]:
    """Re-solve a requested safe retreat from signed final-q and observations."""
    active_arm = str(execution_arm).strip().lower()
    if active_arm not in ("left", "right"):
        raise ValueError("execution arm must be left or right")
    final_q = _require_serialized_j8_zero(
        final_q,
        label=f"resolved {active_arm} final endpoint_q",
    )
    ik_arms = {
        side: np.asarray(current_arms[side], dtype=np.float64).copy()
        for side in ("left", "right")
    }
    # The observed arm remains the source of the action bridge.  Use the
    # signed, in-limit final branch as the local solver retract so a measured
    # start just outside static limits cannot block back_m recomputation.
    ik_arms[active_arm] = final_q.copy()
    state = local_robot_state(
        trunk_q=current_trunk,
        arm_left_q=ik_arms["left"],
        arm_right_q=ik_arms["right"],
        gripper_left_q=current_grippers["left"],
        gripper_right_q=current_grippers["right"],
    )
    final_position, final_quaternion = _local_eef_pose(
        state,
        active_arm,
        final_q,
    )
    pointing = _quat_to_mat_xyzw(final_quaternion)[:, 2]
    pointing /= max(float(np.linalg.norm(pointing)), 1e-12)
    candidates = _exec_safe_back_m_candidates(
        requested_back_m,
        fallback_back_m=fallback_back_m,
    )

    if candidates and abs(float(candidates[0])) <= 1e-6:
        return final_q.copy(), {
            "mode": "runtime_local_safe_replan",
            "requested_back_m": float(requested_back_m),
            "active_back_m": 0.0,
            "back_m_adapted": abs(float(requested_back_m)) > 1e-4,
            "candidate_index": 0,
            "candidate_count": int(len(candidates)),
            "solver": "signed_final_q_as_zero_back_safe",
            "final_pose_source": str(final_q_source),
            "ik_retract_source": "signed_final_q",
            "safe_endpoint_local_fk_checked": True,
            "safe_to_final_joint_gap_rad": 0.0,
            "safe_final_branch_gap_soft": False,
            "j8_locked": LOCKED_J8_INDEX is not None,
        }

    poses = [
        {
            "eef_pos": (
                final_position - float(back_m) * pointing
            ).astype(float).tolist(),
            "quat": np.asarray(
                final_quaternion,
                dtype=np.float64,
            ).astype(float).tolist(),
            "ik_warm_start_q_by_arm": {
                active_arm: final_q.astype(float).tolist()
            },
        }
        for back_m in candidates
    ]
    _check_cancelled(ctx, "exec_plan_pose local back_m IK")
    try:
        left_results, right_results, worker_meta = _run_external_ik(
            state,
            poses,
            pos_tol_m=EXEC_SAFE_POS_TOL_M,
            ori_tol_deg=EXEC_SAFE_ORI_TOL_DEG,
            active_arms=(active_arm,),
            ctx=ctx,
        )
    except Exception as exc:
        raise ValueError(
            "submission-local safe IK worker failed before action: "
            f"{type(exc).__name__}: {exc}"
        ) from exc
    arm_results = left_results if active_arm == "left" else right_results
    if len(arm_results) != len(candidates):
        raise ValueError(
            "local safe IK worker returned an incomplete candidate batch"
        )

    attempts: list[dict[str, Any]] = []
    for candidate_index, (back_m, info) in enumerate(
        zip(candidates, arm_results)
    ):
        attempt = {
            "candidate_index": int(candidate_index),
            "back_m": float(back_m),
            "solver_ok": bool(info.get("ok")),
            "worker_pos_err_m": _json_ready(info.get("pos_err_m")),
            "worker_ori_err_deg": _json_ready(info.get("ori_err_deg")),
            "error": info.get("error"),
        }
        raw_q = info.get("q_arm")
        if not bool(info.get("ok")) or raw_q is None:
            attempts.append(attempt)
            continue
        try:
            safe_q = _j8_locked_copy(
                raw_q,
                label=f"runtime safe IK candidate {candidate_index}",
            )
            safe_q, normalizations = _normalize_arm_q_to_joint_limits(
                safe_q,
                arm=active_arm,
                label=f"runtime safe IK candidate {candidate_index}",
                point="runtime_safe_q",
            )
            actual_position, actual_quaternion = _local_eef_pose(
                state,
                active_arm,
                safe_q,
            )
            target_position = np.asarray(
                poses[candidate_index]["eef_pos"],
                dtype=np.float64,
            )
            position_error = float(
                np.linalg.norm(actual_position - target_position)
            )
            orientation_error = float(
                orientation_error_deg(
                    actual_quaternion,
                    final_quaternion,
                )
            )
            if (
                position_error > EXEC_SAFE_POS_TOL_M
                or orientation_error > EXEC_SAFE_ORI_TOL_DEG
            ):
                attempt.update(
                    {
                        "error": "safe_endpoint_local_fk_failed",
                        "local_fk_pos_err_m": position_error,
                        "local_fk_ori_err_deg": orientation_error,
                    }
                )
                attempts.append(attempt)
                continue
        except (TypeError, ValueError) as exc:
            attempt["error"] = str(exc)
            attempts.append(attempt)
            continue

        branch_gap = float(np.linalg.norm(safe_q - final_q, ord=np.inf))
        attempt.update(
            {
                "accepted": True,
                "local_fk_pos_err_m": position_error,
                "local_fk_ori_err_deg": orientation_error,
                "safe_to_final_joint_gap_rad": branch_gap,
            }
        )
        attempts.append(attempt)
        return safe_q, {
            "mode": "runtime_local_safe_replan",
            "requested_back_m": float(requested_back_m),
            "active_back_m": float(back_m),
            "back_m_adapted": abs(
                float(back_m) - float(requested_back_m)
            )
            > 1e-4,
            "candidate_index": int(candidate_index),
            "candidate_count": int(len(candidates)),
            "attempts": attempts,
            "solver": "submission_local_curobo_gpu_worker",
            "worker": _json_ready(worker_meta),
            "final_pose_source": str(final_q_source),
            "ik_retract_source": "signed_final_q",
            "safe_endpoint_local_fk_checked": True,
            "safe_endpoint_pos_err_m": position_error,
            "safe_endpoint_ori_err_deg": orientation_error,
            "safe_to_final_joint_gap_rad": branch_gap,
            "safe_final_branch_gap_soft": bool(
                branch_gap > EXEC_SAFE_FINAL_BRANCH_GAP_RAD
            ),
            "joint_limit_normalizations": normalizations,
            "j8_locked": LOCKED_J8_INDEX is not None,
        }

    attempted = ", ".join(f"{value:.2f}" for value in candidates)
    raise ValueError(
        "no locally feasible safe pose for requested "
        f"back_m={float(requested_back_m):.3f}m; tried [{attempted}]"
    )


def _image_path(session_id: str, image_id: str, suffix: str) -> str:
    return os.path.join(_images_dir(session_id), f"{image_id}{suffix}")


def _image_meta_path(session_id: str, image_id: str) -> str:
    return _image_path(session_id, image_id, ".meta.json")


def _save_image_meta(
    session_id: str,
    image_id: str,
    meta: dict[str, Any],
) -> None:
    with open(
        _image_meta_path(session_id, image_id),
        "w",
        encoding="utf-8",
    ) as stream:
        json.dump(meta, stream, indent=2, ensure_ascii=False)


def _load_image_meta(session_id: str, image_id: str) -> dict[str, Any]:
    path = _image_meta_path(session_id, image_id)
    if not os.path.isfile(path):
        raise FileNotFoundError(
            f"image metadata does not exist: {session_id}/{image_id}"
        )
    with open(path, encoding="utf-8") as stream:
        return json.load(stream)


def _policy_owned_capture_artifact(
    session_id: str,
    artifact: Any,
) -> str:
    name = str(artifact or "").strip()
    if not name:
        raise ValueError("capture has no depth_linear artifact")
    image_dir = os.path.realpath(_images_dir(session_id))
    candidate = os.path.realpath(
        name if os.path.isabs(name) else os.path.join(image_dir, name)
    )
    try:
        inside_image_dir = os.path.commonpath([image_dir, candidate]) == image_dir
    except ValueError:
        inside_image_dir = False
    if not inside_image_dir:
        raise ValueError(
            "depth_linear artifact is outside policy-owned capture storage"
        )
    return candidate


def _frozen_depth_for_read(
    session_id: str,
    image_id: str,
) -> tuple[np.ndarray, dict[str, Any]]:
    meta = _load_image_meta(session_id, image_id)
    if not isinstance(meta, dict):
        raise ValueError("capture metadata must be an object")
    modalities = meta.get("modalities") or {}
    if not isinstance(modalities, dict):
        raise ValueError("capture modalities metadata must be an object")
    depth_path = _policy_owned_capture_artifact(
        session_id,
        modalities.get("depth_linear"),
    )
    try:
        raw = np.load(depth_path, allow_pickle=False)
    except (OSError, ValueError) as exc:
        raise ValueError(f"cannot load frozen depth_linear artifact: {exc}") from exc
    if raw.ndim == 2:
        depth = raw
    elif raw.ndim == 3 and raw.shape[-1] == 1:
        depth = raw[..., 0]
    else:
        raise ValueError(
            f"depth_linear must be HxW or HxWx1, got shape {raw.shape}"
        )
    camera = meta.get("camera") or {}
    if not isinstance(camera, dict):
        raise ValueError("capture camera metadata must be an object")
    return np.asarray(depth), dict(camera)


def _file_to_data_url(path: str, mime: str = "image/png") -> str | None:
    if not path or not os.path.isfile(path):
        return None
    with open(path, "rb") as stream:
        encoded = base64.b64encode(stream.read()).decode("ascii")
    return f"data:{mime};base64,{encoded}"


def _stamp_selected_minimap_on_bgr(image_bgr: np.ndarray) -> np.ndarray:
    """Keep tool-owned captures independent of process-global map renderers.

    The interface display layer may decorate its own copy with a minimap.  An
    official-v2 tool capture must remain inside this package and may only use
    its evaluator RGB-D/path overlay, so this hook deliberately preserves the
    local image unchanged.
    """

    image = np.asarray(image_bgr)
    if image.ndim != 3 or image.shape[2] != 3:
        raise ValueError("minimap display input must be an HxWx3 image")
    return image


def _camera_intrinsics(role: str, width: int, height: int) -> dict[str, Any]:
    if role == "head":
        fx = fy = 306.0 * float(width) / 720.0
    else:
        fx = fy = 388.6639 * float(width) / 480.0
    focal_length = 17.0
    horizontal_aperture = focal_length * float(width) / fx
    return {
        "image_width": int(width),
        "image_height": int(height),
        "focal_length": float(focal_length),
        "horizontal_aperture": float(horizontal_aperture),
        "fx": float(fx),
        "fy": float(fy),
        # The evaluator contract publishes K with principal point exactly at
        # (width / 2, height / 2), e.g. (360, 360) for the 720px head image.
        "cx": float(width) * 0.5,
        "cy": float(height) * 0.5,
    }


def _depth_visual(depth: np.ndarray) -> np.ndarray:
    arr = np.asarray(depth, dtype=np.float32).squeeze()
    valid = np.isfinite(arr) & (arr > 0.0)
    visual = np.zeros(arr.shape, dtype=np.uint8)
    if np.any(valid):
        lo, hi = np.percentile(arr[valid], [2.0, 98.0])
        if float(hi) <= float(lo):
            hi = float(lo) + 1e-6
        scaled = 255.0 * (np.clip(arr, lo, hi) - lo) / (hi - lo)
        visual[valid] = np.asarray(255.0 - scaled[valid], dtype=np.uint8)
    return cv2.applyColorMap(visual, cv2.COLORMAP_TURBO)


def _quat_to_mat_xyzw(quat) -> np.ndarray:
    x, y, z, w = np.asarray(quat, dtype=np.float64).reshape(4)
    norm = math.sqrt(x * x + y * y + z * z + w * w)
    if norm <= 1e-12:
        return np.eye(3, dtype=np.float64)
    x, y, z, w = x / norm, y / norm, z / norm, w / norm
    return np.array(
        [
            [1 - 2 * (y * y + z * z), 2 * (x * y - z * w), 2 * (x * z + y * w)],
            [2 * (x * y + z * w), 1 - 2 * (x * x + z * z), 2 * (y * z - x * w)],
            [2 * (x * z - y * w), 2 * (y * z + x * w), 1 - 2 * (x * x + y * y)],
        ],
        dtype=np.float64,
    )


def _axis_rotation(axis, angle: float) -> np.ndarray:
    vector = np.asarray(axis, dtype=np.float64).reshape(3)
    vector /= max(float(np.linalg.norm(vector)), 1e-12)
    x, y, z = vector
    c = math.cos(float(angle))
    s = math.sin(float(angle))
    one_c = 1.0 - c
    return np.array(
        [
            [c + x * x * one_c, x * y * one_c - z * s, x * z * one_c + y * s],
            [y * x * one_c + z * s, c + y * y * one_c, y * z * one_c - x * s],
            [z * x * one_c - y * s, z * y * one_c + x * s, c + z * z * one_c],
        ],
        dtype=np.float64,
    )


def _rotation_vector(rotation) -> np.ndarray:
    matrix = np.asarray(rotation, dtype=np.float64).reshape(3, 3)
    cosine = float(np.clip((np.trace(matrix) - 1.0) * 0.5, -1.0, 1.0))
    angle = math.acos(cosine)
    if angle <= 1e-9:
        return 0.5 * np.array(
            [
                matrix[2, 1] - matrix[1, 2],
                matrix[0, 2] - matrix[2, 0],
                matrix[1, 0] - matrix[0, 1],
            ],
            dtype=np.float64,
        )
    sine = math.sin(angle)
    if abs(sine) <= 1e-8:
        diagonal = np.maximum((np.diag(matrix) + 1.0) * 0.5, 0.0)
        axis = np.sqrt(diagonal)
        axis[0] = math.copysign(axis[0], matrix[2, 1] - matrix[1, 2])
        axis[1] = math.copysign(axis[1], matrix[0, 2] - matrix[2, 0])
        axis[2] = math.copysign(axis[2], matrix[1, 0] - matrix[0, 1])
        axis /= max(float(np.linalg.norm(axis)), 1e-12)
        return axis * angle
    axis = np.array(
        [
            matrix[2, 1] - matrix[1, 2],
            matrix[0, 2] - matrix[2, 0],
            matrix[1, 0] - matrix[0, 1],
        ],
        dtype=np.float64,
    ) / (2.0 * sine)
    return axis * angle


def _yaw_matrix(yaw: float) -> np.ndarray:
    c = math.cos(float(yaw))
    s = math.sin(float(yaw))
    return np.array(
        [
            [c, -s, 0.0],
            [s, c, 0.0],
            [0.0, 0.0, 1.0],
        ],
        dtype=np.float64,
    )


def _normalize_angle(angle: float) -> float:
    return math.atan2(math.sin(float(angle)), math.cos(float(angle)))


def _depth_points(
    depth,
    *,
    camera: dict[str, Any],
    stride: int = 6,
) -> np.ndarray:
    arr = np.asarray(depth, dtype=np.float32).squeeze()
    if arr.ndim != 2:
        raise ValueError(f"depth must be 2-D, got {arr.shape}")
    height, width = arr.shape
    step = max(1, int(stride))
    rows, cols = np.mgrid[0:height:step, 0:width:step]
    sampled = arr[::step, ::step]
    valid = np.isfinite(sampled) & (sampled > 1e-4)
    if not np.any(valid):
        return np.empty((0, 3), dtype=np.float64)
    z = sampled[valid].astype(np.float64)
    x = (cols[valid] - float(camera["cx"])) / float(camera["fx"]) * z
    y = -(rows[valid] - float(camera["cy"])) / float(camera["fy"]) * z
    points_camera = np.stack([x, y, -z], axis=1)
    position = np.asarray(camera["pos"], dtype=np.float64).reshape(3)
    rotation = _quat_to_mat_xyzw(camera["quat"])
    return position + (rotation @ points_camera.T).T


def _r1pro_arm_fk_robot(
    arm: str,
    trunk_q,
    arm_q,
) -> tuple[np.ndarray, np.ndarray]:
    side = str(arm).strip().lower()
    if side not in ("left", "right"):
        raise ValueError("arm must be left or right")
    q = np.asarray(arm_q, dtype=np.float64).reshape(-1)
    if q.size not in (7, 8):
        raise ValueError(f"arm qpos must have 7 or 8 values, got {q.size}")
    position, rotation = _r1pro_chest_pose_robot(trunk_q)
    position = position + rotation @ _ARM_BASE_ORIGINS[side]
    origins = _ARM_JOINT_ORIGINS[side]
    for index in range(q.size):
        position = position + rotation @ origins[index]
        rotation = rotation @ _axis_rotation(_ARM_AXES[index], float(q[index]))
    if q.size == 7:
        position = position + rotation @ origins[7]
    return position, rotation


def _solve_j567_keep_orientation(
    *,
    arm: str,
    trunk_q,
    fixed_arm_q,
    seed_arm_q,
    target_rotation,
    tolerance_deg: float = 2.0,
    max_iterations: int = 24,
) -> tuple[np.ndarray, dict[str, Any]]:
    side = str(arm).strip().lower()
    fixed = np.asarray(fixed_arm_q, dtype=np.float64).reshape(-1)
    seed = np.asarray(seed_arm_q, dtype=np.float64).reshape(-1)
    if fixed.size != ARM_DOF or seed.size != ARM_DOF:
        raise ValueError(
            f"{side} arm model requires {ARM_DOF} values, "
            f"got fixed={fixed.size} seed={seed.size}"
        )
    command = fixed.copy()
    command[4:7] = seed[4:7]
    if ARM_DOF == 8:
        command[7] = fixed[7]
    limits = _ARM_LIMITS[side][:ARM_DOF]
    target = np.asarray(target_rotation, dtype=np.float64).reshape(3, 3)
    residual = float("inf")
    iterations = 0
    for iterations in range(1, max(1, int(max_iterations)) + 1):
        _, current = _r1pro_arm_fk_robot(side, trunk_q, command)
        error = _rotation_vector(target @ current.T)
        residual = math.degrees(float(np.linalg.norm(error)))
        if residual <= float(tolerance_deg):
            break
        jacobian = np.zeros((3, 3), dtype=np.float64)
        epsilon = 1e-5
        for column, joint_index in enumerate(range(4, 7)):
            probe = command.copy()
            probe[joint_index] += epsilon
            _, rotation_plus = _r1pro_arm_fk_robot(side, trunk_q, probe)
            jacobian[:, column] = (
                _rotation_vector(rotation_plus @ current.T) / epsilon
            )
        damping = 2e-3
        lhs = jacobian @ jacobian.T + damping * np.eye(3)
        delta = jacobian.T @ np.linalg.solve(lhs, error)
        delta = np.clip(delta, -0.12, 0.12)
        command[4:7] = np.clip(
            command[4:7] + delta,
            limits[4:7, 0],
            limits[4:7, 1],
        )
        command[:4] = fixed[:4]
        if ARM_DOF == 8:
            command[7] = fixed[7]
    _, final_rotation = _r1pro_arm_fk_robot(side, trunk_q, command)
    residual = math.degrees(
        float(np.linalg.norm(_rotation_vector(target @ final_rotation.T)))
    )
    return command, {
        "ok": bool(residual <= float(tolerance_deg)),
        "residual_deg": float(residual),
        "iterations": int(iterations),
        "j1234_unchanged": bool(
            np.allclose(command[:4], fixed[:4], atol=1e-10)
        ),
        "j8_unchanged": bool(
            ARM_DOF != 8 or abs(float(command[7] - fixed[7])) <= 1e-10
        ),
    }


def _reach_trunk_action_overrides(
    trunk_command,
    keep_states: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    command = np.asarray(trunk_command, dtype=np.float64).reshape(4)
    overrides: dict[str, Any] = {"trunk": command.tolist()}
    for side, state in keep_states.items():
        arm_command, solve = _solve_j567_keep_orientation(
            arm=side,
            trunk_q=command,
            fixed_arm_q=state["fixed_q"],
            seed_arm_q=state["seed_q"],
            target_rotation=state["target_rotation"],
        )
        state["seed_q"] = arm_command
        state["all_solutions_ok"] = bool(
            state["all_solutions_ok"] and solve["ok"]
        )
        state["max_orientation_residual_deg"] = max(
            float(state["max_orientation_residual_deg"]),
            float(solve["residual_deg"]),
        )
        predicted_position, _ = _r1pro_arm_fk_robot(
            side,
            command,
            arm_command,
        )
        state["max_position_drift_m"] = max(
            float(state["max_position_drift_m"]),
            float(
                np.linalg.norm(
                    predicted_position - state["entry_position"]
                )
            ),
        )
        overrides[f"arm_{side}"] = arm_command.tolist()
    return overrides


def _reach_pre_lift_request(target_z: float, trunk_q) -> tuple[float, dict[str, Any]]:
    """Convert the v2 shoulder-height band into an adjust-height request."""
    start = np.asarray(trunk_q, dtype=np.float64).reshape(4)
    shoulders = _r1pro_shoulder_positions_robot(start)
    start_mid = 0.5 * (shoulders["left"] + shoulders["right"])
    start_dz = float(start_mid[2] - float(target_z))
    if abs(start_dz) <= REACH_PRE_LIFT_MAX_DZ_M:
        return 0.0, {
            "applied": False,
            "shoulder_z_before_m": float(start_mid[2]),
            "shoulder_z_after_m": float(start_mid[2]),
            "target_z_m": float(target_z),
            "dz_before_m": start_dz,
            "dz_after_m": start_dz,
            "requested_upward_m": 0.0,
            "planner": MOVE_TO_REACH_PRE_LIFT_IMPLEMENTATION_VERSION,
        }
    desired_z = float(target_z) + math.copysign(
        REACH_PRE_LIFT_MAX_DZ_M,
        start_dz,
    )
    requested_upward_m = float(desired_z - float(start_mid[2]))
    return requested_upward_m, {
        "applied": abs(requested_upward_m) > 1e-5,
        "shoulder_z_before_m": float(start_mid[2]),
        "desired_shoulder_z_m": float(desired_z),
        "target_z_m": float(target_z),
        "dz_before_m": start_dz,
        "requested_upward_m": requested_upward_m,
        "planner": MOVE_TO_REACH_PRE_LIFT_IMPLEMENTATION_VERSION,
    }


def _reach_chord_plan(
    target_policy_local,
    trunk_q,
    reach_m: float,
) -> dict[str, Any]:
    target = np.asarray(target_policy_local, dtype=np.float64).reshape(3)
    q_start = np.asarray(trunk_q, dtype=np.float64).reshape(4)
    reach = float(reach_m)
    shoulder_start = _r1pro_shoulder_positions_robot(q_start)
    shoulder_span = float(
        np.linalg.norm(shoulder_start["left"] - shoulder_start["right"])
    )
    half_span = 0.5 * shoulder_span
    if reach <= half_span + 1e-6:
        raise ValueError(
            f"reach={reach:.3f}m must exceed shoulder half-span={half_span:.3f}m"
        )
    longitudinal = math.sqrt(max(0.0, reach * reach - half_span * half_span))
    candidates: list[dict[str, Any]] = []
    rejected_back_facing = 0
    for q3 in np.linspace(TRUNK_LIMITS[2, 0], TRUNK_LIMITS[2, 1], 1081):
        q = q_start.copy()
        q[2] = float(q3)
        shoulders = _r1pro_shoulder_positions_robot(q)
        midpoint = 0.5 * (shoulders["left"] + shoulders["right"])
        _, chest_rotation = _r1pro_chest_pose_robot(q)
        chest_forward = np.asarray(chest_rotation[:, 0], dtype=np.float64)
        desired_target_robot = midpoint + longitudinal * chest_forward
        # Unsigned pitch angles alias a back-facing q3 mirror; v2 reaches forward.
        if (
            float(chest_forward[0]) < -REACH_FORWARD_AXIS_EPS
            or float(desired_target_robot[0]) <= REACH_TARGET_FORWARD_EPS_M
        ):
            rejected_back_facing += 1
            continue
        z_error = float(desired_target_robot[2] - target[2])
        candidates.append(
            {
                "score": abs(z_error) + 1e-4 * abs(float(q3 - q_start[2])),
                "q": q,
                "midpoint": midpoint,
                "desired_target_robot": desired_target_robot,
                "chest_forward_robot": chest_forward,
                "z_error": z_error,
                "left": shoulders["left"],
                "right": shoulders["right"],
            }
        )
    if not candidates:
        raise ValueError(
            "submission-local chord geometry has no forward-facing q3 solution"
        )
    best = min(candidates, key=lambda item: item["score"])
    desired = np.asarray(best["desired_target_robot"], dtype=np.float64)
    horizontal_offset = math.atan2(float(desired[1]), float(desired[0]))
    return {
        "target_trunk_q": np.asarray(best["q"], dtype=np.float64),
        "target_offset_robot_m": desired,
        "target_offset_bearing_rad": float(horizontal_offset),
        "chest_forward_robot_m": np.asarray(
            best["chest_forward_robot"], dtype=np.float64
        ),
        "pitch_branch": "forward_half_plane",
        "forward_candidate_count": len(candidates),
        "rejected_back_facing_candidate_count": int(rejected_back_facing),
        "shoulder_mid_robot_m": np.asarray(
            best["midpoint"],
            dtype=np.float64,
        ),
        "shoulder_span_m": shoulder_span,
        "longitudinal_chord_m": longitudinal,
        "reach_m": reach,
        "target_z_error_m": float(best["z_error"]),
        "left_distance_m": float(
            np.linalg.norm(desired - np.asarray(best["left"], dtype=np.float64))
        ),
        "right_distance_m": float(
            np.linalg.norm(desired - np.asarray(best["right"], dtype=np.float64))
        ),
        "model": "submission-local R1Pro chord-sphere geometry",
    }


def _pick_reach_base_goal(
    *,
    target_policy_local,
    start_pose,
    chord_plan: dict[str, Any],
) -> dict[str, Any]:
    """Select the nearest of the same 13 chord slices used by Interface v2.

    The official observation contract exposes no scene-graph or collision
    clearance callback. Interface v2 treats that callback as optional and
    assigns every candidate free clearance when it is absent; this test-local
    implementation follows that branch instead of substituting RGB-D.
    """
    target = np.asarray(target_policy_local, dtype=np.float64).reshape(3)
    start_xy = np.asarray(start_pose.pos[:2], dtype=np.float64).reshape(2)
    offset_robot = np.asarray(
        chord_plan["target_offset_robot_m"],
        dtype=np.float64,
    ).reshape(3)
    target_delta = target[:2] - start_xy
    target_bearing = math.atan2(
        float(target_delta[1]),
        float(target_delta[0]),
    )
    nominal_yaw = _normalize_angle(
        target_bearing - float(chord_plan["target_offset_bearing_rad"])
    )
    candidate_yaws = [
        _normalize_angle(nominal_yaw + math.radians(offset))
        for offset in (
            0,
            15,
            -15,
            30,
            -30,
            45,
            -45,
            60,
            -60,
            90,
            -90,
            120,
            -120,
        )
    ]
    options: list[dict[str, Any]] = []
    for offset_deg, yaw in zip(
        (0, 15, -15, 30, -30, 45, -45, 60, -60, 90, -90, 120, -120),
        candidate_yaws,
    ):
        base_xy = target[:2] - (_yaw_matrix(yaw) @ offset_robot)[:2]
        travel = float(np.linalg.norm(base_xy - start_xy))
        yaw_delta = abs(_normalize_angle(float(yaw) - float(start_pose.yaw)))
        options.append(
            {
                "base_xy": base_xy,
                "yaw_rad": float(yaw),
                "travel_m": travel,
                "yaw_delta_rad": yaw_delta,
                "yaw_offset_deg": int(offset_deg),
            }
        )
    selected = min(
        options,
        key=lambda item: (
            round(float(item["travel_m"]), 6),
            abs(float(item["yaw_offset_deg"])) * 0.001,
            float(item["yaw_delta_rad"]),
        ),
    )
    return {
        **selected,
        "clearance_m": None,
        "clear": True,
        "required_clearance_m": None,
        "clearance_source": "v2_optional_nav_clearance_unavailable",
        "pick_policy": "nearest_chord_travel_first",
        "candidate_count": len(options),
        "clear_candidate_count": len(options),
        "all_candidates": [
            {
                "base_xy": item["base_xy"].astype(float).tolist(),
                "yaw_deg": math.degrees(item["yaw_rad"]),
                "yaw_offset_deg": int(item["yaw_offset_deg"]),
                "clearance_m": None,
                "clear": True,
                "travel_m": float(item["travel_m"]),
            }
            for item in options
        ],
    }


def _base_action_from_physical_velocity(ctx, physical_cmd):
    """Map robot-frame physical velocity to the submitted controller action."""
    command = np.asarray(physical_cmd, dtype=np.float64).reshape(3)
    scales = np.array(
        [
            ADJUST_CHASSIS_BASE_MAX_LIN_MPS,
            ADJUST_CHASSIS_BASE_MAX_LIN_MPS,
            ADJUST_CHASSIS_BASE_MAX_ANG_RADPS,
        ],
        dtype=np.float64,
    )
    action = np.clip(command / scales, -1.0, 1.0)
    return ctx.world.set_base_velocity(*action.astype(float).tolist())


def _reach_pitch_interpolation_steps(pitch_gap_rad: float) -> int:
    gap = abs(float(pitch_gap_rad))
    if gap <= REACH_PITCH_NOOP_EPS_RAD:
        return 0
    return max(2, int(math.ceil(gap / 0.10)))


def _reach_observation_sequence(ctx) -> int | None:
    adapter = getattr(ctx.world, "_official_adapter", None)
    metadata = getattr(adapter, "observation_metadata", None)
    if callable(metadata):
        try:
            return int(metadata()[0])
        except (IndexError, TypeError, ValueError):
            return None
    status = getattr(adapter, "status", None)
    if callable(status):
        try:
            value = status().get("sequence")
            return None if value is None else int(value)
        except (AttributeError, TypeError, ValueError):
            return None
    return None


def _reach_phase_metrics(
    ctx,
    *,
    started_s: float,
    start_sequence: int | None,
    action_steps: int,
) -> dict[str, Any]:
    end_sequence = _reach_observation_sequence(ctx)
    observation_delta = (
        None
        if start_sequence is None or end_sequence is None
        else max(0, int(end_sequence) - int(start_sequence))
    )
    return {
        "wall_s": round(max(0.0, time.monotonic() - float(started_s)), 6),
        "action_steps": int(action_steps),
        "observation_sequence_start": start_sequence,
        "observation_sequence_end": end_sequence,
        "observation_delta": observation_delta,
    }


def _v2_local_base_command(
    pose,
    *,
    bx: float,
    by: float,
    target_yaw_rad: float,
    pos_tol_m: float,
    yaw_tol_deg: float,
) -> tuple[list[float], float, float]:
    """Interface-v2 signed holonomic command in physical units."""
    dx = float(bx) - float(pose.pos[0])
    dy = float(by) - float(pose.pos[1])
    yaw = float(pose.yaw)
    cos_y, sin_y = math.cos(yaw), math.sin(yaw)
    error_forward = cos_y * dx + sin_y * dy
    error_left = -sin_y * dx + cos_y * dy
    distance = float(math.hypot(dx, dy))
    yaw_error = _normalize_angle(float(target_yaw_rad) - yaw)

    if distance <= float(pos_tol_m):
        vx = 0.0
        vy = 0.0
    else:
        speed = REACH_BASE_MAX_SPEED_MPS
        if distance < REACH_BASE_LIN_SLOW_RADIUS_M:
            speed *= distance / REACH_BASE_LIN_SLOW_RADIUS_M
        inverse_distance = 1.0 / max(distance, 1e-9)
        vx = speed * error_forward * inverse_distance
        vy = speed * error_left * inverse_distance

    if abs(math.degrees(yaw_error)) <= float(yaw_tol_deg):
        wz = 0.0
    else:
        yaw_rate = REACH_BASE_MAX_YAW_RATE_RADPS
        if abs(yaw_error) < REACH_BASE_ANG_SLOW_RADIUS_RAD:
            yaw_rate *= abs(yaw_error) / REACH_BASE_ANG_SLOW_RADIUS_RAD
        wz = math.copysign(yaw_rate, yaw_error)

    linear_ratio = math.hypot(vx, vy) / max(REACH_BASE_MAX_SPEED_MPS, 1e-9)
    angular_ratio = abs(wz) / max(REACH_BASE_MAX_YAW_RATE_RADPS, 1e-9)
    combined_ratio = math.hypot(linear_ratio, angular_ratio)
    if combined_ratio > 1.0:
        vx /= combined_ratio
        vy /= combined_ratio
        wz /= combined_ratio
    return [float(vx), float(vy), float(wz)], distance, abs(
        math.degrees(yaw_error)
    )


def _ramp_v2_base_command(last, desired, *, dt_s: float) -> list[float]:
    previous = np.asarray(last, dtype=np.float64).reshape(3)
    target = np.asarray(desired, dtype=np.float64).reshape(3)
    output = previous.copy()
    linear_delta = target[:2] - previous[:2]
    linear_delta_norm = float(np.linalg.norm(linear_delta))
    max_linear_delta = REACH_BASE_MAX_LIN_ACCEL_MPS2 * max(1e-5, float(dt_s))
    if linear_delta_norm > max_linear_delta > 0.0:
        linear_delta *= max_linear_delta / linear_delta_norm
    output[:2] += linear_delta
    angular_delta = float(target[2] - previous[2])
    max_angular_delta = REACH_BASE_MAX_ANG_ACCEL_RADPS2 * max(
        1e-5, float(dt_s)
    )
    output[2] = previous[2] + float(
        np.clip(angular_delta, -max_angular_delta, max_angular_delta)
    )
    return output.astype(float).tolist()


def _cap_base_linear_speed(command, speed_limit_mps: float) -> list[float]:
    output = np.asarray(command, dtype=np.float64).reshape(3).copy()
    speed = float(np.linalg.norm(output[:2]))
    limit = max(0.0, float(speed_limit_mps))
    if speed > limit and speed > 1e-12:
        output[:2] *= limit / speed
    return output.astype(float).tolist()


def _cap_reach_command_to_official_action(command) -> list[float]:
    output = np.asarray(command, dtype=np.float64).reshape(3).copy()
    linear_speed = float(np.linalg.norm(output[:2]))
    if linear_speed > REACH_BASE_OFFICIAL_MAX_SPEED_MPS:
        output[:2] *= REACH_BASE_OFFICIAL_MAX_SPEED_MPS / linear_speed
    output[2] = float(
        np.clip(
            output[2],
            -REACH_BASE_OFFICIAL_MAX_YAW_RATE_RADPS,
            REACH_BASE_OFFICIAL_MAX_YAW_RATE_RADPS,
        )
    )
    return output.astype(float).tolist()


def _base_goal_brake_limit(
    *,
    distance_m: float,
    along_remaining_m: float | None,
    pos_tol_m: float,
) -> float:
    remaining = max(0.0, float(distance_m) - max(0.0, float(pos_tol_m)))
    if along_remaining_m is not None:
        remaining = min(
            remaining,
            max(
                0.0,
                float(along_remaining_m) - REACH_BASE_GOAL_STOP_MARGIN_M,
            ),
        )
    deceleration = max(
        1e-3,
        REACH_BASE_MAX_LIN_ACCEL_MPS2 * REACH_BASE_BRAKE_DECEL_SAFETY,
    )
    return math.sqrt(2.0 * deceleration * remaining)


def _yield_reach_base_xy_yaw_controller(
    ctx,
    *,
    bx: float,
    by: float,
    target_yaw_rad: float,
    timeout_s: float,
    pos_tol_m: float = REACH_XY_TOL_M,
    yaw_tol_deg: float = REACH_YAW_TOL_DEG,
):
    """Observation-only port of v2's signed holonomic base controller."""
    dt_s = 1.0 / float(CONTROL_HZ)
    max_steps = max(1, int(math.ceil(max(0.1, float(timeout_s)) / dt_s)))
    initial_pose = ctx.world.robot_pose()
    initial_xy = np.asarray(initial_pose.pos[:2], dtype=np.float64).reshape(2)
    goal_xy = np.asarray([float(bx), float(by)], dtype=np.float64)
    goal_delta = goal_xy - initial_xy
    goal_length = float(np.linalg.norm(goal_delta))
    goal_direction = (
        goal_delta / goal_length
        if goal_length > max(1e-6, float(pos_tol_m))
        else None
    )
    adapter = getattr(ctx.world, "_official_adapter", None)
    previous_sequence = None
    if adapter is not None:
        try:
            previous_sequence = int(adapter.status().get("sequence"))
        except (AttributeError, TypeError, ValueError):
            previous_sequence = None

    last_command = [0.0, 0.0, 0.0]
    last_xy_error = float("inf")
    last_yaw_error = float("inf")
    progress_reference_xy: float | None = None
    progress_reference_yaw: float | None = None
    no_progress_steps = 0
    action_steps = 0
    max_goal_overshoot = 0.0
    stop_reason = None

    for _ in range(max_steps):
        _check_cancelled(ctx, "move-to-reach signed holonomic base")
        pose = ctx.world.robot_pose()
        current_xy = np.asarray(pose.pos[:2], dtype=np.float64).reshape(2)
        last_xy_error = float(np.linalg.norm(goal_xy - current_xy))
        last_yaw_error = abs(
            math.degrees(_normalize_angle(float(target_yaw_rad) - float(pose.yaw)))
        )
        along_remaining = None
        if goal_direction is not None:
            along_remaining = float(np.dot(goal_xy - current_xy, goal_direction))
            max_goal_overshoot = max(max_goal_overshoot, max(0.0, -along_remaining))
            if along_remaining < -REACH_BASE_GOAL_PLANE_TOL_M:
                stop_reason = "goal_overshoot"
                for _ in range(REACH_BASE_GOAL_HARD_STOP_STEPS):
                    yield _base_action_from_physical_velocity(ctx, [0.0, 0.0, 0.0])
                    action_steps += 1
                break

        current_sequence = previous_sequence
        if adapter is not None:
            try:
                current_sequence = int(adapter.status().get("sequence"))
            except (AttributeError, TypeError, ValueError):
                current_sequence = previous_sequence
        fresh_observation = bool(
            adapter is None
            or (
                current_sequence is not None
                and previous_sequence is not None
                and current_sequence > previous_sequence
            )
        )
        if current_sequence is not None:
            previous_sequence = current_sequence
        command_active = bool(
            math.hypot(float(last_command[0]), float(last_command[1]))
            >= REACH_BASE_STUCK_MIN_LIN_CMD_MPS
            or abs(float(last_command[2])) >= REACH_BASE_STUCK_MIN_ANG_CMD_RADPS
        )
        if fresh_observation and command_active:
            if progress_reference_xy is None:
                progress_reference_xy = last_xy_error
                progress_reference_yaw = last_yaw_error
                no_progress_steps = 0
            else:
                xy_needed = float(progress_reference_xy) > float(pos_tol_m)
                yaw_needed = float(progress_reference_yaw or 0.0) > float(
                    yaw_tol_deg
                )
                progressed = bool(
                    (
                        xy_needed
                        and float(progress_reference_xy) - last_xy_error
                        >= REACH_BASE_STUCK_XY_PROGRESS_M
                    )
                    or (
                        yaw_needed
                        and float(progress_reference_yaw or 0.0) - last_yaw_error
                        >= REACH_BASE_STUCK_YAW_PROGRESS_DEG
                    )
                )
                if not xy_needed and not yaw_needed:
                    progress_reference_xy = None
                    progress_reference_yaw = None
                    no_progress_steps = 0
                elif progressed:
                    progress_reference_xy = last_xy_error
                    progress_reference_yaw = last_yaw_error
                    no_progress_steps = 0
                else:
                    no_progress_steps += 1
            if no_progress_steps >= int(
                math.ceil(REACH_BASE_STUCK_WINDOW_S * CONTROL_HZ)
            ):
                stop_reason = "no_progress"
                yield _base_action_from_physical_velocity(ctx, [0.0, 0.0, 0.0])
                action_steps += 1
                break
        elif not command_active:
            progress_reference_xy = None
            progress_reference_yaw = None
            no_progress_steps = 0

        desired, last_xy_error, last_yaw_error = _v2_local_base_command(
            pose,
            bx=float(bx),
            by=float(by),
            target_yaw_rad=float(target_yaw_rad),
            pos_tol_m=float(pos_tol_m),
            yaw_tol_deg=float(yaw_tol_deg),
        )
        brake_limit = _base_goal_brake_limit(
            distance_m=last_xy_error,
            along_remaining_m=along_remaining,
            pos_tol_m=float(pos_tol_m),
        )
        desired = _cap_base_linear_speed(desired, brake_limit)
        if last_xy_error <= float(pos_tol_m) and last_yaw_error <= float(yaw_tol_deg):
            desired = [0.0, 0.0, 0.0]
        if (
            last_xy_error <= float(pos_tol_m)
            and last_yaw_error <= float(yaw_tol_deg)
            and max(abs(float(value)) for value in last_command) <= 1e-3
        ):
            for _ in range(4):
                yield _base_action_from_physical_velocity(ctx, [0.0, 0.0, 0.0])
                action_steps += 1
            return {
                "ok": True,
                "xy_ok": True,
                "yaw_ok": True,
                "path_status": "v2_signed_holonomic_arrived",
                "reason": None,
                "safety_abort": False,
                "action_steps": int(action_steps),
                "xy_err_m": float(last_xy_error),
                "yaw_err_deg": float(last_yaw_error),
                "max_goal_overshoot_m": float(max_goal_overshoot),
                "requested_speed_scale": float(
                    REACH_BASE_COMMAND_SPEED_SCALE
                ),
                "requested_max_linear_mps": float(
                    REACH_BASE_MAX_SPEED_MPS
                ),
                "requested_max_yaw_rate_radps": float(
                    REACH_BASE_MAX_YAW_RATE_RADPS
                ),
                "official_max_linear_mps": float(
                    REACH_BASE_OFFICIAL_MAX_SPEED_MPS
                ),
                "official_max_yaw_rate_radps": float(
                    REACH_BASE_OFFICIAL_MAX_YAW_RATE_RADPS
                ),
                "official_action_limit_respected": True,
            }

        physical_command = _ramp_v2_base_command(
            last_command,
            desired,
            dt_s=dt_s,
        )
        physical_command = _cap_base_linear_speed(physical_command, brake_limit)
        physical_command = _cap_reach_command_to_official_action(
            physical_command
        )
        last_command = physical_command
        yield _base_action_from_physical_velocity(ctx, physical_command)
        action_steps += 1
    else:
        stop_reason = "timeout"

    for _ in range(4):
        yield _base_action_from_physical_velocity(ctx, [0.0, 0.0, 0.0])
        action_steps += 1
    final_pose = ctx.world.robot_pose()
    final_xy_error = float(
        np.linalg.norm(goal_xy - np.asarray(final_pose.pos[:2], dtype=np.float64))
    )
    final_yaw_error = abs(
        math.degrees(
            _normalize_angle(float(target_yaw_rad) - float(final_pose.yaw))
        )
    )
    xy_ok = bool(final_xy_error <= float(pos_tol_m))
    yaw_ok = bool(final_yaw_error <= float(yaw_tol_deg))
    return {
        "ok": bool(xy_ok and yaw_ok),
        "xy_ok": xy_ok,
        "yaw_ok": yaw_ok,
        "path_status": f"v2_signed_holonomic_{stop_reason}",
        "reason": stop_reason,
        "safety_abort": bool(stop_reason in {"goal_overshoot", "no_progress"}),
        "action_steps": int(action_steps),
        "xy_err_m": float(final_xy_error),
        "yaw_err_deg": float(final_yaw_error),
        "max_goal_overshoot_m": float(max_goal_overshoot),
        "requested_speed_scale": float(REACH_BASE_COMMAND_SPEED_SCALE),
        "requested_max_linear_mps": float(REACH_BASE_MAX_SPEED_MPS),
        "requested_max_yaw_rate_radps": float(
            REACH_BASE_MAX_YAW_RATE_RADPS
        ),
        "official_max_linear_mps": float(
            REACH_BASE_OFFICIAL_MAX_SPEED_MPS
        ),
        "official_max_yaw_rate_radps": float(
            REACH_BASE_OFFICIAL_MAX_YAW_RATE_RADPS
        ),
        "official_action_limit_respected": True,
    }


def _reach_same_target_measurement(
    ctx,
    target_policy_local,
) -> dict[str, Any]:
    """Measure both shoulders against the immutable clicked policy-local point."""
    target_robot = _point_in_robot_frame(ctx.world, target_policy_local)
    trunk_q = np.asarray(
        ctx.world.trunk_qpos(),
        dtype=np.float64,
    ).reshape(4)
    shoulders = _r1pro_shoulder_positions_robot(trunk_q)
    distances = {
        side: float(np.linalg.norm(target_robot - shoulder))
        for side, shoulder in shoulders.items()
    }
    return {
        "target_robot_m": target_robot,
        "trunk_q": trunk_q,
        "shoulders": shoulders,
        "left_m": float(distances["left"]),
        "right_m": float(distances["right"]),
        "minimum_m": float(min(distances.values())),
        "source": "frozen_RGB-D_click_plus_policy_local_odometry_and_proprio",
    }


def _yield_reach_signed_base_step(
    ctx,
    *,
    signed_distance_m: float,
    target_policy_local,
):
    requested = float(signed_distance_m)
    distance = abs(requested)
    direction_sign = 1.0 if requested >= 0.0 else -1.0
    start_pose = ctx.world.robot_pose()
    heading = np.array(
        [math.cos(float(start_pose.yaw)), math.sin(float(start_pose.yaw))],
        dtype=np.float64,
    )
    if distance <= REACH_COMP_FORWARD_TOL_M:
        return {
            "ok": True,
            "requested_signed_m": requested,
            "actual_signed_m": 0.0,
            "action_steps": 0,
            "safety_abort": None,
            "last_rgbd_guard": None,
        }
    del target_policy_local
    target_xy = np.asarray(start_pose.pos[:2], dtype=np.float64) + (
        direction_sign * distance * heading
    )
    move_report = yield from _yield_reach_base_xy_yaw_controller(
        ctx,
        bx=float(target_xy[0]),
        by=float(target_xy[1]),
        target_yaw_rad=float(start_pose.yaw),
        timeout_s=REACH_COMP_FORWARD_TIMEOUT_S,
        pos_tol_m=0.02,
        yaw_tol_deg=REACH_YAW_TOL_DEG,
    )
    final_pose = ctx.world.robot_pose()
    displacement = np.asarray(final_pose.pos[:2], dtype=np.float64) - np.asarray(
        start_pose.pos[:2],
        dtype=np.float64,
    )
    progress = max(0.0, direction_sign * float(np.dot(displacement, heading)))
    return {
        "ok": bool(move_report.get("ok")),
        "requested_signed_m": requested,
        "actual_signed_m": float(direction_sign * progress),
        "action_steps": int(move_report.get("action_steps") or 0),
        "safety_abort": (
            move_report.get("reason")
            if not move_report.get("ok")
            else None
        ),
        "last_rgbd_guard": None,
        "start_odometry": start_pose.as_dict(),
        "final_odometry": final_pose.as_dict(),
        "verification": "v2 signed holonomic controller over policy-local odometry",
        "base_controller": move_report,
    }


def _yield_reach_compensation(
    ctx,
    *,
    target_policy_local,
    keep_states: dict[str, dict[str, Any]],
    max_dist_m: float = REACH_MAX_SHOULDER_DISTANCE_M,
):
    report: dict[str, Any] = {
        "attempted": False,
        "ok": False,
        "trigger_max_dist_m": float(max_dist_m),
        "min_distance_before_m": None,
        "min_distance_after_m": None,
        "target_identity": "immutable_frozen_RGB-D_click",
        "phase1_forward": {
            "steps": [],
            "stopped_reason": None,
            "best_min_shoulder_m": None,
            "rolled_back_to_best": False,
        },
        "phase2_pitch": {
            "steps": [],
            "stopped_reason": None,
            "total_pitch_deg": 0.0,
        },
        "observation_action_only": True,
    }
    measurement = _reach_same_target_measurement(ctx, target_policy_local)
    distance_now = float(measurement["minimum_m"])
    report["min_distance_before_m"] = distance_now
    if distance_now <= float(max_dist_m):
        report["ok"] = True
        report["min_distance_after_m"] = distance_now
        return report

    report["attempted"] = True
    best_distance = distance_now
    best_progress = 0.0
    cumulative_progress = 0.0
    report["phase1_forward"]["best_min_shoulder_m"] = best_distance
    for step_index in range(1, REACH_COMP_FORWARD_MAX_STEPS + 1):
        move_report = yield from _yield_reach_signed_base_step(
            ctx,
            signed_distance_m=REACH_COMP_FORWARD_STEP_M,
            target_policy_local=target_policy_local,
        )
        cumulative_progress += max(
            0.0,
            float(move_report.get("actual_signed_m") or 0.0),
        )
        measurement = _reach_same_target_measurement(ctx, target_policy_local)
        distance_new = float(measurement["minimum_m"])
        stuck = bool(
            not move_report.get("ok")
            or move_report.get("safety_abort")
        )
        step_report = {
            "step": int(step_index),
            "requested_travel_m": float(REACH_COMP_FORWARD_STEP_M),
            "actual_travel_m": float(
                move_report.get("actual_signed_m") or 0.0
            ),
            "move_ok": bool(move_report.get("ok")),
            "safety_abort": move_report.get("safety_abort"),
            "min_shoulder_m": distance_new,
        }
        report["phase1_forward"]["steps"].append(step_report)
        if distance_new <= float(max_dist_m):
            report["phase1_forward"]["stopped_reason"] = "distance_ok"
            report["ok"] = True
            report["min_distance_after_m"] = distance_new
            return report

        improved = bool(
            distance_new
            < best_distance - REACH_COMP_IMPROVEMENT_EPS_M
        )
        if improved:
            best_distance = distance_new
            best_progress = cumulative_progress
            report["phase1_forward"]["best_min_shoulder_m"] = best_distance
        distance_now = distance_new
        if not improved and not stuck:
            report["phase1_forward"]["stopped_reason"] = (
                "distance_not_decreasing"
            )
            rollback_distance = best_progress - cumulative_progress
            rollback_report = yield from _yield_reach_signed_base_step(
                ctx,
                signed_distance_m=rollback_distance,
                target_policy_local=target_policy_local,
            )
            report["phase1_forward"]["rolled_back_to_best"] = True
            measurement = _reach_same_target_measurement(
                ctx,
                target_policy_local,
            )
            distance_now = float(measurement["minimum_m"])
            report["phase1_forward"]["rollback"] = {
                "requested_signed_m": float(rollback_distance),
                "move_ok": bool(rollback_report.get("ok")),
                "safety_abort": rollback_report.get("safety_abort"),
                "min_shoulder_after_m": distance_now,
            }
            if distance_now <= float(max_dist_m):
                report["ok"] = True
                report["min_distance_after_m"] = distance_now
                return report
            break
        if stuck:
            report["phase1_forward"]["stopped_reason"] = str(
                move_report.get("safety_abort") or "stuck_or_not_reached"
            )
            break
    else:
        report["phase1_forward"]["stopped_reason"] = "max_steps"

    max_pitch_steps = int(
        round(REACH_COMP_PITCH_MAX_DEG / REACH_COMP_PITCH_STEP_DEG)
    )
    total_pitch_deg = 0.0
    for step_index in range(1, max_pitch_steps + 1):
        q_now = np.asarray(
            ctx.world.trunk_qpos(),
            dtype=np.float64,
        ).reshape(4)
        q3_now = float(q_now[2])
        q3_floor_pitch = (
            float(q_now[0])
            + float(q_now[1])
            - math.radians(REACH_COMP_MAX_CHEST_PITCH_DEG)
        )
        q3_floor = max(REACH_COMP_Q3_MIN_RAD, q3_floor_pitch)
        q3_target = max(
            q3_now - math.radians(REACH_COMP_PITCH_STEP_DEG),
            q3_floor,
        )
        if q3_target >= q3_now - 1e-6:
            report["phase2_pitch"]["stopped_reason"] = (
                "q3_at_chest_pitch_limit"
                if q3_floor_pitch > REACH_COMP_Q3_MIN_RAD
                else "q3_at_urdf_limit"
            )
            break
        q_target = q_now.copy()
        q_target[2] = q3_target
        interpolation_steps = max(
            2,
            int(math.ceil(abs(q3_target - q3_now) / 0.08)),
        )
        for interpolation_index in range(1, interpolation_steps + 1):
            _check_cancelled(ctx, "move-to-reach compensation pitch")
            alpha = _smoothstep(interpolation_index / interpolation_steps)
            command = q_now + alpha * (q_target - q_now)
            yield ctx.world.make_action(
                **_reach_trunk_action_overrides(command, keep_states)
            )

        stable_steps = 0
        settle_steps = 0
        for _ in range(max(3, int(3.0 * CONTROL_HZ))):
            _check_cancelled(ctx, "move-to-reach compensation pitch settle")
            yield ctx.world.make_action(
                **_reach_trunk_action_overrides(q_target, keep_states)
            )
            settle_steps += 1
            observed = np.asarray(
                ctx.world.trunk_qpos(),
                dtype=np.float64,
            ).reshape(4)
            if float(np.max(np.abs(observed - q_target))) <= REACH_TRUNK_TOL_RAD:
                stable_steps += 1
                if stable_steps >= 3:
                    break
            else:
                stable_steps = 0

        observed = np.asarray(
            ctx.world.trunk_qpos(),
            dtype=np.float64,
        ).reshape(4)
        trunk_error = float(np.max(np.abs(observed - q_target)))
        trunk_ok = bool(stable_steps >= 3)
        measurement = _reach_same_target_measurement(ctx, target_policy_local)
        distance_new = float(measurement["minimum_m"])
        pitch_delta_deg = math.degrees(q3_now - q3_target)
        total_pitch_deg += pitch_delta_deg
        decreased = bool(
            distance_new < distance_now - REACH_COMP_IMPROVEMENT_EPS_M
        )
        report["phase2_pitch"]["steps"].append(
            {
                "step": int(step_index),
                "q3_before_rad": q3_now,
                "q3_target_rad": q3_target,
                "q3_observed_rad": float(observed[2]),
                "q3_floor_rad": q3_floor,
                "q3_floor_by": (
                    "chest_pitch_165deg"
                    if q3_floor_pitch > REACH_COMP_Q3_MIN_RAD
                    else "urdf_limit"
                ),
                "chest_pitch_target_deg": math.degrees(
                    float(q_target[0])
                    + float(q_target[1])
                    - q3_target
                ),
                "trunk_ok": trunk_ok,
                "trunk_error_rad": trunk_error,
                "settle_action_steps": int(settle_steps),
                "min_shoulder_m": distance_new,
                "decreased": decreased,
            }
        )
        report["phase2_pitch"]["total_pitch_deg"] = total_pitch_deg
        if distance_new <= float(max_dist_m):
            report["phase2_pitch"]["stopped_reason"] = "distance_ok"
            report["ok"] = True
            report["min_distance_after_m"] = distance_new
            return report
        if not trunk_ok:
            report["phase2_pitch"]["stopped_reason"] = "trunk_failed"
            distance_now = distance_new
            break
        if not decreased:
            report["phase2_pitch"]["stopped_reason"] = (
                "no_distance_decrease"
            )
            distance_now = distance_new
            break
        distance_now = distance_new
    else:
        report["phase2_pitch"]["stopped_reason"] = "max_pitch"

    final_measurement = _reach_same_target_measurement(
        ctx,
        target_policy_local,
    )
    report["min_distance_after_m"] = float(final_measurement["minimum_m"])
    report["ok"] = bool(
        float(final_measurement["minimum_m"]) <= float(max_dist_m)
    )
    return report


def _relative_uv_to_pixel(
    u: float,
    v: float,
    width: int,
    height: int,
) -> tuple[int, int]:
    u_f = float(u)
    v_f = float(v)
    if not (math.isfinite(u_f) and math.isfinite(v_f)):
        raise ValueError("u/v must be finite")
    if not (0.0 <= u_f <= 1000.0 and 0.0 <= v_f <= 1000.0):
        raise ValueError("u/v must use relative coordinates 0..1000")
    px = int(round(u_f / 1000.0 * max(0, int(width) - 1)))
    py = int(round(v_f / 1000.0 * max(0, int(height) - 1)))
    return px, py


def _depth_value(
    depth: np.ndarray,
    px: int,
    py: int,
    radius: int = 2,
) -> float:
    arr = np.asarray(depth, dtype=np.float64).squeeze()
    if arr.ndim != 2:
        raise ValueError(f"depth must be 2-D, got shape {arr.shape}")
    height, width = arr.shape
    x0, x1 = max(0, px - radius), min(width, px + radius + 1)
    y0, y1 = max(0, py - radius), min(height, py + radius + 1)
    patch = arr[y0:y1, x0:x1]
    valid = patch[np.isfinite(patch) & (patch > 1e-5)]
    if valid.size == 0:
        raise ValueError(f"no valid depth near pixel ({px}, {py})")
    return float(np.median(valid))


def _unproject_pixel(
    *,
    px: int,
    py: int,
    depth_m: float,
    camera: dict[str, Any],
) -> np.ndarray:
    z = float(depth_m)
    if not math.isfinite(z) or z <= 0.0:
        raise ValueError(f"invalid forward depth {depth_m!r}")
    fx = float(camera["fx"])
    fy = float(camera.get("fy", fx))
    cx = float(camera["cx"])
    cy = float(camera["cy"])
    point_camera = np.array(
        [
            (float(px) - cx) / fx * z,
            -(float(py) - cy) / fy * z,
            -z,
        ],
        dtype=np.float64,
    )
    camera_pos = np.asarray(camera["pos"], dtype=np.float64).reshape(3)
    return camera_pos + _quat_to_mat_xyzw(camera["quat"]) @ point_camera


def _point_from_current_depth_robot_base(
    *,
    depth: np.ndarray,
    u: float,
    v: float,
    role: str,
    camera_relative_pose: dict[str, Any],
) -> tuple[np.ndarray, dict[str, Any]]:
    """Unproject a current evaluator RGB-D pixel directly into robot base.

    This intentionally bypasses command odometry. It is the correct geometry
    path after a collision, where commanded base velocity may differ from
    actual base motion.
    """
    arr = np.asarray(depth, dtype=np.float32).squeeze()
    if arr.ndim != 2:
        raise ValueError(f"depth must be 2-D, got {arr.shape}")
    height, width = arr.shape
    px, py = _relative_uv_to_pixel(u, v, width, height)
    depth_m = _depth_value(arr, px, py)
    relative = dict(camera_relative_pose or {})
    if not relative.get("pos") or not relative.get("quat"):
        raise ValueError("camera_relative_pose must contain pos and quat")
    camera = {
        **_camera_intrinsics(str(role), width, height),
        "pos": relative["pos"],
        "quat": relative["quat"],
    }
    point = _unproject_pixel(
        px=px,
        py=py,
        depth_m=depth_m,
        camera=camera,
    )
    return point, {
        "relative_uv": [float(u), float(v)],
        "pixel_uv": [int(px), int(py)],
        "depth_m": float(depth_m),
        "frame": "robot_base",
        "source": "current_depth_and_cam_rel_pose",
    }


def _load_frozen_capture(
    session_id: str,
    image_id: str,
    *,
    role: str = "head",
) -> _FrozenCapture:
    session = str(session_id or "").strip()
    image = str(image_id or "").strip()
    meta = _load_image_meta(session, image)
    camera = dict(meta.get("camera") or {})
    if not camera:
        raise ValueError(f"capture {image!r} has no camera metadata")
    modalities = meta.get("modalities") or {}
    if not isinstance(modalities, dict):
        raise ValueError(f"capture {image!r} modalities metadata is invalid")
    depth_name = str(modalities.get("depth_linear") or "")
    if not depth_name:
        raise ValueError(f"capture {image!r} has no depth_linear artifact")
    depth_path = _policy_owned_capture_artifact(session, depth_name)
    depth = np.asarray(
        np.load(depth_path, allow_pickle=False),
        dtype=np.float32,
    ).squeeze()
    if depth.ndim != 2:
        raise ValueError(f"capture depth must be 2-D, got {depth.shape}")
    rgb = None
    rgb_name = str((meta.get("rgb") or {}).get(str(role)) or "")
    if rgb_name:
        rgb_path = _policy_owned_capture_artifact(session, rgb_name)
        if os.path.isfile(rgb_path):
            rgb = cv2.imread(rgb_path, cv2.IMREAD_COLOR)
    return _FrozenCapture(
        session_id=session,
        image_id=image,
        role=str(role),
        depth=depth,
        camera=camera,
        rgb=rgb,
        robot=dict(meta.get("robot") or {}),
        evaluator_sequence=(
            int(meta["evaluator_sequence"])
            if isinstance(meta.get("evaluator_sequence"), int)
            else None
        ),
    )


def _point_from_relative_uv(
    capture: _FrozenCapture,
    u: float,
    v: float,
) -> tuple[np.ndarray, dict[str, Any]]:
    height, width = capture.depth.shape[:2]
    px, py = _relative_uv_to_pixel(u, v, width, height)
    depth_m = _depth_value(capture.depth, px, py)
    point = _unproject_pixel(
        px=px,
        py=py,
        depth_m=depth_m,
        camera=capture.camera,
    )
    return point, {
        "relative_uv": [float(u), float(v)],
        "pixel_uv": [int(px), int(py)],
        "depth_m": float(depth_m),
        "frame": str(
            capture.camera.get("frame", "local_command_odometry")
        ),
    }


def _surface_normal_from_relative_uv(
    capture: _FrozenCapture,
    u: float,
    v: float,
    *,
    pixel_radius: int = 4,
) -> tuple[np.ndarray, dict[str, Any]]:
    height, width = capture.depth.shape[:2]
    px, py = _relative_uv_to_pixel(u, v, width, height)
    points: dict[str, np.ndarray] = {}
    offsets = {
        "left": (-pixel_radius, 0),
        "right": (pixel_radius, 0),
        "up": (0, -pixel_radius),
        "down": (0, pixel_radius),
    }
    for name, (dx, dy) in offsets.items():
        x = int(np.clip(px + dx, 0, width - 1))
        y = int(np.clip(py + dy, 0, height - 1))
        z = _depth_value(capture.depth, x, y, radius=1)
        points[name] = _unproject_pixel(
            px=x,
            py=y,
            depth_m=z,
            camera=capture.camera,
        )
    normal = np.cross(
        points["right"] - points["left"],
        points["down"] - points["up"],
    )
    norm = float(np.linalg.norm(normal))
    if norm <= 1e-9:
        raise ValueError("local depth surface normal is degenerate")
    normal /= norm
    if normal[2] < 0.0:
        normal = -normal
    return normal, {
        "normal": normal.astype(float).tolist(),
        "normal_abs_z": abs(float(normal[2])),
        "pixel_radius": int(pixel_radius),
    }


def _point_in_robot_frame(world, point_local) -> np.ndarray:
    point = np.asarray(point_local, dtype=np.float64).reshape(3)
    pose = world.robot_pose()
    base = np.asarray(pose.pos, dtype=np.float64).reshape(3)
    delta = point - base
    yaw = float(pose.yaw)
    cos_y, sin_y = math.cos(yaw), math.sin(yaw)
    return np.array(
        [
            cos_y * delta[0] + sin_y * delta[1],
            -sin_y * delta[0] + cos_y * delta[1],
            delta[2],
        ],
        dtype=np.float64,
    )


def _r1pro_chest_pose_robot(
    trunk_q,
) -> tuple[np.ndarray, np.ndarray]:
    """Exact R1Pro torso_link4 FK in the robot base frame."""
    q1, q2, q3, q4 = np.asarray(trunk_q, dtype=np.float64).reshape(4)

    def rot_y(angle: float) -> np.ndarray:
        cos_a, sin_a = math.cos(angle), math.sin(angle)
        return np.array(
            [
                [cos_a, 0.0, sin_a],
                [0.0, 1.0, 0.0],
                [-sin_a, 0.0, cos_a],
            ],
            dtype=np.float64,
        )

    def rot_z(angle: float) -> np.ndarray:
        cos_a, sin_a = math.cos(angle), math.sin(angle)
        return np.array(
            [
                [cos_a, -sin_a, 0.0],
                [sin_a, cos_a, 0.0],
                [0.0, 0.0, 1.0],
            ],
            dtype=np.float64,
        )

    position = np.array([-0.079032, 0.0, 0.34265], dtype=np.float64)
    rotation = rot_y(q1)
    position += rotation @ np.array([0.0, 0.0, 0.400])
    rotation = rotation @ rot_y(q2)
    position += rotation @ np.array([0.0, 0.0001005, 0.300])
    rotation = rotation @ rot_y(-q3)
    position += rotation @ np.array([0.0, -0.00010015, 0.09962])
    rotation = rotation @ rot_z(q4)
    return position, rotation


def _r1pro_shoulder_positions_robot(trunk_q) -> dict[str, np.ndarray]:
    chest, rotation = _r1pro_chest_pose_robot(trunk_q)
    return {
        "left": chest
        + rotation @ np.array([-0.00048618, 0.170734, 0.30302]),
        "right": chest
        + rotation @ np.array([-0.00048706, -0.170736, 0.30302]),
    }


def _shoulder_distances_robot(
    target_robot: np.ndarray,
    trunk_qpos: np.ndarray,
) -> tuple[dict[str, np.ndarray], dict[str, float]]:
    target = np.asarray(target_robot, dtype=np.float64).reshape(3)
    shoulders = _r1pro_shoulder_positions_robot(trunk_qpos)
    distances = {
        side: float(np.linalg.norm(target - shoulder))
        for side, shoulder in shoulders.items()
    }
    return shoulders, distances


def _prepared_rgbd_target_robot_point(
    *,
    prepared_target: dict[str, Any],
    capture: _FrozenCapture,
    focal_length: float,
    horizontal_aperture: float,
    world,
) -> tuple[np.ndarray, dict[str, Any]]:
    """Express the planner's selected depth sample in robot-base frame."""
    hit_audit = dict(prepared_target.get("hit_audit") or {})
    depth_pixel = np.asarray(
        hit_audit.get("depth_pixel", []),
        dtype=np.int64,
    ).reshape(-1)
    depth_m = float(hit_audit.get("depth_m", float("nan")))
    camera_relative_pose = dict(
        capture.camera.get("robot_relative_pose") or {}
    )
    relative_pos = camera_relative_pose.get("pos")
    relative_quat = camera_relative_pose.get("quat")
    if (
        depth_pixel.size == 2
        and math.isfinite(depth_m)
        and depth_m > 0.0
        and relative_pos is not None
        and relative_quat is not None
    ):
        height, width = capture.depth.shape[:2]
        focal_px = (
            float(focal_length)
            / float(horizontal_aperture)
            * float(width)
        )
        relative_camera = {
            "fx": focal_px,
            "fy": focal_px,
            "cx": float(width) * 0.5,
            "cy": float(height) * 0.5,
            "pos": relative_pos,
            "quat": relative_quat,
        }
        point = _unproject_pixel(
            px=int(depth_pixel[0]),
            py=int(depth_pixel[1]),
            depth_m=depth_m,
            camera=relative_camera,
        )
        return point, {
            "frame": "robot_base",
            "source": "planner_depth_column_hit_and_cam_rel_pose",
            "depth_pixel": depth_pixel.astype(int).tolist(),
            "depth_m": depth_m,
        }

    point = _point_in_robot_frame(world, prepared_target["hit"])
    return point, {
        "frame": "robot_base",
        "source": "planner_hit_and_policy_owned_odometry_fallback",
        "depth_pixel": depth_pixel.astype(int).tolist(),
        "depth_m": depth_m if math.isfinite(depth_m) else None,
    }


def _plan_grasp_shoulder_reach_report(
    *,
    target_robot: np.ndarray,
    trunk_qpos: np.ndarray,
    plan_arm: str,
    threshold_m: float = REACH_MAX_SHOULDER_DISTANCE_M,
) -> dict[str, Any]:
    requested_arm = str(plan_arm or "any").strip().lower()
    if requested_arm not in ("left", "right", "any"):
        requested_arm = "any"
    target = np.asarray(target_robot, dtype=np.float64).reshape(3)
    shoulders, distances = _shoulder_distances_robot(target, trunk_qpos)
    checked_distance = (
        min(distances.values())
        if requested_arm == "any"
        else distances[requested_arm]
    )
    return {
        "ok": bool(checked_distance < float(threshold_m)),
        "plan_arm": requested_arm,
        "comparison": "strict_less_than",
        "threshold_m": float(threshold_m),
        "checked_distance_m": float(checked_distance),
        "left_m": distances["left"],
        "right_m": distances["right"],
        "target_robot_m": target.astype(float).tolist(),
        "left_shoulder_robot_m": shoulders["left"].astype(float).tolist(),
        "right_shoulder_robot_m": shoulders["right"].astype(float).tolist(),
        "trunk_source": "frozen_capture",
        "static_model": "exact submission-local R1Pro URDF FK",
    }


def _r1pro_pitch_for_aligned_target(
    target_robot,
    trunk_q,
) -> dict[str, Any]:
    """Solve q3 so the shoulder-mid forward ray passes through the target.

    The target is reduced to its base-relative horizontal radius, which is
    equivalent to first aligning base yaw with the target. q1/q2 remain fixed
    and q4 is set to zero for the sagittal-plane solve.
    """
    target = np.asarray(target_robot, dtype=np.float64).reshape(3)
    q_start = np.asarray(trunk_q, dtype=np.float64).reshape(4)
    q1, q2, q3_start, _ = q_start
    target_aligned = np.array(
        [float(np.linalg.norm(target[:2])), 0.0, float(target[2])],
        dtype=np.float64,
    )
    a12 = float(q1 + q2)
    pitch_min = a12 - float(TRUNK_LIMITS[2, 1])
    pitch_max = a12 - float(TRUNK_LIMITS[2, 0])
    current_pitch = a12 - float(q3_start)

    def evaluate(pitch: float) -> dict[str, Any]:
        q3 = a12 - float(pitch)
        q = np.array([q1, q2, q3, 0.0], dtype=np.float64)
        shoulders = _r1pro_shoulder_positions_robot(q)
        shoulder_mid = 0.5 * (shoulders["left"] + shoulders["right"])
        _, rotation = _r1pro_chest_pose_robot(q)
        forward = rotation[:, 0]
        delta = target_aligned - shoulder_mid
        along = float(np.dot(delta, forward))
        residual_vec = delta - along * forward
        return {
            "pitch": float(pitch),
            "q3": float(q3),
            "cross": float(
                delta[0] * forward[2] - delta[2] * forward[0]
            ),
            "along": along,
            "residual_m": float(np.linalg.norm(residual_vec)),
            "shoulder_mid": shoulder_mid,
        }

    samples = np.linspace(pitch_min, pitch_max, 721)
    evaluated = [evaluate(float(pitch)) for pitch in samples]
    candidates: list[dict[str, Any]] = []
    for left, right in zip(evaluated[:-1], evaluated[1:]):
        if left["along"] > 0.0 and abs(left["cross"]) <= 1e-10:
            candidates.append(left)
        if left["cross"] * right["cross"] > 0.0:
            continue
        lo, hi = float(left["pitch"]), float(right["pitch"])
        f_lo = float(left["cross"])
        for _ in range(60):
            mid = 0.5 * (lo + hi)
            probe = evaluate(mid)
            if abs(probe["cross"]) <= 1e-12:
                lo = hi = mid
                break
            if f_lo * float(probe["cross"]) <= 0.0:
                hi = mid
            else:
                lo = mid
                f_lo = float(probe["cross"])
        candidate = evaluate(0.5 * (lo + hi))
        if candidate["along"] > 0.0:
            candidates.append(candidate)

    if not candidates:
        candidates = [
            min(
                (item for item in evaluated if item["along"] > 0.0),
                key=lambda item: item["residual_m"],
                default=min(evaluated, key=lambda item: item["residual_m"]),
            )
        ]
    best = min(
        candidates,
        key=lambda item: (
            item["residual_m"],
            abs(item["pitch"] - current_pitch),
        ),
    )
    return {
        "chest_pitch_deg": math.degrees(best["pitch"]),
        "q3_rad": best["q3"],
        "pitch_delta_deg": math.degrees(best["pitch"] - current_pitch),
        "ray_residual_m": best["residual_m"],
        "ray_forward_distance_m": best["along"],
        "target_aligned_robot_m": target_aligned.astype(float).tolist(),
        "shoulder_mid_at_solution_robot_m": best["shoulder_mid"]
        .astype(float)
        .tolist(),
        "assumption": "base yaw aligned to target; q1/q2 fixed; q4=0",
    }


def _motion_step_shape(distance: float, speed: float) -> dict[str, Any]:
    duration = abs(float(distance)) / float(speed) if speed > 0.0 else 0.0
    exact_steps = duration * CONTROL_HZ
    full_steps = int(math.floor(exact_steps + 1e-9))
    remainder = float(np.clip(exact_steps - full_steps, 0.0, 1.0))
    return {
        "duration_s": float(duration),
        "full_steps": int(full_steps),
        "remainder_scale": remainder,
        "steps": int(full_steps + int(remainder > 1e-9)),
    }


def _capture_robot_state(
    ctx,
    *,
    proprio: Any | None = None,
) -> dict[str, Any]:
    adapter = getattr(ctx.world, "_official_adapter", None)
    if proprio is None:
        proprio = None if adapter is None else adapter.proprio_vector()
    else:
        proprio = np.asarray(proprio, dtype=np.float64).reshape(-1)
        if proprio.size < PROPRIO_DIM or not np.all(
            np.isfinite(proprio[:PROPRIO_DIM])
        ):
            raise ValueError("frozen evaluator proprioception is invalid")
        proprio = proprio[:PROPRIO_DIM]

    if proprio is not None:
        def observed_values(name: str) -> list[float]:
            return np.asarray(
                proprio[PROPRIO_SLICES[name]],
                dtype=np.float64,
            ).astype(float).tolist()

        def observed_eef(side: str) -> dict[str, Any]:
            return ctx.world.local_pose_from_robot_relative(
                observed_values(f"eef_{side}_pos"),
                observed_values(f"eef_{side}_quat"),
            )

        observed = {
            "eef_left": observed_eef("left"),
            "eef_right": observed_eef("right"),
            "trunk_qpos": observed_values("trunk_qpos"),
            "trunk_qvel": observed_values("trunk_qvel"),
            "base_qvel": observed_values("base_qvel"),
            "arm_left_qpos": observed_values("arm_left_qpos"),
            "arm_left_qvel": observed_values("arm_left_qvel"),
            "arm_right_qpos": observed_values("arm_right_qpos"),
            "arm_right_qvel": observed_values("arm_right_qvel"),
            "gripper_left_qpos": observed_values("gripper_left_qpos"),
            "gripper_left_qvel": observed_values("gripper_left_qvel"),
            "gripper_right_qpos": observed_values("gripper_right_qpos"),
            "gripper_right_qvel": observed_values("gripper_right_qvel"),
        }
    else:
        observed = {
            "eef_left": ctx.world.eef_pose("left"),
            "eef_right": ctx.world.eef_pose("right"),
            "trunk_qpos": ctx.world.trunk_qpos().astype(float).tolist(),
            "trunk_qvel": [],
            "base_qvel": ctx.world.base_qvel().astype(float).tolist(),
            "arm_left_qpos": ctx.world.arm_qpos_list("left"),
            "arm_left_qvel": ctx.world.arm_qvel_list("left"),
            "arm_right_qpos": ctx.world.arm_qpos_list("right"),
            "arm_right_qvel": ctx.world.arm_qvel_list("right"),
            "gripper_left_qpos": ctx.world.gripper_qpos_list("left"),
            "gripper_left_qvel": ctx.world.gripper_qvel_list("left"),
            "gripper_right_qpos": ctx.world.gripper_qpos_list("right"),
            "gripper_right_qvel": ctx.world.gripper_qvel_list("right"),
        }
    return {
        "base_pose": ctx.world.robot_pose().as_dict(),
        **observed,
        "motion_epoch": int(ctx.world.motion_epoch()),
        "episode_id": str(ctx.world.episode_id()),
        "frame": "local_command_odometry",
        "proprio_source": (
            "frozen_evaluator_observation"
            if proprio is not None
            else "current_evaluator_observation"
        ),
    }


@dataclass(frozen=True)
class _FrozenWristObservation:
    frame: np.ndarray | None
    depth: np.ndarray | None
    camera_relative_pose: dict[str, list[float]] | None
    proprio: np.ndarray | None
    sequence: int | None
    received_ts: float | None


def _snapshot_array(value: Any, *, dtype: Any | None = None) -> np.ndarray:
    if hasattr(value, "detach"):
        value = value.detach().cpu().numpy()
    return np.asarray(value, dtype=dtype)


def _wrist_camera_role(key: str) -> str | None:
    lowered = str(key).lower()
    if "left_realsense" in lowered or "left_wrist" in lowered:
        return "left_wrist"
    if "right_realsense" in lowered or "right_wrist" in lowered:
        return "right_wrist"
    if "zed_link" in lowered or "head" in lowered:
        return "head"
    return None


def _freeze_wrist_observation(
    adapter: Any,
    role: str,
) -> _FrozenWristObservation:
    reader = getattr(adapter, "borrow_snapshot_for_reading", None)
    if not callable(reader):
        reader = getattr(adapter, "snapshot", None)
    if not callable(reader):
        raise RuntimeError(
            "official evaluator adapter does not expose an atomic observation snapshot"
        )
    snapshot = reader()
    observation = getattr(snapshot, "observation", None)
    if not isinstance(observation, Mapping):
        raise RuntimeError("official evaluator observation snapshot is invalid")

    rgb_value = next(
        (
            value
            for key, value in observation.items()
            if str(key).endswith("::rgb") and _wrist_camera_role(key) == role
        ),
        None,
    )
    frame = None
    if rgb_value is not None:
        canonical_rgb = tracker_rgb_as_uint8(
            _snapshot_array(rgb_value),
            "rgb",
        )
        frame = cv2.cvtColor(canonical_rgb, cv2.COLOR_RGB2BGR)

    depth_value = next(
        (
            value
            for key, value in observation.items()
            if str(key).endswith("::depth_linear")
            and _wrist_camera_role(key) == role
        ),
        None,
    )
    depth = None
    if depth_value is not None:
        candidate = _snapshot_array(depth_value, dtype=np.float32).squeeze()
        if candidate.ndim >= 2 and candidate.size:
            depth = candidate

    proprio_value = next(
        (
            value
            for key, value in observation.items()
            if str(key).endswith("::proprio")
        ),
        None,
    )
    proprio = None
    if proprio_value is not None:
        candidate = _snapshot_array(proprio_value, dtype=np.float64).reshape(-1)
        if candidate.size >= PROPRIO_DIM:
            proprio = candidate[:PROPRIO_DIM].copy()

    camera_relative_pose = None
    pose_value = next(
        (
            value
            for key, value in observation.items()
            if str(key).endswith("::cam_rel_poses")
        ),
        None,
    )
    if pose_value is not None:
        poses = _snapshot_array(pose_value, dtype=np.float64).reshape(-1)
        role_index = {
            "left_wrist": 0,
            "right_wrist": 1,
            "head": 2,
        }.get(str(role))
        if role_index is not None:
            start = 7 * role_index
            if poses.size >= start + 7:
                camera_relative_pose = {
                    "pos": poses[start : start + 3].astype(float).tolist(),
                    "quat": poses[start + 3 : start + 7].astype(float).tolist(),
                }

    raw_sequence = getattr(snapshot, "sequence", None)
    sequence = (
        int(raw_sequence)
        if isinstance(raw_sequence, (int, np.integer))
        and not isinstance(raw_sequence, bool)
        else None
    )
    raw_received_ts = getattr(snapshot, "received_ts", None)
    received_ts = None
    if raw_received_ts is not None:
        try:
            parsed_ts = float(raw_received_ts)
        except (TypeError, ValueError):
            parsed_ts = math.nan
        if math.isfinite(parsed_ts):
            received_ts = parsed_ts
    return _FrozenWristObservation(
        frame=frame,
        depth=depth,
        camera_relative_pose=camera_relative_pose,
        proprio=proprio,
        sequence=sequence,
        received_ts=received_ts,
    )


def _wrist_capture_alignment_report(
    *,
    proprio: np.ndarray | None,
    side: str,
    sequence: int | None,
) -> dict[str, Any]:
    qvel = (
        np.asarray([], dtype=np.float64)
        if proprio is None
        else np.asarray(
            proprio[PROPRIO_SLICES[f"gripper_{side}_qvel"]],
            dtype=np.float64,
        ).reshape(-1)
    )
    return {
        "settled": True,
        "settle_required": False,
        "action_steps": 0,
        "stable_steps": 0,
        "required_stable_steps": 0,
        "max_steps": 0,
        "qvel_limit_m_s": None,
        "initial_qvel_m_s": qvel.astype(float).tolist(),
        "final_qvel_m_s": qvel.astype(float).tolist(),
        "alignment": "single_evaluator_observation",
        "observation_sequence": sequence,
    }


def _blocked_payload(name: str) -> dict[str, Any]:
    return {
        "ok": False,
        "error": "; ".join(
            TOOL_CAPABILITIES[name]["current_violations"]
        ),
        "blocked_by": "official evaluator observation/action boundary",
    }


def _capture_artifacts_async_enabled(ctx) -> bool:
    """Enable deferred media work only for the live official runtime.

    Direct tool/unit callers intentionally keep the historical one-yield
    behavior.  New runtimes set the explicit marker after constructing their
    observation-backed world.  The second predicate recognizes a runtime
    created before that marker was added: the request-commit guard and the
    official adapter are both policy-owned invariants and are absent from
    simulator/unit worlds.  This lets a transactional tool-stack reload pick
    up the fix without restarting the evaluator process.
    """

    world = getattr(ctx, "world", None)
    explicit_runtime = bool(
        getattr(world, "_official_async_capture_artifacts", False)
    )
    legacy_official_runtime = (
        callable(getattr(world, "_official_request_commit_guard", None))
        and getattr(world, "_official_adapter", None) is not None
        and getattr(world, "_official_tracked_object_distances", None)
        is not None
    )
    if not (explicit_runtime or legacy_official_runtime):
        return False
    value = os.environ.get("BEHAVIOR_OFFICIAL_ASYNC_CAPTURE", "1")
    return value.strip().lower() not in {"0", "false", "no", "off"}


def _freeze_adapter_camera_array(
    adapter: Any,
    value: Any,
    *,
    dtype: Any | None = None,
    squeeze: bool = False,
) -> np.ndarray:
    """Retain official adapter-owned camera arrays without a second copy.

    The production adapter replaces its complete observation snapshot instead
    of mutating arrays in place. Unknown/test adapters retain the defensive
    copy used by the historical capture path.
    """

    array = np.asarray(value, dtype=dtype)
    if squeeze:
        array = array.squeeze()
    if bool(getattr(adapter, "_official_camera_arrays_owned", False)):
        return array
    return array.copy()


def _capture_artifact_process_enabled() -> bool:
    value = os.environ.get("BEHAVIOR_OFFICIAL_CAPTURE_PROCESS", "1")
    return value.strip().lower() not in {"0", "false", "no", "off"}


def _submit_capture_artifact_worker(
    worker: Callable[[], dict[str, Any]],
) -> tuple[concurrent.futures.Future, bool]:
    """Submit to a spawn-isolated worker, with a local-thread fallback."""

    if _capture_artifact_process_enabled():
        try:
            return _get_capture_artifact_process_executor().submit(worker), True
        except Exception:
            # A restricted runtime may reject process creation.  The thread
            # fallback preserves the capture contract; normal deployments use
            # the isolated path above.
            pass
    return _CAPTURE_ARTIFACT_EXECUTOR.submit(worker), False


def _is_capture_process_infrastructure_error(exc: BaseException) -> bool:
    if isinstance(exc, BrokenProcessPool):
        return True
    if isinstance(exc, pickle.PicklingError):
        return True
    if isinstance(exc, (AttributeError, TypeError)):
        message = str(exc).lower()
        return "pickle" in message or "local object" in message
    return False


def _capture_artifact_detach_enabled(ctx) -> bool:
    """Whether this runtime can publish a capture result out of band.

    Direct unit-test worlds and the legacy interface deliberately keep the
    original generator contract.  Only the official evaluator world opts into
    detached completion because its HTTP waiter knows how to resolve the
    private token below.
    """

    if not _capture_artifacts_async_enabled(ctx):
        _capture_trace("detach_decision", enabled=False, reason="async_disabled")
        return False
    world = getattr(ctx, "world", None)
    explicit_runtime = bool(
        getattr(world, "_official_detached_capture_results", False)
    )
    # Older policy-interface processes can be transactionally reloaded after
    # the detached flag was added, so their world object may lack that one
    # attribute even though all policy-owned invariants are present.  Infer
    # the same official runtime boundary used by
    # _capture_artifacts_async_enabled; ordinary simulator/unit worlds do not
    # expose this guard, adapter, and tracker trio.
    legacy_official_runtime = (
        callable(getattr(world, "_official_request_commit_guard", None))
        and getattr(world, "_official_adapter", None) is not None
        and getattr(world, "_official_tracked_object_distances", None)
        is not None
    )
    if not (explicit_runtime or legacy_official_runtime):
        _capture_trace("detach_decision", enabled=False, reason="non_official_world")
        return False
    value = os.environ.get("BEHAVIOR_OFFICIAL_DETACH_CAPTURE", "1")
    enabled = value.strip().lower() not in {"0", "false", "no", "off"}
    _capture_trace(
        "detach_decision",
        enabled=bool(enabled),
        explicit=bool(explicit_runtime),
        inferred=bool(legacy_official_runtime),
    )
    return enabled


def _prune_capture_artifacts_locked(now: float | None = None) -> None:
    now = time.monotonic() if now is None else float(now)
    for token, entry in tuple(_CAPTURE_ARTIFACT_PENDING.items()):
        age = now - float(entry.created_mono)
        if age < _CAPTURE_ARTIFACT_PENDING_TTL_S:
            continue
        # Never discard an active worker: a request may legitimately spend
        # several minutes rendering a large evaluator frame.  A completed
        # future without a finalized result means its HTTP waiter vanished;
        # retaining that orphan forever would permanently block hot reload.
        worker_done = False
        try:
            done = getattr(entry.future, "done", None)
            worker_done = bool(done()) if callable(done) else False
        except Exception:
            worker_done = False
        with entry.lock:
            terminal = (
                entry.final_result is not None
                or entry.final_error is not None
                or entry.cancelled
                or worker_done
            )
        if terminal:
            _CAPTURE_ARTIFACT_PENDING.pop(token, None)


def _register_capture_artifact(
    future: Any,
    *,
    isolated: bool,
    worker: Callable[[], dict[str, Any]],
    tool_name: str,
    finalize: Callable[[dict[str, Any]], Any],
) -> str:
    token = f"capture-{secrets.token_urlsafe(18)}"
    entry = _PendingCaptureArtifact(
        future=future,
        isolated=bool(isolated),
        worker=worker,
        tool_name=str(tool_name),
        finalize=finalize,
        created_mono=time.monotonic(),
    )
    with _CAPTURE_ARTIFACT_PENDING_LOCK:
        _prune_capture_artifacts_locked()
        _CAPTURE_ARTIFACT_PENDING[token] = entry
    return token


def _capture_artifact_entry(token: str) -> _PendingCaptureArtifact:
    normalized = str(token or "").strip()
    if not normalized:
        raise RuntimeError("capture artifact token is empty")
    with _CAPTURE_ARTIFACT_PENDING_LOCK:
        _prune_capture_artifacts_locked()
        entry = _CAPTURE_ARTIFACT_PENDING.get(normalized)
    if entry is None:
        raise RuntimeError("capture artifact is no longer available")
    return entry


def _resolve_capture_artifact_future(
    entry: _PendingCaptureArtifact,
    *,
    timeout_s: float,
) -> dict[str, Any]:
    """Resolve one worker, retrying only process-start infrastructure errors."""

    with entry.lock:
        if entry.final_result is not None:
            return dict(entry.final_result)
        if entry.final_error is not None:
            raise entry.final_error
        if entry.cancelled:
            raise RuntimeError("capture artifact was cancelled")

    timeout = max(0.0, float(timeout_s))
    deadline = time.monotonic() + timeout
    resolve_started = time.perf_counter()
    _capture_trace(
        "future_result_start",
        tool=entry.tool_name,
        isolated=bool(entry.isolated),
    )
    try:
        raw = entry.future.result(timeout=timeout)
    except concurrent.futures.TimeoutError as exc:
        raise TimeoutError(
            f"等待 {entry.tool_name} media artifact 超时 ({timeout_s}s)"
        ) from exc
    except Exception as exc:
        # Spawn can be unavailable in constrained deployments.  Match the
        # former bounded-thread fallback, but only for an infrastructure error;
        # genuine renderer failures must remain visible to the caller.
        if entry.isolated and _is_capture_process_infrastructure_error(exc):
            remaining = max(0.0, deadline - time.monotonic())
            if remaining <= 0.0:
                raise
            try:
                raw = _CAPTURE_ARTIFACT_EXECUTOR.submit(entry.worker).result(
                    timeout=remaining
                )
            except concurrent.futures.TimeoutError as timeout_exc:
                raise TimeoutError(
                    f"等待 {entry.tool_name} media artifact 超时 ({timeout_s}s)"
                ) from timeout_exc
            except Exception as fallback_exc:
                raw = {
                    "ok": False,
                    "error": f"{type(fallback_exc).__name__}: {fallback_exc}",
                }
        else:
            # The synchronous implementation surfaced renderer exceptions as a
            # normal failed skill result.  Keep that API shape even though the
            # evaluator callback has already been released.
            raw = {"ok": False, "error": f"{type(exc).__name__}: {exc}"}

    _capture_trace(
        "future_result_done",
        tool=entry.tool_name,
        elapsed_ms=(time.perf_counter() - resolve_started) * 1000.0,
        raw_type=type(raw).__name__,
        raw_keys=len(raw) if isinstance(raw, Mapping) else -1,
        raw_rgb_chars=(
            len(str(raw.get("rgb_main") or ""))
            if isinstance(raw, Mapping)
            else 0
        ),
    )
    if not isinstance(raw, Mapping):
        raw = {
            "ok": False,
            "error": (
                f"{entry.tool_name} media worker returned "
                f"{type(raw).__name__}, expected an object"
            ),
        }
    else:
        raw = dict(raw)

    with entry.lock:
        if entry.final_result is None and entry.final_error is None:
            if entry.cancelled:
                entry.final_error = RuntimeError("capture artifact was cancelled")
            else:
                finalize_started = time.perf_counter()
                _capture_trace(
                    "finalize_start",
                    tool=entry.tool_name,
                    raw_rgb_chars=len(str(raw.get("rgb_main") or "")),
                )
                try:
                    finalized = entry.finalize(raw)
                    if isinstance(finalized, Mapping):
                        entry.final_result = dict(finalized)
                    else:
                        entry.final_result = dict(raw)
                except Exception as exc:
                    entry.final_error = exc
                finally:
                    _capture_trace(
                        "finalize_done",
                        tool=entry.tool_name,
                        elapsed_ms=(time.perf_counter() - finalize_started) * 1000.0,
                        final_result=entry.final_result is not None,
                    )
        if entry.final_error is not None:
            raise entry.final_error
        return dict(entry.final_result or raw)


def wait_for_capture_artifact(token: str, timeout_s: float = 120.0) -> dict[str, Any]:
    """Resolve a detached capture token and install its normal public result."""

    entry = _capture_artifact_entry(token)
    return _resolve_capture_artifact_future(entry, timeout_s=timeout_s)


def cancel_capture_artifact(token: str) -> bool:
    """Cancel a detached artifact without touching simulator state."""

    try:
        entry = _capture_artifact_entry(token)
    except RuntimeError:
        return False
    with entry.lock:
        entry.cancelled = True
        try:
            entry.future.cancel()
        except Exception:
            pass
    return True


def cancel_all_capture_artifacts() -> int:
    """Cancel every detached artifact during an episode/runtime reset."""

    with _CAPTURE_ARTIFACT_PENDING_LOCK:
        _prune_capture_artifacts_locked()
        tokens = tuple(_CAPTURE_ARTIFACT_PENDING)
    cancelled = 0
    for token in tokens:
        if cancel_capture_artifact(token):
            cancelled += 1
    return cancelled


def capture_artifact_pending_count() -> int:
    with _CAPTURE_ARTIFACT_PENDING_LOCK:
        _prune_capture_artifacts_locked()
        return sum(
            1
            for entry in _CAPTURE_ARTIFACT_PENDING.values()
            if entry.final_result is None
            and entry.final_error is None
            and not entry.cancelled
        )


def _yield_capture_artifact(
    ctx,
    tool_name: str,
    worker: Callable[[], dict[str, Any]],
):
    """Run media serialization off the evaluator callback thread.

    The worker never touches the mutable ``SkillContext``.  Results are
    installed on the caller thread after completion, preserving the original
    result callback and cancellation boundary.  A single worker also bounds
    disk/CPU pressure when several interfaces capture concurrently.
    """

    # A coordinator created before detached capture support may still expose
    # the legacy waiter.  Repair that one server instance before publishing a
    # private token, so the HTTP request cannot observe and return the marker
    # without draining the process-worker pipe.
    if _capture_artifacts_async_enabled(ctx):
        _ensure_capture_wait_bridge(ctx)
        # The monitor store is created by the long-lived web app before this
        # reloadable tool module runs. Upgrade its HTTP-only card finalizer at
        # the first official capture so thumbnail/NAS work stays off the
        # evaluator callback critical path.
        _install_async_agent_monitor_finish()

    if not _capture_artifacts_async_enabled(ctx):
        _capture_trace("yield_sync_start", tool=tool_name)
        result = worker()
        _capture_trace("yield_sync_done", tool=tool_name)
        _set_result(ctx, tool_name, result)
        yield ctx.world.hold_action()
        return

    submit_started = time.perf_counter()
    _capture_trace("worker_submit_start", tool=tool_name)
    future, isolated = _submit_capture_artifact_worker(worker)
    _capture_trace(
        "worker_submit_done",
        tool=tool_name,
        isolated=bool(isolated),
        elapsed_ms=(time.perf_counter() - submit_started) * 1000.0,
    )

    if _capture_artifact_detach_enabled(ctx):
        # The worker owns only frozen arrays/dicts.  Installing the eventual
        # result through this callback preserves the old server/job metadata
        # path, while the generator can finish on the very next simulator tick.
        def _finalize(result: dict[str, Any]):
            return _set_result(ctx, tool_name, result)

        token = _register_capture_artifact(
            future,
            isolated=isolated,
            worker=worker,
            tool_name=tool_name,
            finalize=_finalize,
        )
        _capture_trace("detached_token", tool=tool_name, token=token)
        detached_set_started = time.perf_counter()
        _capture_trace("detached_set_result_start", tool=tool_name)
        _set_result(
            ctx,
            tool_name,
            {
                "ok": True,
                "_official_capture_pending_token": token,
            },
        )
        _capture_trace(
            "detached_set_result_done",
            tool=tool_name,
            elapsed_ms=(time.perf_counter() - detached_set_started) * 1000.0,
        )
        _capture_trace("detached_before_yield", tool=tool_name)
        yield ctx.world.hold_action()
        _capture_trace("detached_after_yield", tool=tool_name)
        return

    while not future.done():
        _check_cancelled(ctx, f"wait for {tool_name} artifact")
        yield ctx.world.hold_action()
    # Propagate worker exceptions through the same server-level error path as
    # the former synchronous implementation.
    try:
        result = future.result()
    except Exception as exc:
        if not isolated or not _is_capture_process_infrastructure_error(exc):
            raise
        # A process can fail before executing the callable (for example when
        # a deployment's multiprocessing policy rejects spawn).  Retry once in
        # the existing bounded thread executor so capture remains available.
        result = _CAPTURE_ARTIFACT_EXECUTOR.submit(worker).result()
    _set_result(ctx, tool_name, result)
    yield ctx.world.hold_action()


def _build_head_capture_artifact(
    *,
    session: str,
    image_id: str,
    frame: np.ndarray,
    depth: np.ndarray | None,
    evaluator_sequence: Any,
    camera: dict[str, Any],
    robot_state: dict[str, Any],
    tracking_binding: dict[str, Any],
    task_name: str,
) -> dict[str, Any]:
    """Serialize one frozen head capture without reading runtime state."""

    worker_started = time.perf_counter()
    _capture_trace(
        "head_worker_start",
        image=image_id,
        shape=list(np.asarray(frame).shape),
    )
    role = "head"
    rgb_path = _image_path(session, image_id, ".png")
    if not cv2.imwrite(rgb_path, frame):
        return {"ok": False, "error": f"failed to write {rgb_path}"}
    modalities: dict[str, str] = {}
    depth_visual_path: str | None = None
    if depth is not None:
        depth_path = _image_path(session, image_id, ".depth.npy")
        depth_visual_path = _image_path(session, image_id, ".depth.png")
        np.save(depth_path, np.asarray(depth, dtype=np.float32))
        cv2.imwrite(depth_visual_path, _depth_visual(depth))
        modalities["depth_linear"] = depth_path

    height, width = frame.shape[:2]
    path_overlay_path = _image_path(session, image_id, ".path.png")
    if depth is not None and bool(camera.get("pose_available")):
        base_path_overlay = render_head_path_overlay(
            rgb_path=rgb_path,
            depth_linear=depth,
            camera=camera,
            robot=robot_state,
            output_path=path_overlay_path,
        )
    else:
        base_path_overlay = {
            "ok": False,
            "error": (
                "v2 base-path HUD requires evaluator depth_linear "
                "and camera-relative pose"
            ),
            "path": path_overlay_path,
        }
    display_rgb_path = (
        path_overlay_path
        if bool(base_path_overlay.get("ok"))
        else rgb_path
    )
    spatial_map_overlay_applied = False
    try:
        display_bgr = cv2.imread(display_rgb_path, cv2.IMREAD_COLOR)
        if display_bgr is not None:
            stamped_bgr = _stamp_selected_minimap_on_bgr(display_bgr)
            spatial_map_overlay_applied = not np.array_equal(
                stamped_bgr, display_bgr
            )
            if spatial_map_overlay_applied:
                cv2.imwrite(display_rgb_path, stamped_bgr)
    except Exception:
        spatial_map_overlay_applied = False

    omitted = [
        "segmentation",
        "normal",
        "object_pose",
        "scene_graph",
        "BDDL_live_state",
        "simulator_mesh",
    ]
    meta = {
        "image_id": image_id,
        "session_id": session,
        "rgb": {
            role: os.path.basename(rgb_path),
            f"{role}_path_overlay": os.path.basename(display_rgb_path),
        },
        "modalities": {
            key: os.path.basename(path) for key, path in modalities.items()
        },
        "overlays": {
            "base_forward_path": os.path.basename(display_rgb_path),
        },
        "base_path_overlay": base_path_overlay,
        "spatial_map_overlay_applied": spatial_map_overlay_applied,
        "camera": camera,
        "robot": robot_state,
        "track_object_distance_binding": tracking_binding,
        "observation_policy": "official_allowlist",
        "evaluator_sequence": evaluator_sequence,
    }
    _save_image_meta(session, image_id, meta)
    result = {
        "ok": True,
        "feed": role,
        "image_id": image_id,
        "image_width": int(width),
        "image_height": int(height),
        "rgb_main": _file_to_data_url(display_rgb_path),
        "rgb_main_path": display_rgb_path,
        "rgb_path": rgb_path,
        "rgb_overlay_path": display_rgb_path,
        "base_path_overlay": base_path_overlay,
        "spatial_map_overlay_applied": spatial_map_overlay_applied,
        "camera": camera,
        "robot": robot_state,
        "track_object_distance_binding": tracking_binding,
        "modalities": list(modalities),
        "forbidden_modalities_omitted": omitted,
        "memory": {
            **task_memory_fields(str(task_name or "")),
            "image_id": image_id,
            "observation_policy": "official_allowlist",
            "available": [
                "rgb",
                *([] if depth is None else ["depth_linear"]),
                "proprioception",
                "camera_relative_pose",
            ],
            "omitted": omitted,
        },
    }
    hint = ""
    eef_near = ""
    nearby = ""
    if isinstance(base_path_overlay, dict):
        hint = str(base_path_overlay.get("chassis_forward_2m") or "").strip()
        eef_near = str(base_path_overlay.get("eef_near_0.1m") or "").strip()
        nearby = str(base_path_overlay.get("nearby_object_warning") or "").strip()
    if hint:
        result["chassis_forward_2m"] = hint
    if eef_near:
        result["eef_near_0.1m"] = eef_near
    if not nearby:
        # Model warning reports the chassis only; retain eef_near for checking.
        nearby = compose_nearby_object_warning(hint)
    if nearby:
        result["nearby_object_warning"] = nearby
    if depth_visual_path is not None:
        result.update(
            {
                "depth_path": modalities["depth_linear"],
                "depth_visual_path": depth_visual_path,
                "depth": _file_to_data_url(depth_visual_path),
            }
        )
    _capture_trace(
        "head_worker_done",
        image=image_id,
        elapsed_ms=(time.perf_counter() - worker_started) * 1000.0,
    )
    return result


def _build_wrist_capture_artifact(
    *,
    role: str,
    side: str,
    session: str,
    image_id: str,
    frame: np.ndarray,
    depth: np.ndarray | None,
    evaluator_sequence: Any,
    camera: dict[str, Any],
    robot_state: dict[str, Any],
    capture_settle: dict[str, Any],
    task_name: str,
) -> dict[str, Any]:
    """Serialize one frozen wrist capture without reading runtime state."""

    rgb_path = _image_path(session, image_id, f".{role}.png")
    if not cv2.imwrite(rgb_path, frame):
        return {"ok": False, "error": f"failed to write {rgb_path}"}
    modalities: dict[str, str] = {}
    depth_visual_path: str | None = None
    if depth is not None:
        depth_path = _image_path(session, image_id, f".{role}.depth.npy")
        depth_visual_path = _image_path(session, image_id, f".{role}.depth.png")
        np.save(depth_path, np.asarray(depth, dtype=np.float32))
        cv2.imwrite(depth_visual_path, _depth_visual(depth))
        modalities["depth_linear"] = depth_path

    grasp_overlay_path = _image_path(
        session,
        image_id,
        f".{role}.grasp_volume.png",
    )
    red_mask_path = _image_path(
        session,
        image_id,
        f".{role}.red_mask.npy",
    )
    if depth is not None and bool(camera.get("pose_available")):
        grasp_zone_overlay = render_wrist_grasp_volume_overlay(
            rgb_path=rgb_path,
            depth_linear=depth,
            camera=camera,
            eef_pose=robot_state[f"eef_{side}"],
            gripper_qpos=robot_state.get(f"gripper_{side}_qpos"),
            gripper_qvel=robot_state.get(f"gripper_{side}_qvel"),
            output_path=grasp_overlay_path,
            mask_path=red_mask_path,
        )
    else:
        grasp_zone_overlay = {
            "ok": False,
            "error": (
                "red grasp-volume overlay requires evaluator depth_linear "
                "and camera-relative pose"
            ),
            "path": grasp_overlay_path,
            "mask_path": red_mask_path,
        }
    display_rgb_path = (
        grasp_overlay_path
        if bool(grasp_zone_overlay.get("ok"))
        else rgb_path
    )
    if bool(grasp_zone_overlay.get("ok")):
        modalities["red_grasp_volume_mask"] = red_mask_path
    omitted = [
        "segmentation",
        "normal",
        "object_pose",
        "scene_graph",
        "BDDL_live_state",
        "simulator_mesh",
    ]
    meta = {
        "image_id": image_id,
        "session_id": session,
        "rgb": {
            role: os.path.basename(rgb_path),
            f"{role}_grasp_volume_overlay": os.path.basename(display_rgb_path),
        },
        "modalities": {
            key: os.path.basename(path) for key, path in modalities.items()
        },
        "overlays": {
            "wrist_grasp_volume": os.path.basename(display_rgb_path),
        },
        "grasp_zone_overlay": grasp_zone_overlay,
        "capture_settle": capture_settle,
        "camera": camera,
        "robot": robot_state,
        "observation_policy": "official_allowlist",
        "evaluator_sequence": evaluator_sequence,
    }
    _save_image_meta(session, image_id, meta)
    result = {
        "ok": True,
        "feed": role,
        "image_id": image_id,
        "image_width": int(frame.shape[1]),
        "image_height": int(frame.shape[0]),
        "rgb_main": _file_to_data_url(display_rgb_path),
        "rgb_main_path": display_rgb_path,
        "rgb_path": rgb_path,
        "rgb_overlay_path": display_rgb_path,
        "grasp_zone_overlay": grasp_zone_overlay,
        "capture_settle": capture_settle,
        "red_mask_path": (
            red_mask_path if bool(grasp_zone_overlay.get("ok")) else None
        ),
        "camera": camera,
        "robot": robot_state,
        "modalities": list(modalities),
        "forbidden_modalities_omitted": omitted,
        "memory": {
            **task_memory_fields(str(task_name or "")),
            "image_id": image_id,
            "observation_policy": "official_allowlist",
            "available": [
                "rgb",
                *([] if depth is None else ["depth_linear"]),
                "proprioception",
                "camera_relative_pose",
            ],
            "omitted": omitted,
        },
    }
    if depth_visual_path is not None:
        result.update(
            {
                "depth_path": modalities["depth_linear"],
                "depth_visual_path": depth_visual_path,
                "depth": _file_to_data_url(depth_visual_path),
            }
        )
    return result


def _capture_head_camera_sync(ctx, session_id: str, **kwargs):
    del kwargs
    role = "head"
    adapter = getattr(ctx.world, "_official_adapter", None)
    if adapter is None:
        _set_result(
            ctx,
            "capture_head_camera",
            {"ok": False, "error": "official evaluator adapter is unavailable"},
        )
        yield ctx.world.hold_action()
        return
    frame = adapter.camera_frame(role)
    depth = adapter.camera_depth_frame(role)
    evaluator_sequence = adapter.status().get("sequence")
    session = str(session_id or "").strip()
    if frame is None:
        _set_result(
            ctx,
            "capture_head_camera",
            {"ok": False, "feed": role, "error": "head RGB is unavailable"},
        )
        yield ctx.world.hold_action()
        return
    if not session:
        _set_result(
            ctx,
            "capture_head_camera",
            {"ok": False, "error": "session_id is required"},
        )
        yield ctx.world.hold_action()
        return
    _ensure_session(session)
    image_id = _next_image_id(session)
    rgb_path = _image_path(session, image_id, ".png")
    if not cv2.imwrite(rgb_path, frame):
        _set_result(
            ctx,
            "capture_head_camera",
            {"ok": False, "error": f"failed to write {rgb_path}"},
        )
        yield ctx.world.hold_action()
        return
    modalities: dict[str, str] = {}
    depth_visual_path = None
    if depth is not None:
        depth_path = _image_path(session, image_id, ".depth.npy")
        depth_visual_path = _image_path(session, image_id, ".depth.png")
        np.save(depth_path, np.asarray(depth, dtype=np.float32))
        cv2.imwrite(depth_visual_path, _depth_visual(depth))
        modalities["depth_linear"] = depth_path
    relative_pose = adapter.camera_relative_poses().get(role)
    if relative_pose is None:
        camera_pose = {
            "pos": [0.0, 0.0, 0.0],
            "quat": [0.0, 0.0, 0.0, 1.0],
            "frame": "local_command_odometry",
            "pose_available": False,
        }
    else:
        camera_pose = ctx.world.local_pose_from_robot_relative(
            relative_pose["pos"],
            relative_pose["quat"],
        )
        camera_pose["pose_available"] = True
    height, width = frame.shape[:2]
    camera = {
        **camera_pose,
        **_camera_intrinsics(role, width, height),
        "source": "official_evaluator_cam_rel_poses",
        "robot_relative_pose": (
            None
            if relative_pose is None
            else {
                "pos": list(relative_pose["pos"]),
                "quat": list(relative_pose["quat"]),
                "frame": "robot_base",
            }
        ),
    }
    robot_state = _capture_robot_state(ctx)
    tracking_binding: dict[str, Any]
    distance_manager = getattr(
        ctx.world,
        "_official_tracked_object_distances",
        None,
    )
    if distance_manager is None:
        tracking_binding = {
            "ok": False,
            "trackable": False,
            "reason": "tracker_unavailable",
            "error": "official dynamic distance tracker is unavailable",
        }
    elif depth is None:
        tracking_binding = {
            "ok": False,
            "trackable": False,
            "reason": "missing_depth_linear",
            "error": "head depth_linear is unavailable for frame binding",
        }
    else:
        try:
            tracking_binding = distance_manager.register_capture(
                session_id=session,
                image_id=image_id,
                observation_sequence=evaluator_sequence,
                episode_id=robot_state["episode_id"],
                image_shape=(height, width),
            )
        except TrackObjectDistanceBindingError as exc:
            tracking_binding = {
                "ok": False,
                "trackable": False,
                "reason": exc.reason,
                "error": str(exc),
            }
        except (TypeError, ValueError) as exc:
            tracking_binding = {
                "ok": False,
                "trackable": False,
                "reason": "binding_registration_failed",
                "error": str(exc),
            }
    path_overlay_path = _image_path(session, image_id, ".path.png")
    if (
        depth is not None
        and bool(camera.get("pose_available"))
    ):
        base_path_overlay = render_head_path_overlay(
            rgb_path=rgb_path,
            depth_linear=depth,
            camera=camera,
            robot=robot_state,
            output_path=path_overlay_path,
        )
    else:
        base_path_overlay = {
            "ok": False,
            "error": (
                "v2 base-path HUD requires evaluator depth_linear "
                "and camera-relative pose"
            ),
            "path": path_overlay_path,
        }
    display_rgb_path = (
        path_overlay_path
        if bool(base_path_overlay.get("ok"))
        else rgb_path
    )
    spatial_map_overlay_applied = False
    try:
        display_bgr = cv2.imread(display_rgb_path, cv2.IMREAD_COLOR)
        if display_bgr is not None:
            stamped_bgr = _stamp_selected_minimap_on_bgr(display_bgr)
            spatial_map_overlay_applied = not np.array_equal(
                stamped_bgr, display_bgr
            )
            if spatial_map_overlay_applied:
                cv2.imwrite(display_rgb_path, stamped_bgr)
    except Exception:
        spatial_map_overlay_applied = False
    omitted = [
        "segmentation",
        "normal",
        "object_pose",
        "scene_graph",
        "BDDL_live_state",
        "simulator_mesh",
    ]
    meta = {
        "image_id": image_id,
        "session_id": session,
        "rgb": {
            role: os.path.basename(rgb_path),
            f"{role}_path_overlay": os.path.basename(display_rgb_path),
        },
        "modalities": {
            key: os.path.basename(path) for key, path in modalities.items()
        },
        "overlays": {
            "base_forward_path": os.path.basename(display_rgb_path),
        },
        "base_path_overlay": base_path_overlay,
        "spatial_map_overlay_applied": spatial_map_overlay_applied,
        "camera": camera,
        "robot": robot_state,
        "track_object_distance_binding": tracking_binding,
        "observation_policy": "official_allowlist",
        "evaluator_sequence": evaluator_sequence,
    }
    _save_image_meta(session, image_id, meta)
    result = {
        "ok": True,
        "feed": role,
        "image_id": image_id,
        "image_width": int(width),
        "image_height": int(height),
        "rgb_main": _file_to_data_url(display_rgb_path),
        "rgb_main_path": display_rgb_path,
        "rgb_path": rgb_path,
        "rgb_overlay_path": display_rgb_path,
        "base_path_overlay": base_path_overlay,
        "spatial_map_overlay_applied": spatial_map_overlay_applied,
        "camera": camera,
        "robot": robot_state,
        "track_object_distance_binding": tracking_binding,
        "modalities": list(modalities),
        "forbidden_modalities_omitted": omitted,
        "memory": {
            **task_memory_fields(
                str(getattr(ctx, "task_name", "") or "")
            ),
            "image_id": image_id,
            "observation_policy": "official_allowlist",
            "available": [
                "rgb",
                *([] if depth is None else ["depth_linear"]),
                "proprioception",
                "camera_relative_pose",
            ],
            "omitted": omitted,
        },
    }
    hint = ""
    eef_near = ""
    nearby = ""
    if isinstance(base_path_overlay, dict):
        hint = str(base_path_overlay.get("chassis_forward_2m") or "").strip()
        eef_near = str(base_path_overlay.get("eef_near_0.1m") or "").strip()
        nearby = str(base_path_overlay.get("nearby_object_warning") or "").strip()
    if hint:
        result["chassis_forward_2m"] = hint
    if eef_near:
        result["eef_near_0.1m"] = eef_near
    if not nearby:
        # 模型预警只报底盘；eef_near 留给核对，先不并进去。
        nearby = compose_nearby_object_warning(hint)
    if nearby:
        result["nearby_object_warning"] = nearby
    if depth_visual_path is not None:
        result.update(
            {
                "depth_path": modalities["depth_linear"],
                "depth_visual_path": depth_visual_path,
                "depth": _file_to_data_url(depth_visual_path),
            }
        )
    _set_result(ctx, "capture_head_camera", result)
    yield ctx.world.hold_action()


