def _move_point_depth_value(
    depth: np.ndarray,
    px: int,
    py: int,
    *,
    radius: int = 4,
) -> tuple[float, str]:
    arr = np.asarray(depth, dtype=np.float64)
    if arr.ndim != 2:
        raise ValueError(f"depth_linear must be 2-D, got shape {arr.shape}")
    height, width = arr.shape
    if not (0 <= int(px) < width and 0 <= int(py) < height):
        raise ValueError(f"pixel ({px}, {py}) is outside the frozen depth image")
    center = float(arr[int(py), int(px)])
    if math.isfinite(center) and 0.01 < center < 50.0:
        return center, "center"
    for current_radius in range(1, max(1, int(radius)) + 1):
        x0 = max(0, int(px) - current_radius)
        x1 = min(width, int(px) + current_radius + 1)
        y0 = max(0, int(py) - current_radius)
        y1 = min(height, int(py) + current_radius + 1)
        patch = arr[y0:y1, x0:x1]
        valid = patch[
            np.isfinite(patch) & (patch > 0.01) & (patch < 50.0)
        ]
        if valid.size:
            return float(np.median(valid)), f"median_radius_{current_radius}"
    raise ValueError(f"no valid depth near pixel ({px}, {py})")


def _move_point_robot_base_click(
    capture: _FrozenCapture,
    point: dict[str, float],
) -> tuple[np.ndarray, dict[str, Any]]:
    depth = np.asarray(capture.depth, dtype=np.float64)
    if depth.ndim != 2:
        raise ValueError(f"depth_linear must be 2-D, got shape {depth.shape}")
    height, width = depth.shape
    camera_width = int(capture.camera.get("image_width", 0))
    camera_height = int(capture.camera.get("image_height", 0))
    if (camera_width, camera_height) != (width, height):
        raise ValueError(
            "frozen camera/depth resolution mismatch: "
            f"camera={camera_width}x{camera_height} depth={width}x{height}"
        )
    if capture.rgb is None:
        raise ValueError("frozen capture has no readable head RGB artifact")
    if tuple(np.asarray(capture.rgb).shape[:2]) != (height, width):
        raise ValueError(
            "frozen RGB/depth resolution mismatch: "
            f"rgb={np.asarray(capture.rgb).shape[:2]} depth={(height, width)}"
        )
    relative_pose = capture.camera.get("robot_relative_pose")
    if not isinstance(relative_pose, dict):
        raise ValueError("frozen capture has no camera-relative pose")
    if relative_pose.get("pos") is None or relative_pose.get("quat") is None:
        raise ValueError("frozen camera-relative pose must contain pos and quat")
    px, py = _relative_uv_to_pixel(point["u"], point["v"], width, height)
    depth_m, depth_method = _move_point_depth_value(depth, px, py)
    camera = {
        "fx": capture.camera.get("fx"),
        "fy": capture.camera.get("fy"),
        "cx": capture.camera.get("cx"),
        "cy": capture.camera.get("cy"),
        "pos": relative_pose.get("pos"),
        "quat": relative_pose.get("quat"),
    }
    for key in ("fx", "fy", "cx", "cy"):
        value = float(camera[key])
        if not math.isfinite(value) or (key in ("fx", "fy") and value <= 0.0):
            raise ValueError(f"frozen camera intrinsic {key} is invalid")
    point_robot = _unproject_pixel(
        px=px,
        py=py,
        depth_m=depth_m,
        camera=camera,
    )
    return point_robot, {
        "relative_uv": [float(point["u"]), float(point["v"])],
        "pixel_uv": [int(px), int(py)],
        "depth_m": float(depth_m),
        "depth_method": depth_method,
        "frame": "robot_base",
        "source": "frozen_evaluator_rgbd_and_cam_rel_pose",
    }


def _move_point_gripper_state(
    qpos: Any,
    qvel: Any,
) -> dict[str, Any]:
    position = np.asarray(qpos if qpos is not None else [], dtype=np.float64).reshape(-1)
    velocity = np.asarray(qvel if qvel is not None else [], dtype=np.float64).reshape(-1)
    if position.size != 2 or not np.all(np.isfinite(position)):
        raise ValueError("capture gripper qpos must contain two finite values")
    if velocity.size != 2 or not np.all(np.isfinite(velocity)):
        raise ValueError("capture gripper qvel must contain two finite values")
    limits = np.array([[0.0, 0.05], [0.0, 0.05]], dtype=np.float64)
    fractions = np.clip(
        (position - limits[:, 0]) / (limits[:, 1] - limits[:, 0]),
        0.0,
        1.0,
    )
    fully_open = bool(
        np.all(fractions >= MOVE_POINT_TO_POINT_GRIPPER_OPEN_FRACTION)
    )
    fully_closed = bool(
        np.all(fractions <= MOVE_POINT_TO_POINT_GRIPPER_CLOSED_FRACTION)
    )
    state = (
        "fully_open"
        if fully_open
        else "fully_closed"
        if fully_closed
        else "intermediate"
    )
    settled = bool(
        float(np.max(np.abs(velocity)))
        <= MOVE_POINT_TO_POINT_GRIPPER_SETTLED_QVEL_RAD_S
    )
    validated = bool(state == "intermediate" and settled)
    return {
        "state": state,
        "settled": settled,
        "validated": validated,
        "qpos": position.astype(float).tolist(),
        "qvel": velocity.astype(float).tolist(),
        "open_fraction": fractions.astype(float).tolist(),
        "joint_limits": limits.astype(float).tolist(),
        "open_threshold": MOVE_POINT_TO_POINT_GRIPPER_OPEN_FRACTION,
        "closed_threshold": MOVE_POINT_TO_POINT_GRIPPER_CLOSED_FRACTION,
        "settled_qvel_threshold": (
            MOVE_POINT_TO_POINT_GRIPPER_SETTLED_QVEL_RAD_S
        ),
        "source": "capture_time_evaluator_proprioception_static_limits",
        "reason": (
            "stable intermediate aperture"
            if validated
            else "candidate gripper must be stable and neither fully open nor fully closed"
        ),
    }


def _move_point_capture_kinematics(
    capture: _FrozenCapture,
) -> dict[str, Any]:
    robot = dict(capture.robot or {})
    trunk = np.asarray(robot.get("trunk_qpos"), dtype=np.float64).reshape(-1)
    if trunk.size != 4 or not np.all(np.isfinite(trunk)):
        raise ValueError("capture trunk_qpos must contain four finite values")
    arm_q: dict[str, np.ndarray] = {}
    arm_qvel: dict[str, np.ndarray] = {}
    gripper_q: dict[str, np.ndarray] = {}
    gripper_qvel: dict[str, np.ndarray] = {}
    for side in ("left", "right"):
        raw_q = np.asarray(
            robot.get(f"arm_{side}_qpos"),
            dtype=np.float64,
        ).reshape(-1)
        if raw_q.size != ARM_DOF or not np.all(np.isfinite(raw_q)):
            raise ValueError(
                f"capture {side} arm_qpos must contain {ARM_DOF} finite values"
            )
        if (
            ARM_DOF == 8
            and abs(float(raw_q[7])) > LOCKED_J8_CAPTURE_TOLERANCE_RAD
        ):
            raise ValueError(
                f"capture {side} J8={raw_q[7]:.6f}rad is outside the lock tolerance"
            )
        arm_q[side] = locked_arm_vector(
            raw_q,
            label=f"capture {side} arm_qpos",
        )
        raw_qvel = np.asarray(
            robot.get(f"arm_{side}_qvel"),
            dtype=np.float64,
        ).reshape(-1)
        if raw_qvel.size != ARM_DOF or not np.all(np.isfinite(raw_qvel)):
            raise ValueError(
                f"capture {side} arm_qvel must contain {ARM_DOF} finite values"
            )
        arm_qvel[side] = raw_qvel.copy()
        gripper_q[side] = np.asarray(
            robot.get(f"gripper_{side}_qpos"),
            dtype=np.float64,
        ).reshape(-1)
        gripper_qvel[side] = np.asarray(
            robot.get(f"gripper_{side}_qvel"),
            dtype=np.float64,
        ).reshape(-1)
    state = local_robot_state(
        trunk_q=trunk,
        arm_left_q=arm_q["left"],
        arm_right_q=arm_q["right"],
        gripper_left_q=gripper_q["left"],
        gripper_right_q=gripper_q["right"],
    )
    eef: dict[str, dict[str, np.ndarray]] = {}
    for side in ("left", "right"):
        position, quaternion = _local_eef_pose(state, side, arm_q[side])
        eef[side] = {
            "position": np.asarray(position, dtype=np.float64).reshape(3),
            "quaternion": np.asarray(quaternion, dtype=np.float64).reshape(4),
        }
    motion_epoch = robot.get("motion_epoch")
    if not isinstance(motion_epoch, int) or motion_epoch < 0:
        raise ValueError("capture has no valid policy motion_epoch")
    episode_id = str(robot.get("episode_id", "")).strip()
    if not episode_id:
        raise ValueError("capture has no valid evaluator episode_id")
    return {
        "state": state,
        "trunk": trunk,
        "arm_q": arm_q,
        "arm_qvel": arm_qvel,
        "gripper_q": gripper_q,
        "gripper_qvel": gripper_qvel,
        "eef": eef,
        "motion_epoch": int(motion_epoch),
        "episode_id": episode_id,
    }


def _move_point_start_state_validation(
    ctx,
    capture_state: dict[str, Any],
) -> tuple[bool, dict[str, Any]]:
    if str(ctx.world.episode_id()) != str(capture_state["episode_id"]):
        return False, {"reason": "episode_changed"}
    if int(ctx.world.motion_epoch()) != int(capture_state["motion_epoch"]):
        return False, {"reason": "motion_epoch_changed"}
    adapter, sequence = _adjust_adapter(ctx)

    def invalid_observation(reason: str, error: str) -> tuple[bool, dict[str, Any]]:
        return False, {
            "reason": str(reason),
            "error": str(error),
            "observation_sequence": int(sequence),
            "adapter": adapter,
        }

    current = {
        "trunk": np.asarray(ctx.world.trunk_qpos(), dtype=np.float64).reshape(-1),
        "trunk_qvel": np.asarray(
            adapter.proprio_vector()[PROPRIO_SLICES["trunk_qvel"]],
            dtype=np.float64,
        ).reshape(-1),
        "base_qvel": np.asarray(ctx.world.base_qvel(), dtype=np.float64).reshape(-1),
    }
    if current["trunk"].size != 4 or not np.all(np.isfinite(current["trunk"])):
        return invalid_observation(
            "invalid_start_state",
            "evaluator trunk proprioception is invalid",
        )
    if current["trunk_qvel"].size != 4 or not np.all(
        np.isfinite(current["trunk_qvel"])
    ):
        return invalid_observation(
            "invalid_start_state",
            "evaluator trunk velocity proprioception is invalid",
        )
    if current["base_qvel"].size < 3 or not np.all(
        np.isfinite(current["base_qvel"][:3])
    ):
        return invalid_observation(
            "invalid_start_state",
            "evaluator base velocity proprioception is invalid",
        )
    errors: dict[str, float] = {
        "trunk_inf_rad": float(
            np.linalg.norm(current["trunk"] - capture_state["trunk"], ord=np.inf)
        ),
        "trunk_qvel_inf_rad_s": float(
            np.linalg.norm(current["trunk_qvel"], ord=np.inf)
        ),
        "base_qvel_inf": float(
            np.linalg.norm(current["base_qvel"][:3], ord=np.inf)
        ),
    }
    for side in ("left", "right"):
        raw_q = np.asarray(ctx.world.arm_qpos_list(side), dtype=np.float64)
        if raw_q.size != ARM_DOF or not np.all(np.isfinite(raw_q)):
            return invalid_observation(
                "invalid_start_state",
                f"evaluator {side} arm position proprioception is invalid",
            )
        if (
            ARM_DOF == 8
            and raw_q.size >= 8
            and abs(float(raw_q[7])) > LOCKED_J8_CAPTURE_TOLERANCE_RAD
        ):
            return invalid_observation(
                f"{side}_j8_not_locked",
                f"evaluator {side} J8 is outside the locked-zero tolerance",
            )
        arm_q = locked_arm_vector(raw_q, label=f"current {side} arm_qpos")
        arm_qvel = np.asarray(ctx.world.arm_qvel_list(side), dtype=np.float64)
        gripper_q = np.asarray(ctx.world.gripper_qpos_list(side), dtype=np.float64)
        if arm_qvel.size != ARM_DOF or not np.all(np.isfinite(arm_qvel)):
            return invalid_observation(
                "invalid_start_state",
                f"evaluator {side} arm velocity proprioception is invalid",
            )
        if gripper_q.size != 2 or not np.all(np.isfinite(gripper_q)):
            return invalid_observation(
                "invalid_start_state",
                f"evaluator {side} gripper position proprioception is invalid",
            )
        # J8 is a contract-locked joint.  Its observed velocity can contain
        # residual controller telemetry that cannot be changed by an official
        # action, so it must not make the controllable J1-J7 start gate fail.
        arm_qvel_for_motion = (
            arm_qvel[:7] if ARM_DOF == 8 else arm_qvel
        )
        errors[f"{side}_arm_inf_rad"] = float(
            np.linalg.norm(arm_q - capture_state["arm_q"][side], ord=np.inf)
        )
        errors[f"{side}_arm_qvel_inf_rad_s"] = float(
            np.linalg.norm(arm_qvel_for_motion, ord=np.inf)
        )
        if ARM_DOF == 8:
            errors[f"{side}_j8_qvel_abs_rad_s"] = abs(float(arm_qvel[7]))
        errors[f"{side}_gripper_inf_rad"] = float(
            np.linalg.norm(
                gripper_q - capture_state["gripper_q"][side],
                ord=np.inf,
            )
        )
    if not all(math.isfinite(value) for value in errors.values()):
        return False, {
            "reason": "nonfinite_start_state",
            "errors": errors,
            "observation_sequence": int(sequence),
            "adapter": adapter,
        }
    stale = bool(
        errors["trunk_inf_rad"] > MOVE_POINT_TO_POINT_START_TRUNK_TOLERANCE_RAD
        or errors["trunk_qvel_inf_rad_s"]
        > MOVE_POINT_TO_POINT_START_TRUNK_QVEL_RAD_S
        or errors["base_qvel_inf"] > MOVE_POINT_TO_POINT_START_BASE_QVEL
        or any(
            errors[f"{side}_arm_inf_rad"]
            > MOVE_POINT_TO_POINT_START_ARM_TOLERANCE_RAD
            or errors[f"{side}_arm_qvel_inf_rad_s"]
            > MOVE_POINT_TO_POINT_START_ARM_QVEL_RAD_S
            or errors[f"{side}_gripper_inf_rad"]
            > MOVE_POINT_TO_POINT_START_GRIPPER_TOLERANCE_RAD
            for side in ("left", "right")
        )
    )
    return (not stale), {
        "reason": "start_state_matches_capture" if not stale else "stale_capture",
        "errors": errors,
        "observation_sequence": int(sequence),
        "adapter": adapter,
    }


def _move_point_compile_trajectory(
    *,
    plan_id: str,
    args: dict[str, Any],
    capture_state: dict[str, Any],
    arm: str,
    source_robot: np.ndarray,
    target_robot: np.ndarray,
    target_above_robot: np.ndarray,
    target_eef_position: np.ndarray,
    target_eef_quaternion: np.ndarray,
) -> dict[str, Any]:
    start_q = locked_arm_vector(
        capture_state["arm_q"][arm],
        label=f"planned {arm} start qpos",
    )
    start_eef = capture_state["eef"][arm]
    source_anchor_eef = _quat_to_mat_xyzw(
        start_eef["quaternion"]
    ).T @ (
        np.asarray(source_robot, dtype=np.float64)
        - np.asarray(start_eef["position"], dtype=np.float64)
    )
    translation = np.asarray(target_eef_position, dtype=np.float64) - np.asarray(
        start_eef["position"],
        dtype=np.float64,
    )
    nominal_cartesian_samples = max(
        1,
        int(
            math.ceil(
                float(np.linalg.norm(translation)) / MAX_TRANSLATION_STEP_M
            )
        ),
    )
    waypoints: list[list[float]] = []
    ik_reports: list[dict[str, Any]] = []
    previous_q = start_q.copy()
    previous_dq: np.ndarray | None = None
    limits = _ARM_LIMITS[arm][:ARM_DOF]
    max_path_position_error_m = 0.0
    planning_position_tolerance_m = min(
        0.003,
        max(0.001, float(args["pos_tol"])),
    )
    planning_orientation_tolerance_deg = max(
        0.1,
        float(args["ori_tol_deg"]),
    )
    planner_step_budget = max(
        1,
        int(args["max_steps"]) - MOVE_POINT_TO_POINT_STABLE_STEPS,
    )
    final_position_error_m = float("inf")
    final_orientation_error_deg = float("inf")
    final_rigid_point_error_m = float("inf")
    rigid_point_tolerance_m = max(0.002, float(args["pos_tol"]) * 1.5)
    converged = False

    for index in range(1, planner_step_budget + 1):
        current_position, current_quaternion = _local_eef_pose(
            capture_state["state"],
            arm,
            previous_q,
        )
        position_error_vector = np.asarray(
            target_eef_position,
            dtype=np.float64,
        ) - current_position
        orientation_error_vector_value = orientation_error_vector(
            current_quaternion,
            target_eef_quaternion,
        )
        final_position_error_m = float(
            np.linalg.norm(position_error_vector)
        )
        final_orientation_error_deg = math.degrees(
            float(np.linalg.norm(orientation_error_vector_value))
        )
        current_source_robot = (
            _quat_to_mat_xyzw(current_quaternion) @ source_anchor_eef
            + current_position
        )
        final_rigid_point_error_m = float(
            np.linalg.norm(current_source_robot - target_above_robot)
        )
        if (
            final_position_error_m <= planning_position_tolerance_m
            and final_orientation_error_deg
            <= planning_orientation_tolerance_deg
            and final_rigid_point_error_m <= rigid_point_tolerance_m
        ):
            converged = True
            break

        jacobian, _position, _quaternion = numerical_eef_jacobian(
            capture_state["state"],
            arm,
            previous_q,
            joint_indices=range(7),
        )
        delta_q, report = bounded_pose_tangent_step(
            jacobian,
            position_error_vector,
            orientation_error_vector_value,
            previous_q[:7],
            q_lower=limits[:7, 0],
            q_upper=limits[:7, 1],
            previous_dq=previous_dq,
            joint_goal=None,
            position_satisfied=(
                final_position_error_m <= planning_position_tolerance_m
            ),
        )
        if float(np.linalg.norm(delta_q, ord=np.inf)) <= 1e-8:
            raise ValueError(
                "submission-local tangent IK stalled before reaching the target"
            )
        solved_q = previous_q.copy()
        solved_q[:7] = np.clip(
            previous_q[:7] + delta_q,
            limits[:7, 0],
            limits[:7, 1],
        )
        if ARM_DOF == 8:
            solved_q[7] = 0.0
        solved_q = _require_serialized_j8_zero(
            solved_q,
            label=f"planned {arm} tangent waypoint {index}",
        )
        solved_position, solved_quaternion = _local_eef_pose(
            capture_state["state"],
            arm,
            solved_q,
        )
        if not (
            np.all(np.isfinite(solved_position))
            and np.all(np.isfinite(solved_quaternion))
        ):
            raise ValueError("submission-local FK produced a non-finite waypoint")
        translation_norm_sq = float(translation @ translation)
        if translation_norm_sq > 1e-12:
            alpha = float(
                np.clip(
                    (solved_position - start_eef["position"]) @ translation
                    / translation_norm_sq,
                    0.0,
                    1.0,
                )
            )
            straight_path_point = start_eef["position"] + alpha * translation
            max_path_position_error_m = max(
                max_path_position_error_m,
                float(np.linalg.norm(solved_position - straight_path_point)),
            )
        waypoints.append(solved_q.astype(float).tolist())
        ik_reports.append(
            {
                "iteration": int(index),
                "position_error_before_m": final_position_error_m,
                "orientation_error_before_deg": final_orientation_error_deg,
                "command_dq_inf_rad": float(
                    np.linalg.norm(delta_q, ord=np.inf)
                ),
                "predicted_translation_m": report[
                    "predicted_translation_m"
                ],
                "translation_residual_slack_m": report[
                    "translation_residual_slack_m"
                ],
            }
        )
        previous_q = solved_q
        previous_dq = delta_q.copy()

    if not converged:
        current_position, current_quaternion = _local_eef_pose(
            capture_state["state"],
            arm,
            previous_q,
        )
        final_position_error_m = float(
            np.linalg.norm(target_eef_position - current_position)
        )
        final_orientation_error_deg = orientation_error_deg(
            current_quaternion,
            target_eef_quaternion,
        )
        final_rigid_point_error_m = float(
            np.linalg.norm(
                _quat_to_mat_xyzw(current_quaternion) @ source_anchor_eef
                + current_position
                - target_above_robot
            )
        )
        converged = bool(
            final_position_error_m <= planning_position_tolerance_m
            and final_orientation_error_deg
            <= planning_orientation_tolerance_deg
            and final_rigid_point_error_m <= rigid_point_tolerance_m
        )
    if not converged:
        raise ValueError(
            "submission-local tangent IK did not converge within max_steps: "
            f"pos_err={final_position_error_m:.4f}m "
            f"ori_err={final_orientation_error_deg:.3f}deg "
            f"rigid_point_err={final_rigid_point_error_m:.4f}m"
        )

    if not waypoints:
        waypoints.append(start_q.astype(float).tolist())
    if len(waypoints) + MOVE_POINT_TO_POINT_STABLE_STEPS > int(args["max_steps"]):
        raise ValueError(
            f"planned trajectory needs {len(waypoints)} waypoint actions plus "
            f"{MOVE_POINT_TO_POINT_STABLE_STEPS} stable observations, exceeding "
            f"max_steps={args['max_steps']}"
        )
    if len(waypoints) > MAX_TRAJECTORY_WAYPOINTS:
        raise ValueError("planned trajectory contains too many waypoints")

    trajectory: dict[str, Any] = {
        "schema": MOVE_POINT_TO_POINT_TRAJECTORY_SCHEMA,
        "schema_version": MOVE_POINT_TO_POINT_TRAJECTORY_SCHEMA_VERSION,
        "plan_id": str(plan_id),
        "session_id": str(args["session_id"]),
        "tool_version": TOOL_VERSION,
        "source_tool": "move_point_to_point",
        "source_image_id": str(args["image_id"]),
        "robot_profile": ROBOT_PROFILE,
        "arm_dof": int(ARM_DOF),
        "action_dim": int(ACTION_DIM),
        "active_arm": str(arm),
        "locked_arm_joints": (
            {"J8": LOCKED_J8_VALUE_RAD}
            if LOCKED_J8_INDEX is not None
            else {}
        ),
        "start_state": {
            "episode_id": str(capture_state["episode_id"]),
            "motion_epoch": int(capture_state["motion_epoch"]),
            "trunk_qpos": capture_state["trunk"].astype(float).tolist(),
            "arm_qpos": {
                side: capture_state["arm_q"][side].astype(float).tolist()
                for side in ("left", "right")
            },
            "arm_qvel": {
                side: capture_state["arm_qvel"][side].astype(float).tolist()
                for side in ("left", "right")
            },
            "gripper_qpos": {
                side: capture_state["gripper_q"][side].astype(float).tolist()
                for side in ("left", "right")
            },
            "gripper_qvel": {
                side: capture_state["gripper_qvel"][side].astype(float).tolist()
                for side in ("left", "right")
            },
        },
        "parameters": {
            "points": args["points"],
            "above_target_point_m": float(args["above_target_point_m"]),
            "pos_tol": float(args["pos_tol"]),
            "ori_tol_deg": float(args["ori_tol_deg"]),
            "max_steps": int(args["max_steps"]),
            "timeout_s": float(args["timeout_s"]),
        },
        "target": {
            "source_robot_base_m": np.asarray(
                source_robot,
                dtype=np.float64,
            ).astype(float).tolist(),
            "clicked_target_robot_base_m": np.asarray(
                target_robot,
                dtype=np.float64,
            ).astype(float).tolist(),
            "offset_target_robot_base_m": np.asarray(
                target_above_robot,
                dtype=np.float64,
            ).astype(float).tolist(),
            "eef_position_robot_base_m": np.asarray(
                target_eef_position,
                dtype=np.float64,
            ).astype(float).tolist(),
            "eef_quaternion_xyzw": np.asarray(
                target_eef_quaternion,
                dtype=np.float64,
            ).astype(float).tolist(),
        },
        "tracking": {
            "waypoint_tolerance_rad": (
                MOVE_POINT_TO_POINT_WAYPOINT_TOLERANCE_RAD
            ),
            "max_tracking_error_rad": (
                MOVE_POINT_TO_POINT_MAX_TRACKING_ERROR_RAD
            ),
            "stall_steps": int(ADJUST_EEF_STALL_STEPS),
            "final_arm_qvel_threshold_rad_s": (
                MOVE_POINT_TO_POINT_FINAL_ARM_QVEL_RAD_S
            ),
            "stable_steps": int(MOVE_POINT_TO_POINT_STABLE_STEPS),
        },
        "waypoints": waypoints,
        "planner": {
            "controller": "frozen_cartesian_samples_submission_local_ik",
            "nominal_cartesian_sample_count": int(nominal_cartesian_samples),
            "tangent_iteration_count": int(len(ik_reports)),
            "joint_waypoint_count": int(len(waypoints)),
            "max_joint_step_rad": MOVE_POINT_TO_POINT_MAX_JOINT_STEP_RAD,
            "max_path_position_error_m": float(max_path_position_error_m),
            "planning_position_tolerance_m": float(
                planning_position_tolerance_m
            ),
            "planning_orientation_tolerance_deg": float(
                planning_orientation_tolerance_deg
            ),
            "final_position_error_m": float(final_position_error_m),
            "final_orientation_error_deg": float(
                final_orientation_error_deg
            ),
            "final_rigid_point_error_m": float(
                final_rigid_point_error_m
            ),
            "rigid_point_tolerance_m": float(rigid_point_tolerance_m),
            "ik_reports": ik_reports,
            "joint_limits_checked": True,
            "local_fk_finite_checked": True,
            "j8_locked_zero": LOCKED_J8_INDEX is not None,
            "frozen_rgbd_collision_checked": False,
            "simulator_collision_checked": False,
            "object_truth_used": False,
        },
    }
    trajectory["integrity"] = {
        "algorithm": "hmac-sha256",
        "digest": _trajectory_digest(trajectory),
    }
    return trajectory


def _move_point_write_plan(
    trajectory: dict[str, Any],
) -> str:
    path = _plan_record_path(
        str(trajectory["session_id"]),
        str(trajectory["plan_id"]),
    )
    _write_plan_record(
        path,
        {
            "ok": True,
            "tool": "move_point_to_point",
            "tool_version": TOOL_VERSION,
            "session_id": trajectory["session_id"],
            "plan_id": trajectory["plan_id"],
            "trajectory": trajectory,
        },
    )
    return path


def _move_point_load_trajectory(
    session_id: str,
    plan_id: str,
) -> tuple[dict[str, Any], str]:
    path = _plan_record_path(session_id, plan_id)
    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    descriptor = os.open(path, flags)
    try:
        stat = os.fstat(descriptor)
        if stat.st_size <= 0 or stat.st_size > MAX_PLAN_RECORD_BYTES:
            raise ValueError("move-point plan record has an invalid size")
        raw = os.read(descriptor, stat.st_size + 1)
    finally:
        os.close(descriptor)
    if len(raw) != stat.st_size:
        raise ValueError("move-point plan record changed while it was read")
    record = json.loads(
        raw.decode("utf-8"),
        object_pairs_hook=_reject_duplicate_json_keys,
        parse_constant=lambda value: (_ for _ in ()).throw(
            ValueError(f"non-standard JSON constant {value!r}")
        ),
    )
    if not isinstance(record, dict):
        raise ValueError("move-point plan record must be an object")
    if record.get("tool") != "move_point_to_point":
        raise ValueError("move-point plan record has the wrong source tool")
    trajectory = record.get("trajectory")
    if not isinstance(trajectory, dict):
        raise ValueError("move-point plan record has no trajectory")
    expected = {
        "schema": MOVE_POINT_TO_POINT_TRAJECTORY_SCHEMA,
        "schema_version": MOVE_POINT_TO_POINT_TRAJECTORY_SCHEMA_VERSION,
        "plan_id": str(plan_id),
        "session_id": str(session_id),
        "tool_version": TOOL_VERSION,
        "source_tool": "move_point_to_point",
        "robot_profile": ROBOT_PROFILE,
        "arm_dof": int(ARM_DOF),
        "action_dim": int(ACTION_DIM),
    }
    for key, value in expected.items():
        if trajectory.get(key) != value:
            raise ValueError(
                f"move-point trajectory {key} does not match the active contract"
            )
    integrity = trajectory.get("integrity")
    if (
        not isinstance(integrity, dict)
        or integrity.get("algorithm") != "hmac-sha256"
        or not hmac.compare_digest(
            str(integrity.get("digest", "")),
            _trajectory_digest(trajectory),
        )
    ):
        raise ValueError("move-point trajectory digest mismatch")
    arm = str(trajectory.get("active_arm", "")).strip().lower()
    if arm not in ("left", "right"):
        raise ValueError("move-point trajectory active arm is invalid")
    expected_locked = (
        {"J8": LOCKED_J8_VALUE_RAD}
        if LOCKED_J8_INDEX is not None
        else {}
    )
    if trajectory.get("locked_arm_joints") != expected_locked:
        raise ValueError("move-point trajectory locked-joint contract is invalid")
    start_state = trajectory.get("start_state")
    if not isinstance(start_state, dict):
        raise ValueError("move-point trajectory start state is missing")
    if not str(start_state.get("episode_id", "")).strip():
        raise ValueError("move-point trajectory episode id is invalid")
    if not isinstance(start_state.get("motion_epoch"), int):
        raise ValueError("move-point trajectory motion epoch is invalid")
    for side in ("left", "right"):
        _require_serialized_j8_zero(
            (start_state.get("arm_qpos") or {}).get(side),
            label=f"move-point start {side} arm_qpos",
        )
        _arm_vector(
            (start_state.get("arm_qvel") or {}).get(side),
            label=f"move-point start {side} arm_qvel",
        )
        for field in ("gripper_qpos", "gripper_qvel"):
            values = np.asarray(
                (start_state.get(field) or {}).get(side),
                dtype=np.float64,
            ).reshape(-1)
            if values.size != 2 or not np.all(np.isfinite(values)):
                raise ValueError(
                    f"move-point start {side} {field} is invalid"
                )
    trunk = np.asarray(
        start_state.get("trunk_qpos"),
        dtype=np.float64,
    ).reshape(-1)
    if trunk.size != 4 or not np.all(np.isfinite(trunk)):
        raise ValueError("move-point trajectory trunk state is invalid")
    parameters = trajectory.get("parameters")
    tracking = trajectory.get("tracking")
    planner = trajectory.get("planner")
    target = trajectory.get("target")
    if not all(
        isinstance(value, dict)
        for value in (parameters, tracking, planner, target)
    ):
        raise ValueError("move-point trajectory metadata is incomplete")
    if planner.get("joint_limits_checked") is not True:
        raise ValueError("move-point trajectory joint-limit validation is missing")
    if planner.get("local_fk_finite_checked") is not True:
        raise ValueError("move-point trajectory local-FK validation is missing")
    if planner.get("simulator_collision_checked") is not False:
        raise ValueError("move-point trajectory contains forbidden collision truth")
    waypoints = trajectory.get("waypoints")
    if not isinstance(waypoints, list) or not waypoints:
        raise ValueError("move-point trajectory has no waypoints")
    if len(waypoints) > MAX_TRAJECTORY_WAYPOINTS:
        raise ValueError("move-point trajectory contains too many waypoints")
    limits = _ARM_LIMITS[arm][:ARM_DOF]
    previous = _require_serialized_j8_zero(
        start_state["arm_qpos"][arm],
        label="move-point trajectory start qpos",
    )
    for raw_q in waypoints:
        q = _require_serialized_j8_zero(
            raw_q,
            label="move-point trajectory waypoint",
        )
        if np.any(q < limits[:, 0]) or np.any(q > limits[:, 1]):
            raise ValueError("move-point trajectory waypoint exceeds joint limits")
        if (
            float(np.linalg.norm(q - previous, ord=np.inf))
            > MOVE_POINT_TO_POINT_MAX_JOINT_STEP_RAD
            + TRAJECTORY_STEP_VALIDATION_EPS_RAD
        ):
            raise ValueError("move-point trajectory waypoint step is too large")
        previous = q
    return trajectory, path


def _move_point_gripper_action_overrides(
    ctx,
    capture_state: dict[str, Any],
    *,
    enable_open_recovery: bool = False,
) -> tuple[dict[str, Any], dict[str, Any]]:
    overrides: dict[str, Any] = {}
    report: dict[str, Any] = {}
    for side in ("left", "right"):
        close_latched = bool(
            getattr(
                ctx.world,
                "gripper_close_keepalive_active",
                lambda _arm: False,
            )(side)
        )
        if close_latched:
            report[side] = {
                "mode": "verified_close_keepalive",
                "capture_qpos": capture_state["gripper_q"][side].tolist(),
            }
            continue
        if bool(
            getattr(
                ctx.world,
                "gripper_uses_effort",
                lambda _arm: False,
            )(side)
        ):
            current_q = np.asarray(
                ctx.world.gripper_qpos_list(side),
                dtype=np.float64,
            ).reshape(2)
            current_qvel = np.asarray(
                ctx.world.gripper_qvel_list(side),
                dtype=np.float64,
            ).reshape(2)
            error = capture_state["gripper_q"][side] - current_q
            effort = np.clip(
                MOVE_POINT_TO_POINT_GRIPPER_SERVO_KP_N_PER_M * error
                - MOVE_POINT_TO_POINT_GRIPPER_SERVO_KD_N_PER_MPS
                * current_qvel,
                -MOVE_POINT_TO_POINT_GRIPPER_SERVO_MAX_N,
                MOVE_POINT_TO_POINT_GRIPPER_SERVO_MAX_N,
            )
            outward_only = (
                capture_state["gripper_q"][side]
                >= MOVE_TRACKED_POINT_GRIPPER_OPEN_HOLD_THRESHOLD_M
            )
            boosted_open = np.zeros(2, dtype=bool)
            # Negative effort is the evaluator's assisted-close intent.  A
            # near-open capture target must never receive close intent merely
            # because its measured qvel points outward.  This clamp is part of
            # the ordinary hold and adds no evaluator step on the fast path.
            effort[outward_only] = np.maximum(effort[outward_only], 0.0)
            if enable_open_recovery:
                boosted_open = np.logical_and(
                    outward_only,
                    error > MOVE_TRACKED_POINT_GRIPPER_OPEN_RECOVERY_DEADBAND_M,
                )
                effort[boosted_open] = (
                    MOVE_TRACKED_POINT_GRIPPER_OPEN_RECOVERY_EFFORT_N
                )
            overrides[f"gripper_effort_{side}"] = effort.astype(float).tolist()
            report[side] = {
                "mode": "capture_qpos_local_effort_servo",
                "capture_qpos": capture_state["gripper_q"][side].tolist(),
                "observed_qpos": current_q.astype(float).tolist(),
                "observed_qvel": current_qvel.astype(float).tolist(),
                "error_m": error.astype(float).tolist(),
                "command": effort.astype(float).tolist(),
                "outward_only_fingers": np.flatnonzero(outward_only)
                .astype(int)
                .tolist(),
                "boosted_open_fingers": np.flatnonzero(boosted_open)
                .astype(int)
                .tolist(),
                "outward_recovery_effort_n": float(
                    MOVE_TRACKED_POINT_GRIPPER_OPEN_RECOVERY_EFFORT_N
                ),
            }
        else:
            mean_q = float(np.mean(capture_state["gripper_q"][side]))
            command = float(np.clip(2.0 * mean_q / 0.05 - 1.0, -1.0, 1.0))
            overrides[f"gripper_{side}"] = [command]
            report[side] = {
                "mode": "capture_qpos_static_limit_position_command",
                "capture_qpos": capture_state["gripper_q"][side].tolist(),
                "command": [command],
            }
    return overrides, report


def _move_point_waypoint_stalled_sample(
    *,
    previous_error: float,
    error: float,
    before_q: np.ndarray,
    after_q: np.ndarray,
    after_qvel: np.ndarray,
) -> tuple[bool, float, float]:
    observed_joint_delta = float(
        np.linalg.norm(
            np.asarray(after_q, dtype=np.float64)[:7]
            - np.asarray(before_q, dtype=np.float64)[:7],
            ord=np.inf,
        )
    )
    observed_arm_qvel = float(
        np.linalg.norm(np.asarray(after_qvel, dtype=np.float64)[:7], ord=np.inf)
    )
    stalled = bool(
        math.isfinite(float(previous_error))
        and float(previous_error) - float(error) <= 1e-4
        and observed_joint_delta
        <= MOVE_POINT_TO_POINT_STALL_POSITION_DELTA_RAD
        and observed_arm_qvel <= MOVE_POINT_TO_POINT_STALL_QVEL_RAD_S
    )
    return stalled, observed_joint_delta, observed_arm_qvel


def _move_point_effective_stability_qvel(
    *,
    arm: str,
    previous_q: np.ndarray,
    current_q: np.ndarray,
    current_qvel: np.ndarray,
) -> tuple[float, float, float, list[str]]:
    q = np.asarray(current_q, dtype=np.float64).reshape(ARM_DOF)
    previous = np.asarray(previous_q, dtype=np.float64).reshape(ARM_DOF)
    qvel = np.asarray(current_qvel, dtype=np.float64).reshape(ARM_DOF)
    if not all(np.all(np.isfinite(value)) for value in (q, previous, qvel)):
        raise ValueError("final stability proprioception contains non-finite values")
    limits = _ARM_LIMITS[str(arm)][:ARM_DOF]
    position_delta = np.abs(q - previous)
    distance_to_limit = np.minimum(
        np.abs(q - limits[:, 0]),
        np.abs(q - limits[:, 1]),
    )
    limit_chatter = np.logical_and(
        distance_to_limit <= MOVE_POINT_TO_POINT_FINAL_LIMIT_PROXIMITY_RAD,
        position_delta <= MOVE_POINT_TO_POINT_FINAL_LIMIT_POSITION_STEP_RAD,
    )
    if LOCKED_J8_INDEX is not None:
        limit_chatter[LOCKED_J8_INDEX] = False
    effective_qvel = qvel.copy()
    effective_qvel[limit_chatter] = 0.0
    active = slice(0, min(7, ARM_DOF))
    filtered = [
        f"J{index + 1}"
        for index in np.flatnonzero(limit_chatter[active])
    ]
    return (
        float(np.linalg.norm(qvel[active], ord=np.inf)),
        float(np.linalg.norm(effective_qvel[active], ord=np.inf)),
        float(np.linalg.norm(position_delta[active], ord=np.inf)),
        filtered,
    )


def _move_point_execute_trajectory(
    ctx,
    *,
    trajectory: dict[str, Any],
    capture_state: dict[str, Any],
    adapter,
    observation_sequence: int,
    timeout_s: float,
    max_steps: int,
    step_monitor=None,
    operation_name: str = "move_point_to_point",
    allow_start_rebase: bool = False,
    allow_gripper_recovery: bool = False,
    continue_during_gripper_disturbance: bool = False,
    recover_active_arm_disturbance: bool = False,
    execution_waypoints: Sequence[Sequence[float]] | None = None,
    execution_max_step_rad: float | None = None,
    tracker_reacquisition_max_steps: int | None = None,
):
    arm = str(trajectory["active_arm"])
    inactive_arm = "right" if arm == "left" else "left"
    expected_episode_id = str(trajectory["start_state"]["episode_id"])
    tracking = dict(trajectory["tracking"])
    waypoint_tolerance = float(tracking["waypoint_tolerance_rad"])
    max_tracking_error = float(tracking["max_tracking_error_rad"])
    execution_mode = str(
        tracking.get("execution_mode", "settled_waypoint_replay")
    )
    if execution_mode not in {
        "settled_waypoint_replay",
        "continuous_waypoint_stream",
    }:
        raise ValueError(f"unsupported trajectory execution mode {execution_mode!r}")
    continuous_stream = execution_mode == "continuous_waypoint_stream"
    if tracker_reacquisition_max_steps is not None:
        if (
            isinstance(tracker_reacquisition_max_steps, bool)
            or int(tracker_reacquisition_max_steps)
            != tracker_reacquisition_max_steps
            or int(tracker_reacquisition_max_steps) < 1
        ):
            raise ValueError(
                "tracker_reacquisition_max_steps must be a positive integer"
            )
        tracker_reacquisition_max_steps = int(
            tracker_reacquisition_max_steps
        )
    raw_trunk_assisted = tracking.get("trunk_assisted", False)
    if not isinstance(raw_trunk_assisted, bool):
        raise ValueError("trajectory trunk-assisted flag is invalid")
    if raw_trunk_assisted:
        raise ValueError(
            f"{operation_name} does not execute whole-body trajectories"
        )
    sequence = int(observation_sequence)
    initial = _adjust_kinematic_observation(ctx, arm)
    initial_trunk = np.asarray(initial["trunk"], dtype=np.float64).reshape(4)
    signed_waypoints = list(trajectory["waypoints"])
    signed_waypoint_count = len(signed_waypoints)
    if trajectory.get("trunk_waypoints") is not None:
        raise ValueError("arm-only trajectory contains trunk waypoints")
    if execution_waypoints is None:
        execution_waypoints_list = signed_waypoints
    else:
        execution_waypoints_list = []
        for waypoint_index, raw_waypoint in enumerate(execution_waypoints):
            execution_waypoints_list.append(
                _require_serialized_j8_zero(
                    raw_waypoint,
                    label=f"{operation_name} execution schedule waypoint {waypoint_index + 1}",
                )
            )
        if not execution_waypoints_list:
            raise ValueError("execution schedule produced no waypoints")
    bridge_step = (
        float(execution_max_step_rad)
        if execution_max_step_rad is not None
        else float(
            tracking.get(
                "max_joint_step_rad",
                MOVE_POINT_TO_POINT_MAX_JOINT_STEP_RAD,
            )
        )
    )
    if not math.isfinite(bridge_step) or bridge_step <= 0.0:
        raise ValueError("execution_max_step_rad must be positive and finite")
    execution_bridge_waypoint_count = 0
    if allow_start_rebase:
        execution_waypoints_list, execution_bridge_waypoint_count = (
            _move_tracked_execution_bridge(
                initial["q"],
                execution_waypoints_list,
                arm=arm,
                max_step_rad=bridge_step,
            )
        )
    initial_inactive_q = np.asarray(
        ctx.world.arm_qpos_list(inactive_arm),
        dtype=np.float64,
    ).reshape(ARM_DOF)
    ctx.world.set_trunk_pin_qpos(initial_trunk)
    ctx.world.set_arm_pin_qpos(arm, initial["q"])
    ctx.world.set_arm_pin_qpos(inactive_arm, initial_inactive_q)
    safety_monitor = _adjust_safety_monitor(ctx, initial)
    started = time.monotonic()
    action_steps = 0
    completed_waypoints = 0
    max_observed_tracking_error = 0.0
    max_inactive_arm_drift = 0.0
    max_gripper_drift = 0.0
    final_gripper_drift = 0.0
    max_observed_j8 = abs(float(initial["observed_j8"]))
    tracking_recovery_steps = 0
    tracking_recovery_events: list[dict[str, Any]] = []
    tracker_reacquisition_hold_q: np.ndarray | None = None
    tracker_reacquisition_hold_steps = 0
    tracker_reacquisition_events: list[dict[str, Any]] = []
    gripper_recovery_hold_q: np.ndarray | None = None
    gripper_recovery_fingers: dict[str, list[int]] = {}
    gripper_recovery_steps = 0
    gripper_recovery_streak = 0
    gripper_recovery_stable_steps = 0
    gripper_recovery_events: list[dict[str, Any]] = []
    gripper_recovery_samples: list[dict[str, Any]] = []
    gripper_disturbance_active = False
    gripper_disturbance_steps = 0
    reason = "trajectory_complete"
    last_observed = initial
    last_gripper_report: dict[str, Any] = {}
    last_waypoint: dict[str, Any] = {}
    last_step_monitor: dict[str, Any] = {}

    for waypoint_index, raw_target in enumerate(execution_waypoints_list):
        target = _require_serialized_j8_zero(
            raw_target,
            label=f"{operation_name} waypoint {waypoint_index + 1}",
        )
        previous_error = float("inf")
        waypoint_stall_steps = 0
        while True:
            _check_cancelled(
                ctx,
                f"{operation_name} waypoint {waypoint_index + 1}",
            )
            if str(ctx.world.episode_id()) != expected_episode_id:
                reason = "episode_changed"
                break
            if time.monotonic() - started >= float(timeout_s):
                reason = "timeout"
                break
            if action_steps >= int(max_steps):
                reason = "max_steps"
                break
            before = _adjust_kinematic_observation(ctx, arm)
            gripper_overrides, last_gripper_report = (
                _move_point_gripper_action_overrides(
                    ctx,
                    capture_state,
                    # Preserve the existing local servo on the fast path.
                    # The outward-only command is enabled only after a fresh
                    # proprio sample has crossed the soft recovery boundary.
                    enable_open_recovery=bool(
                        allow_gripper_recovery
                        and (
                            continue_during_gripper_disturbance
                            or gripper_recovery_hold_q is not None
                        )
                    ),
                )
            )
            command_is_reacquisition_hold = (
                tracker_reacquisition_hold_q is not None
            )
            if (
                command_is_reacquisition_hold
                and tracker_reacquisition_max_steps is not None
                and tracker_reacquisition_hold_steps
                >= tracker_reacquisition_max_steps
            ):
                tracker_reacquisition_events.append(
                    {
                        "event": "reacquisition_exhausted",
                        "waypoint_index": int(waypoint_index + 1),
                        "observation_sequence": int(sequence),
                        "hold_steps": int(tracker_reacquisition_hold_steps),
                        "max_hold_steps": int(
                            tracker_reacquisition_max_steps
                        ),
                    }
                )
                reason = "tracked_point_reacquisition_failed"
                break
            command_is_gripper_recovery_hold = bool(
                not command_is_reacquisition_hold
                and gripper_recovery_hold_q is not None
            )
            command = (
                tracker_reacquisition_hold_q.copy()
                if command_is_reacquisition_hold
                else (
                    gripper_recovery_hold_q.copy()
                    if command_is_gripper_recovery_hold
                    else target
                )
            )
            action_overrides = {
                f"arm_{arm}": command.astype(float).tolist(),
                **gripper_overrides,
            }
            action = ctx.world.make_action(**action_overrides)
            if command_is_reacquisition_hold:
                tracker_reacquisition_hold_steps += 1
            yield action
            action_steps += 1
            advanced, current_sequence = _adjust_observation_advanced(
                adapter,
                sequence,
            )
            if not advanced:
                reason = "observation_not_advanced"
                break
            sequence = current_sequence
            if str(ctx.world.episode_id()) != expected_episode_id:
                reason = "episode_changed"
                break
            after = _adjust_kinematic_observation(ctx, arm)
            last_observed = after
            max_observed_j8 = max(
                max_observed_j8,
                abs(float(after["observed_j8"])),
            )
            arm_error = float(np.linalg.norm(command - after["q"], ord=np.inf))
            error = arm_error
            (
                stalled_sample,
                observed_joint_delta,
                observed_arm_qvel,
            ) = _move_point_waypoint_stalled_sample(
                previous_error=previous_error,
                error=error,
                before_q=before["q"],
                after_q=after["q"],
                after_qvel=after["qvel"],
            )
            max_observed_tracking_error = max(
                max_observed_tracking_error,
                error,
            )
            inactive_q = np.asarray(
                ctx.world.arm_qpos_list(inactive_arm),
                dtype=np.float64,
            ).reshape(ARM_DOF)
            inactive_drift = float(
                np.linalg.norm(inactive_q - initial_inactive_q, ord=np.inf)
            )
            max_inactive_arm_drift = max(
                max_inactive_arm_drift,
                inactive_drift,
            )
            gripper_observation: dict[str, dict[str, Any]] = {}
            for side in ("left", "right"):
                observed_gripper_q = np.asarray(
                    ctx.world.gripper_qpos_list(side),
                    dtype=np.float64,
                ).reshape(2)
                observed_gripper_qvel = np.asarray(
                    ctx.world.gripper_qvel_list(side),
                    dtype=np.float64,
                ).reshape(2)
                gripper_error = (
                    capture_state["gripper_q"][side] - observed_gripper_q
                )
                gripper_observation[side] = {
                    "capture_qpos_m": capture_state["gripper_q"][side]
                    .astype(float)
                    .tolist(),
                    "observed_qpos_m": observed_gripper_q.astype(float).tolist(),
                    "observed_qvel_mps": observed_gripper_qvel.astype(float).tolist(),
                    "error_m": gripper_error.astype(float).tolist(),
                    "drift_inf_m": float(
                        np.linalg.norm(gripper_error, ord=np.inf)
                    ),
                    "close_keepalive_active": bool(
                        getattr(
                            ctx.world,
                            "gripper_close_keepalive_active",
                            lambda _arm: False,
                        )(side)
                    ),
                    "effort_controlled": bool(
                        getattr(
                            ctx.world,
                            "gripper_uses_effort",
                            lambda _arm: False,
                        )(side)
                    ),
                }
            current_gripper_drift = max(
                float(item["drift_inf_m"])
                for item in gripper_observation.values()
            )
            max_gripper_drift = max(
                max_gripper_drift,
                current_gripper_drift,
            )
            final_gripper_drift = current_gripper_drift
            safety_reason, safety_observation = _adjust_safety_after_action(
                ctx,
                safety_monitor,
                before=before,
                command=command,
                after=after,
                base_translation_limit_m=(
                    MOVE_POINT_TO_POINT_BASE_TRANSLATION_LIMIT_M
                ),
                base_yaw_limit_rad=MOVE_POINT_TO_POINT_BASE_YAW_LIMIT_RAD,
                proprio_stall_requires_stationary=True,
                expected_trunk=None,
            )
            last_waypoint = {
                "index": int(waypoint_index + 1),
                "command_role": (
                    "tracker_reacquisition_hold"
                    if command_is_reacquisition_hold
                    else (
                        "gripper_recovery_hold"
                        if command_is_gripper_recovery_hold
                        else "trajectory_waypoint"
                    )
                ),
                "tracking_error_inf_rad": error,
                "arm_tracking_error_inf_rad": arm_error,
                "observed_joint_delta_inf_rad": observed_joint_delta,
                "observed_arm_qvel_inf_rad_s": observed_arm_qvel,
                "inactive_arm_drift_inf_rad": inactive_drift,
                "gripper_drift_inf_m": current_gripper_drift,
                "gripper_observation": gripper_observation,
                "safety_observation": safety_observation,
            }
            monitor_requests_reacquisition_hold = False
            if callable(step_monitor):
                monitor_reason, last_step_monitor = step_monitor(
                    after,
                    int(sequence),
                )
                if monitor_reason is not None:
                    reason = str(monitor_reason)
                    break
                monitor_requests_reacquisition_hold = bool(
                    last_step_monitor.get("temporarily_unobserved", False)
                )
            if (
                safety_reason == "proprio_stall"
                and recover_active_arm_disturbance
                and error > max_tracking_error
            ):
                # A finite active-arm displacement can be an external tug, not
                # a controller failure.  Reissuing the immutable target is the
                # recovery; timeout and max_steps remain the hard bound.
                safety_reason = None
                safety_monitor.proprio_stall_steps = 0
            if safety_reason is not None:
                reason = safety_reason
                break
            if inactive_drift > MOVE_POINT_TO_POINT_START_ARM_TOLERANCE_RAD:
                reason = "inactive_arm_drift"
                break
            if continue_during_gripper_disturbance:
                disturbance_now = bool(
                    current_gripper_drift
                    > MOVE_TRACKED_POINT_GRIPPER_RECOVERY_SOFT_LIMIT_M
                )
                if disturbance_now:
                    gripper_disturbance_steps += 1
                    gripper_recovery_steps += 1
                    gripper_recovery_samples.append(
                        {
                            "waypoint_index": int(waypoint_index + 1),
                            "observation_sequence": int(sequence),
                            "drift_inf_m": float(current_gripper_drift),
                            "gripper_observation": gripper_observation,
                            "arm_trajectory_continued": True,
                        }
                    )
                    if not gripper_disturbance_active:
                        gripper_recovery_events.append(
                            {
                                "event": "concurrent_recovery_started",
                                "waypoint_index": int(waypoint_index + 1),
                                "observation_sequence": int(sequence),
                                "drift_inf_m": float(current_gripper_drift),
                                "soft_limit_m": float(
                                    MOVE_TRACKED_POINT_GRIPPER_RECOVERY_SOFT_LIMIT_M
                                ),
                                "hard_limit_m": float(
                                    MOVE_TRACKED_POINT_GRIPPER_RECOVERY_HARD_LIMIT_M
                                ),
                                "arm_trajectory_continued": True,
                            }
                        )
                    gripper_disturbance_active = True
                elif gripper_disturbance_active and (
                    current_gripper_drift
                    <= MOVE_TRACKED_POINT_GRIPPER_RECOVERY_RELEASE_M
                ):
                    gripper_recovery_events.append(
                        {
                            "event": "concurrent_recovery_observed",
                            "waypoint_index": int(waypoint_index + 1),
                            "observation_sequence": int(sequence),
                            "drift_inf_m": float(current_gripper_drift),
                            "disturbance_steps": int(gripper_disturbance_steps),
                            "arm_trajectory_continued": True,
                        }
                    )
                    gripper_disturbance_active = False
            elif (
                current_gripper_drift
                > MOVE_TRACKED_POINT_GRIPPER_RECOVERY_HARD_LIMIT_M
            ):
                gripper_recovery_events.append(
                    {
                        "event": "hard_limit_exceeded",
                        "waypoint_index": int(waypoint_index + 1),
                        "observation_sequence": int(sequence),
                        "drift_inf_m": float(current_gripper_drift),
                        "hard_limit_m": float(
                            MOVE_TRACKED_POINT_GRIPPER_RECOVERY_HARD_LIMIT_M
                        ),
                        "gripper_observation": gripper_observation,
                    }
                )
                reason = "gripper_drift"
                break
            if (
                not continue_during_gripper_disturbance
                and gripper_recovery_hold_q is not None
            ):
                recovery_supported = bool(
                    gripper_recovery_fingers
                    and all(
                        bool(gripper_observation[side]["effort_controlled"])
                        and not bool(
                            gripper_observation[side]["close_keepalive_active"]
                        )
                        for side in gripper_recovery_fingers
                    )
                )
                if not recovery_supported:
                    gripper_recovery_events.append(
                        {
                            "event": "hard_limit_or_mode_failure",
                            "waypoint_index": int(waypoint_index + 1),
                            "observation_sequence": int(sequence),
                            "drift_inf_m": float(current_gripper_drift),
                            "gripper_observation": gripper_observation,
                        }
                    )
                    reason = "gripper_drift"
                    break
                gripper_recovery_steps += 1
                gripper_recovery_streak += 1
                recovery_drift = max(
                    abs(float(gripper_observation[side]["error_m"][index]))
                    for side, indices in gripper_recovery_fingers.items()
                    for index in indices
                )
                max_gripper_qvel = max(
                    abs(
                        float(
                            gripper_observation[side]["observed_qvel_mps"][
                                index
                            ]
                        )
                    )
                    for side, indices in gripper_recovery_fingers.items()
                    for index in indices
                )
                gripper_recovery_samples.append(
                    {
                        "waypoint_index": int(waypoint_index + 1),
                        "observation_sequence": int(sequence),
                        "recovery_streak": int(gripper_recovery_streak),
                        "drift_inf_m": float(recovery_drift),
                        "overall_drift_inf_m": float(current_gripper_drift),
                        "max_qvel_mps": float(max_gripper_qvel),
                        "recovery_fingers": {
                            side: list(indices)
                            for side, indices in gripper_recovery_fingers.items()
                        },
                        "qpos_m": {
                            side: list(item["observed_qpos_m"])
                            for side, item in gripper_observation.items()
                        },
                        "qvel_mps": {
                            side: list(item["observed_qvel_mps"])
                            for side, item in gripper_observation.items()
                        },
                        "command_n": {
                            side: list(
                                last_gripper_report.get(side, {}).get(
                                    "command", []
                                )
                            )
                            for side in ("left", "right")
                        },
                    }
                )
                recovery_sample_stable = bool(
                    recovery_drift
                    <= MOVE_TRACKED_POINT_GRIPPER_RECOVERY_RELEASE_M
                    and max_gripper_qvel
                    <= MOVE_TRACKED_POINT_GRIPPER_RECOVERY_QVEL_MPS
                )
                gripper_recovery_stable_steps = (
                    gripper_recovery_stable_steps + 1
                    if recovery_sample_stable
                    else 0
                )
                if (
                    gripper_recovery_stable_steps
                    >= MOVE_TRACKED_POINT_GRIPPER_RECOVERY_STABLE_STEPS
                ):
                    gripper_recovery_events.append(
                        {
                            "event": "recovered",
                            "waypoint_index": int(waypoint_index + 1),
                            "observation_sequence": int(sequence),
                            "drift_inf_m": float(recovery_drift),
                            "overall_drift_inf_m": float(
                                current_gripper_drift
                            ),
                            "max_qvel_mps": float(max_gripper_qvel),
                            "recovery_streak": int(gripper_recovery_streak),
                            "stable_steps": int(
                                gripper_recovery_stable_steps
                            ),
                        }
                    )
                    gripper_recovery_hold_q = None
                    gripper_recovery_fingers = {}
                    gripper_recovery_streak = 0
                    gripper_recovery_stable_steps = 0
                    previous_error = float("inf")
                    waypoint_stall_steps = 0
                    # The arm was deliberately held while the fingers
                    # recovered. Re-issue this same immutable waypoint.
                    continue
                if (
                    gripper_recovery_streak
                    >= MOVE_TRACKED_POINT_GRIPPER_RECOVERY_MAX_STEPS
                ):
                    gripper_recovery_events.append(
                        {
                            "event": "recovery_exhausted",
                            "waypoint_index": int(waypoint_index + 1),
                            "observation_sequence": int(sequence),
                            "drift_inf_m": float(recovery_drift),
                            "overall_drift_inf_m": float(
                                current_gripper_drift
                            ),
                            "max_qvel_mps": float(max_gripper_qvel),
                            "recovery_streak": int(gripper_recovery_streak),
                        }
                    )
                    reason = "gripper_drift"
                    break
                previous_error = float("inf")
                waypoint_stall_steps = 0
                continue
            recoverable_fingers: dict[str, list[int]] = {}
            if allow_gripper_recovery and not continue_during_gripper_disturbance:
                for side, item in gripper_observation.items():
                    if not bool(item["effort_controlled"]) or bool(
                        item["close_keepalive_active"]
                    ):
                        continue
                    capture_q = np.asarray(
                        item["capture_qpos_m"], dtype=np.float64
                    )
                    error_q = np.asarray(item["error_m"], dtype=np.float64)
                    indices = np.flatnonzero(
                        np.logical_and(
                            capture_q
                            >= MOVE_TRACKED_POINT_GRIPPER_OPEN_HOLD_THRESHOLD_M,
                            error_q
                            > MOVE_TRACKED_POINT_GRIPPER_RECOVERY_SOFT_LIMIT_M,
                        )
                    ).astype(int).tolist()
                    if indices:
                        recoverable_fingers[side] = indices
            if recoverable_fingers:
                gripper_recovery_hold_q = np.asarray(
                    after["q"], dtype=np.float64
                ).reshape(ARM_DOF).copy()
                gripper_recovery_fingers = {
                    side: list(indices)
                    for side, indices in recoverable_fingers.items()
                }
                gripper_recovery_streak = 0
                gripper_recovery_stable_steps = 0
                gripper_recovery_events.append(
                    {
                        "event": "hold_started",
                        "waypoint_index": int(waypoint_index + 1),
                        "observation_sequence": int(sequence),
                        "recovery_fingers": {
                            side: list(indices)
                            for side, indices in gripper_recovery_fingers.items()
                        },
                        "drift_inf_m": float(current_gripper_drift),
                        "soft_limit_m": float(
                            MOVE_TRACKED_POINT_GRIPPER_RECOVERY_SOFT_LIMIT_M
                        ),
                        "release_limit_m": float(
                            MOVE_TRACKED_POINT_GRIPPER_RECOVERY_RELEASE_M
                        ),
                        "hard_limit_m": float(
                            MOVE_TRACKED_POINT_GRIPPER_RECOVERY_HARD_LIMIT_M
                        ),
                        "gripper_observation": gripper_observation,
                        "hold_q_rad": gripper_recovery_hold_q.astype(
                            float
                        ).tolist(),
                    }
                )
                previous_error = float("inf")
                waypoint_stall_steps = 0
                continue
            if ARM_DOF == 8:
                raw_inactive = np.asarray(
                    ctx.world.arm_qpos_list(inactive_arm),
                    dtype=np.float64,
                ).reshape(ARM_DOF)
                if (
                    abs(float(raw_inactive[7]))
                    > LOCKED_J8_CAPTURE_TOLERANCE_RAD
                ):
                    reason = "inactive_arm_j8_not_locked"
                    break
            if error > max_tracking_error:
                moving_toward_target = bool(
                    math.isfinite(observed_joint_delta)
                    and observed_joint_delta > 1.0e-5
                ) or bool(
                    math.isfinite(observed_arm_qvel)
                    and observed_arm_qvel > 1.0e-3
                )
                if recover_active_arm_disturbance:
                    tracking_recovery_steps += 1
                    tracking_recovery_events.append(
                        {
                            "waypoint_index": int(waypoint_index + 1),
                            "attempt": int(tracking_recovery_steps),
                            "tracking_error_inf_rad": float(error),
                            "observed_joint_delta_inf_rad": float(
                                observed_joint_delta
                            ),
                            "observed_arm_qvel_inf_rad_s": float(
                                observed_arm_qvel
                            ),
                            "reason": "external_disturbance_target_reissued",
                            "bounded_by": "timeout_and_max_steps",
                        }
                    )
                    previous_error = error
                    continue
                if (
                    continuous_stream
                    and moving_toward_target
                    and error <= MOVE_TRACKED_POINT_STREAM_RECOVERY_ERROR_RAD
                    and tracking_recovery_steps
                    < MOVE_TRACKED_POINT_STREAM_MAX_RECOVERY_STEPS
                ):
                    tracking_recovery_steps += 1
                    tracking_recovery_events.append(
                        {
                            "waypoint_index": int(waypoint_index + 1),
                            "attempt": int(tracking_recovery_steps),
                            "tracking_error_inf_rad": float(error),
                            "observed_joint_delta_inf_rad": float(
                                observed_joint_delta
                            ),
                            "observed_arm_qvel_inf_rad_s": float(
                                observed_arm_qvel
                            ),
                            "reason": "moving_toward_target_retry",
                        }
                    )
                    # Re-send the same command once.  This is an execution
                    # recovery only; the signed waypoint order and endpoint
                    # remain unchanged.  A hard retry bound prevents a slow
                    # controller from consuming the entire evaluator budget.
                    previous_error = error
                    continue
                reason = "tracking_error"
                break
            tracking_recovery_steps = 0
            if monitor_requests_reacquisition_hold:
                if tracker_reacquisition_hold_q is None:
                    tracker_reacquisition_hold_q = np.asarray(
                        after["q"], dtype=np.float64
                    ).reshape(ARM_DOF).copy()
                    tracker_reacquisition_events.append(
                        {
                            "event": "hold_started",
                            "waypoint_index": int(waypoint_index + 1),
                            "observation_sequence": int(sequence),
                            "hold_q_rad": tracker_reacquisition_hold_q.astype(
                                float
                            ).tolist(),
                        }
                    )
                previous_error = float("inf")
                waypoint_stall_steps = 0
                continue
            if command_is_reacquisition_hold:
                tracker_reacquisition_events.append(
                    {
                        "event": "observation_reacquired",
                        "waypoint_index": int(waypoint_index + 1),
                        "observation_sequence": int(sequence),
                        "hold_steps": int(tracker_reacquisition_hold_steps),
                    }
                )
                tracker_reacquisition_hold_q = None
                previous_error = float("inf")
                waypoint_stall_steps = 0
                # Resume this same immutable waypoint on the next evaluator step.
                continue
            if continuous_stream:
                # This waypoint is one sample of a globally time-parameterized
                # trajectory, not a pose at which the robot should stop.  One
                # fresh evaluator observation validates its tracking corridor;
                # the final target receives the ordinary stable-pose check.
                completed_waypoints += 1
                break
            if error <= waypoint_tolerance:
                completed_waypoints += 1
                break
            # A finite-impedance controller can briefly overshoot a close
            # waypoint while the arm is still moving quickly.  Error
            # monotonicity alone therefore cannot establish a proprioceptive
            # stall.  Require both negligible measured displacement and low
            # measured velocity so transient inertia remains executable while
            # a genuinely stationary controller still fails closed.
            waypoint_stall_steps = (
                waypoint_stall_steps + 1 if stalled_sample else 0
            )
            previous_error = error
            if waypoint_stall_steps >= ADJUST_EEF_STALL_STEPS:
                reason = "proprio_stall"
                break
        if reason != "trajectory_complete":
            break

    completed = bool(
        reason == "trajectory_complete"
        and completed_waypoints == len(execution_waypoints_list)
    )
    ctx.world.set_arm_pin_qpos(arm, last_observed["q"])
    return {
        "ok": completed,
        "reason": reason,
        "controller": (
            "immutable_signed_joint_trajectory_stream"
            if continuous_stream
            else "immutable_signed_joint_waypoint_replay"
        ),
        "execution_mode": execution_mode,
        "waypoint_completion_semantics": (
            "one_official_action_per_waypoint_with_proprio_tracking_corridor"
            if continuous_stream
            else "hold_until_waypoint_tolerance"
        ),
        "observation_action_loop": True,
        "steps_executed": int(action_steps),
        "waypoint_count": int(len(execution_waypoints_list)),
        "signed_waypoint_count": int(signed_waypoint_count),
        "execution_schedule_applied": bool(execution_waypoints is not None),
        "execution_max_step_rad": float(bridge_step),
        "execution_bridge_waypoint_count": int(execution_bridge_waypoint_count),
        "execution_start_rebased": bool(allow_start_rebase),
        "trunk_motion": False,
        "waypoints_completed": int(completed_waypoints),
        "waypoint_tolerance_rad": waypoint_tolerance,
        "max_tracking_error_limit_rad": max_tracking_error,
        "max_observed_tracking_error_rad": float(
            max_observed_tracking_error
        ),
        "tracking_recovery_steps": int(
            sum(
                int(item.get("attempt", 0))
                for item in tracking_recovery_events
            )
        ),
        "tracking_recovery_events": tracking_recovery_events,
        "active_arm_disturbance_recovery_enabled": bool(
            recover_active_arm_disturbance
        ),
        "tracker_reacquisition_hold_steps": int(
            tracker_reacquisition_hold_steps
        ),
        "tracker_reacquisition_max_steps": tracker_reacquisition_max_steps,
        "tracker_reacquisition_events": tracker_reacquisition_events,
        "gripper_recovery_enabled": bool(allow_gripper_recovery),
        "gripper_recovery_concurrent_with_arm": bool(
            allow_gripper_recovery and continue_during_gripper_disturbance
        ),
        "gripper_recovery_steps": int(gripper_recovery_steps),
        "gripper_recovery_events": gripper_recovery_events,
        "gripper_recovery_samples": gripper_recovery_samples,
        "gripper_recovery_active_at_exit": bool(
            gripper_recovery_hold_q is not None or gripper_disturbance_active
        ),
        "gripper_recovery_fingers_active_at_exit": {
            side: list(indices)
            for side, indices in gripper_recovery_fingers.items()
        },
        "gripper_recovery_soft_limit_m": float(
            MOVE_TRACKED_POINT_GRIPPER_RECOVERY_SOFT_LIMIT_M
        ),
        "gripper_recovery_release_m": float(
            MOVE_TRACKED_POINT_GRIPPER_RECOVERY_RELEASE_M
        ),
        "gripper_recovery_hard_limit_m": float(
            MOVE_TRACKED_POINT_GRIPPER_RECOVERY_HARD_LIMIT_M
        ),
        "gripper_recovery_max_steps": int(
            MOVE_TRACKED_POINT_GRIPPER_RECOVERY_MAX_STEPS
        ),
        "gripper_recovery_required_stable_steps": int(
            MOVE_TRACKED_POINT_GRIPPER_RECOVERY_STABLE_STEPS
        ),
        "gripper_recovery_qvel_threshold_mps": float(
            MOVE_TRACKED_POINT_GRIPPER_RECOVERY_QVEL_MPS
        ),
        "gripper_recovery_effort_n": float(
            MOVE_TRACKED_POINT_GRIPPER_OPEN_RECOVERY_EFFORT_N
        ),
        "gripper_recovery_target_policy": (
            "concurrent_servo_without_arm_interruption_final_goal_revalidated"
            if continue_during_gripper_disturbance
            else "near_open_inward_drift_only_intermediate_and_close_latch_unchanged"
        ),
        "max_inactive_arm_drift_inf_rad": float(max_inactive_arm_drift),
        "max_gripper_drift_inf_m": float(max_gripper_drift),
        "final_gripper_drift_inf_m": float(final_gripper_drift),
        "max_observed_j8_abs_rad": float(max_observed_j8),
        "gripper_command": last_gripper_report,
        "safety": _adjust_safety_report(safety_monitor),
        "last_waypoint": last_waypoint,
        "last_step_monitor": last_step_monitor,
        "last_observation_sequence": int(sequence),
    }


def _move_point_is_cancellation(exc: BaseException) -> bool:
    return any(
        cls.__name__ == "SkillCancelled"
        for cls in type(exc).__mro__
    )


def _move_point_verify_stable_pose(
    ctx,
    *,
    arm: str,
    adapter,
    observation_sequence: int,
    target_position: np.ndarray,
    target_quaternion: np.ndarray,
    target_q: np.ndarray | None = None,
    pos_tol: float,
    ori_tol_deg: float,
    timeout_s: float,
    expected_episode_id: str | None = None,
):
    sequence = int(observation_sequence)
    observation = _adjust_kinematic_observation(ctx, arm)
    hold_q = (
        observation["q"].copy()
        if target_q is None
        else _require_serialized_j8_zero(
            target_q,
            label=f"{arm} final stability target q",
        )
    )
    stable_steps = 0
    verification_steps = 0
    reason = "stable_steps_not_met"
    started = time.monotonic()
    final_position_error = float("inf")
    final_orientation_error = float("inf")
    final_qvel_inf = float("inf")
    final_raw_qvel_inf = float("inf")
    final_position_step_inf = float("inf")
    filtered_limit_velocity_joints: list[str] = []
    previous_q = observation["q"].copy()

    while verification_steps < MOVE_POINT_TO_POINT_MAX_STABILITY_STEPS:
        _check_cancelled(
            ctx,
            f"move_point_to_point stability step {verification_steps + 1}",
        )
        if (
            expected_episode_id is not None
            and str(ctx.world.episode_id()) != str(expected_episode_id)
        ):
            reason = "episode_changed"
            break
        if time.monotonic() - started >= max(0.1, float(timeout_s)):
            reason = "timeout"
            break

        yield _adjust_action(ctx, arm, hold_q)
        verification_steps += 1
        advanced, current_sequence = _adjust_observation_advanced(
            adapter,
            sequence,
        )
        if not advanced:
            reason = "observation_not_advanced"
            break
        sequence = current_sequence
        if (
            expected_episode_id is not None
            and str(ctx.world.episode_id()) != str(expected_episode_id)
        ):
            reason = "episode_changed"
            break
        observation = _adjust_kinematic_observation(ctx, arm)
        final_position_error = float(
            np.linalg.norm(
                np.asarray(target_position, dtype=np.float64)
                - observation["position"]
            )
        )
        final_orientation_error = orientation_error_deg(
            observation["quaternion"],
            target_quaternion,
        )
        (
            final_raw_qvel_inf,
            final_qvel_inf,
            final_position_step_inf,
            filtered_limit_velocity_joints,
        ) = _move_point_effective_stability_qvel(
            arm=arm,
            previous_q=previous_q,
            current_q=observation["q"],
            current_qvel=observation["qvel"],
        )
        previous_q = observation["q"].copy()
        sample_stable = bool(
            final_position_error <= max(0.001, float(pos_tol))
            and final_orientation_error <= max(0.1, float(ori_tol_deg))
            and final_qvel_inf <= MOVE_POINT_TO_POINT_FINAL_ARM_QVEL_RAD_S
            and abs(float(observation["observed_j8"]))
            <= LOCKED_J8_CAPTURE_TOLERANCE_RAD
        )
        stable_steps = stable_steps + 1 if sample_stable else 0
        if stable_steps >= MOVE_POINT_TO_POINT_STABLE_STEPS:
            reason = "stable_pose_converged"
            break

    ctx.world.set_arm_pin_qpos(arm, observation["q"])
    return {
        "ok": bool(stable_steps >= MOVE_POINT_TO_POINT_STABLE_STEPS),
        "reason": reason,
        "required_stable_steps": int(MOVE_POINT_TO_POINT_STABLE_STEPS),
        "stable_steps": int(stable_steps),
        "verification_steps": int(verification_steps),
        "arm_qvel_threshold_rad_s": float(
            MOVE_POINT_TO_POINT_FINAL_ARM_QVEL_RAD_S
        ),
        "final_arm_qvel_inf_rad_s": float(final_qvel_inf),
        "final_raw_arm_qvel_inf_rad_s": float(final_raw_qvel_inf),
        "final_position_step_inf_rad": float(final_position_step_inf),
        "filtered_limit_velocity_joints": list(
            filtered_limit_velocity_joints
        ),
        "limit_velocity_filter": {
            "limit_proximity_rad": float(
                MOVE_POINT_TO_POINT_FINAL_LIMIT_PROXIMITY_RAD
            ),
            "max_position_step_rad": float(
                MOVE_POINT_TO_POINT_FINAL_LIMIT_POSITION_STEP_RAD
            ),
            "applies_only_when_both_conditions_hold": True,
        },
        "final_position_error_m": float(final_position_error),
        "final_orientation_error_deg": float(final_orientation_error),
        "last_observation_sequence": int(sequence),
        "hold_target_q": hold_q.astype(float).tolist(),
    }


@dataclass
class _AdjustSafetyMonitor:
    trunk_start: np.ndarray
    base_xy_start: np.ndarray
    base_yaw_start: float
    proprio_stall_steps: int = 0
    tracking_error_steps: int = 0
    base_disturbance_steps: int = 0
    max_tracking_error_rad: float = 0.0
    min_progress_ratio: float = 1.0
    max_base_linear_speed_mps: float = 0.0
    max_base_yaw_rate_rad_s: float = 0.0
    max_base_translation_m: float = 0.0
    max_base_yaw_drift_rad: float = 0.0
    max_trunk_drift_rad: float = 0.0


def _adjust_angle_delta(current: float, start: float) -> float:
    delta = float(current) - float(start)
    return math.atan2(math.sin(delta), math.cos(delta))


def _adjust_safety_monitor(ctx, initial: dict[str, Any]) -> _AdjustSafetyMonitor:
    pose = ctx.world.robot_pose()
    return _AdjustSafetyMonitor(
        trunk_start=np.asarray(initial["trunk"], dtype=np.float64)[:3].copy(),
        base_xy_start=np.asarray(pose.pos, dtype=np.float64)[:2].copy(),
        base_yaw_start=float(pose.yaw),
    )


def _adjust_safety_report(monitor: _AdjustSafetyMonitor) -> dict[str, Any]:
    return {
        "fresh_observation_stall_limit": int(ADJUST_EEF_STALL_STEPS),
        "proprio_stall_steps": int(monitor.proprio_stall_steps),
        "tracking_error_steps": int(monitor.tracking_error_steps),
        "tracking_error_is_diagnostic_only": True,
        "base_disturbance_steps": int(monitor.base_disturbance_steps),
        "min_command_progress_ratio": float(monitor.min_progress_ratio),
        "max_tracking_error_inf_rad": float(monitor.max_tracking_error_rad),
        "max_base_linear_speed_mps": float(monitor.max_base_linear_speed_mps),
        "max_base_yaw_rate_rad_s": float(monitor.max_base_yaw_rate_rad_s),
        "max_base_translation_m": float(monitor.max_base_translation_m),
        "max_base_yaw_drift_rad": float(monitor.max_base_yaw_drift_rad),
        "max_trunk_q123_drift_inf_rad": float(monitor.max_trunk_drift_rad),
    }


def _adjust_next_step_scale(
    current_scale: float,
    safety_observation: dict[str, Any],
    *,
    near_target: bool,
) -> float:
    """Increase command reach only after one well-tracked official action."""

    scale = float(
        np.clip(
            current_scale,
            ADJUST_EEF_ADAPTIVE_MIN_SCALE,
            ADJUST_EEF_ADAPTIVE_MAX_SCALE,
        )
    )
    if near_target:
        return min(scale, 1.0)
    progress_ratio = float(
        safety_observation.get("command_progress_ratio", 0.0)
    )
    tracking_error = float(
        safety_observation.get("tracking_error_inf_rad", float("inf"))
    )
    if (
        progress_ratio >= ADJUST_EEF_ADAPTIVE_GOOD_PROGRESS_RATIO
        and tracking_error <= ADJUST_EEF_ADAPTIVE_GOOD_TRACKING_ERROR_RAD
    ):
        return min(
            ADJUST_EEF_ADAPTIVE_MAX_SCALE,
            scale + ADJUST_EEF_ADAPTIVE_SCALE_INCREMENT,
        )
    if (
        progress_ratio < ADJUST_EEF_ADAPTIVE_POOR_PROGRESS_RATIO
        or tracking_error > ADJUST_EEF_ADAPTIVE_POOR_TRACKING_ERROR_RAD
    ):
        return max(ADJUST_EEF_ADAPTIVE_MIN_SCALE, 0.5 * scale)
    return scale


def _adjust_settle_steps(
    measured: dict[str, Any],
    *,
    target_reached: bool,
    skip_when_reached: bool,
) -> int:
    """Choose a bounded measured-hold tail from evaluator proprioception."""

    if not target_reached:
        return ADJUST_EEF_FAILURE_SETTLE_STEPS
    if skip_when_reached:
        return 0
    qvel = np.asarray(measured.get("qvel", []), dtype=np.float64).reshape(-1)
    if qvel.size >= 7 and np.all(np.isfinite(qvel[:7])):
        if float(np.linalg.norm(qvel[:7], ord=np.inf)) <= ADJUST_EEF_SETTLED_QVEL_RAD_S:
            return 0
    return ADJUST_EEF_SUCCESS_SETTLE_MAX_STEPS


def _adjust_safety_after_action(
    ctx,
    monitor: _AdjustSafetyMonitor,
    *,
    before: dict[str, Any],
    command: np.ndarray,
    after: dict[str, Any],
    base_translation_limit_m: float = ADJUST_EEF_BASE_TRANSLATION_LIMIT_M,
    base_yaw_limit_rad: float = ADJUST_EEF_BASE_YAW_LIMIT_RAD,
    proprio_stall_requires_stationary: bool = False,
    expected_trunk: Sequence[float] | None = None,
) -> tuple[str | None, dict[str, Any]]:
    command_delta = np.asarray(command[:7], dtype=np.float64) - np.asarray(
        before["q"][:7],
        dtype=np.float64,
    )
    actual_delta = np.asarray(after["q"][:7], dtype=np.float64) - np.asarray(
        before["q"][:7],
        dtype=np.float64,
    )
    command_inf = float(np.linalg.norm(command_delta, ord=np.inf))
    progress_ratio = 1.0
    if command_inf >= ADJUST_EEF_MIN_COMMAND_RAD:
        denominator = float(command_delta @ command_delta)
        progress_ratio = float(actual_delta @ command_delta) / max(
            denominator,
            1e-12,
        )
        monitor.min_progress_ratio = min(
            monitor.min_progress_ratio,
            progress_ratio,
        )
        low_progress = bool(progress_ratio < ADJUST_EEF_MIN_PROGRESS_RATIO)
        if proprio_stall_requires_stationary:
            observed_joint_delta = float(
                np.linalg.norm(actual_delta, ord=np.inf)
            )
            observed_arm_qvel = float(
                np.linalg.norm(
                    np.asarray(after.get("qvel", []), dtype=np.float64)[:7],
                    ord=np.inf,
                )
            )
            low_progress = bool(
                low_progress
                and observed_joint_delta
                <= MOVE_POINT_TO_POINT_STALL_POSITION_DELTA_RAD
                and observed_arm_qvel
                <= MOVE_POINT_TO_POINT_STALL_QVEL_RAD_S
            )
        monitor.proprio_stall_steps = (
            monitor.proprio_stall_steps + 1 if low_progress else 0
        )
    else:
        monitor.proprio_stall_steps = 0

    tracking_error = float(
        np.linalg.norm(after["q"][:7] - command[:7], ord=np.inf)
    )
    monitor.max_tracking_error_rad = max(
        monitor.max_tracking_error_rad,
        tracking_error,
    )
    monitor.tracking_error_steps = (
        monitor.tracking_error_steps + 1
        if tracking_error > ADJUST_EEF_MAX_TRACKING_ERROR_RAD
        else 0
    )
    # Match v2's finite-impedance loop: command tracking lag is telemetry, not
    # a failure. Every action is a fresh measured-q tangent target, so a joint
    # need not settle to the previous one-frame target before the loop advances.
    # Directional progress below the floor is handled separately by the true
    # proprio_stall guard.

    base_qvel = np.asarray(after["base_qvel"], dtype=np.float64).reshape(3)
    base_linear_speed = float(np.linalg.norm(base_qvel[:2]))
    base_yaw_rate = abs(float(base_qvel[2]))
    monitor.max_base_linear_speed_mps = max(
        monitor.max_base_linear_speed_mps,
        base_linear_speed,
    )
    monitor.max_base_yaw_rate_rad_s = max(
        monitor.max_base_yaw_rate_rad_s,
        base_yaw_rate,
    )
    base_velocity_disturbed = bool(
        base_linear_speed > ADJUST_EEF_BASE_LINEAR_DISTURBANCE_MPS
        or base_yaw_rate > ADJUST_EEF_BASE_YAW_DISTURBANCE_RAD_S
    )
    monitor.base_disturbance_steps = (
        monitor.base_disturbance_steps + 1
        if base_velocity_disturbed
        else 0
    )

    pose = ctx.world.robot_pose()
    base_translation = float(
        np.linalg.norm(
            np.asarray(pose.pos, dtype=np.float64)[:2]
            - monitor.base_xy_start
        )
    )
    base_yaw_drift = abs(
        _adjust_angle_delta(float(pose.yaw), monitor.base_yaw_start)
    )
    monitor.max_base_translation_m = max(
        monitor.max_base_translation_m,
        base_translation,
    )
    monitor.max_base_yaw_drift_rad = max(
        monitor.max_base_yaw_drift_rad,
        base_yaw_drift,
    )

    trunk_drift = float(
        np.linalg.norm(
            np.asarray(after["trunk"], dtype=np.float64)[:3]
            - monitor.trunk_start,
            ord=np.inf,
        )
    )
    monitor.max_trunk_drift_rad = max(
        monitor.max_trunk_drift_rad,
        trunk_drift,
    )
    trunk_tracking_error = 0.0
    if expected_trunk is not None:
        expected_trunk_array = np.asarray(
            expected_trunk, dtype=np.float64
        ).reshape(4)
        if not np.all(np.isfinite(expected_trunk_array)):
            raise ValueError("expected trunk command is non-finite")
        trunk_tracking_error = float(
            np.linalg.norm(
                np.asarray(after["trunk"], dtype=np.float64).reshape(4)
                - expected_trunk_array,
                ord=np.inf,
            )
        )

    reason = None
    if (
        base_linear_speed > ADJUST_EEF_BASE_IMMEDIATE_LINEAR_MPS
        or base_yaw_rate > ADJUST_EEF_BASE_IMMEDIATE_YAW_RAD_S
    ):
        reason = "base_disturbance"
    elif (
        base_translation > float(base_translation_limit_m)
        or base_yaw_drift > float(base_yaw_limit_rad)
    ):
        reason = "base_odometry_disturbance"
    elif (
        expected_trunk is None
        and trunk_drift > ADJUST_EEF_TRUNK_DRIFT_LIMIT_RAD
    ):
        reason = "trunk_disturbance"
    elif monitor.base_disturbance_steps >= ADJUST_EEF_BASE_DISTURBANCE_STEPS:
        reason = "base_disturbance"
    elif monitor.proprio_stall_steps >= ADJUST_EEF_STALL_STEPS:
        reason = "proprio_stall"

    return reason, {
        "command_inf_rad": command_inf,
        "command_progress_ratio": progress_ratio,
        "tracking_error_inf_rad": tracking_error,
        "proprio_stall_requires_stationary": bool(
            proprio_stall_requires_stationary
        ),
        "base_linear_speed_mps": base_linear_speed,
        "base_yaw_rate_rad_s": base_yaw_rate,
        "base_translation_m": base_translation,
        "base_translation_limit_m": float(base_translation_limit_m),
        "base_yaw_drift_rad": base_yaw_drift,
        "base_yaw_limit_rad": float(base_yaw_limit_rad),
        "trunk_q123_drift_inf_rad": trunk_drift,
        "trunk_motion_commanded": bool(expected_trunk is not None),
        "trunk_tracking_error_inf_rad": float(trunk_tracking_error),
    }


def _adjust_adapter(ctx):
    adapter = getattr(ctx.world, "_official_adapter", None)
    if adapter is None:
        raise RuntimeError("official evaluator observation adapter is unavailable")
    snapshot = adapter.snapshot()
    if int(snapshot.sequence) <= 0 or float(snapshot.received_ts) <= 0.0:
        raise RuntimeError("no evaluator observation is available")
    proprio = adapter.proprio_vector()
    if proprio is None:
        raise RuntimeError("evaluator proprioception is unavailable")
    return adapter, int(snapshot.sequence)


def _adjust_camera_pose(ctx, role: str) -> tuple[dict[str, Any], int, Any]:
    adapter, sequence = _adjust_adapter(ctx)
    camera = dict(adapter.camera_relative_poses().get(str(role)) or {})
    if camera.get("pos") is None or camera.get("quat") is None:
        raise RuntimeError(
            f"evaluator {role} camera-relative pose is unavailable"
        )
    position = np.asarray(camera["pos"], dtype=np.float64).reshape(3)
    quaternion = np.asarray(camera["quat"], dtype=np.float64).reshape(4)
    if not np.all(np.isfinite(position)) or not np.all(np.isfinite(quaternion)):
        raise RuntimeError(f"evaluator {role} camera-relative pose is invalid")
    quaternion_norm = float(np.linalg.norm(quaternion))
    if quaternion_norm <= 1e-9:
        raise RuntimeError(f"evaluator {role} camera quaternion is invalid")
    return {
        "pos": position,
        "quat": quaternion / quaternion_norm,
        "frame": "robot_base",
        "source": "evaluator_cam_rel_poses",
    }, sequence, adapter


def _move_tracked_head_camera_pose(
    ctx,
    *,
    expected_sequence: int,
) -> tuple[np.ndarray, np.ndarray]:
    """Read the frozen head camera pose used by camera-facing presets."""

    camera, sequence, _adapter = _adjust_camera_pose(ctx, "head")
    if int(sequence) != int(expected_sequence):
        raise RuntimeError(
            "head camera pose is not synchronized with the tracked-point observation"
        )
    position = np.asarray(camera["pos"], dtype=np.float64).reshape(3)
    quaternion = np.asarray(camera["quat"], dtype=np.float64).reshape(4)
    if not np.all(np.isfinite(position)) or not np.all(np.isfinite(quaternion)):
        raise RuntimeError("head camera pose contains a non-finite value")
    return position.copy(), quaternion.copy()


def _move_tracked_camera_pose_payload(
    position: Sequence[float] | None,
    quaternion: Sequence[float] | None,
    *,
    label: str = "move-tracked head camera pose",
) -> dict[str, Any] | None:
    """Validate and canonicalize a camera pose persisted with a faceto plan.

    A camera-relative pose is policy observation data, not simulator state.  Keep
    the signed representation small and deterministic so a plan reload uses the
    exact same optical axis that was used to solve its endpoint.
    """

    if position is None and quaternion is None:
        return None
    if position is None or quaternion is None:
        raise ValueError(f"{label} requires both position and quaternion")
    try:
        position_array = np.asarray(position, dtype=np.float64).reshape(3)
        quaternion_array = np.asarray(quaternion, dtype=np.float64).reshape(4)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{label} must contain a 3-vector and a 4-vector") from exc
    if not np.all(np.isfinite(position_array)) or not np.all(
        np.isfinite(quaternion_array)
    ):
        raise ValueError(f"{label} contains a non-finite value")
    norm = float(np.linalg.norm(quaternion_array))
    if norm <= 1.0e-12:
        raise ValueError(f"{label} quaternion is degenerate")
    return {
        "position_robot_base_m": position_array.astype(float).tolist(),
        "quaternion_xyzw": (quaternion_array / norm).astype(float).tolist(),
        "frame": "robot_base",
        "source": "frozen_evaluator_cam_rel_poses",
    }


def _adjust_gripper_vector(value: Any) -> np.ndarray:
    raw = np.asarray(value if value is not None else [], dtype=np.float64).reshape(-1)
    if raw.size < 2:
        raw = np.pad(raw, (0, 2 - raw.size))
    raw = raw[:2]
    if not np.all(np.isfinite(raw)):
        raise RuntimeError("evaluator gripper proprioception is invalid")
    return raw


def _adjust_kinematic_observation(ctx, arm: str) -> dict[str, Any]:
    side = str(arm).strip().lower()
    if side not in ("left", "right"):
        raise ValueError("arm must be left or right")
    trunk = np.asarray(ctx.world.trunk_qpos(), dtype=np.float64).reshape(-1)
    if trunk.size != 4 or not np.all(np.isfinite(trunk)):
        raise RuntimeError("evaluator trunk proprioception is invalid")
    raw_left = np.asarray(
        ctx.world.arm_qpos_list("left"),
        dtype=np.float64,
    ).reshape(-1)
    raw_right = np.asarray(
        ctx.world.arm_qpos_list("right"),
        dtype=np.float64,
    ).reshape(-1)
    raw_selected_qvel = np.asarray(
        ctx.world.arm_qvel_list(side),
        dtype=np.float64,
    ).reshape(-1)
    if (
        raw_selected_qvel.size < ARM_DOF
        or not np.all(np.isfinite(raw_selected_qvel[:ARM_DOF]))
    ):
        raise RuntimeError(f"evaluator {side} arm qvel is invalid")
    base_qvel = np.asarray(
        ctx.world.base_qvel(),
        dtype=np.float64,
    ).reshape(-1)
    if base_qvel.size < 3 or not np.all(np.isfinite(base_qvel[:3])):
        raise RuntimeError("evaluator base qvel is invalid")
    left = locked_arm_vector(raw_left, label="left arm proprioception")
    right = locked_arm_vector(raw_right, label="right arm proprioception")
    gripper_left = _adjust_gripper_vector(
        ctx.world.gripper_qpos_list("left")
    )
    gripper_right = _adjust_gripper_vector(
        ctx.world.gripper_qpos_list("right")
    )
    state = local_robot_state(
        trunk_q=trunk,
        arm_left_q=left,
        arm_right_q=right,
        gripper_left_q=gripper_left,
        gripper_right_q=gripper_right,
    )
    selected = left if side == "left" else right
    raw_selected = raw_left if side == "left" else raw_right
    position, quaternion = _local_eef_pose(state, side, selected)
    observed_j8 = (
        float(raw_selected[7])
        if ARM_DOF == 8 and raw_selected.size >= 8
        else 0.0
    )
    return {
        "state": state,
        "trunk": trunk,
        "left": left,
        "right": right,
        "q": selected.copy(),
        "raw_q": raw_selected.copy(),
        "qvel": raw_selected_qvel[:ARM_DOF].copy(),
        "base_qvel": base_qvel[:3].copy(),
        "position": np.asarray(position, dtype=np.float64).reshape(3),
        "quaternion": np.asarray(quaternion, dtype=np.float64).reshape(4),
        "observed_j8": observed_j8,
        "gripper": gripper_left if side == "left" else gripper_right,
    }


def _adjust_observation_advanced(adapter, previous_sequence: int) -> tuple[bool, int]:
    current_sequence, _received_ts = adapter.observation_metadata()
    return int(current_sequence) > int(previous_sequence), int(current_sequence)


def _adjust_action(ctx, arm: str, q_target: np.ndarray) -> np.ndarray:
    command = locked_arm_vector(q_target, label=f"{arm} action target")
    return ctx.world.make_action(**{f"arm_{arm}": command.tolist()})


def _move_tracked_execution_bridge(
    initial_q: np.ndarray,
    signed_waypoints: list[Any],
    *,
    arm: str,
    max_step_rad: float = MOVE_POINT_TO_POINT_MAX_JOINT_STEP_RAD,
) -> tuple[list[np.ndarray], int]:
    """Prepend bounded joint interpolation when handoff q differs from plan.

    The signed trajectory is never rewritten.  This returns an execution-only
    sequence whose first command starts at the latest evaluator proprioception
    and whose every adjacent joint step remains within the action contract.
    """

    if not math.isfinite(float(max_step_rad)) or float(max_step_rad) <= 0.0:
        raise ValueError("execution bridge max_step_rad must be positive and finite")
    current = locked_arm_vector(initial_q, label=f"{arm} handoff qpos").copy()
    limits = _ARM_LIMITS[arm][:ARM_DOF]
    if not np.all(np.isfinite(current)):
        raise ValueError("handoff qpos contains a non-finite value")

    execution: list[np.ndarray] = []
    bridge_count = 0
    # Proprioception is measured state, not a planned action.  A controller can
    # report a small residual just beyond a URDF limit after an otherwise valid
    # trajectory.  Recover it with one bounded, in-limit command before replaying
    # the signed trajectory.  Larger discrepancies still fail closed instead of
    # hiding a stale/wrong robot state.
    lower_violation = np.maximum(limits[:, 0] - current, 0.0)
    upper_violation = np.maximum(current - limits[:, 1], 0.0)
    limit_violation = np.maximum(lower_violation, upper_violation)
    max_limit_violation = float(np.max(limit_violation))
    if max_limit_violation > 0.0:
        if max_limit_violation > float(max_step_rad):
            joint_index = int(np.argmax(limit_violation))
            raise ValueError(
                "handoff qpos exceeds the recoverable local joint-limit "
                f"residual: arm={arm} J{joint_index + 1}="
                f"{current[joint_index]:.12g}rad outside "
                f"[{limits[joint_index, 0]:.12g},"
                f"{limits[joint_index, 1]:.12g}] by "
                f"{max_limit_violation:.12g}rad; max recoverable residual is "
                f"{float(max_step_rad):.12g}rad"
            )
        current = np.clip(current, limits[:, 0], limits[:, 1])
        current = _require_serialized_j8_zero(
            current,
            label=f"{arm} handoff joint-limit recovery waypoint",
        )
        execution.append(current.astype(np.float64, copy=False))
        bridge_count += 1

    for waypoint_index, raw_target in enumerate(signed_waypoints):
        target = _require_serialized_j8_zero(
            raw_target,
            label=f"move_tracked execution waypoint {waypoint_index + 1}",
        )
        delta = target - current
        max_delta = float(np.linalg.norm(delta, ord=np.inf))
        # The execution scheduler accepts a transition at ``cap +`` its
        # serialized lock tolerance.  Recomputing that same subtraction here
        # can differ by a few ULPs; a strict ceil then turns a valid one-step
        # transition into two commands.  Across a compressed path this used to
        # manufacture dozens of unbudgeted bridge actions and stop a healthy
        # trajectory near its endpoint.  Ignore only numerical-scale excess;
        # any physically meaningful excess is still split below.
        effective_delta = max(
            0.0,
            max_delta
            - MOVE_TRACKED_POINT_EXECUTION_STEP_NUMERIC_TOLERANCE_RAD,
        )
        segment_steps = max(
            1,
            int(math.ceil(effective_delta / float(max_step_rad))),
        )
        for step_index in range(1, segment_steps + 1):
            point = current + (delta * (float(step_index) / float(segment_steps)))
            point = _require_serialized_j8_zero(
                point,
                label=f"move_tracked execution bridge waypoint {len(execution) + 1}",
            )
            if np.any(point < limits[:, 0]) or np.any(point > limits[:, 1]):
                raise ValueError("execution bridge waypoint exceeds local joint limits")
            execution.append(point.astype(np.float64, copy=False))
        if segment_steps > 1:
            bridge_count += segment_steps - 1
        current = target.copy()
    if not execution:
        raise ValueError("signed trajectory has no execution waypoints")
    return execution, int(bridge_count)


def _move_tracked_prepare_execution_schedule(
    *,
    trajectory: dict[str, Any],
    state: LocalRobotState,
    arm: str,
    start_q: Sequence[float],
    max_steps: int,
    available_time_s: float,
    observation_dt_s: float | None,
    visual_tracked_point_count: int | None = None,
) -> dict[str, Any]:
    """Derive a bounded execution view of a signed local trajectory.

    Planning remains immutable and is still loaded/verified from disk.  This
    helper only chooses a monotone subsequence for the current evaluator
    budget; it never edits the signed trajectory or queries simulator state.
    """

    tracking = trajectory.get("tracking")
    if not isinstance(tracking, dict):
        raise ValueError("move-tracked trajectory tracking metadata is missing")
    if tracking.get("trunk_assisted") is True:
        raise ValueError(
            "move_tracked_point does not schedule whole-body trajectories"
        )
    scheduled_start_q, start_limit_recovery = _normalize_arm_q_to_joint_limits(
        start_q,
        arm=arm,
        label="move-tracked execution scheduling start qpos",
        point="execution_schedule_start",
        recover_observed_overshoot=True,
    )
    base_step = float(
        tracking.get("max_joint_step_rad", MOVE_TRACKED_POINT_MAX_JOINT_STEP_RAD)
    )
    # A measured start just outside a static local limit needs one explicit,
    # in-limit recovery command before the signed path.  Reserve that command
    # before scheduling rather than discovering it after the budget is full.
    start_bridge_reserve = 1 if start_limit_recovery else 0
    scheduled_max_steps = int(max_steps) - int(start_bridge_reserve)
    scheduled_available_time_s = float(available_time_s)
    if observation_dt_s is not None and start_bridge_reserve:
        scheduled_available_time_s -= float(observation_dt_s)
    if scheduled_max_steps < 1 or scheduled_available_time_s <= 0.0:
        return {
            "ok": False,
            "reason": "execution_budget_infeasible",
            "error": (
                "remaining evaluator budget cannot accommodate the observed "
                "joint-limit recovery and one trajectory action"
            ),
            "execution_start_joint_limit_recovery": _json_ready(
                start_limit_recovery
            ),
            "execution_bridge_reserved_waypoints": int(start_bridge_reserve),
            "budget_steps": int(max(0, max_steps)),
        }
    schedule_kwargs = {
        "start_q": scheduled_start_q,
        "max_steps": int(scheduled_max_steps),
        "available_time_s": float(scheduled_available_time_s),
        "observation_dt_s": observation_dt_s,
        "max_joint_step_rad": base_step,
        "preferred_max_steps": (
            MOVE_TRACKED_POINT_EXECUTION_PREFERRED_MAX_STEPS
        ),
        "max_joint_corridor_deviation_rad": (
            MOVE_TRACKED_POINT_EXECUTION_MAX_JOINT_CORRIDOR_DEVIATION_RAD
        ),
        "safety_time_steps": MOVE_TRACKED_POINT_EXECUTION_SAFETY_TIME_STEPS,
        "j8_index": LOCKED_J8_INDEX,
        "j8_value": LOCKED_J8_VALUE_RAD,
        "lock_tolerance": LOCKED_J8_SERIALIZED_TOLERANCE_RAD,
    }
    relaxed_execution = False
    visual_speedup_cap = (
        MOVE_TRACKED_POINT_NPOINT_VISUAL_MAX_SPEEDUP_FACTOR
        if visual_tracked_point_count is not None
        and int(visual_tracked_point_count)
        >= MOVE_TRACKED_POINT_NPOINT_VISUAL_MIN_POINTS
        else MOVE_TRACKED_POINT_EXECUTION_MAX_SPEEDUP_FACTOR
    )
    report = _schedule_tracked_execution_waypoints(
        trajectory.get("waypoints", []),
        max_speedup_factor=visual_speedup_cap,
        **schedule_kwargs,
    )
    if (
        not bool(report.get("ok"))
        and report.get("reason") == "execution_budget_infeasible"
        and visual_speedup_cap
        == MOVE_TRACKED_POINT_EXECUTION_MAX_SPEEDUP_FACTOR
    ):
        # Preserve the bounded scheduler byte-for-byte whenever it succeeds.
        # Only a path that cannot fit under that generic cap gets a second,
        # path-derived pass.  The signed trajectory already proved adjacent
        # same-branch IK continuity; this pass merely drops redundant temporal
        # samples and is revalidated by local FK below.
        bounded_report = {
            key: value
            for key, value in report.items()
            if key
            in {
                "reason",
                "error",
                "budget_steps",
                "time_budget_steps",
                "input_waypoint_count",
                "required_waypoints_at_max_speedup",
            }
        }
        relaxed_report = _schedule_tracked_execution_waypoints(
            trajectory.get("waypoints", []),
            max_speedup_factor=None,
            **schedule_kwargs,
        )
        relaxed_report["bounded_safety_attempt"] = bounded_report
        report = relaxed_report
        relaxed_execution = bool(report.get("ok"))
    if not bool(report.get("ok")):
        report["visual_tracked_point_count"] = visual_tracked_point_count
        report["visual_speedup_cap"] = float(visual_speedup_cap)
        return report

    schedule_drops_signed_samples = int(
        report.get("dropped_waypoint_count", 0)
    ) > 0
    if relaxed_execution or schedule_drops_signed_samples:
        # Every compressed schedule is admissible only for a trajectory whose
        # signed source already proved the IK branch and global path ordering.
        # This applies to both the bounded fast path and the last-resort
        # relaxed pass: either may omit samples, but neither may manufacture a
        # new branch or silently stop before the signed endpoint.
        planner = trajectory.get("planner")
        if not isinstance(planner, dict):
            return {
                **report,
                "ok": False,
                "reason": "execution_schedule_invalid",
                "error": "compressed execution requires signed planner metadata",
            }
        if (
            planner.get("same_branch_checked") is not True
            or planner.get("monotonic_progress_checked") is not True
            or planner.get("internal_stop_count") != 0
        ):
            return {
                **report,
                "ok": False,
                "reason": "execution_schedule_invalid",
                "error": (
                    "compressed execution requires a signed same-branch, "
                    "monotone trajectory"
                ),
            }
        signed_waypoints = trajectory.get("waypoints")
        selected_indices = report.get("selected_indices")
        selected_waypoints = report.get("waypoints")
        endpoint_index_valid = False
        if isinstance(selected_indices, list) and selected_indices:
            try:
                endpoint_index_valid = (
                    int(selected_indices[-1]) == len(signed_waypoints) - 1
                    if isinstance(signed_waypoints, list)
                    else False
                )
            except (TypeError, ValueError):
                endpoint_index_valid = False
        if (
            not isinstance(signed_waypoints, list)
            or not signed_waypoints
            or not isinstance(selected_indices, list)
            or not isinstance(selected_waypoints, list)
            or len(selected_indices) != len(selected_waypoints)
            or not selected_indices
            or not endpoint_index_valid
        ):
            return {
                **report,
                "ok": False,
                "reason": "execution_schedule_invalid",
                "error": "compressed execution must retain the signed endpoint",
            }
        previous_index = -1
        previous_q = scheduled_start_q.copy()
        local_lower, local_upper = _local_arm_joint_limits(state, arm)
        transition_limits = np.column_stack(
            (
                np.asarray(local_lower, dtype=np.float64).reshape(-1),
                np.asarray(local_upper, dtype=np.float64).reshape(-1),
            )
        )[:ARM_DOF]
        transition_samples = 0
        transition_max_step = 0.0
        for selected_index, raw_q in zip(selected_indices, selected_waypoints):
            try:
                source_index = int(selected_index)
            except (TypeError, ValueError):
                return {
                    **report,
                    "ok": False,
                    "reason": "execution_schedule_invalid",
                    "error": "relaxed execution contains a non-integer source index",
                }
            if source_index < 0 or source_index >= len(signed_waypoints):
                return {
                    **report,
                    "ok": False,
                    "reason": "execution_schedule_invalid",
                    "error": "relaxed execution source index is out of range",
                }
            if source_index <= previous_index:
                return {
                    **report,
                    "ok": False,
                    "reason": "execution_schedule_invalid",
                    "error": "relaxed execution source indices are not increasing",
                }
            target_q = _require_serialized_j8_zero(
                raw_q,
                label=f"relaxed execution transition {source_index}",
            )
            transition_step = float(
                np.linalg.norm(target_q - previous_q, ord=np.inf)
            )
            if not math.isfinite(transition_step):
                return {
                    **report,
                    "ok": False,
                    "reason": "execution_schedule_invalid",
                    "error": "relaxed execution transition is non-finite",
                }
            transition_max_step = max(transition_max_step, transition_step)
            sample_count = max(
                1,
                min(
                    32,
                    int(
                        math.ceil(
                            transition_step
                            / max(base_step, 1.0e-6)
                        )
                    ),
                ),
            )
            for sample_index in range(1, sample_count + 1):
                fraction = float(sample_index) / float(sample_count)
                q_sample = _require_serialized_j8_zero(
                    previous_q
                    + fraction * (target_q - previous_q),
                    label=(
                        "relaxed execution local-FK sample "
                        f"{source_index}:{sample_index}"
                    ),
                )
                if np.any(q_sample < transition_limits[:, 0]) or np.any(
                    q_sample > transition_limits[:, 1]
                ):
                    return {
                        **report,
                        "ok": False,
                        "reason": "execution_schedule_invalid",
                        "error": "relaxed execution transition exceeds local limits",
                    }
                position, quaternion = _local_eef_pose(state, arm, q_sample)
                if not np.all(np.isfinite(position)) or not np.all(
                    np.isfinite(quaternion)
                ):
                    return {
                        **report,
                        "ok": False,
                        "reason": "execution_schedule_invalid",
                        "error": "relaxed execution local FK transition is non-finite",
                    }
                transition_samples += 1
            previous_q = target_q.copy()
            previous_index = source_index
        report.update(
            {
                "execution_start_joint_limit_recovery": _json_ready(
                    start_limit_recovery
                ),
                "same_branch_inherited_from_signed_path": True,
                "transition_local_fk_finite_checked": True,
                "transition_local_fk_sample_count": int(transition_samples),
                "transition_max_joint_step_rad": float(transition_max_step),
                "execution_path_validation": (
                    "signed_same_branch_with_local_fk_transition_sampling"
                ),
            }
        )

    # A schedule is still policy-owned data.  Revalidate every selected state
    # against the local robot model before an action can be emitted.  This
    # catches malformed/reordered schedule output and keeps the fallback
    # independent of simulator collision or pose APIs.
    local_lower, local_upper = _local_arm_joint_limits(state, arm)
    limits = np.column_stack(
        (
            np.asarray(local_lower, dtype=np.float64).reshape(-1),
            np.asarray(local_upper, dtype=np.float64).reshape(-1),
        )
    )[:ARM_DOF]
    checked: list[list[float]] = []
    previous = np.asarray(start_q, dtype=np.float64).reshape(ARM_DOF)
    max_step = 0.0
    for index, raw_q in enumerate(report.get("waypoints", [])):
        q = _require_serialized_j8_zero(
            raw_q,
            label=f"move-tracked execution schedule waypoint {index + 1}",
        )
        if np.any(q < limits[:, 0]) or np.any(q > limits[:, 1]):
            return {
                **report,
                "ok": False,
                "reason": "execution_schedule_invalid",
                "error": "execution schedule waypoint exceeds local joint limits",
            }
        step = float(np.linalg.norm(q - previous, ord=np.inf))
        if not math.isfinite(step):
            return {
                **report,
                "ok": False,
                "reason": "execution_schedule_invalid",
                "error": "execution schedule contains a non-finite joint step",
            }
        max_step = max(max_step, step)
        position, quaternion = _local_eef_pose(state, arm, q)
        if not np.all(np.isfinite(position)) or not np.all(np.isfinite(quaternion)):
            return {
                **report,
                "ok": False,
                "reason": "execution_schedule_invalid",
                "error": "execution schedule local FK returned non-finite pose",
            }
        checked.append(q.astype(float).tolist())
        previous = q
    if not checked:
        return {
            **report,
            "ok": False,
            "reason": "execution_schedule_invalid",
            "error": "execution schedule contains no waypoints",
        }
    execution_max_step = max(
        float(report.get("max_joint_step_rad", base_step)),
        float(report.get("actual_max_joint_step_rad", 0.0)),
        float(max_step),
    )
    try:
        predicted_execution, predicted_bridge_count = (
            _move_tracked_execution_bridge(
                np.asarray(start_q, dtype=np.float64).reshape(ARM_DOF),
                checked,
                arm=arm,
                max_step_rad=execution_max_step,
            )
        )
    except (TypeError, ValueError) as exc:
        return {
            **report,
            "ok": False,
            "reason": "execution_schedule_invalid",
            "error": f"execution bridge preflight failed: {exc}",
        }
    selected_budget = int(report.get("budget_steps", scheduled_max_steps))
    total_budget = selected_budget + int(start_bridge_reserve)
    predicted_count = len(predicted_execution)
    if predicted_count > total_budget or predicted_count > int(max_steps):
        return {
            **report,
            "ok": False,
            "reason": "execution_budget_infeasible",
            "error": (
                "bridge-expanded execution trajectory exceeds the remaining "
                "action/time budget"
            ),
            "execution_start_joint_limit_recovery": _json_ready(
                start_limit_recovery
            ),
            "execution_bridge_reserved_waypoints": int(start_bridge_reserve),
            "predicted_execution_bridge_waypoint_count": int(
                predicted_bridge_count
            ),
            "predicted_execution_waypoint_count": int(predicted_count),
            "execution_budget_steps_total": int(total_budget),
            "execution_budget_includes_bridge": True,
            "execution_max_joint_step_rad": float(execution_max_step),
        }
    return {
        **report,
        "waypoints": checked,
        "actual_max_joint_step_rad": float(max_step),
        "execution_max_joint_step_rad": float(execution_max_step),
        "execution_step_numeric_tolerance_rad": float(
            MOVE_TRACKED_POINT_EXECUTION_STEP_NUMERIC_TOLERANCE_RAD
        ),
        "execution_start_joint_limit_recovery": _json_ready(
            start_limit_recovery
        ),
        "execution_bridge_reserved_waypoints": int(start_bridge_reserve),
        "predicted_execution_bridge_waypoint_count": int(
            predicted_bridge_count
        ),
        "predicted_execution_waypoint_count": int(predicted_count),
        "execution_budget_steps_total": int(total_budget),
        "execution_budget_includes_bridge": True,
        "local_fk_finite_checked": True,
        "visual_tracked_point_count": visual_tracked_point_count,
        "visual_speedup_cap": float(visual_speedup_cap),
    }


def _move_tracked_execution_cadence_estimate(
    *,
    start_validation: Mapping[str, Any] | None,
    preplanning_source_sync: Mapping[str, Any] | None,
    planner: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Estimate a conservative evaluator period from this request only."""

    samples: list[dict[str, Any]] = []

    def add_sample(raw_value: Any, source: str) -> None:
        try:
            value = float(raw_value)
        except (TypeError, ValueError):
            return
        if not math.isfinite(value) or value < 1.0e-4 or value > 5.0:
            return
        samples.append({"source": str(source), "observation_dt_s": value})

    def add_validation(
        raw_report: Mapping[str, Any] | None,
        source_prefix: str,
    ) -> None:
        if not isinstance(raw_report, Mapping):
            return
        raw_samples = raw_report.get("handoff_observation_dt_samples_s")
        if isinstance(raw_samples, Sequence) and not isinstance(
            raw_samples, (str, bytes, bytearray)
        ):
            for index, value in enumerate(raw_samples):
                add_sample(value, f"{source_prefix}.handoff_window[{index}]")
        add_sample(
            raw_report.get("last_handoff_observation_dt_s"),
            f"{source_prefix}.last_handoff",
        )
        assessment = raw_report.get("handoff_assessment")
        if isinstance(assessment, Mapping):
            add_sample(
                assessment.get("observation_dt_s"),
                f"{source_prefix}.handoff_assessment",
            )

    add_validation(preplanning_source_sync, "preplanning_source_sync")
    add_validation(start_validation, "execution_start_validation")
    if isinstance(planner, Mapping):
        try:
            planning_elapsed_s = float(planner.get("planning_elapsed_s"))
            planning_hold_steps = int(planner.get("planning_hold_steps"))
        except (TypeError, ValueError):
            planning_elapsed_s = float("nan")
            planning_hold_steps = 0
        if (
            math.isfinite(planning_elapsed_s)
            and planning_elapsed_s > 0.0
            and planning_hold_steps > 0
        ):
            add_sample(
                planning_elapsed_s / float(planning_hold_steps),
                "planner.hold_action_average",
            )

    if not samples:
        return {
            "ok": False,
            "reason": "no_valid_observation_period_samples",
            "observation_dt_s": None,
            "max_observed_observation_dt_s": None,
            "safety_factor": float(
                MOVE_TRACKED_POINT_EXECUTION_CADENCE_SAFETY_FACTOR
            ),
            "samples": [],
        }
    max_observed = max(float(item["observation_dt_s"]) for item in samples)
    conservative = min(
        5.0,
        max_observed
        * float(MOVE_TRACKED_POINT_EXECUTION_CADENCE_SAFETY_FACTOR),
    )
    return {
        "ok": True,
        "reason": "slowest_request_local_period_with_jitter_reserve",
        "observation_dt_s": float(conservative),
        "max_observed_observation_dt_s": float(max_observed),
        "safety_factor": float(
            MOVE_TRACKED_POINT_EXECUTION_CADENCE_SAFETY_FACTOR
        ),
        "samples": _json_ready(samples),
    }


def _adjust_latch_measured_hold(
    ctx,
    *,
    arm: str,
    adapter,
    observation_sequence: int,
    measured: dict[str, Any],
    settle_steps: int,
):
    sequence = int(observation_sequence)
    observation = measured
    steps = 0
    observation_advanced = True
    bounded_settle_steps = int(
        np.clip(
            int(settle_steps),
            ADJUST_EEF_SETTLE_MIN_STEPS,
            ADJUST_EEF_SETTLE_MAX_STEPS,
        )
    )
    for _ in range(bounded_settle_steps):
        hold_target = np.asarray(observation["q"], dtype=np.float64).copy()
        yield _adjust_action(ctx, arm, hold_target)
        steps += 1
        advanced, current_sequence = _adjust_observation_advanced(
            adapter,
            sequence,
        )
        if not advanced:
            observation_advanced = False
            break
        sequence = current_sequence
        observation = _adjust_kinematic_observation(ctx, arm)

    # The outer tool emits one final hold action after this helper returns.
    # Refreshing the pin here makes that action use the newest measured pose.
    ctx.world.set_arm_pin_qpos(arm, observation["q"])
    return {
        "steps": int(steps),
        "observation_advanced": bool(observation_advanced),
        "last_observation_sequence": int(sequence),
        "observation": observation,
    }


def _execute_local_pose_closed_loop(
    ctx,
    *,
    arm: str,
    adapter,
    observation_sequence: int,
    target_position: np.ndarray,
    target_quaternion: np.ndarray,
    pos_tol: float,
    ori_tol_deg: float,
    max_steps: int,
    timeout_s: float,
    stage_name: str,
    deadline_monotonic: float | None = None,
    skip_success_settle: bool = False,
):
    deadline = (
        float(deadline_monotonic)
        if deadline_monotonic is not None
        else time.monotonic() + max(1.0, float(timeout_s))
    )
    initial = _adjust_kinematic_observation(ctx, arm)
    safety_monitor = _adjust_safety_monitor(ctx, initial)
    q_start = initial["q"].copy()
    start_position = initial["position"].copy()
    start_quaternion = initial["quaternion"].copy()
    lower, upper = _local_arm_joint_limits(initial["state"], arm)
    initial_position_error = float(
        np.linalg.norm(np.asarray(target_position) - start_position)
    )
    initial_orientation_error = orientation_error_deg(
        start_quaternion,
        target_quaternion,
    )
    target_q, target_ik = solve_pose_target(
        initial["state"],
        arm,
        q_start,
        target_position=target_position,
        target_quaternion=target_quaternion,
        joint_indices=range(7),
        pos_tol_m=max(0.010, float(pos_tol)),
        ori_tol_deg=max(3.0, float(ori_tol_deg)),
    )
    position_scale = max(0.010, float(pos_tol))
    orientation_scale = max(3.0, float(ori_tol_deg))
    initial_ik_score = (
        initial_position_error / position_scale
        + initial_orientation_error / orientation_scale
    )
    initial_ik_max_score = max(
        initial_position_error / position_scale,
        initial_orientation_error / orientation_scale,
    )
    target_ik_position_error = float(
        target_ik.get("pos_err_m", float("inf"))
    )
    target_ik_orientation_error = float(
        target_ik.get("ori_err_deg", float("inf"))
    )
    candidate_ik_score = (
        target_ik_position_error / position_scale
        + target_ik_orientation_error / orientation_scale
    )
    candidate_ik_max_score = max(
        target_ik_position_error / position_scale,
        target_ik_orientation_error / orientation_scale,
    )
    # Preserve the v2 contract: a preflight solution is guidance only after it
    # satisfies both pose tolerances. A partial least-squares solution can pull
    # the tangent loop toward a position/orientation compromise near limits.
    guidance_accepted = bool(
        np.all(np.isfinite(target_q[:7]))
        and bool(target_ik.get("ok", False))
    )
    target_ik["guidance_accepted"] = guidance_accepted
    target_ik["initial_normalized_error"] = float(initial_ik_score)
    target_ik["initial_normalized_max_error"] = float(initial_ik_max_score)
    target_ik["candidate_normalized_error"] = float(candidate_ik_score)
    target_ik["candidate_normalized_max_error"] = float(
        candidate_ik_max_score
    )
    gross_preflight_rejection = bool(
        not guidance_accepted
        and (
            not math.isfinite(candidate_ik_max_score)
            or candidate_ik_max_score
            > ADJUST_EEF_GROSS_PREFLIGHT_MAX_NORMALIZED_ERROR
        )
    )
    target_ik["motion_rejected"] = gross_preflight_rejection
    target_ik["gross_rejection_normalized_error_limit"] = float(
        ADJUST_EEF_GROSS_PREFLIGHT_MAX_NORMALIZED_ERROR
    )
    joint_goal = target_q[:7] if guidance_accepted else None
    nominal_position_steps = max(
        1,
        int(math.ceil(initial_position_error / MAX_TRANSLATION_STEP_M)),
    )
    nominal_orientation_steps = max(
        1,
        int(math.ceil(math.radians(initial_orientation_error) / 0.06)),
    )
    relinearization_multiplier = (
        ADJUST_EEF_GUIDED_RELINEARIZATION_MULTIPLIER
        if guidance_accepted
        else ADJUST_EEF_RELINEARIZATION_MULTIPLIER
    )
    guided_joint_nominal_steps = (
        int(
            math.ceil(
                float(np.linalg.norm(target_q[:7] - q_start[:7], ord=np.inf))
                / (
                    ADJUST_POSE_MAX_JOINT_STEP_RAD
                    * ADJUST_EEF_GUIDED_STEP_SCALE
                )
            )
        )
        if guidance_accepted
        else 0
    )
    guided_joint_tracking_steps = (
        ADJUST_EEF_GUIDED_JOINT_TRACKING_MULTIPLIER
        * guided_joint_nominal_steps
    )
    nominal_execution_steps = min(
        max(1, int(max_steps)),
        max(
            8,
            relinearization_multiplier
            * max(nominal_position_steps, nominal_orientation_steps),
            guided_joint_tracking_steps,
        ),
    )
    # A mildly imperfect terminal solve still uses the observation-relinearized
    # tangent fallback. A grossly invalid solve must not spend dozens of
    # official actions chasing an unreachable pose and exciting the arm near
    # its limits.
    execution_steps = (
        0 if gross_preflight_rejection else nominal_execution_steps
    )
    previous_dq = None
    adaptive_step_scale = 1.0
    max_adaptive_step_scale = 1.0
    min_adaptive_step_scale = 1.0
    action_steps = 0
    max_observed_j8 = abs(float(initial["observed_j8"]))
    reason = (
        "terminal_ik_grossly_unreachable"
        if gross_preflight_rejection
        else "max_steps"
    )
    last_step: dict[str, Any] = {}
    last_observed = initial
    sequence = int(observation_sequence)
    best_pose_score = max(
        initial_position_error / position_scale,
        initial_orientation_error / orientation_scale,
    )
    pose_stall_steps = 0
    near_zero_command_steps = 0
    guided_steps = 0
    tangent_steps = 0
    guided_fallbacks = 0
    max_observed_orientation_error_deg = float(initial_orientation_error)
    orientation_divergence_limit_deg = max(
        ADJUST_EEF_ORIENTATION_DIVERGENCE_MARGIN_DEG,
        initial_orientation_error
        + ADJUST_EEF_ORIENTATION_DIVERGENCE_MARGIN_DEG,
        ADJUST_EEF_ORIENTATION_DIVERGENCE_TOL_MULTIPLIER
        * orientation_scale,
    )

    for step in range(execution_steps):
        _check_cancelled(ctx, f"{stage_name} step {step + 1}")
        if time.monotonic() >= deadline:
            reason = "timeout"
            break
        observed = _adjust_kinematic_observation(ctx, arm)
        last_observed = observed
        max_observed_j8 = max(
            max_observed_j8,
            abs(float(observed["observed_j8"])),
        )
        q_current = observed["q"]
        position_error_vector = np.asarray(
            target_position,
            dtype=np.float64,
        ) - observed["position"]
        position_error = float(np.linalg.norm(position_error_vector))
        orientation_vector = orientation_error_vector(
            observed["quaternion"],
            target_quaternion,
        )
        orientation_error_value = math.degrees(
            float(np.linalg.norm(orientation_vector))
        )
        max_observed_orientation_error_deg = max(
            max_observed_orientation_error_deg,
            orientation_error_value,
        )
        if (
            position_error <= max(0.001, float(pos_tol))
            and orientation_error_value <= max(0.1, float(ori_tol_deg))
        ):
            reason = "target_converged"
            break

        max_adaptive_step_scale = max(
            max_adaptive_step_scale,
            adaptive_step_scale,
        )
        min_adaptive_step_scale = min(
            min_adaptive_step_scale,
            adaptive_step_scale,
        )
        try:
            delta_q = np.zeros(7, dtype=np.float64)
            solver_report: dict[str, Any] = {}
            if joint_goal is not None:
                delta_q, solver_report = bounded_pose_goal_step(
                    observed["state"],
                    arm,
                    q_current,
                    target_q,
                    target_position=target_position,
                    target_quaternion=target_quaternion,
                    pos_tol_m=max(0.001, float(pos_tol)),
                    ori_tol_deg=max(0.1, float(ori_tol_deg)),
                    max_joint_step_rad=(
                        ADJUST_POSE_MAX_JOINT_STEP_RAD
                        * ADJUST_EEF_GUIDED_STEP_SCALE
                    ),
                    max_translation_step_m=(
                        MAX_TRANSLATION_STEP_M * ADJUST_EEF_GUIDED_STEP_SCALE
                    ),
                    max_orientation_step_rad=(
                        MAX_ORIENTATION_STEP_RAD * ADJUST_EEF_GUIDED_STEP_SCALE
                    ),
                    previous_dq=previous_dq,
                )
                if bool(solver_report.get("guided_goal_step_accepted")):
                    guided_steps += 1
                    max_adaptive_step_scale = max(
                        max_adaptive_step_scale,
                        ADJUST_EEF_GUIDED_STEP_SCALE,
                    )
                else:
                    guided_fallbacks += 1
            if not bool(solver_report.get("guided_goal_step_accepted")):
                jacobian, _position, _quaternion = numerical_eef_jacobian(
                    observed["state"],
                    arm,
                    q_current,
                    joint_indices=range(7),
                )
                delta_q, solver_report = bounded_pose_tangent_step(
                    jacobian,
                    position_error_vector,
                    orientation_vector,
                    q_current[:7],
                    q_lower=lower[:7],
                    q_upper=upper[:7],
                    previous_dq=previous_dq,
                    joint_goal=joint_goal,
                    position_satisfied=position_error
                    <= max(0.001, float(pos_tol)),
                    max_joint_step_rad=(
                        ADJUST_POSE_MAX_JOINT_STEP_RAD * adaptive_step_scale
                    ),
                    max_translation_step_m=(
                        MAX_TRANSLATION_STEP_M * adaptive_step_scale
                    ),
                    max_orientation_step_rad=(
                        MAX_ORIENTATION_STEP_RAD * adaptive_step_scale
                    ),
                )
                tangent_steps += 1
        except Exception as exc:
            reason = f"local_solver_error:{type(exc).__name__}"
            last_step = {"error": str(exc)}
            break

        command = q_current.copy()
        command[:7] = np.clip(
            q_current[:7] + delta_q,
            lower[:7],
            upper[:7],
        )
        if ARM_DOF == 8:
            command[7] = 0.0
        last_step = {
            **solver_report,
            "index": int(step + 1),
            "position_error_m": position_error,
            "orientation_error_deg": orientation_error_value,
            "adaptive_step_scale": float(adaptive_step_scale),
            "command_q_rad": command.tolist(),
        }
        yield _adjust_action(ctx, arm, command)
        action_steps += 1

        advanced, current_sequence = _adjust_observation_advanced(adapter, sequence)
        if not advanced:
            reason = "observation_not_advanced"
            break
        sequence = current_sequence
        after_action = _adjust_kinematic_observation(ctx, arm)
        last_observed = after_action
        safety_reason, safety_observation = _adjust_safety_after_action(
            ctx,
            safety_monitor,
            before=observed,
            command=command,
            after=after_action,
        )
        last_step["safety_observation"] = safety_observation
        if safety_reason is not None:
            reason = safety_reason
            break
        after_position_error = float(
            np.linalg.norm(
                np.asarray(target_position, dtype=np.float64)
                - after_action["position"]
            )
        )
        after_orientation_error = orientation_error_deg(
            after_action["quaternion"],
            target_quaternion,
        )
        max_observed_orientation_error_deg = max(
            max_observed_orientation_error_deg,
            after_orientation_error,
        )
        if (
            not guidance_accepted
            and after_orientation_error > orientation_divergence_limit_deg
        ):
            reason = "orientation_error_diverged"
            last_step["orientation_divergence_limit_deg"] = float(
                orientation_divergence_limit_deg
            )
            break
        after_pose_score = max(
            after_position_error / position_scale,
            after_orientation_error / orientation_scale,
        )
        if (
            after_position_error <= max(0.001, float(pos_tol))
            and after_orientation_error <= max(0.1, float(ori_tol_deg))
        ):
            reason = "target_converged"
            best_pose_score = min(best_pose_score, after_pose_score)
            break
        if after_pose_score < best_pose_score - ADJUST_EEF_POSE_PROGRESS_EPS:
            best_pose_score = after_pose_score
            pose_stall_steps = 0
        else:
            pose_stall_steps += 1
        command_inf = float(safety_observation["command_inf_rad"])
        near_zero_command_steps = (
            near_zero_command_steps + 1
            if command_inf <= ADJUST_EEF_NEAR_ZERO_COMMAND_RAD
            else 0
        )
        if near_zero_command_steps >= ADJUST_EEF_NEAR_ZERO_COMMAND_STEPS:
            reason = "near_zero_command_stall"
            break
        if pose_stall_steps >= ADJUST_EEF_POSE_STALL_STEPS:
            reason = "pose_error_stall"
            break
        adaptive_step_scale = _adjust_next_step_scale(
            adaptive_step_scale,
            safety_observation,
            near_target=bool(
                after_position_error
                <= max(
                    ADJUST_EEF_ADAPTIVE_NEAR_POSITION_M,
                    2.0 * float(pos_tol),
                )
                and after_orientation_error
                <= max(
                    ADJUST_EEF_ADAPTIVE_NEAR_ORIENTATION_DEG,
                    2.0 * float(ori_tol_deg),
                )
            ),
        )
        previous_dq = delta_q.copy()
    else:
        if not gross_preflight_rejection:
            reason = "fixed_budget_complete"

    pre_settle_position_error = float(
        np.linalg.norm(
            np.asarray(target_position, dtype=np.float64)
            - last_observed["position"]
        )
    )
    pre_settle_orientation_error = orientation_error_deg(
        last_observed["quaternion"],
        target_quaternion,
    )
    target_reached_before_settle = bool(
        pre_settle_position_error <= max(0.001, float(pos_tol))
        and pre_settle_orientation_error <= max(0.1, float(ori_tol_deg))
    )
    requested_settle_steps = _adjust_settle_steps(
        last_observed,
        target_reached=target_reached_before_settle,
        skip_when_reached=bool(skip_success_settle),
    )
    hold_report = yield from _adjust_latch_measured_hold(
        ctx,
        arm=arm,
        adapter=adapter,
        observation_sequence=sequence,
        measured=last_observed,
        settle_steps=requested_settle_steps,
    )
    settle_steps = int(hold_report["steps"])
    sequence = int(hold_report["last_observation_sequence"])

    final = _adjust_kinematic_observation(ctx, arm)
    final_position_error = float(
        np.linalg.norm(np.asarray(target_position) - final["position"])
    )
    final_orientation_error = orientation_error_deg(
        final["quaternion"],
        target_quaternion,
    )
    max_observed_orientation_error_deg = max(
        max_observed_orientation_error_deg,
        final_orientation_error,
    )
    converged = bool(
        final_position_error <= max(0.001, float(pos_tol))
        and final_orientation_error <= max(0.1, float(ori_tol_deg))
    )
    requested_delta = np.asarray(target_position, dtype=np.float64) - start_position
    actual_delta = final["position"] - start_position
    requested_distance = float(np.linalg.norm(requested_delta))
    actual_distance = float(np.linalg.norm(actual_delta))
    if requested_distance > 1e-9:
        requested_direction = requested_delta / requested_distance
        projected_progress = float(actual_delta @ requested_direction)
        lateral_delta = actual_delta - projected_progress * requested_direction
        lateral_error = float(np.linalg.norm(lateral_delta))
        progress_ratio = float(
            np.clip(projected_progress / requested_distance, 0.0, 1.0)
        )
    else:
        projected_progress = 0.0
        lateral_error = actual_distance
        progress_ratio = 1.0
    loop_exit_reason = reason
    if converged and reason in {
        "max_steps",
        "fixed_budget_complete",
        "timeout",
        "near_zero_command_stall",
        "pose_error_stall",
    }:
        reason = "target_converged_after_settle"
    command_completed = bool(
        converged
        and reason
        in {
            "target_converged",
            "target_converged_after_settle",
        }
    )
    return {
        "ok": bool(command_completed),
        "command_completed": bool(command_completed),
        "converged": converged,
        "reason": reason,
        "loop_exit_reason": loop_exit_reason,
        "controller": "observation_relinearized_static_urdf_tangent_ik_7dof",
        "observation_action_loop": True,
        "reference_frame": "robot_base",
        "action_dim": int(ACTION_DIM),
        "action_only": True,
        "j8_participates": False,
        "j8_target_rad": 0.0,
        "max_observed_j8_abs_rad": float(max_observed_j8),
        "target_ik": target_ik,
        "steps_planned": int(execution_steps),
        "nominal_steps_planned": int(nominal_execution_steps),
        "gross_preflight_rejection": bool(gross_preflight_rejection),
        "gross_preflight_normalized_error_limit": float(
            ADJUST_EEF_GROSS_PREFLIGHT_MAX_NORMALIZED_ERROR
        ),
        "relinearization_multiplier": int(relinearization_multiplier),
        "fallback_relinearization_multiplier": int(
            ADJUST_EEF_RELINEARIZATION_MULTIPLIER
        ),
        "guided_relinearization_multiplier": int(
            ADJUST_EEF_GUIDED_RELINEARIZATION_MULTIPLIER
        ),
        "guided_joint_nominal_steps": int(guided_joint_nominal_steps),
        "guided_joint_tracking_multiplier": int(
            ADJUST_EEF_GUIDED_JOINT_TRACKING_MULTIPLIER
        ),
        "guided_joint_tracking_steps": int(guided_joint_tracking_steps),
        "guided_step_scale": float(ADJUST_EEF_GUIDED_STEP_SCALE),
        "guided_steps_executed": int(guided_steps),
        "guided_fallback_steps": int(guided_fallbacks),
        "tangent_steps_executed": int(tangent_steps),
        "pose_stall_steps": int(pose_stall_steps),
        "pose_stall_limit": int(ADJUST_EEF_POSE_STALL_STEPS),
        "orientation_divergence_guard_active": bool(
            not guidance_accepted
        ),
        "orientation_divergence_limit_deg": float(
            orientation_divergence_limit_deg
        ),
        "max_observed_orientation_error_deg": float(
            max_observed_orientation_error_deg
        ),
        "near_zero_command_steps": int(near_zero_command_steps),
        "near_zero_command_limit": int(ADJUST_EEF_NEAR_ZERO_COMMAND_STEPS),
        "best_normalized_max_pose_error": float(best_pose_score),
        "steps_executed": int(action_steps),
        "settle_steps_executed": int(settle_steps),
        "settle_steps_requested": int(requested_settle_steps),
        "target_reached_before_settle": bool(target_reached_before_settle),
        "measured_hold_observation_advanced": bool(
            hold_report["observation_advanced"]
        ),
        "max_tracking_error_inf_rad": float(
            safety_monitor.max_tracking_error_rad
        ),
        "adaptive_step_scale_max": float(max_adaptive_step_scale),
        "adaptive_step_scale_min": float(min_adaptive_step_scale),
        "adaptive_step_scale_limit": float(ADJUST_EEF_ADAPTIVE_MAX_SCALE),
        "safety": _adjust_safety_report(safety_monitor),
        "q_start_rad": q_start.tolist(),
        "q_final_rad": final["q"].tolist(),
        "eef_start_robot_m": start_position.tolist(),
        "eef_final_robot_m": final["position"].tolist(),
        "requested_distance_m": requested_distance,
        "actual_distance_m": actual_distance,
        "actual_delta_robot_m": actual_delta.tolist(),
        "projected_progress_m": projected_progress,
        "lateral_error_m": lateral_error,
        "progress_ratio": progress_ratio,
        "final_position_error_m": final_position_error,
        "final_orientation_error_deg": final_orientation_error,
        "last_step": last_step,
        "last_observation_sequence": int(sequence),
    }


def _execute_local_j567_closed_loop(
    ctx,
    *,
    arm: str,
    adapter,
    observation_sequence: int,
    target_quaternion: np.ndarray,
    ori_tol_deg: float,
    max_steps: int,
    timeout_s: float,
    stage_name: str,
    deadline_monotonic: float | None = None,
    skip_success_settle: bool = False,
):
    deadline = (
        float(deadline_monotonic)
        if deadline_monotonic is not None
        else time.monotonic() + max(1.0, float(timeout_s))
    )
    initial = _adjust_kinematic_observation(ctx, arm)
    safety_monitor = _adjust_safety_monitor(ctx, initial)
    q_start = initial["q"].copy()
    if time.monotonic() >= deadline:
        return {
            "ok": False,
            "command_completed": False,
            "reason": "timeout_before_orientation_solve",
            "orientation_solve": {
                "ok": False,
                "skipped": True,
                "reason": "shared tool timeout exhausted",
                "fixed_joint_numbers": [1, 2, 3, 4],
                "commanded_joint_numbers": [5, 6, 7],
                "j8_participates": False,
            },
            "action_only": True,
            "controller": "observation_tracked_static_urdf_j567_target",
            "controller_steps": 0,
            "settle_steps": 0,
            "settle_steps_requested": 0,
            "fixed_q1234_rad": q_start[:4].tolist(),
            "commanded_joint_numbers": [5, 6, 7],
            "j8_participates": False,
            "j8_target_rad": 0.0,
            "last_observation_sequence": int(observation_sequence),
        }
    target_q, solve_report = solve_j567_orientation_target(
        initial["state"],
        arm,
        q_start,
        target_quaternion,
        ori_tol_deg=float(ori_tol_deg),
    )
    if not solve_report.get("ok", False):
        return {
            "ok": False,
            "reason": "j567_target_unreachable",
            "orientation_solve": solve_report,
            "controller_steps": 0,
            "fixed_q1234_rad": q_start[:4].tolist(),
            "commanded_joint_numbers": [5, 6, 7],
            "j8_participates": False,
            "last_observation_sequence": int(observation_sequence),
        }

    fixed_q1234 = q_start[:4].copy()
    tolerance_rad = math.radians(max(0.25, min(float(ori_tol_deg), 1.0)))
    sequence = int(observation_sequence)
    steps = 0
    adaptive_step_scale = 1.0
    max_adaptive_step_scale = 1.0
    min_adaptive_step_scale = 1.0
    reason = "max_steps"
    max_j1234_drift = 0.0
    max_observed_j8 = abs(float(initial["observed_j8"]))
    last_observed = initial
    for step in range(min(max(1, int(max_steps)), 120)):
        _check_cancelled(ctx, f"{stage_name} step {step + 1}")
        if time.monotonic() >= deadline:
            reason = "timeout"
            break
        observed = _adjust_kinematic_observation(ctx, arm)
        last_observed = observed
        max_observed_j8 = max(
            max_observed_j8,
            abs(float(observed["observed_j8"])),
        )
        error = target_q[4:7] - observed["q"][4:7]
        max_j1234_drift = max(
            max_j1234_drift,
            float(np.linalg.norm(observed["q"][:4] - fixed_q1234, ord=np.inf)),
        )
        if float(np.max(np.abs(error))) <= tolerance_rad:
            reason = "target_converged"
            break
        max_adaptive_step_scale = max(
            max_adaptive_step_scale,
            adaptive_step_scale,
        )
        min_adaptive_step_scale = min(
            min_adaptive_step_scale,
            adaptive_step_scale,
        )
        command = observed["q"].copy()
        command[:4] = fixed_q1234
        command[4:7] += np.clip(
            error,
            -WRIST_MAX_JOINT_STEP_RAD * adaptive_step_scale,
            WRIST_MAX_JOINT_STEP_RAD * adaptive_step_scale,
        )
        if ARM_DOF == 8:
            command[7] = 0.0
        yield _adjust_action(ctx, arm, command)
        steps += 1
        advanced, current_sequence = _adjust_observation_advanced(adapter, sequence)
        if not advanced:
            reason = "observation_not_advanced"
            break
        sequence = current_sequence
        after_action = _adjust_kinematic_observation(ctx, arm)
        last_observed = after_action
        safety_reason, safety_observation = _adjust_safety_after_action(
            ctx,
            safety_monitor,
            before=observed,
            command=command,
            after=after_action,
        )
        if safety_reason is not None:
            reason = safety_reason
            break
        remaining_joint_error = float(
            np.linalg.norm(
                target_q[4:7] - after_action["q"][4:7],
                ord=np.inf,
            )
        )
        adaptive_step_scale = _adjust_next_step_scale(
            adaptive_step_scale,
            safety_observation,
            near_target=bool(remaining_joint_error <= 2.0 * tolerance_rad),
        )
    else:
        reason = "fixed_budget_complete"

    target_reached_before_settle = bool(
        float(
            np.linalg.norm(
                target_q[4:7] - last_observed["q"][4:7],
                ord=np.inf,
            )
        )
        <= tolerance_rad
    )
    requested_settle_steps = _adjust_settle_steps(
        last_observed,
        target_reached=target_reached_before_settle,
        skip_when_reached=bool(skip_success_settle),
    )
    hold_report = yield from _adjust_latch_measured_hold(
        ctx,
        arm=arm,
        adapter=adapter,
        observation_sequence=sequence,
        measured=last_observed,
        settle_steps=requested_settle_steps,
    )
    settle_steps = int(hold_report["steps"])
    sequence = int(hold_report["last_observation_sequence"])

    final = _adjust_kinematic_observation(ctx, arm)
    joint_error_deg = np.degrees(target_q - final["q"])
    max_j1234_drift = max(
        max_j1234_drift,
        float(np.linalg.norm(final["q"][:4] - fixed_q1234, ord=np.inf)),
    )
    converged = bool(
        np.max(np.abs(joint_error_deg[4:7]))
        <= max(0.25, float(ori_tol_deg))
    )
    if converged and reason in {"max_steps", "fixed_budget_complete"}:
        reason = "target_converged_after_settle"
    command_completed = bool(
        converged
        and reason
        in {
            "target_converged",
            "target_converged_after_settle",
        }
    )
    return {
        "ok": command_completed,
        "command_completed": command_completed,
        "reason": reason,
        "orientation_solve": solve_report,
        "action_only": True,
        "controller": "observation_tracked_static_urdf_j567_target",
        "controller_steps": int(steps),
        "settle_steps": int(settle_steps),
        "settle_steps_requested": int(requested_settle_steps),
        "target_reached_before_settle": bool(target_reached_before_settle),
        "measured_hold_observation_advanced": bool(
            hold_report["observation_advanced"]
        ),
        "safety": _adjust_safety_report(safety_monitor),
        "adaptive_step_scale_max": float(max_adaptive_step_scale),
        "adaptive_step_scale_min": float(min_adaptive_step_scale),
        "adaptive_step_scale_limit": float(ADJUST_EEF_ADAPTIVE_MAX_SCALE),
        "qpos_start_deg": np.degrees(q_start).round(4).tolist(),
        "qpos_target_deg": np.degrees(target_q).round(4).tolist(),
        "qpos_after_deg": np.degrees(final["q"]).round(4).tolist(),
        "final_error_deg": joint_error_deg.round(4).tolist(),
        "fixed_q1234_rad": fixed_q1234.tolist(),
        "commanded_joint_numbers": [5, 6, 7],
        "max_measured_j1234_drift_rad": float(max_j1234_drift),
        "j8_participates": False,
        "j8_target_rad": 0.0,
        "max_observed_j8_abs_rad": float(max_observed_j8),
        "last_observation_sequence": int(sequence),
    }


def _validate_adjust_values(
    *,
    translation: tuple[float, float, float],
    roll: float,
    pitch: float,
    yaw: float,
    pos_tol: float,
    ori_tol_deg: float,
    max_steps: int,
    timeout_s: float,
) -> np.ndarray:
    values = np.asarray(
        [
            *translation,
            roll,
            pitch,
            yaw,
            pos_tol,
            ori_tol_deg,
            max_steps,
            timeout_s,
        ],
        dtype=np.float64,
    )
    if not np.all(np.isfinite(values)):
        raise ValueError("all EEF adjustment values must be finite")
    if float(pos_tol) <= 0.0:
        raise ValueError("pos_tol must be positive")
    if float(ori_tol_deg) <= 0.0:
        raise ValueError("ori_tol_deg must be positive")
    if int(max_steps) <= 0:
        raise ValueError("max_steps must be positive")
    if float(timeout_s) <= 0.0:
        raise ValueError("timeout_s must be positive")
    return values


def _head_translation_request(
    *,
    x: float | None,
    y: float | None,
    z: float | None,
    forward: float | None,
    leftward: float | None,
    upward: float | None,
) -> dict[str, Any]:
    base_raw = {"x": x, "y": y, "z": z}
    camera_raw = {
        "forward": forward,
        "leftward": leftward,
        "upward": upward,
    }
    base_present = [key for key, value in base_raw.items() if value is not None]
    camera_present = [
        key for key, value in camera_raw.items() if value is not None
    ]
    if base_present and camera_present:
        raise ValueError(
            "head-frame translation parameter families are mutually exclusive: "
            "use only x/y/z (robot base frame) or only "
            "forward/leftward/upward (head camera frame); got base keys "
            f"{base_present} and camera keys {camera_present}"
        )

    if base_present:
        requested = {
            key: float(0.0 if value is None else value)
            for key, value in base_raw.items()
        }
        return {
            "mode": "robot_base_xyz",
            "frame": "robot_base",
            "provided": base_present,
            "requested": requested,
            "vector": (requested["x"], requested["y"], requested["z"]),
        }

    requested = {
        key: float(0.0 if value is None else value)
        for key, value in camera_raw.items()
    }
    return {
        "mode": "head_camera_forward_leftward_upward",
        "frame": "head_camera",
        "provided": camera_present,
        "requested": requested,
        "vector": (
            requested["forward"],
            requested["leftward"],
            requested["upward"],
        ),
    }


def _adjust_eef_pose_in_head_frame_local(
    ctx,
    *,
    arm: str,
    tool_name: str,
    forward: float | None,
    upward: float | None,
    leftward: float | None,
    x: float | None,
    y: float | None,
    z: float | None,
    roll: float,
    pitch: float,
    yaw: float,
    pos_tol: float,
    ori_tol_deg: float,
    max_steps: int,
    timeout_s: float,
):
    try:
        translation = _head_translation_request(
            x=x,
            y=y,
            z=z,
            forward=forward,
            leftward=leftward,
            upward=upward,
        )
        values = _validate_adjust_values(
            translation=translation["vector"],
            roll=roll,
            pitch=pitch,
            yaw=yaw,
            pos_tol=pos_tol,
            ori_tol_deg=ori_tol_deg,
            max_steps=max_steps,
            timeout_s=timeout_s,
        )
        camera, sequence, adapter = _adjust_camera_pose(ctx, "head")
        initial = _adjust_kinematic_observation(ctx, arm)
        if ARM_DOF == 8 and abs(float(initial["observed_j8"])) > LOCKED_J8_CAPTURE_TOLERANCE_RAD:
            raise RuntimeError(
                f"{arm} J8 is not locked at 0rad in evaluator proprioception"
            )
        if translation["frame"] == "robot_base":
            target = robot_base_frame_pose_target(
                eef_position=initial["position"],
                eef_quaternion=initial["quaternion"],
                camera_quaternion=camera["quat"],
                x=translation["requested"]["x"],
                y=translation["requested"]["y"],
                z=translation["requested"]["z"],
                roll=float(roll),
                pitch=float(pitch),
                yaw=float(yaw),
            )
        else:
            target = camera_frame_pose_target(
                eef_position=initial["position"],
                eef_quaternion=initial["quaternion"],
                camera_quaternion=camera["quat"],
                forward=translation["requested"]["forward"],
                leftward=translation["requested"]["leftward"],
                upward=translation["requested"]["upward"],
                roll=float(roll),
                pitch=float(pitch),
                yaw=float(yaw),
            )
    except (RuntimeError, TypeError, ValueError) as exc:
        _set_result(ctx, tool_name, {"ok": False, "error": str(exc)})
        yield ctx.world.hold_action()
        return

    move_position = bool(np.linalg.norm(values[:3]) > 1e-8)
    move_orientation = bool(np.any(np.abs(values[3:6]) > 1e-9))
    if not move_position and not move_orientation:
        _set_result(
            ctx,
            tool_name,
            {
                "ok": True,
                "build": ADJUST_EEF_LOCAL_BUILD,
                "arm": arm,
                "feed": "head",
                "note": "all deltas are zero; no action",
                "translation_input_mode": translation["mode"],
                "translation_frame": translation["frame"],
                "translation_m": translation["requested"],
                "j8_participates": False,
                "j8_target_rad": 0.0,
                "camera_pose_source": "evaluator_cam_rel_poses",
                "finger_qpos": initial["gripper"].tolist(),
            },
        )
        yield ctx.world.hold_action()
        return

    pose_report = yield from _execute_local_pose_closed_loop(
        ctx,
        arm=arm,
        adapter=adapter,
        observation_sequence=sequence,
        target_position=target.position,
        target_quaternion=target.quaternion,
        pos_tol=float(pos_tol),
        ori_tol_deg=float(ori_tol_deg),
        max_steps=int(max_steps),
        timeout_s=float(timeout_s),
        stage_name=f"{tool_name}.pose",
    )
    final = _adjust_kinematic_observation(ctx, arm)
    position_error = float(np.linalg.norm(final["position"] - target.position))
    orientation_error = orientation_error_deg(
        final["quaternion"],
        target.quaternion,
    )
    position_ok = bool(
        not move_position or position_error <= max(0.001, float(pos_tol))
    )
    orientation_limit = max(float(ori_tol_deg) * 2.0, 6.0)
    orientation_ok = bool(orientation_error <= orientation_limit)
    j8_ok = bool(
        ARM_DOF != 8
        or abs(float(final["observed_j8"])) <= LOCKED_J8_CAPTURE_TOLERANCE_RAD
    )
    overall_ok = bool(
        pose_report.get("ok", False)
        and position_ok
        and orientation_ok
        and j8_ok
    )
    failure_reason = None
    if not overall_ok:
        reason = str(pose_report.get("reason", "pose_controller_incomplete"))
        steps_executed = int(pose_report.get("steps_executed", 0))
        steps_planned = int(pose_report.get("steps_planned", 0))
        if reason == "timeout":
            reason_text = (
                "pose control timed out after "
                f"{steps_executed}/{steps_planned} fresh observation/action steps"
            )
        elif reason == "terminal_ik_grossly_unreachable":
            reason_text = (
                "pose control rejected before arm motion because the terminal "
                "pose is grossly unreachable in the submission-local model"
            )
        else:
            reason_text = f"pose control stopped with reason={reason}"
        details = [reason_text]
        target_ik = pose_report.get("target_ik") or {}
        if not bool(target_ik.get("ok", False)):
            details.append(
                "terminal-pose local IK preflight did not converge "
                f"(position residual {float(target_ik.get('pos_err_m', float('nan'))) * 1000.0:.1f}mm, "
                f"orientation residual {float(target_ik.get('ori_err_deg', float('nan'))):.2f}deg)"
            )
        details.append(
            f"measured requested-direction progress "
            f"{float(pose_report.get('projected_progress_m', 0.0)):.3f}m/"
            f"{float(pose_report.get('requested_distance_m', 0.0)):.3f}m"
        )
        if not position_ok:
            details.append(f"final position error {position_error * 1000.0:.1f}mm")
        if not orientation_ok:
            details.append(
                f"final orientation error {orientation_error:.2f}deg exceeds "
                f"{orientation_limit:.2f}deg"
            )
        if not j8_ok:
            details.append("observed J8 is outside its 0rad lock tolerance")
        failure_reason = "; ".join(details)
    _set_result(
        ctx,
        tool_name,
        {
            "ok": overall_ok,
            "build": ADJUST_EEF_LOCAL_BUILD,
            "arm": arm,
            "feed": "head",
            "translation_input_mode": translation["mode"],
            "translation_frame": translation["frame"],
            "translation_parameters_present": translation["provided"],
            "translation_m": translation["requested"],
            "delta_head_camera_m": target.delta_camera.round(6).tolist(),
            "delta_robot_base_m": target.delta_robot.round(6).tolist(),
            "rotation_deg": {
                "roll": float(roll),
                "pitch": float(pitch),
                "yaw": float(yaw),
            },
            "rpy_deg": {
                "roll": float(roll),
                "pitch": float(pitch),
                "yaw": float(yaw),
            },
            "convention": {
                "translation": (
                    "robot base +X chassis-forward, +Y chassis-left, +Z chassis-up"
                    if translation["frame"] == "robot_base"
                    else "head camera -Z/-X/+Y for forward/leftward/upward"
                ),
                "translation_parameter_families": (
                    "x/y/z and forward/leftward/upward are mutually exclusive"
                ),
                "rotation": "local gripper roll/pitch/yaw; positive pitch is fingertips-up",
            },
            "rpy_convention": {
                "translation": (
                    "x/y/z are robot-base-frame translation deltas"
                    if translation["frame"] == "robot_base"
                    else "forward/leftward/upward are head-camera-frame translation deltas"
                ),
                "rotation": "roll/pitch/yaw are local gripper axes, same convention as adjust_plan_pose",
                "positive_pitch": "positive pitch is nose-up / fingertips-up",
            },
            "camera_before": {
                "pos": camera["pos"].round(6).tolist(),
                "quat": camera["quat"].round(6).tolist(),
                "frame": "robot_base",
                "source": "evaluator_cam_rel_poses",
            },
            "delta_camera_m": target.delta_camera.round(6).tolist(),
            "delta_robot_m": target.delta_robot.round(6).tolist(),
            "delta_world_m": target.delta_robot.round(6).tolist(),
            "eef_before": initial["position"].round(6).tolist(),
            "eef_target": target.position.round(6).tolist(),
            "eef_after": final["position"].round(6).tolist(),
            "quat_before": initial["quaternion"].round(6).tolist(),
            "quat_target": target.quaternion.round(6).tolist(),
            "quat_after": final["quaternion"].round(6).tolist(),
            "kinematics_source": "submission_local_static_urdf_fk",
            "pos_err_mm": round(position_error * 1000.0, 3),
            "ori_err_deg": round(orientation_error, 3),
            "pos_ok": position_ok,
            "ori_ok": orientation_ok,
            "target_reached": bool(position_ok and orientation_ok),
            "pose_control": pose_report,
            "failure_reason": failure_reason,
            "external_object_motion_checked": False,
            "external_object_motion_evidence": (
                "requires a subsequent evaluator RGB-D observation"
            ),
            "finger_qpos": final["gripper"].tolist(),
            "j8_participates": False,
            "j8_target_rad": 0.0,
            "j8_ok": j8_ok,
            "observation_contract": [
                "evaluator_proprioception",
                "evaluator_head_cam_rel_poses",
                "submission_local_static_robot_model",
            ],
            "simulator_fk_ik_used": False,
            "simulator_eef_pose_used": False,
            "direct_simulator_mutation": False,
            "error": failure_reason,
        },
    )
    yield ctx.world.hold_action()


def _adjust_eef_pose_in_wrist_frame_local(
    ctx,
    *,
    arm: str,
    tool_name: str,
    forward: float,
    leftward: float,
    upward: float,
    roll: float,
    pitch: float,
    yaw: float,
    pos_tol: float,
    ori_tol_deg: float,
    max_steps: int,
    timeout_s: float,
):
    try:
        values = _validate_adjust_values(
            translation=(forward, leftward, upward),
            roll=roll,
            pitch=pitch,
            yaw=yaw,
            pos_tol=pos_tol,
            ori_tol_deg=ori_tol_deg,
            max_steps=max_steps,
            timeout_s=timeout_s,
        )
        camera, sequence, adapter = _adjust_camera_pose(ctx, f"{arm}_wrist")
        initial = _adjust_kinematic_observation(ctx, arm)
        if ARM_DOF == 8 and abs(float(initial["observed_j8"])) > LOCKED_J8_CAPTURE_TOLERANCE_RAD:
            raise RuntimeError(
                f"{arm} J8 is not locked at 0rad in evaluator proprioception"
            )
        target = camera_frame_pose_target(
            eef_position=initial["position"],
            eef_quaternion=initial["quaternion"],
            camera_quaternion=camera["quat"],
            forward=float(forward),
            leftward=float(leftward),
            upward=float(upward),
            roll=float(roll),
            pitch=float(pitch),
            yaw=float(yaw),
        )
    except (RuntimeError, TypeError, ValueError) as exc:
        _set_result(ctx, tool_name, {"ok": False, "error": str(exc)})
        yield ctx.world.hold_action()
        return

    move_position = bool(np.linalg.norm(values[:3]) > 1e-8)
    move_orientation = bool(np.any(np.abs(values[3:6]) > 1e-9))
    joint_mapping = {
        "fixed": [f"{arm}_arm_joint{index}" for index in range(1, 5)],
        "solved": [f"{arm}_arm_joint{index}" for index in range(5, 8)],
        "locked": [f"{arm}_arm_joint8"] if ARM_DOF == 8 else [],
    }
    if not move_position and not move_orientation:
        _set_result(
            ctx,
            tool_name,
            {
                "ok": True,
                "build": ADJUST_EEF_LOCAL_BUILD,
                "arm": arm,
                "feed": f"{arm}_wrist",
                "note": "all deltas are zero; no action",
                "joint_mapping": joint_mapping,
                "j8_participates": False,
                "j8_target_rad": 0.0,
                "camera_pose_source": "evaluator_cam_rel_poses",
            },
        )
        yield ctx.world.hold_action()
        return

    translation_report: dict[str, Any] = {
        "ok": True,
        "converged": True,
        "reason": "no_translation",
        "steps_executed": 0,
        "j8_participates": False,
    }
    control_deadline = time.monotonic() + max(1.0, float(timeout_s))
    if move_position:
        translation_report = yield from _execute_local_pose_closed_loop(
            ctx,
            arm=arm,
            adapter=adapter,
            observation_sequence=sequence,
            target_position=target.position,
            target_quaternion=initial["quaternion"],
            pos_tol=float(pos_tol),
            ori_tol_deg=float(ori_tol_deg),
            max_steps=int(max_steps),
            timeout_s=float(timeout_s),
            stage_name=f"{tool_name}.translation",
            deadline_monotonic=control_deadline,
            skip_success_settle=bool(move_orientation),
        )
        sequence = int(
            translation_report.get("last_observation_sequence", sequence)
        )

    after_translation = _adjust_kinematic_observation(ctx, arm)
    translation_position_error = float(
        np.linalg.norm(after_translation["position"] - target.position)
    )
    translation_orientation_error = orientation_error_deg(
        after_translation["quaternion"],
        initial["quaternion"],
    )
    translation_orientation_limit = max(float(ori_tol_deg) * 2.0, 6.0)
    translation_position_ok = bool(
        not move_position
        or translation_position_error <= max(0.001, float(pos_tol))
    )
    translation_orientation_ok = bool(
        not move_position
        or move_orientation
        or translation_orientation_error <= translation_orientation_limit
    )

    q_before_rotation = after_translation["q"].copy()
    orientation_motion: dict[str, Any] = {
        "ok": True,
        "reason": "no_rotation",
        "controller_steps": 0,
        "fixed_q1234_rad": q_before_rotation[:4].tolist(),
        "commanded_joint_numbers": [5, 6, 7],
        "j8_participates": False,
        "last_observation_sequence": int(sequence),
    }
    if move_orientation:
        orientation_motion = yield from _execute_local_j567_closed_loop(
            ctx,
            arm=arm,
            adapter=adapter,
            observation_sequence=sequence,
            target_quaternion=target.quaternion,
            ori_tol_deg=float(ori_tol_deg),
            max_steps=int(max_steps),
            timeout_s=float(timeout_s),
            stage_name=f"{tool_name}.orientation",
            deadline_monotonic=control_deadline,
        )

    final = _adjust_kinematic_observation(ctx, arm)
    final_position_error = float(
        np.linalg.norm(final["position"] - target.position)
    )
    final_orientation_error = orientation_error_deg(
        final["quaternion"],
        target.quaternion,
    )
    final_position_ok = bool(
        not move_position
        or final_position_error <= max(0.001, float(pos_tol))
    )
    final_orientation_limit = (
        max(0.25, float(ori_tol_deg))
        if move_orientation
        else translation_orientation_limit
    )
    final_orientation_ok = bool(
        final_orientation_error <= final_orientation_limit
    )
    j1234_drift = float(
        np.linalg.norm(final["q"][:4] - q_before_rotation[:4], ord=np.inf)
    )
    j1234_held = bool(
        not move_orientation
        or j1234_drift <= math.radians(max(0.25, float(ori_tol_deg)))
    )
    j8_ok = bool(
        ARM_DOF != 8
        or abs(float(final["observed_j8"])) <= LOCKED_J8_CAPTURE_TOLERANCE_RAD
    )
    overall_ok = bool(
        (not move_position or translation_report.get("ok", False))
        and translation_position_ok
        and translation_orientation_ok
        and orientation_motion.get("ok", False)
        and final_position_ok
        and final_orientation_ok
        and j1234_held
        and j8_ok
    )
    orientation_solve = dict(
        orientation_motion.get("orientation_solve")
        or {
            "ok": True,
            "skipped": True,
            "reason": "no_rotation",
            "fixed_joint_numbers": [1, 2, 3, 4],
            "commanded_joint_numbers": [5, 6, 7],
            "j8_participates": False,
        }
    )
    tool_roll_motion = {
        "ok": j8_ok,
        "active": bool(ARM_DOF == 8),
        "joint": f"{arm}_arm_joint8" if ARM_DOF == 8 else None,
        "qpos_before_deg": round(math.degrees(initial["observed_j8"]), 4),
        "qpos_target_deg": 0.0,
        "qpos_after_deg": round(math.degrees(final["observed_j8"]), 4),
        "locked_after_motion": j8_ok,
        "lock_target_deg": 0.0,
        "j8_participates": False,
        "note": "J8 is fixed by the official robot profile and excluded from EEF control",
    }
    _set_result(
        ctx,
        tool_name,
        {
            "ok": overall_ok,
            "build": ADJUST_EEF_LOCAL_BUILD,
            "robot_dof": int(ARM_DOF),
            "arm": arm,
            "feed": f"{arm}_wrist",
            "translation_m": {
                "forward": float(forward),
                "leftward": float(leftward),
                "upward": float(upward),
            },
            "rotation_deg": {
                "roll": float(roll),
                "pitch": float(pitch),
                "yaw": float(yaw),
            },
            "rotation_mode": "local gripper RPY solved with fixed-J1234 J567 IK",
            "shared_timeout_budget_s": float(timeout_s),
            "translation_and_orientation_share_timeout": True,
            "joint_mapping": joint_mapping,
            "orientation_solve": orientation_solve,
            "convention": {
                "positive_leftward": "image left / camera -X",
                "translation_stage_orientation": (
                    "the initial EEF orientation is held during translation; "
                    "the final orientation is applied afterward with fixed J1-J4"
                ),
                "rotation_mode": "local gripper RPY target solved with J5-J7 only",
                "solver_joint_numbers": [5, 6, 7],
                "fixed_joint_numbers": [1, 2, 3, 4],
                "j8_participates": False,
            },
            "camera_before": {
                "pos": camera["pos"].round(6).tolist(),
                "quat": camera["quat"].round(6).tolist(),
                "frame": "robot_base",
                "source": "evaluator_cam_rel_poses",
            },
            "wrist_camera_before": {
                "pos": camera["pos"].round(6).tolist(),
                "quat": camera["quat"].round(6).tolist(),
            },
            "delta_camera_m": target.delta_camera.round(6).tolist(),
            "delta_robot_m": target.delta_robot.round(6).tolist(),
            "eef_before": {
                "pos": initial["position"].round(6).tolist(),
                "quat": initial["quaternion"].round(6).tolist(),
                "source": "submission_local_static_urdf_fk",
            },
            "eef_target": {
                "pos": target.position.round(6).tolist(),
                "quat": target.quaternion.round(6).tolist(),
            },
            "eef_after_translation": {
                "pos": after_translation["position"].round(6).tolist(),
                "quat": after_translation["quaternion"].round(6).tolist(),
            },
            "eef_after": {
                "pos": final["position"].round(6).tolist(),
                "quat": final["quaternion"].round(6).tolist(),
                "source": "submission_local_static_urdf_fk",
            },
            "translation_stage_pos_err_mm": round(
                translation_position_error * 1000.0,
                3,
            ),
            "translation_stage_ori_err_deg": round(
                translation_orientation_error,
                3,
            ),
            "pos_err_mm": round(final_position_error * 1000.0, 3),
            "ori_err_deg": round(final_orientation_error, 3),
            "translation_stage_pos_ok": translation_position_ok,
            "translation_stage_ori_ok": translation_orientation_ok,
            "pos_ok": final_position_ok,
            "ori_ok": final_orientation_ok,
            "target_reached": bool(final_position_ok and final_orientation_ok),
            "translation_control": translation_report,
            "translation_command_ok": bool(
                not move_position or translation_report.get("ok", False)
            ),
            "wrist_joint_motion": {
                "arm_joints": orientation_motion,
                "tool_roll_j8": tool_roll_motion,
                "body_lock": {
                    "active": True,
                    "mode": "official action targets hold base, trunk, and inactive arm",
                    "direct_root_lock": False,
                },
            },
            "tool_roll_lock": tool_roll_motion,
            "legacy_7dof_precondition": {
                "required": bool(ARM_DOF == 8),
                "reset": False,
                "replacement": "episode initialization and profile-level J8=0 action lock",
                "direct_joint_write": False,
            },
            "arm_qpos_before_rotation_deg": np.degrees(
                q_before_rotation
            ).round(4).tolist(),
            "arm_qpos_after_all_deg": np.degrees(final["q"]).round(4).tolist(),
            "arm_qpos_delta_after_all_deg": np.degrees(
                final["q"] - q_before_rotation
            ).round(5).tolist(),
            "j1234_command_policy": "fixed at post-translation observed values for every rotation action",
            "j1234_measured_drift_inf_rad": j1234_drift,
            "j1234_held": j1234_held,
            "j567_only_orientation_control": True,
            "j8_participates": False,
            "j8_target_rad": 0.0,
            "j8_ok": j8_ok,
            "finger_qpos": final["gripper"].tolist(),
            "kinematic_snap": {
                "snapped": False,
                "disabled": True,
                "reason": "motion is observation-tracked official action output only",
            },
            "observation_contract": [
                "evaluator_proprioception",
                f"evaluator_{arm}_wrist_cam_rel_poses",
                "submission_local_static_robot_model",
            ],
            "simulator_fk_ik_used": False,
            "simulator_eef_pose_used": False,
            "direct_simulator_mutation": False,
            "error": None if overall_ok else "local observation/action wrist adjustment did not converge",
        },
    )
    yield ctx.world.hold_action()


