def move_point_to_point(
    ctx,
    session_id: str,
    image_id: str,
    points: list[Any],
    above_target_point_m: float = 0.0,
    pos_tol: float = 0.012,
    ori_tol_deg: float = 5.0,
    max_steps: int = 360,
    timeout_s: float = 90.0,
):
    raw_args = {
        "session_id": session_id,
        "image_id": image_id,
        "points": points,
        "above_target_point_m": above_target_point_m,
        "pos_tol": pos_tol,
        "ori_tol_deg": ori_tol_deg,
        "max_steps": max_steps,
        "timeout_s": timeout_s,
    }
    try:
        args = validate_move_point_to_point_args(raw_args)
    except (TypeError, ValueError) as exc:
        _move_point_failure(
            ctx,
            stage="input validation",
            error=str(exc),
            image_id=str(image_id),
        )
        yield ctx.world.hold_action()
        return
    try:
        _require_episode_initialized(ctx, "move_point_to_point")
        capture = _load_frozen_capture(
            args["session_id"],
            args["image_id"],
            role="head",
        )
        if capture.evaluator_sequence is None or capture.evaluator_sequence <= 0:
            raise ValueError("frozen capture has no valid evaluator sequence")
        source_robot, source_meta = _move_point_robot_base_click(
            capture,
            args["points"][0],
        )
        target_robot, target_meta = _move_point_robot_base_click(
            capture,
            args["points"][1],
        )
        capture_state = _move_point_capture_kinematics(capture)
    except (FileNotFoundError, KeyError, OSError, TypeError, ValueError) as exc:
        _move_point_failure(
            ctx,
            stage="observation validation",
            error=str(exc),
            image_id=args["image_id"],
        )
        yield ctx.world.hold_action()
        return

    distances = {
        side: float(
            np.linalg.norm(
                source_robot - capture_state["eef"][side]["position"]
            )
        )
        for side in ("left", "right")
    }
    arm = min(("left", "right"), key=lambda side: distances[side])
    try:
        gripper = _move_point_gripper_state(
            capture_state["gripper_q"][arm],
            capture_state["gripper_qvel"][arm],
        )
    except (TypeError, ValueError) as exc:
        _move_point_failure(
            ctx,
            stage="observation validation",
            error=str(exc),
            image_id=args["image_id"],
            details={"arm_candidate": arm, "eef_distance_m": distances},
        )
        yield ctx.world.hold_action()
        return
    if not gripper["validated"]:
        _move_point_failure(
            ctx,
            stage="observation validation",
            error=(
                f"nearest {arm} gripper failed the stable intermediate-aperture "
                "proprioceptive heuristic"
            ),
            image_id=args["image_id"],
            details={
                "arm_candidate": arm,
                "eef_distance_m": distances,
                "gripper": gripper,
            },
        )
        yield ctx.world.hold_action()
        return

    target_above_robot = target_robot + np.array(
        [0.0, 0.0, args["above_target_point_m"]],
        dtype=np.float64,
    )
    delta_robot = target_above_robot - source_robot
    translation_m = float(np.linalg.norm(delta_robot))
    if translation_m > MOVE_POINT_TO_POINT_MAX_TRANSLATION_M:
        _move_point_failure(
            ctx,
            stage="planning",
            error=(
                f"requested translation {translation_m:.3f}m exceeds "
                f"{MOVE_POINT_TO_POINT_MAX_TRANSLATION_M:.3f}m"
            ),
            image_id=args["image_id"],
            details={
                "arm": arm,
                "delta_robot_base_m": delta_robot.astype(float).tolist(),
                "translation_m": translation_m,
            },
        )
        yield ctx.world.hold_action()
        return

    capture_eef = capture_state["eef"][arm]
    source_anchor_eef = _quat_to_mat_xyzw(
        capture_eef["quaternion"]
    ).T @ (source_robot - capture_eef["position"])
    target_eef_position = capture_eef["position"] + delta_robot
    target_eef_quaternion = capture_eef["quaternion"].copy()

    try:
        _ensure_session(args["session_id"])
        plan_id = _next_plan_id(args["session_id"])
        planned_trajectory = _move_point_compile_trajectory(
            plan_id=plan_id,
            args=args,
            capture_state=capture_state,
            arm=arm,
            source_robot=source_robot,
            target_robot=target_robot,
            target_above_robot=target_above_robot,
            target_eef_position=target_eef_position,
            target_eef_quaternion=target_eef_quaternion,
        )
        _move_point_write_plan(planned_trajectory)
        trajectory, plan_path = _move_point_load_trajectory(
            args["session_id"],
            plan_id,
        )
    except (FileNotFoundError, KeyError, OSError, TypeError, ValueError) as exc:
        _move_point_failure(
            ctx,
            stage="planning",
            error=str(exc),
            image_id=args["image_id"],
            details={
                "arm": arm,
                "gripper": gripper,
                "plan_id": locals().get("plan_id"),
            },
        )
        yield ctx.world.hold_action()
        return

    try:
        start_ok, start_validation = _move_point_start_state_validation(
            ctx,
            capture_state,
        )
    except (RuntimeError, TypeError, ValueError) as exc:
        _move_point_failure(
            ctx,
            stage="start-state validation",
            error=str(exc),
            image_id=args["image_id"],
            details={"arm": arm, "gripper": gripper},
        )
        yield ctx.world.hold_action()
        return
    if not start_ok:
        reason = str(start_validation.get("reason", "stale_capture"))
        _move_point_failure(
            ctx,
            stage="start-state validation",
            error=f"frozen capture cannot be executed: {reason}",
            image_id=args["image_id"],
            details={
                "arm": arm,
                "gripper": gripper,
                "start_state_validation": start_validation,
            },
        )
        yield ctx.world.hold_action()
        return

    adapter = start_validation.pop("adapter")
    observation_sequence = int(start_validation["observation_sequence"])
    execution_started = time.monotonic()
    try:
        motion_generator = _move_point_execute_trajectory(
            ctx,
            trajectory=trajectory,
            capture_state=capture_state,
            adapter=adapter,
            observation_sequence=observation_sequence,
            timeout_s=args["timeout_s"],
            max_steps=args["max_steps"] - MOVE_POINT_TO_POINT_STABLE_STEPS,
        )
        while True:
            try:
                yield next(motion_generator)
            except StopIteration as stopped:
                motion = stopped.value
                break
        elapsed_s = time.monotonic() - execution_started
        remaining_timeout_s = float(args["timeout_s"]) - elapsed_s
        if remaining_timeout_s <= 0.0:
            stability = {
                "ok": False,
                "reason": "timeout",
                "required_stable_steps": int(
                    MOVE_POINT_TO_POINT_STABLE_STEPS
                ),
                "stable_steps": 0,
                "verification_steps": 0,
                "arm_qvel_threshold_rad_s": float(
                    MOVE_POINT_TO_POINT_FINAL_ARM_QVEL_RAD_S
                ),
            }
        else:
            stability_generator = _move_point_verify_stable_pose(
                ctx,
                arm=arm,
                adapter=adapter,
                observation_sequence=int(
                    motion["last_observation_sequence"]
                ),
                target_position=target_eef_position,
                target_quaternion=target_eef_quaternion,
                target_q=np.asarray(
                    trajectory["waypoints"][-1], dtype=np.float64
                ),
                pos_tol=args["pos_tol"],
                ori_tol_deg=args["ori_tol_deg"],
                timeout_s=remaining_timeout_s,
                expected_episode_id=str(capture_state["episode_id"]),
            )
            while True:
                try:
                    yield next(stability_generator)
                except StopIteration as stopped:
                    stability = stopped.value
                    break
    except Exception as exc:
        if not _move_point_is_cancellation(exc):
            raise
        observed = _adjust_kinematic_observation(ctx, arm)
        cancellation_trunk_q = np.asarray(
            observed["trunk"], dtype=np.float64
        ).reshape(4).copy()
        cancellation_trunk_q[3] = 0.0
        ctx.world.set_arm_pin_qpos(arm, observed["q"])
        _move_point_failure(
            ctx,
            stage="cancellation",
            error=str(exc) or "move_point_to_point was cancelled",
            image_id=args["image_id"],
            details={
                "arm": arm,
                "gripper": gripper,
                "cancellation_hold_source": (
                    "subsequent_proprioception_measured_arm_qpos"
                ),
                "plan_id": plan_id,
                "trajectory_digest": trajectory["integrity"]["digest"],
            },
        )
        gripper_overrides, _gripper_report = (
            _move_point_gripper_action_overrides(ctx, capture_state)
        )
        yield ctx.world.make_action(
            **{
                f"arm_{arm}": observed["q"].astype(float).tolist(),
                **gripper_overrides,
            }
        )
        return

    final_observed = _adjust_kinematic_observation(ctx, arm)
    final_source_robot = (
        _quat_to_mat_xyzw(final_observed["quaternion"])
        @ source_anchor_eef
        + final_observed["position"]
    )
    point_error_m = float(
        np.linalg.norm(final_source_robot - target_above_robot)
    )
    point_tolerance_m = max(0.002, args["pos_tol"] * 1.5)
    point_reached = bool(point_error_m <= point_tolerance_m)
    motion_reason = str(motion.get("reason", "tracking_failed"))
    motion_completed = bool(motion.get("ok"))
    overall_ok = bool(
        motion_completed and stability.get("ok") and point_reached
    )
    stability_reason = str(stability.get("reason", "tracking_failed"))
    failure_stage = None
    if not overall_ok:
        failure_stage = (
            "timeout"
            if "timeout" in {motion_reason, stability_reason}
            else "tracking"
        )

    _set_result(
        ctx,
        "move_point_to_point",
        {
            **_move_point_common_result(),
            "ok": overall_ok,
            "error": (
                None
                if overall_ok
                else "local EEF tracking or final rigid-point constraint did not converge"
            ),
            "failure_stage": failure_stage,
            "build": MOVE_POINT_TO_POINT_LOCAL_BUILD,
            "image_id": args["image_id"],
            "image_width": int(capture.depth.shape[1]),
            "image_height": int(capture.depth.shape[0]),
            "points": [
                {"role": "source", **args["points"][0]},
                {"role": "target", **args["points"][1]},
            ],
            "point_observation": {
                "source": source_meta,
                "target": target_meta,
            },
            "frozen_observation": {
                "episode_id": capture_state["episode_id"],
                "motion_epoch": capture_state["motion_epoch"],
                "evaluator_sequence": capture.evaluator_sequence,
                "rgb_depth_camera_proprio_same_capture": True,
            },
            "robot_profile": ROBOT_PROFILE,
            "plan_id": plan_id,
            "plan_record_path": plan_path,
            "trajectory_schema": trajectory["schema"],
            "trajectory_schema_version": trajectory["schema_version"],
            "trajectory_digest": trajectory["integrity"]["digest"],
            "trajectory_waypoint_count": len(trajectory["waypoints"]),
            "arm": arm,
            "eef_distance_m": distances,
            "gripper": gripper,
            "gripper_command_preservation": (
                "capture_qpos_local_servo_or_verified_close_keepalive"
            ),
            "above_target_point_m": args["above_target_point_m"],
            "target_clearance_robot_base_z_m": args[
                "above_target_point_m"
            ],
            "delta_robot_base_m": delta_robot.astype(float).tolist(),
            "translation_m": translation_m,
            "target_eef_robot_m": target_eef_position.astype(float).tolist(),
            "eef_orientation_locked": True,
            "point_error_m": point_error_m,
            "point_tolerance_m": point_tolerance_m,
            "point_reached": point_reached,
            "point_reached_source": "subsequent_proprioception_and_static_fk",
            "motion": motion,
            "stability": stability,
            "start_state_validation": start_validation,
            "collision_checked": False,
        },
    )
    yield ctx.world.hold_action()


MOVE_TRACKED_POINT_LOCAL_BUILD = (
    "official_v2_live_tracked_symbolic_rigid_trajectory_v78_arm_only_safe_exec"
)
MOVE_TRACKED_POINT_TRAJECTORY_SCHEMA = (
    "official_v2_move_tracked_point_trajectory"
)
MOVE_TRACKED_POINT_TRAJECTORY_SCHEMA_VERSION = 4
MOVE_TRACKED_POINT_OVERLAP_POSE_FAMILY_BASE_COUNT = 3
MOVE_TRACKED_POINT_OVERLAP_POSE_FAMILY_MAX_IK_TARGETS = 32
MOVE_TRACKED_POINT_OVERLAP_POSE_FAMILY_COARSE_BASE_COUNT = 1
MOVE_TRACKED_POINT_OVERLAP_POSE_FAMILY_COARSE_MAX_IK_TARGETS = 8
