def _exec_gripper_qpos_is_open(qpos: Any) -> bool:
    try:
        observed = np.asarray(
            qpos if qpos is not None else [],
            dtype=np.float64,
        ).reshape(-1)
    except (TypeError, ValueError):
        return False
    return bool(
        observed.size == 2
        and np.all(np.isfinite(observed))
        and np.all(
            observed
            >= GRIPPER_CLOSE_UPPER_LIMIT_M
            - GRIPPER_CLOSE_FULL_OPEN_QPOS_TOLERANCE_M
        )
    )


def _ensure_exec_selected_gripper_open(
    ctx,
    arm: str,
    *,
    result_out: dict[str, Any],
):
    """Open the execution gripper when needed without blocking arm execution."""
    side = str(arm).strip().lower()
    before = ctx.world.gripper_qpos_list(side)
    already_open = _exec_gripper_qpos_is_open(before)
    close_keepalive_before = bool(
        getattr(
            ctx.world,
            "gripper_close_keepalive_active",
            lambda _arm: False,
        )(side)
    )
    release_keepalive = getattr(
        ctx.world,
        "release_gripper_close_keepalive",
        None,
    )
    if callable(release_keepalive):
        release_keepalive(side)
    if LOCKED_J8_INDEX is not None:
        # Gripper-only frames still cross the same official action boundary;
        # the selected arm's locked J8 must therefore be zero from frame one.
        ctx.world.set_tool_roll_pin_qpos(side, LOCKED_J8_VALUE_RAD)

    uses_effort = bool(
        getattr(ctx.world, "gripper_uses_effort", lambda _arm: False)(side)
    )
    command = [GRIPPER_OPEN_EFFORT_N, GRIPPER_OPEN_EFFORT_N]
    action_steps = 0
    target_reached = bool(already_open)
    if not already_open:
        for _ in range(GRIPPER_OPEN_MAX_STEPS):
            _check_cancelled(ctx, f"exec_plan_pose open {side} gripper")
            if uses_effort:
                yield ctx.world.make_action(
                    **{f"gripper_effort_{side}": command}
                )
            else:
                yield ctx.world.make_action(**{f"gripper_{side}": [1.0]})
            action_steps += 1
            target_reached = _exec_gripper_qpos_is_open(
                ctx.world.gripper_qpos_list(side)
            )
            if target_reached:
                break

    hold_target = None
    if uses_effort:
        capture_hold = getattr(
            ctx.world,
            "capture_gripper_hold_qpos",
            None,
        )
        if callable(capture_hold):
            hold_target = capture_hold(
                side,
                allow_close_effort=False,
            )
    after = ctx.world.gripper_qpos_list(side)
    result_out.clear()
    result_out.update(
        {
            "arm": side,
            "checked_before_motion": True,
            "already_open": bool(already_open),
            "open_invoked": bool(not already_open),
            "open_action_steps": int(action_steps),
            "open_target_reached": bool(target_reached),
            "execution_continues": True,
            "gripper_qpos_before": before,
            "gripper_qpos_after": after,
            "commanded_gripper_action": (
                command if uses_effort else [1.0]
            ),
            "control_mode": (
                "independent_effort" if uses_effort else "position"
            ),
            "post_open_hold_qpos": hold_target,
            "close_keepalive_before": bool(close_keepalive_before),
            "close_keepalive_after": bool(
                getattr(
                    ctx.world,
                    "gripper_close_keepalive_active",
                    lambda _arm: False,
                )(side)
            ),
        }
    )


def exec_plan_pose(ctx, **kwargs):
    session_id = str(kwargs.get("session_id", "")).strip()
    plan_id = str(kwargs.get("plan_id", "")).strip()
    requested_arm = str(kwargs.get("arm", "")).strip().lower()
    stop_after_safe = bool(kwargs.get("stop_after_safe", False))
    reset_tool_roll = bool(
        kwargs.get("reset_tool_roll_at_start", True)
    )
    requested_back_m = kwargs.get("back_m")
    active_arm = None
    selected_j8_before_action = None
    pre_exec_gripper_open = None
    j8_reset = None
    start_arm_velocity_observation: dict[str, Any] = {}
    try:
        _require_episode_initialized(ctx, "exec_plan_pose")
        trajectory, plan_path, plan_record = _load_plan_trajectory(
            session_id,
            plan_id,
            include_record=True,
        )
        planned_arm = str(trajectory["active_arm"])
        if requested_arm in ("", "any"):
            active_arm = planned_arm
        elif requested_arm in ("left", "right"):
            active_arm = requested_arm
        else:
            raise ValueError("arm must be left, right, or omitted")
        parameters = dict(trajectory["parameters"])
        if reset_tool_roll != bool(
            parameters["reset_tool_roll_at_start"]
        ):
            raise ValueError(
                "reset_tool_roll_at_start does not match the immutable plan"
            )
        if requested_back_m not in (None, ""):
            back_m = float(requested_back_m)
            if not math.isfinite(back_m):
                raise ValueError("back_m must be finite")
            if (
                back_m != 0.0
                and not 0.02 <= back_m <= EXEC_SAFE_BACK_MAX_M
            ):
                raise ValueError(
                    "back_m must be 0 or in "
                    f"0.02..{EXEC_SAFE_BACK_MAX_M:.2f}m"
                )
        else:
            back_m = float(parameters["back_m"])

        tracking = dict(trajectory["tracking"])
        start_state = dict(trajectory["start_state"])
        if str(ctx.world.episode_id()) != str(start_state["episode_id"]):
            raise ValueError(
                "plan is stale because the evaluator episode changed"
            )
        current_epoch = int(ctx.world.motion_epoch())
        if current_epoch != int(start_state["motion_epoch"]):
            raise ValueError(
                "plan is stale because base or trunk motion occurred after capture"
            )
        final_q, final_q_resolution = _resolve_exec_final_q(
            trajectory=trajectory,
            record=plan_record,
            execution_arm=active_arm,
        )
        arm_switched = active_arm != planned_arm
        current_arms: dict[str, np.ndarray] = {}
        for side in ("left", "right"):
            current_q = _arm_vector(
                ctx.world.arm_qpos_list(side),
                label=f"current {side} arm_qpos",
            )
            if side == active_arm and LOCKED_J8_INDEX is not None:
                selected_j8_before_action = float(
                    current_q[LOCKED_J8_INDEX]
                )
            current_arms[side] = (
                _j8_locked_copy(
                    current_q,
                    label=f"current {side} normalized arm_qpos",
                )
                if side == active_arm
                else current_q.copy()
            )
            current_qvel = _arm_vector(
                ctx.world.arm_qvel_list(side),
                label=f"current {side} arm_qvel",
            )
            qvel_limit = float(
                tracking["stationary_qvel_tolerance_rad_s"]
            )
            start_arm_velocity_observation[side] = {
                "values_rad_s": current_qvel.astype(float).tolist(),
                "max_abs_rad_s": float(np.max(np.abs(current_qvel))),
                "legacy_stationary_tolerance_rad_s": qvel_limit,
                "exceeds_legacy_stationary_tolerance": bool(
                    float(np.max(np.abs(current_qvel))) > qvel_limit
                ),
                "policy": "diagnostic_only",
            }
        current_trunk = np.asarray(
            ctx.world.trunk_qpos(),
            dtype=np.float64,
        ).reshape(-1)
        planned_trunk = np.asarray(
            start_state["trunk_qpos"],
            dtype=np.float64,
        ).reshape(4)
        trunk_error = float(
            np.linalg.norm(current_trunk - planned_trunk, ord=np.inf)
        )
        trunk_tolerance = float(
            tracking["start_trunk_tolerance_rad"]
        )
        if trunk_error > trunk_tolerance:
            raise ValueError(
                f"plan start trunk mismatch {trunk_error:.4f}rad "
                f"exceeds {trunk_tolerance:.4f}rad"
            )
        current_grippers: dict[str, np.ndarray] = {}
        for side in ("left", "right"):
            current_gripper = np.asarray(
                ctx.world.gripper_qpos_list(side),
                dtype=np.float64,
            ).reshape(-1)
            if current_gripper.size == 0 or not np.all(np.isfinite(current_gripper)):
                raise ValueError(
                    f"current {side} gripper proprioception is invalid"
                )
            current_grippers[side] = current_gripper
        stored_back_m = float(parameters["back_m"])
        runtime_safe_q = None
        if arm_switched or abs(back_m - stored_back_m) > EXEC_SAFE_BACK_MATCH_TOL_M:
            final_pose_source = (
                "signed_final_q_submission_local_fk"
                if not arm_switched
                else (
                    "signed_requested_arm_final_q_submission_local_fk"
                    if str(final_q_resolution["source"])
                    == "signed_final_q_by_arm"
                    else "locally_verified_requested_arm_final_q_submission_local_fk"
                )
            )
            runtime_safe_q, back_m_resolution = _recompute_exec_safe_q(
                ctx=ctx,
                execution_arm=active_arm,
                final_q=final_q,
                current_arms=current_arms,
                current_trunk=current_trunk,
                current_grippers=current_grippers,
                requested_back_m=back_m,
                fallback_back_m=(None if arm_switched else stored_back_m),
                final_q_source=final_pose_source,
            )
        else:
            back_m_resolution = {
                "mode": "signed_planned_safe",
                "requested_back_m": float(back_m),
                "active_back_m": float(stored_back_m),
                "back_m_adapted": False,
                "solver": "planner_signed_safe_q",
                "execution_arm": active_arm,
                "j8_locked": LOCKED_J8_INDEX is not None,
            }
        execution_segments, start_resolution = _prepare_exec_segments(
            trajectory=trajectory,
            current_q=current_arms[active_arm],
            current_trunk=current_trunk,
            stop_after_safe=stop_after_safe,
            execution_arm=active_arm,
            runtime_safe_q=runtime_safe_q,
            runtime_final_q=(final_q if arm_switched else None),
            back_m_resolution=back_m_resolution,
        )

        # All read-only path checks have passed. Pin every non-gripper
        # controller to the current evaluator observation before emitting the
        # first action, then establish the selected gripper's open state before
        # J8 reset or trajectory motion.
        for side in ("left", "right"):
            ctx.world.set_arm_pin_qpos(side, current_arms[side])
        ctx.world.set_trunk_pin_qpos(current_trunk.astype(float).tolist())

        pre_exec_gripper_open = {}
        for open_action in _ensure_exec_selected_gripper_open(
            ctx,
            active_arm,
            result_out=pre_exec_gripper_open,
        ):
            yield open_action

        j8_reset = {}
        for reset_action in _reset_and_lock_selected_j8(
            ctx,
            active_arm,
            stage="exec_plan_pose.start",
            result_out=j8_reset,
        ):
            yield reset_action
        if not bool(j8_reset["ok"]):
            raise RuntimeError(
                f"exec_plan_pose failed to reset and lock {active_arm} J8: "
                f"{j8_reset.get('error', 'unknown J8 reset failure')}"
            )
        if selected_j8_before_action is not None:
            j8_reset["before_deg"] = math.degrees(
                selected_j8_before_action
            )
            j8_reset["already_zero"] = bool(
                abs(selected_j8_before_action) <= 1e-9
            )
            j8_reset["lock_applied_from_first_exec_action"] = True
        observed_active_arm = _arm_vector(
            ctx.world.arm_qpos_list(active_arm),
            label=f"post-reset {active_arm} arm_qpos",
        )
        if (
            LOCKED_J8_INDEX is not None
            and abs(float(observed_active_arm[LOCKED_J8_INDEX]))
            > LOCKED_J8_CAPTURE_TOLERANCE_RAD
        ):
            raise ValueError(
                f"exec start failed to lock {active_arm} J8 at zero; observed "
                f"{observed_active_arm[LOCKED_J8_INDEX]:.4f}rad after reset"
            )
        current_arms[active_arm] = _j8_locked_copy(
            observed_active_arm,
            label=f"post-reset {active_arm} normalized arm_qpos",
        )
        observed_gripper = np.asarray(
            ctx.world.gripper_qpos_list(active_arm),
            dtype=np.float64,
        ).reshape(-1)
        if observed_gripper.size and np.all(np.isfinite(observed_gripper)):
            current_grippers[active_arm] = observed_gripper
    except (FileNotFoundError, OSError, RuntimeError, TypeError, ValueError) as exc:
        _set_result(
            ctx,
            "exec_plan_pose",
            {
                "ok": False,
                "error": str(exc),
                "session_id": session_id,
                "plan_id": plan_id,
                "arm": active_arm,
                "start_arm_velocity_observation": _json_ready(
                    start_arm_velocity_observation
                ),
                "pre_exec_gripper_open": _json_ready(
                    pre_exec_gripper_open
                ),
                "j8_reset": _json_ready(j8_reset),
                "execution": (
                    "rejected_after_j8_reset"
                    if j8_reset is not None
                    and int(j8_reset.get("action_steps", 0)) > 0
                    else "rejected_after_pre_exec_gripper_open"
                    if pre_exec_gripper_open is not None
                    and int(
                        pre_exec_gripper_open.get("open_action_steps", 0)
                    )
                    > 0
                    else "rejected_before_action"
                ),
            },
        )
        yield ctx.world.hold_action()
        return

    settle_tolerance = float(tracking["settle_tolerance_rad"])
    max_tracking_error = float(tracking["max_tracking_error_rad"])
    waypoint_timeout_steps = max(
        1,
        int(
            math.ceil(
                float(tracking["waypoint_timeout_s"]) * CONTROL_HZ
            )
        ),
    )
    stall_limit = max(1, int(tracking["stall_steps"]))
    executed_segments: list[str] = []
    action_steps = 0
    max_observed_error = 0.0

    for side in ("left", "right"):
        ctx.world.set_arm_pin_qpos(side, current_arms[side])
    ctx.world.set_trunk_pin_qpos(current_trunk.astype(float).tolist())

    gripper_holds: dict[str, dict[str, Any]] = {}
    for side in ("left", "right"):
        close_active = bool(
            getattr(
                ctx.world,
                "gripper_close_keepalive_active",
                lambda _arm: False,
            )(side)
        )
        uses_effort = bool(
            getattr(
                ctx.world,
                "gripper_uses_effort",
                lambda _arm: False,
            )(side)
        )
        hold_target = None
        if close_active:
            hold_mode = "close_keepalive"
        elif uses_effort:
            capture_hold = getattr(
                ctx.world,
                "capture_gripper_hold_qpos",
                None,
            )
            hold_target = (
                capture_hold(side) if callable(capture_hold) else None
            )
            hold_mode = (
                "qpos_effort_servo"
                if hold_target is not None
                else "effort_hold_unavailable"
            )
        else:
            hold_mode = "position_controller_pin"
        gripper_holds[side] = {
            "mode": hold_mode,
            "entry_qpos": current_grippers[side].astype(float).tolist(),
            "hold_qpos": hold_target,
            "hold_allows_close_effort": getattr(
                ctx.world,
                "gripper_hold_allows_close_effort",
                lambda _arm: None,
            )(side),
        }

    def pin_observed_body_for_hold() -> tuple[np.ndarray, np.ndarray]:
        observed_q = _arm_vector(
            ctx.world.arm_qpos_list(active_arm),
            label=f"observed {active_arm} arm_qpos",
        )
        ctx.world.set_arm_pin_qpos(active_arm, observed_q)
        observed_trunk = np.asarray(
            ctx.world.trunk_qpos(), dtype=np.float64
        ).reshape(4)
        if not np.all(np.isfinite(observed_trunk)):
            raise ValueError("observed trunk qpos is non-finite")
        observed_trunk[3] = 0.0
        ctx.world.set_trunk_pin_qpos(observed_trunk.astype(float).tolist())
        return observed_q, observed_trunk

    for segment in execution_segments:
        segment_name = str(segment["name"])
        for waypoint_index, raw_target in enumerate(segment["waypoints"]):
            target = _require_serialized_j8_zero(
                raw_target,
                label=f"{segment_name} waypoint",
            )
            previous_error = float("inf")
            stall_steps = 0
            for settle_step in range(waypoint_timeout_steps):
                is_cancelled = getattr(ctx, "is_cancelled", None)
                if callable(is_cancelled) and bool(is_cancelled()):
                    pin_observed_body_for_hold()
                _check_cancelled(
                    ctx,
                    f"exec_plan_pose {segment_name} waypoint {waypoint_index}",
                )
                action_overrides: dict[str, Any] = {
                    f"arm_{active_arm}": target.tolist()
                }
                yield ctx.world.make_action(**action_overrides)
                action_steps += 1
                observed = _arm_vector(
                    ctx.world.arm_qpos_list(active_arm),
                    label=f"observed {active_arm} arm_qpos",
                )
                arm_error = float(
                    np.linalg.norm(target - observed, ord=np.inf)
                )
                error = arm_error
                max_observed_error = max(max_observed_error, error)
                if error <= settle_tolerance:
                    break
                if error > max_tracking_error:
                    failure = (
                        f"tracking error {error:.4f}rad exceeds "
                        f"{max_tracking_error:.4f}rad"
                    )
                    pin_observed_body_for_hold()
                    _set_result(
                        ctx,
                        "exec_plan_pose",
                        {
                            "ok": False,
                            "error": failure,
                            "session_id": session_id,
                            "plan_id": plan_id,
                            "arm": active_arm,
                            "start_arm_velocity_observation": _json_ready(
                                start_arm_velocity_observation
                            ),
                            "pre_exec_gripper_open": _json_ready(
                                pre_exec_gripper_open
                            ),
                            "segment": segment_name,
                            "waypoint_index": int(waypoint_index),
                            "action_steps": int(action_steps),
                            "execution": "stopped_on_tracking_error",
                        },
                    )
                    yield ctx.world.hold_action()
                    return
                if previous_error - error <= 1e-4:
                    stall_steps += 1
                else:
                    stall_steps = 0
                previous_error = error
                if stall_steps >= stall_limit:
                    pin_observed_body_for_hold()
                    _set_result(
                        ctx,
                        "exec_plan_pose",
                        {
                            "ok": False,
                            "error": "proprioceptive tracking stalled",
                            "session_id": session_id,
                            "plan_id": plan_id,
                            "arm": active_arm,
                            "start_arm_velocity_observation": _json_ready(
                                start_arm_velocity_observation
                            ),
                            "pre_exec_gripper_open": _json_ready(
                                pre_exec_gripper_open
                            ),
                            "segment": segment_name,
                            "waypoint_index": int(waypoint_index),
                            "action_steps": int(action_steps),
                            "execution": "stopped_on_tracking_stall",
                        },
                    )
                    yield ctx.world.hold_action()
                    return
            else:
                pin_observed_body_for_hold()
                _set_result(
                    ctx,
                    "exec_plan_pose",
                    {
                        "ok": False,
                        "error": "waypoint tracking timeout",
                        "session_id": session_id,
                        "plan_id": plan_id,
                        "arm": active_arm,
                        "start_arm_velocity_observation": _json_ready(
                            start_arm_velocity_observation
                        ),
                        "pre_exec_gripper_open": _json_ready(
                            pre_exec_gripper_open
                        ),
                        "segment": segment_name,
                        "waypoint_index": int(waypoint_index),
                        "action_steps": int(action_steps),
                        "execution": "stopped_on_tracking_timeout",
                    },
                )
                yield ctx.world.hold_action()
                return
        executed_segments.append(segment_name)

    final_q = _require_serialized_j8_zero(
        execution_segments[-1]["endpoint_q"],
        label="executed endpoint_q",
    )
    ctx.world.set_arm_pin_qpos(active_arm, final_q)
    _set_result(
        ctx,
        "exec_plan_pose",
        {
            "ok": True,
            "session_id": session_id,
            "plan_id": plan_id,
            "plan_record_path": plan_path,
            "trajectory_digest": trajectory["integrity"]["digest"],
            "source_image_id": trajectory["source_image_id"],
            "arm": active_arm,
            "planned_arm": planned_arm,
            "requested_arm": requested_arm or None,
            "arm_switched": bool(arm_switched),
            "start_arm_velocity_observation": _json_ready(
                start_arm_velocity_observation
            ),
            "pre_exec_gripper_open": _json_ready(
                pre_exec_gripper_open
            ),
            "j8_reset": _json_ready(j8_reset),
            "final_q_resolution": _json_ready(final_q_resolution),
            "segments_executed": executed_segments,
            "start_mode": start_resolution["mode"],
            "start_resolution": start_resolution,
            "requested_back_m": float(
                start_resolution["back_m_resolution"]["requested_back_m"]
            ),
            "active_back_m": float(
                start_resolution["back_m_resolution"]["active_back_m"]
            ),
            "back_m_adapted": bool(
                start_resolution["back_m_resolution"]["back_m_adapted"]
            ),
            "gripper_policy": (
                "open_selected_before_motion_then_hold_observed_qpos"
            ),
            "gripper_holds": gripper_holds,
            "stop_after_safe": bool(stop_after_safe),
            "action_steps": int(action_steps),
            "max_observed_tracking_error_rad": float(
                max_observed_error
            ),
            "endpoint_q": final_q.astype(float).tolist(),
            "trunk_motion": False,
            "execution": "official_action_joint_trajectory_replay",
            "direct_simulator_mutation": False,
        },
    )
    yield ctx.world.hold_action()


def grasp_prep_hard_timeout_s(timeout_s: float) -> float:
    timeout = float(timeout_s)
    if not math.isfinite(timeout) or timeout <= 0.0:
        raise ValueError("timeout_s must be a positive finite value")
    grace = min(GRASP_PREP_PROGRESS_GRACE_MAX_S, timeout)
    return timeout + GRASP_PREP_PROGRESS_GRACE_EXTENSIONS * grace


def _grasp_prep_snapshot(
    ctx,
    arms: list[str],
) -> tuple[dict[str, np.ndarray], dict[str, np.ndarray]]:
    # Read one adapter-owned proprio vector when available.  Reading qpos and
    # qvel through separate provider calls can straddle a WebSocket update and
    # mix two evaluator frames in one control decision.
    adapter = getattr(ctx.world, "_official_adapter", None)
    proprio_provider = getattr(adapter, "proprio_vector", None)
    shared_proprio: np.ndarray | None = None
    if callable(proprio_provider):
        raw_proprio = proprio_provider()
        if raw_proprio is not None:
            shared_proprio = np.asarray(
                raw_proprio,
                dtype=np.float64,
            ).reshape(-1)
            if shared_proprio.size < PROPRIO_DIM:
                raise ValueError(
                    "evaluator proprio has "
                    f"{shared_proprio.size} values; active robot contract "
                    f"requires at least {PROPRIO_DIM}"
                )
            if not np.all(np.isfinite(shared_proprio)):
                raise ValueError("evaluator proprio contains non-finite values")
    qpos: dict[str, np.ndarray] = {}
    qvel: dict[str, np.ndarray] = {}
    for side in arms:
        if shared_proprio is None:
            position = np.asarray(
                ctx.world.arm_qpos_list(side),
                dtype=np.float64,
            ).reshape(-1)
            velocity = np.asarray(
                ctx.world.arm_qvel_list(side),
                dtype=np.float64,
            ).reshape(-1)
        else:
            position = shared_proprio[
                PROPRIO_SLICES[f"arm_{side}_qpos"]
            ].copy()
            velocity = shared_proprio[
                PROPRIO_SLICES[f"arm_{side}_qvel"]
            ].copy()
        if position.size != ARM_DOF or velocity.size != ARM_DOF:
            raise ValueError(
                f"{side} arm proprio has qpos/qvel dimensions "
                f"{position.size}/{velocity.size}; active robot contract "
                f"requires {ARM_DOF}/{ARM_DOF}"
            )
        if not np.all(np.isfinite(position)) or not np.all(np.isfinite(velocity)):
            raise ValueError(f"{side} arm proprio contains non-finite values")
        qpos[side] = position
        qvel[side] = velocity
    return qpos, qvel


def _grasp_prep_active_indices() -> np.ndarray:
    """Return joints that are actually controlled by grasp preparation.

    The custom profile exposes J8 in the action/proprio contract, but that
    joint is a fixed tool-roll lock.  It must not make a moving arm look
    unstable and it must never participate in progress or convergence.
    """
    return np.arange(ARM_DOF - 1 if ARM_DOF == 8 else ARM_DOF, dtype=int)


def _grasp_prep_max_velocity(qvel: dict[str, np.ndarray]) -> float:
    active = _grasp_prep_active_indices()
    if active.size == 0:
        return 0.0
    return max(float(np.max(np.abs(value[active]))) for value in qvel.values())


def _grasp_prep_derived_qvel(
    previous: dict[str, np.ndarray],
    current: dict[str, np.ndarray],
    *,
    observation_steps: int,
) -> dict[str, np.ndarray]:
    """Estimate arm velocity from consecutive official proprio qpos frames."""
    steps = max(1, int(observation_steps))
    scale = float(CONTROL_HZ) / float(steps)
    derived: dict[str, np.ndarray] = {}
    for side, current_q in current.items():
        velocity = (
            np.asarray(current_q, dtype=np.float64).reshape(ARM_DOF)
            - np.asarray(previous[side], dtype=np.float64).reshape(ARM_DOF)
        ) * scale
        if ARM_DOF == 8:
            velocity[7] = 0.0
        derived[side] = velocity
    return derived


def _grasp_prep_stationarity(
    raw_qvel: dict[str, np.ndarray],
    derived_qvel: dict[str, np.ndarray] | None,
) -> dict[str, Any]:
    """Resolve stationarity without trusting an incoherent raw qvel alone."""
    raw_max = _grasp_prep_max_velocity(raw_qvel)
    derived_max = (
        None
        if derived_qvel is None
        else _grasp_prep_max_velocity(derived_qvel)
    )
    raw_stationary = bool(
        raw_max <= GRASP_PREP_TRACKING_QVEL_TOLERANCE_RAD_S
    )
    derived_stationary = bool(
        derived_max is not None
        and derived_max <= GRASP_PREP_TRACKING_QVEL_TOLERANCE_RAD_S
    )
    return {
        "stationary": bool(raw_stationary or derived_stationary),
        "evidence": (
            "raw_qvel"
            if raw_stationary
            else (
                "consecutive_qpos_delta"
                if derived_stationary
                else "none"
            )
        ),
        "raw_max_qvel_rad_s": float(raw_max),
        "derived_max_qvel_rad_s": (
            None if derived_max is None else float(derived_max)
        ),
        "raw_qvel_incoherent": bool(
            not raw_stationary and derived_stationary
        ),
    }


def _grasp_prep_position_status(
    side: str,
    target: np.ndarray,
    measured: np.ndarray,
    tolerance: float,
) -> tuple[np.ndarray, np.ndarray]:
    """Return strict/limit-relaxed per-joint position masks.

    A relaxed mask is deliberately limited to a target that is coincident
    with a static hard joint limit.  This handles the observed R1Pro J6
    controller plateau without weakening the caller's tolerance for normal
    joints or for an arbitrary unreachable pose.
    """
    target = np.asarray(target, dtype=np.float64).reshape(ARM_DOF)
    measured = np.asarray(measured, dtype=np.float64).reshape(ARM_DOF)
    errors = np.abs(target - measured)
    active = _grasp_prep_active_indices()
    strict = np.ones(ARM_DOF, dtype=bool)
    strict[active] = errors[active] <= float(tolerance)
    allowance = max(
        float(tolerance),
        min(
            GRASP_PREP_LIMIT_ACCEPTANCE_CAP_RAD,
            float(tolerance) * GRASP_PREP_LIMIT_ACCEPTANCE_SCALE,
        ),
    )
    limits = _ARM_LIMITS.get(str(side).strip().lower())
    if limits is None:
        return strict, np.zeros(ARM_DOF, dtype=bool)
    relaxed = np.zeros(ARM_DOF, dtype=bool)
    for index in active:
        if (
            strict[index]
            or index >= len(limits)
            or index not in GRASP_PREP_LIMIT_ACCEPTANCE_JOINTS
        ):
            continue
        lower, upper = limits[index]
        target_at_lower = abs(float(target[index]) - float(lower)) <= (
            GRASP_PREP_LIMIT_TARGET_EPS_RAD
        )
        target_at_upper = abs(float(target[index]) - float(upper)) <= (
            GRASP_PREP_LIMIT_TARGET_EPS_RAD
        )
        at_lower_side = target_at_lower and float(measured[index]) >= (
            float(target[index]) - GRASP_PREP_LIMIT_TARGET_EPS_RAD
        )
        at_upper_side = target_at_upper and float(measured[index]) <= (
            float(target[index]) + GRASP_PREP_LIMIT_TARGET_EPS_RAD
        )
        if (
            (at_lower_side or at_upper_side)
            and errors[index] <= allowance
        ):
            relaxed[index] = True
    return strict, relaxed


def _grasp_prep_measured_command(
    *,
    measured: np.ndarray,
    qvel: np.ndarray,
    target: np.ndarray,
    start: np.ndarray,
    previous: np.ndarray,
    step_limit: float,
) -> tuple[np.ndarray, dict[str, Any]]:
    """Build one target-directed command from the latest evaluator frame.

    ``previous`` is used only for telemetry.  It is intentionally never used
    as a fallback target: resending an old waypoint after the measured arm has
    moved is what caused the previous back-and-forth behavior.
    """
    measured = np.asarray(measured, dtype=np.float64).reshape(ARM_DOF)
    qvel = np.asarray(qvel, dtype=np.float64).reshape(ARM_DOF)
    target = np.asarray(target, dtype=np.float64).reshape(ARM_DOF)
    start = np.asarray(start, dtype=np.float64).reshape(ARM_DOF)
    previous = np.asarray(previous, dtype=np.float64).reshape(ARM_DOF)
    command = measured.copy()
    active = _grasp_prep_active_indices()
    reversal_count = 0
    for index in active:
        error = float(target[index] - measured[index])
        if abs(error) <= 1.0e-9:
            # At the target, mirror the measured position while the joint is
            # still moving; this is a small damping handoff, not a retreat.
            command[index] = (
                measured[index]
                if abs(float(qvel[index]))
                > GRASP_PREP_TRACKING_QVEL_TOLERANCE_RAD_S
                else target[index]
            )
            continue
        direction = 1.0 if error > 0.0 else -1.0
        speed_toward = float(qvel[index]) * direction
        if speed_toward > GRASP_PREP_ADVANCE_QVEL_LIMIT_RAD_S:
            scale = GRASP_PREP_BRAKE_STEP_SCALE
        elif speed_toward > GRASP_PREP_TRACKING_QVEL_TOLERANCE_RAD_S:
            scale = GRASP_PREP_CRUISE_STEP_SCALE
        else:
            scale = 1.0
        step = min(abs(error), max(1.0e-9, float(step_limit)) * scale)
        command[index] = measured[index] + direction * step

        # A reversal is only expected after the measured position has crossed
        # the final target.  Compare command direction to the latest measured
        # state, not to the prior command; a lagging measured arm can make two
        # perfectly target-directed absolute commands appear numerically out
        # of order.
        initial_direction = float(np.sign(target[index] - start[index]))
        command_delta = float(command[index] - measured[index])
        crossed = (
            initial_direction != 0.0
            and (measured[index] - target[index]) * initial_direction > 0.0
        )
        if (
            initial_direction != 0.0
            and command_delta * initial_direction < -1.0e-6
            and not crossed
        ):
            reversal_count += 1
    if ARM_DOF == 8:
        command[7] = LOCKED_J8_VALUE_RAD
    return command, {
        "command_reversals_before_target_crossing": int(reversal_count),
        "max_measured_to_command_step_rad": float(
            np.max(np.abs(command - measured))
        ),
    }


def _grasp_prep_latch_measured_hold(
    ctx,
    *,
    arms: list[str],
    max_steps: int,
    stage: str,
    check_cancelled: bool,
    targets: dict[str, np.ndarray] | None = None,
    step_limits: dict[str, float] | None = None,
):
    steps = 0
    raw_stable_steps = 0
    derived_stable_steps = 0
    qpos, qvel = _grasp_prep_snapshot(ctx, arms)
    initial_max_qvel = _grasp_prep_max_velocity(qvel)
    previous_qpos = {side: qpos[side].copy() for side in arms}
    previous_sequence = _reach_observation_sequence(ctx)
    derived_qvel: dict[str, np.ndarray] | None = None
    stationarity = _grasp_prep_stationarity(qvel, derived_qvel)
    raw_qvel_incoherent = False
    settled = False
    while True:
        raw_stable_steps = (
            raw_stable_steps + 1
            if stationarity["evidence"] == "raw_qvel"
            else 0
        )
        derived_stable_steps = (
            derived_stable_steps + 1
            if stationarity["evidence"] == "consecutive_qpos_delta"
            else 0
        )
        raw_qvel_incoherent = bool(
            raw_qvel_incoherent or stationarity["raw_qvel_incoherent"]
        )
        settled = bool(
            raw_stable_steps >= GRASP_PREP_HOLD_REQUIRED_STABLE_STEPS
            or derived_stable_steps
            >= GRASP_PREP_DERIVED_HOLD_REQUIRED_STABLE_STEPS
        )
        if settled or steps >= max(0, int(max_steps)):
            break
        if check_cancelled:
            _check_cancelled(ctx, stage)
        commands: dict[str, list[float]] = {}
        for side in arms:
            measured = qpos[side]
            target = None if targets is None else targets.get(side)
            if target is None:
                command = measured.copy()
            else:
                command, _metrics = _grasp_prep_measured_command(
                    measured=measured,
                    qvel=qvel[side],
                    target=target,
                    start=measured,
                    previous=measured,
                    step_limit=(
                        float(step_limits.get(side, GRASP_PREP_MAX_DQ_PER_STEP))
                        if step_limits is not None
                        else GRASP_PREP_MAX_DQ_PER_STEP
                    ),
                )
            if ARM_DOF == 8:
                command[7] = LOCKED_J8_VALUE_RAD
            commands[f"arm_{side}"] = command.astype(float).tolist()
        yield ctx.world.make_action(**commands)
        steps += 1
        next_qpos, next_qvel = _grasp_prep_snapshot(ctx, arms)
        current_sequence = _reach_observation_sequence(ctx)
        sequence_advanced = bool(
            current_sequence is None
            or previous_sequence is None
            or current_sequence > previous_sequence
        )
        if sequence_advanced:
            observation_steps = (
                1
                if current_sequence is None or previous_sequence is None
                else max(1, int(current_sequence) - int(previous_sequence))
            )
            derived_qvel = _grasp_prep_derived_qvel(
                previous_qpos,
                next_qpos,
                observation_steps=observation_steps,
            )
            previous_qpos = {
                side: next_qpos[side].copy() for side in arms
            }
            previous_sequence = current_sequence
        else:
            derived_qvel = None
        qpos, qvel = next_qpos, next_qvel
        stationarity = _grasp_prep_stationarity(qvel, derived_qvel)

    for side in arms:
        ctx.world.set_arm_pin_qpos(side, qpos[side])
    return {
        "steps": int(steps),
        "stable_steps": int(max(raw_stable_steps, derived_stable_steps)),
        "raw_stable_steps": int(raw_stable_steps),
        "derived_stable_steps": int(derived_stable_steps),
        "settled": bool(settled),
        "stationarity_evidence": stationarity["evidence"],
        "raw_qvel_incoherence_detected": bool(raw_qvel_incoherent),
        "initial_max_qvel_rad_s": float(initial_max_qvel),
        "terminal_max_qvel_rad_s": float(_grasp_prep_max_velocity(qvel)),
        "terminal_derived_max_qvel_rad_s": stationarity[
            "derived_max_qvel_rad_s"
        ],
        "qpos": qpos,
        "qvel": qvel,
    }


def set_arm_to_grasp_position(
    ctx,
    arm: str = "right",
    keep_ori_arm: str = "none",
    gripper: str = "keep",
    max_dq_per_step: float = GRASP_PREP_DEFAULT_MAX_DQ_PER_STEP,
    tol: float = 0.08,
    timeout_s: float = GRASP_PREP_DEFAULT_TIMEOUT_S,
    **kwargs,
):
    function_started_monotonic = time.monotonic()
    observation_sequence_start = _reach_observation_sequence(ctx)
    arm_eff = str(arm).strip().lower()
    arms = ["left", "right"] if arm_eff == "both" else [arm_eff]
    if any(side not in ("left", "right") for side in arms):
        _set_result(
            ctx,
            "set_arm_to_grasp_position",
            {"ok": False, "error": "arm must be left, right, or both"},
        )
        yield ctx.world.hold_action()
        return
    keep_ori = str(keep_ori_arm or "none").strip().lower()
    if keep_ori in ("", "false", "0", "no"):
        keep_ori = "none"
    if keep_ori not in ("none", "left", "right", "both"):
        _set_result(
            ctx,
            "set_arm_to_grasp_position",
            {
                "ok": False,
                "error": "keep_ori_arm must be none, left, right, or both",
            },
        )
        yield ctx.world.hold_action()
        return
    requested_keep_arms = (
        {"left", "right"} if keep_ori == "both" else {keep_ori}
    ) - {"none"}
    invalid_keep_arms = requested_keep_arms - set(arms)
    if invalid_keep_arms:
        _set_result(
            ctx,
            "set_arm_to_grasp_position",
            {
                "ok": False,
                "error": (
                    f"keep_ori_arm={keep_ori} includes an arm outside arm={arm_eff}"
                ),
            },
        )
        yield ctx.world.hold_action()
        return
    if requested_keep_arms:
        _set_result(
            ctx,
            "set_arm_to_grasp_position",
            {
                "ok": False,
                "error": (
                    "keep_ori_arm is not available in the fixed joint-space "
                    "official_v2 replacement; use none"
                ),
                "keep_ori_arm": keep_ori,
            },
        )
        yield ctx.world.hold_action()
        return
    tolerance = float(tol)
    timeout = float(timeout_s)
    if not math.isfinite(tolerance) or tolerance <= 0.0:
        _set_result(
            ctx,
            "set_arm_to_grasp_position",
            {"ok": False, "error": "tol must be a positive finite value"},
        )
        yield ctx.world.hold_action()
        return
    if not math.isfinite(timeout) or timeout <= 0.0:
        _set_result(
            ctx,
            "set_arm_to_grasp_position",
            {"ok": False, "error": "timeout_s must be a positive finite value"},
        )
        yield ctx.world.hold_action()
        return
    mode = str(gripper or "keep").strip().lower()
    if kwargs.get("open_gripper") is True:
        mode = "open"
    if mode not in ("keep", "open"):
        _set_result(
            ctx,
            "set_arm_to_grasp_position",
            {"ok": False, "error": "gripper must be keep or open"},
        )
        yield ctx.world.hold_action()
        return
    requested_max_step = float(max_dq_per_step)
    if not math.isfinite(requested_max_step) or requested_max_step <= 0.0:
        _set_result(
            ctx,
            "set_arm_to_grasp_position",
            {
                "ok": False,
                "error": "max_dq_per_step must be a positive finite value",
            },
        )
        yield ctx.world.hold_action()
        return
    if ARM_DOF > GRASP_PREP_Q.size:
        raise ValueError(
            f"grasp-prep target has {GRASP_PREP_Q.size} joints, "
            f"but the active profile requires {ARM_DOF}"
        )

    # Respect the caller's speed request exactly (the old lower clamp silently
    # turned a 0.01-rad safety request into 0.03 rad per frame).
    max_step = min(requested_max_step, GRASP_PREP_MAX_DQ_PER_STEP)
    if ARM_DOF == 8:
        for side in ("left", "right"):
            ctx.world.set_tool_roll_pin_qpos(side, LOCKED_J8_VALUE_RAD)
    target_template = GRASP_PREP_Q[:ARM_DOF].copy()
    targets = {side: target_template.copy() for side in arms}
    if ARM_DOF == 8:
        for side in arms:
            targets[side][7] = LOCKED_J8_VALUE_RAD

    close_keepalive = {
        side: bool(
            getattr(
                ctx.world,
                "gripper_close_keepalive_active",
                lambda _arm: False,
            )(side)
        )
        for side in arms
    }
    step_limits = {
        side: min(
            max_step,
            GRASP_PREP_CARRY_MAX_DQ_PER_STEP
            if close_keepalive[side]
            else GRASP_PREP_MAX_DQ_PER_STEP,
        )
        for side in arms
    }

    terminal_pins_latched = False
    entry_hold = {
        "steps": 0,
        "stable_steps": 0,
        "settled": True,
        "initial_max_qvel_rad_s": 0.0,
        "terminal_max_qvel_rad_s": 0.0,
        "terminal_derived_max_qvel_rad_s": None,
        "stationarity_evidence": "raw_qvel",
        "raw_qvel_incoherence_detected": False,
    }
    failure_hold = {
        "steps": 0,
        "stable_steps": 0,
        "settled": True,
        "initial_max_qvel_rad_s": 0.0,
        "terminal_max_qvel_rad_s": 0.0,
        "terminal_derived_max_qvel_rad_s": None,
        "stationarity_evidence": "raw_qvel",
        "raw_qvel_incoherence_detected": False,
    }
    failure_reason: str | None = None
    failure_qpos: dict[str, np.ndarray] | None = None
    failure_qvel: dict[str, np.ndarray] | None = None
    converged = False
    timed_out = False
    stalled = False
    timeout_reason: str | None = None
    action_steps = 0
    command_advance_steps = 0
    stable_steps = 0
    stall_steps = 0
    max_observed_qvel = 0.0
    max_tracking_lag = 0.0
    max_command_step = 0.0
    terminal_derived_max_qvel: float | None = None
    stationarity_evidence = "raw_qvel"
    raw_qvel_incoherence_detected = False
    extensions = 0
    extension_reasons: list[str] = []
    open_steps = 0

    try:
        observed_q, observed_qvel = _grasp_prep_snapshot(ctx, arms)
        max_observed_qvel = _grasp_prep_max_velocity(observed_qvel)
        if (
            max_observed_qvel
            > GRASP_PREP_TRACKING_QVEL_TOLERANCE_RAD_S
        ):
            entry_hold_generator = _grasp_prep_latch_measured_hold(
                ctx,
                arms=arms,
                max_steps=GRASP_PREP_ENTRY_HANDOFF_MAX_STEPS,
                stage="grasp-prep entry stabilization",
                check_cancelled=True,
                targets=targets,
                step_limits=step_limits,
            )
            while True:
                try:
                    yield next(entry_hold_generator)
                except StopIteration as stopped:
                    entry_hold = stopped.value
                    break
            observed_q = entry_hold["qpos"]
            observed_qvel = entry_hold["qvel"]
            max_observed_qvel = max(
                max_observed_qvel,
                float(entry_hold["initial_max_qvel_rad_s"]),
                float(entry_hold["terminal_max_qvel_rad_s"]),
            )
            # Do not reject a request merely because the entry arm is still
            # moving.  The main measured-relative loop below continues with a
            # fresh start and brakes it without replaying an old waypoint.

        starts = {side: observed_q[side].copy() for side in arms}
        start_qvel = {
            side: observed_qvel[side].copy() for side in arms
        }
        commands = {side: starts[side].copy() for side in arms}
        active_indices = _grasp_prep_active_indices()
        best_joint_error = {
            side: np.abs(targets[side] - starts[side]).astype(np.float64)
            for side in arms
        }
        joint_stall_counts = {
            side: np.zeros(ARM_DOF, dtype=np.int64) for side in arms
        }
        last_observed_q = {
            side: starts[side].copy() for side in arms
        }
        best_progress_metric = float(
            sum(float(np.sum(best_joint_error[side][active_indices])) for side in arms)
        )
        extension_reference_metric = best_progress_metric
        last_observation_sequence = _reach_observation_sequence(ctx)
        first_feedback = True
        fresh_observation_count = 0
        stale_observation_steps = 0
        motion_since_extension = False
        command_reversal_count = 0
        handoff_forced = bool(
            max_observed_qvel
            > GRASP_PREP_TRACKING_QVEL_TOLERANCE_RAD_S
            and not bool(entry_hold["settled"])
        )
        relaxed_limit_by_arm = {
            side: np.zeros(ARM_DOF, dtype=bool) for side in arms
        }
        max_gap = max(
            float(
                np.max(
                    np.abs(
                        targets[side][active_indices]
                        - starts[side][active_indices]
                    )
                )
            )
            for side in arms
        )
        planned_interpolation_steps = max(
            1,
            max(
                int(
                    math.ceil(
                        float(
                            np.max(
                                np.abs(
                                    targets[side][active_indices]
                                    - starts[side][active_indices]
                                )
                            )
                        )
                        / step_limits[side]
                    )
                )
                for side in arms
            ),
        )
        initial_error = max_gap
        best_error = initial_error
        progress_threshold = max(
            GRASP_PREP_EXTENSION_MIN_PROGRESS_RAD,
            0.25 * tolerance,
        )
        soft_step_limit = max(1, int(math.ceil(timeout * CONTROL_HZ)))
        grace_s = min(GRASP_PREP_PROGRESS_GRACE_MAX_S, timeout)
        grace_steps = max(1, int(math.ceil(grace_s * CONTROL_HZ)))
        hard_timeout = grasp_prep_hard_timeout_s(timeout)
        hard_step_limit = (
            soft_step_limit
            + GRASP_PREP_PROGRESS_GRACE_EXTENSIONS * grace_steps
        )
        started_monotonic = time.monotonic()
        soft_deadline = started_monotonic + timeout
        hard_deadline = started_monotonic + hard_timeout
        stall_limit = GRASP_PREP_TRACKING_STALL_STEPS

        while failure_reason is None:
            observed_q, observed_qvel = _grasp_prep_snapshot(ctx, arms)
            errors = {
                side: targets[side] - observed_q[side] for side in arms
            }
            observed_error = max(
                float(np.max(np.abs(error[active_indices])))
                for error in errors.values()
            )
            observed_max_qvel = _grasp_prep_max_velocity(observed_qvel)
            max_observed_qvel = max(max_observed_qvel, observed_max_qvel)

            current_sequence = _reach_observation_sequence(ctx)
            sequence_delta: int | None = None
            fresh_observation = bool(
                first_feedback
                or current_sequence is None
                or last_observation_sequence is None
                or current_sequence > last_observation_sequence
            )
            if fresh_observation and action_steps > 0:
                if current_sequence is None or last_observation_sequence is None:
                    sequence_delta = 1
                elif current_sequence > last_observation_sequence:
                    sequence_delta = max(
                        1,
                        int(current_sequence) - int(last_observation_sequence),
                    )
            if current_sequence is not None:
                last_observation_sequence = max(
                    int(last_observation_sequence or current_sequence),
                    int(current_sequence),
                )
            first_feedback = False
            if fresh_observation:
                fresh_observation_count += 1
                stale_observation_steps = 0
            else:
                stale_observation_steps += 1

            derived_qvel = (
                _grasp_prep_derived_qvel(
                    last_observed_q,
                    observed_q,
                    observation_steps=sequence_delta,
                )
                if fresh_observation and sequence_delta is not None
                else None
            )
            stationarity = _grasp_prep_stationarity(
                observed_qvel,
                derived_qvel,
            )
            terminal_derived_max_qvel = stationarity[
                "derived_max_qvel_rad_s"
            ]
            stationarity_evidence = stationarity["evidence"]
            raw_qvel_incoherence_detected = bool(
                raw_qvel_incoherence_detected
                or stationarity["raw_qvel_incoherent"]
                or entry_hold["raw_qvel_incoherence_detected"]
            )

            accepted_position = True
            accepted_masks_by_arm: dict[str, np.ndarray] = {}
            for side in arms:
                strict_mask, relaxed_mask = _grasp_prep_position_status(
                    side,
                    targets[side],
                    observed_q[side],
                    tolerance,
                )
                accepted_mask = strict_mask | relaxed_mask
                accepted_masks_by_arm[side] = accepted_mask
                relaxed_limit_by_arm[side] = relaxed_mask
                accepted_position = bool(
                    accepted_position and np.all(accepted_mask[active_indices])
                )
                if fresh_observation:
                    absolute_error = np.abs(errors[side])
                    observed_motion = np.abs(
                        observed_q[side] - last_observed_q[side]
                    )
                    for index in active_indices:
                        if accepted_mask[index]:
                            joint_stall_counts[side][index] = 0
                        elif (
                            absolute_error[index]
                            <= best_joint_error[side][index]
                            - GRASP_PREP_PROGRESS_EPS_RAD
                        ):
                            best_joint_error[side][index] = absolute_error[
                                index
                            ]
                            joint_stall_counts[side][index] = 0
                        elif (
                            observed_motion[index]
                            >= GRASP_PREP_MIN_OBSERVED_MOTION_RAD
                        ):
                            # The joint is responding; do not call it stalled
                            # merely because this frame's error improvement is
                            # smaller than the progress epsilon.
                            joint_stall_counts[side][index] = 0
                        elif action_steps > 0:
                            joint_stall_counts[side][index] += 1
                    if bool(
                        np.any(
                            observed_motion[active_indices]
                            >= GRASP_PREP_MIN_OBSERVED_MOTION_RAD
                        )
                    ):
                        motion_since_extension = True
                    last_observed_q[side] = observed_q[side].copy()
            if fresh_observation:
                current_progress_metric = float(
                    sum(
                        float(np.sum(np.abs(errors[side][active_indices])))
                        for side in arms
                    )
                )
                best_progress_metric = min(
                    best_progress_metric,
                    current_progress_metric,
                )

            velocity_ok = bool(stationarity["stationary"])

            if (
                fresh_observation
                and accepted_position
                and velocity_ok
            ):
                stable_steps += 1
                if stable_steps >= GRASP_PREP_REQUIRED_STABLE_STEPS:
                    converged = True
                    break
            elif fresh_observation:
                stable_steps = 0

            if fresh_observation and observed_error <= best_error - GRASP_PREP_PROGRESS_EPS_RAD:
                best_error = observed_error

            unsatisfied = [
                (side, int(index))
                for side in arms
                for index in active_indices
                if not accepted_masks_by_arm[side][index]
            ]
            if unsatisfied:
                stall_steps = min(
                    int(joint_stall_counts[side][index])
                    for side, index in unsatisfied
                )
                all_joints_stalled = all(
                    int(joint_stall_counts[side][index]) >= stall_limit
                    for side, index in unsatisfied
                )
            else:
                stall_steps = 0
                all_joints_stalled = False
            if all_joints_stalled and action_steps > 0:
                stalled = True
                failure_reason = (
                    "arm tracking stalled before reaching grasp prep"
                )
                break
            if stale_observation_steps >= stall_limit:
                stalled = True
                stall_steps = stall_limit
                failure_reason = (
                    "arm tracking stalled before reaching grasp prep "
                    "(evaluator proprioception did not advance)"
                )
                break

            now = time.monotonic()
            hard_budget_hit = bool(
                now >= hard_deadline or action_steps >= hard_step_limit
            )
            soft_budget_hit = bool(
                now >= soft_deadline or action_steps >= soft_step_limit
            )
            if hard_budget_hit:
                timed_out = True
                timeout_reason = "hard_progress_deadline"
                failure_reason = (
                    "arms did not reach a stationary grasp-prep pose before "
                    "the progress-aware hard deadline"
                )
                break
            if soft_budget_hit:
                progress = extension_reference_metric - best_progress_metric
                near_target = observed_error <= max(2.0 * tolerance, 0.15)
                if (
                    extensions < GRASP_PREP_PROGRESS_GRACE_EXTENSIONS
                    and (
                        progress >= progress_threshold
                        or near_target
                        or motion_since_extension
                    )
                ):
                    reason = (
                        "near_target_settling"
                        if near_target and progress < progress_threshold
                        else "proprioceptive_error_progress"
                    )
                    extension_reasons.append(reason)
                    extensions += 1
                    extension_reference_metric = best_progress_metric
                    motion_since_extension = False
                    soft_deadline = min(
                        hard_deadline,
                        max(soft_deadline, now) + grace_s,
                    )
                    soft_step_limit = min(
                        hard_step_limit,
                        soft_step_limit + grace_steps,
                    )
                else:
                    timed_out = True
                    timeout_reason = "soft_deadline_without_progress"
                    failure_reason = (
                        "arms did not reach a stationary grasp-prep pose "
                        "before timeout and no continuing proprioceptive "
                        "progress justified an extension"
                    )
                    break

            _check_cancelled(ctx, "feedback-governed grasp preparation")
            next_commands: dict[str, np.ndarray] = {}
            advanced = False
            for side in arms:
                previous = commands[side]
                measured = observed_q[side]
                target = targets[side]
                tracking_lag = float(
                    np.max(
                        np.abs(
                            previous[active_indices]
                            - measured[active_indices]
                        )
                    )
                )
                max_tracking_lag = max(max_tracking_lag, tracking_lag)
                command_qvel = observed_qvel[side]
                if derived_qvel is not None:
                    raw_side_max = float(
                        np.max(np.abs(command_qvel[active_indices]))
                    )
                    derived_side_max = float(
                        np.max(np.abs(derived_qvel[side][active_indices]))
                    )
                    if (
                        raw_side_max
                        > GRASP_PREP_TRACKING_QVEL_TOLERANCE_RAD_S
                        and derived_side_max
                        <= GRASP_PREP_TRACKING_QVEL_TOLERANCE_RAD_S
                    ):
                        command_qvel = derived_qvel[side]
                command, command_metrics = _grasp_prep_measured_command(
                    measured=measured,
                    qvel=command_qvel,
                    target=target,
                    start=starts[side],
                    previous=previous,
                    step_limit=step_limits[side],
                )
                command_reversal_count += int(
                    command_metrics[
                        "command_reversals_before_target_crossing"
                    ]
                )
                if float(
                    np.max(np.abs(command[active_indices] - measured[active_indices]))
                ) > 1.0e-9:
                    advanced = True
                max_command_step = max(
                    max_command_step,
                    float(
                        np.max(
                            np.abs(
                                command[active_indices]
                                - previous[active_indices]
                            )
                        )
                    ),
                )
                next_commands[side] = command

            commands = next_commands
            if advanced:
                command_advance_steps += 1
            yield ctx.world.make_action(
                **{
                    f"arm_{side}": commands[side].astype(float).tolist()
                    for side in arms
                }
            )
            action_steps += 1

        if converged:
            if mode == "open":
                for _ in range(4):
                    _check_cancelled(ctx, "grasp-prep gripper opening")
                    yield ctx.world.make_action(
                        **{f"gripper_{side}": [1.0] for side in arms}
                    )
                    open_steps += 1
        else:
            failure_qpos, failure_qvel = _grasp_prep_snapshot(ctx, arms)
            failure_hold_generator = _grasp_prep_latch_measured_hold(
                ctx,
                arms=arms,
                max_steps=GRASP_PREP_FAILURE_HOLD_MAX_STEPS,
                stage="grasp-prep failure measured hold",
                check_cancelled=False,
            )
            while True:
                try:
                    yield next(failure_hold_generator)
                except StopIteration as stopped:
                    failure_hold = stopped.value
                    break
            terminal_pins_latched = True

        achieved, achieved_qvel = _grasp_prep_snapshot(ctx, arms)
        errors = {
            side: targets[side] - achieved[side] for side in arms
        }
        max_error = max(
            float(np.max(np.abs(error[active_indices])))
            for error in errors.values()
        )
        terminal_max_qvel = _grasp_prep_max_velocity(achieved_qvel)
        max_observed_qvel = max(max_observed_qvel, terminal_max_qvel)
        final_strict_position_by_arm: dict[str, bool] = {}
        final_accepted_position_by_arm: dict[str, bool] = {}
        final_relaxed_limit_by_arm: dict[str, list[int]] = {}
        if converged:
            for side in arms:
                strict_mask, relaxed_mask = _grasp_prep_position_status(
                    side,
                    targets[side],
                    achieved[side],
                    tolerance,
                )
                final_strict_position_by_arm[side] = bool(
                    np.all(strict_mask[active_indices])
                )
                final_accepted_position_by_arm[side] = bool(
                    np.all((strict_mask | relaxed_mask)[active_indices])
                )
                final_relaxed_limit_by_arm[side] = [
                    int(index)
                    for index in active_indices
                    if bool(relaxed_mask[index])
                ]
                # A hard-limit plateau is accepted only as a stationary
                # measured pose.  Re-pinning that joint to the unreachable
                # mathematical endpoint would reintroduce post-success
                # chatter; strict convergence still pins the exact target.
                terminal_q = (
                    targets[side]
                    if final_strict_position_by_arm[side]
                    else achieved[side]
                )
                ctx.world.set_arm_pin_qpos(side, terminal_q)
            terminal_pins_latched = True
        observation_sequence_end = _reach_observation_sequence(ctx)
        observation_delta = (
            None
            if observation_sequence_start is None
            or observation_sequence_end is None
            else max(
                0,
                int(observation_sequence_end)
                - int(observation_sequence_start),
            )
        )
        wall_s = max(
            0.0,
            time.monotonic() - function_started_monotonic,
        )
        observed_action_hz = (
            None
            if observation_delta is None or wall_s <= 1e-9
            else float(observation_delta) / wall_s
        )
        limiting_joint_by_arm = {}
        for side in arms:
            joint_index = int(
                active_indices[
                    int(np.argmax(np.abs(errors[side][active_indices])))
                ]
            )
            limiting_joint_by_arm[side] = {
                "index": joint_index,
                "name": f"J{joint_index + 1}",
                "error_rad": float(errors[side][joint_index]),
                "qpos_rad": float(achieved[side][joint_index]),
                "qvel_rad_s": float(achieved_qvel[side][joint_index]),
                "target_rad": float(targets[side][joint_index]),
            }
        total_action_steps = (
            int(entry_hold["steps"])
            + action_steps
            + int(failure_hold["steps"])
            + open_steps
        )
        _set_result(
            ctx,
            "set_arm_to_grasp_position",
            {
                "ok": bool(converged),
                "arms": arms,
                "keep_ori_arm": keep_ori,
                "target_qpos": {
                    side: targets[side].astype(float).tolist() for side in arms
                },
                "start_qpos": {
                    side: starts[side].astype(float).tolist() for side in arms
                },
                "start_qvel": {
                    side: start_qvel[side].astype(float).tolist()
                    for side in arms
                },
                "achieved_qpos": {
                    side: achieved[side].astype(float).tolist() for side in arms
                },
                "achieved_qvel": {
                    side: achieved_qvel[side].astype(float).tolist()
                    for side in arms
                },
                "error_rad": {
                    side: errors[side].astype(float).tolist() for side in arms
                },
                "converged": bool(converged),
                "tolerance_rad": tolerance,
                "velocity_tolerance_rad_s": (
                    GRASP_PREP_TRACKING_QVEL_TOLERANCE_RAD_S
                ),
                "convergence_requires_position_and_velocity": True,
                "stationarity_velocity_sources": [
                    "raw_qvel",
                    "consecutive_qpos_delta",
                ],
                "timeout_s": timeout,
                "soft_timeout_s": timeout,
                "hard_timeout_s": float(hard_timeout),
                "timeout_reason": timeout_reason,
                "progress_deadline_extensions": int(extensions),
                "progress_extension_reasons": extension_reasons,
                "requested_max_dq_per_step": requested_max_step,
                "effective_max_dq_per_step": float(max(step_limits.values())),
                "effective_max_dq_per_step_by_arm": {
                    side: float(step_limits[side]) for side in arms
                },
                "carry_aware_step_limit_active": bool(
                    any(close_keepalive.values())
                ),
                "close_keepalive_by_arm": close_keepalive,
                "planned_interpolation_steps": int(
                    planned_interpolation_steps
                ),
                "interpolation_steps": int(command_advance_steps),
                "action_steps": int(action_steps),
                "total_action_steps": int(total_action_steps),
                "entry_settle_steps": int(entry_hold["steps"]),
                "entry_settled": bool(entry_hold["settled"]),
                "entry_stationarity_evidence": entry_hold[
                    "stationarity_evidence"
                ],
                "entry_handoff_forced": bool(handoff_forced),
                "failure_hold_steps": int(failure_hold["steps"]),
                "failure_hold_settled": bool(failure_hold["settled"]),
                "failure_hold_stationarity_evidence": failure_hold[
                    "stationarity_evidence"
                ],
                "terminal_hold_source": (
                    "fixed_grasp_prep_target"
                    if converged
                    else "latest_evaluator_proprioception"
                ),
                "stable_steps": int(stable_steps),
                "required_stable_steps": GRASP_PREP_REQUIRED_STABLE_STEPS,
                "stall_steps": int(stall_steps),
                "stall_limit": int(stall_limit),
                "tracking_stalled": bool(stalled),
                "timed_out": bool(timed_out),
                "strict_position_converged": bool(
                    all(final_strict_position_by_arm.values())
                    if final_strict_position_by_arm
                    else False
                ),
                "accepted_position_converged": bool(
                    all(final_accepted_position_by_arm.values())
                    if final_accepted_position_by_arm
                    else False
                ),
                "limit_residual_joints_by_arm": final_relaxed_limit_by_arm,
                "max_abs_error_rad": float(max_error),
                "best_abs_error_rad": float(best_error),
                "max_observed_qvel_rad_s": float(max_observed_qvel),
                "terminal_max_qvel_rad_s": float(terminal_max_qvel),
                "terminal_derived_max_qvel_rad_s": (
                    None
                    if terminal_derived_max_qvel is None
                    else float(terminal_derived_max_qvel)
                ),
                "terminal_stationarity_evidence": stationarity_evidence,
                "raw_qvel_incoherence_detected": bool(
                    raw_qvel_incoherence_detected
                    or failure_hold["raw_qvel_incoherence_detected"]
                ),
                "max_tracking_lag_rad": float(max_tracking_lag),
                "max_command_step_rad": float(max_command_step),
                "command_reversals_before_target_crossing": int(
                    command_reversal_count
                ),
                "handoff_max_steps": int(GRASP_PREP_ENTRY_HANDOFF_MAX_STEPS),
                "stale_observation_steps": int(stale_observation_steps),
                "fresh_observation_count": int(fresh_observation_count),
                "joint_stall_steps_by_arm": {
                    side: joint_stall_counts[side].astype(int).tolist()
                    for side in arms
                },
                "limiting_joint_by_arm": limiting_joint_by_arm,
                "wall_s": float(wall_s),
                "observation_sequence_start": observation_sequence_start,
                "observation_sequence_end": observation_sequence_end,
                "fresh_observation_delta": observation_delta,
                "observed_fresh_action_hz": observed_action_hz,
                "gripper": mode,
                "execution": (
                    "feedback_governed_observed_qpos_to_absolute_targets"
                ),
                "failure_observed_qpos": (
                    None
                    if failure_qpos is None
                    else {
                        side: failure_qpos[side].astype(float).tolist()
                        for side in arms
                    }
                ),
                "failure_observed_qvel": (
                    None
                    if failure_qvel is None
                    else {
                        side: failure_qvel[side].astype(float).tolist()
                        for side in arms
                    }
                ),
                "collision_checked": False,
                "held_object_collision_truth_used": False,
                "direct_simulator_mutation": False,
                **({} if converged else {"error": failure_reason}),
            },
        )
        yield ctx.world.hold_action()
    finally:
        if not terminal_pins_latched:
            try:
                latest_q, _latest_qvel = _grasp_prep_snapshot(ctx, arms)
                for side in arms:
                    ctx.world.set_arm_pin_qpos(side, latest_q[side])
            except (RuntimeError, TypeError, ValueError):
                pass


@dataclass
class _ResetBodyKeepOriState:
    arm: str
    reference_position: np.ndarray
    reference_quaternion: np.ndarray
    initial_q: np.ndarray
    last_command: np.ndarray
    raw_reference_position: np.ndarray | None
    raw_reference_quaternion: np.ndarray | None
    solve_calls: int = 0
    max_observed_position_error_m: float = 0.0
    max_observed_orientation_error_deg: float = 0.0
    max_command_q1234_delta_rad: float = 0.0
    max_command_j567_delta_rad: float = 0.0
    max_command_tracking_error_rad: float = 0.0
    last_solver_report: dict[str, Any] | None = None


def _reset_body_keep_arms(value: Any) -> tuple[str, ...]:
    normalized = str(value if value is not None else "none").strip().lower()
    if normalized in ("", "false", "0", "no"):
        normalized = "none"
    if normalized == "none":
        return ()
    if normalized == "both":
        return ("left", "right")
    if normalized in ("left", "right"):
        return (normalized,)
    raise ValueError("keep_ori_arm must be none, left, right, or both")


def _reset_body_raw_eef_pose(ctx, arm: str) -> dict[str, np.ndarray] | None:
    adapter = getattr(ctx.world, "_official_adapter", None)
    if adapter is None:
        return None
    try:
        raw = dict((adapter.eef_pose() or {}).get(arm) or {})
        position = np.asarray(raw.get("pos"), dtype=np.float64).reshape(3)
        quaternion = np.asarray(raw.get("quat"), dtype=np.float64).reshape(4)
    except (TypeError, ValueError):
        return None
    norm = float(np.linalg.norm(quaternion))
    if (
        not np.all(np.isfinite(position))
        or not np.all(np.isfinite(quaternion))
        or norm <= 1e-9
    ):
        return None
    return {
        "position": position.copy(),
        "quaternion": quaternion / norm,
    }


def _reset_body_init_keep_states(
    ctx,
    arms: tuple[str, ...],
) -> dict[str, _ResetBodyKeepOriState]:
    states: dict[str, _ResetBodyKeepOriState] = {}
    for arm in arms:
        observed = _adjust_kinematic_observation(ctx, arm)
        raw_pose = _reset_body_raw_eef_pose(ctx, arm)
        states[arm] = _ResetBodyKeepOriState(
            arm=arm,
            reference_position=observed["position"].copy(),
            reference_quaternion=observed["quaternion"].copy(),
            initial_q=observed["q"].copy(),
            last_command=observed["q"].copy(),
            raw_reference_position=(
                None if raw_pose is None else raw_pose["position"].copy()
            ),
            raw_reference_quaternion=(
                None if raw_pose is None else raw_pose["quaternion"].copy()
            ),
        )
    return states


def _reset_body_local_state(ctx, trunk_q: Any) -> LocalRobotState:
    trunk = np.asarray(trunk_q, dtype=np.float64).reshape(4)
    left = locked_arm_vector(
        ctx.world.arm_qpos_list("left"),
        label="left arm proprioception",
    )
    right = locked_arm_vector(
        ctx.world.arm_qpos_list("right"),
        label="right arm proprioception",
    )
    return local_robot_state(
        trunk_q=trunk,
        arm_left_q=left,
        arm_right_q=right,
        gripper_left_q=_adjust_gripper_vector(
            ctx.world.gripper_qpos_list("left")
        ),
        gripper_right_q=_adjust_gripper_vector(
            ctx.world.gripper_qpos_list("right")
        ),
    )


def _reset_body_orientation_residual_deg(solve_report: dict[str, Any]) -> float:
    for key in ("ori_err_deg", "residual_deg"):
        raw = solve_report.get(key)
        try:
            value = float(raw)
        except (TypeError, ValueError):
            continue
        if math.isfinite(value):
            return value
    return float("inf")


def _reset_body_solve_bounded_j567(
    state: LocalRobotState,
    arm: str,
    q_candidate: np.ndarray,
    measured_q: np.ndarray,
    target_quaternion: np.ndarray,
    *,
    max_step_rad: float = RESET_BODY_KEEP_J567_MAX_STEP_RAD,
) -> tuple[np.ndarray, dict[str, Any], int]:
    """Solve J5-J7 and validate the command after per-action clipping."""
    candidate = np.asarray(q_candidate, dtype=np.float64).reshape(ARM_DOF).copy()
    measured = np.asarray(measured_q, dtype=np.float64).reshape(ARM_DOF)
    solved, solve_report = solve_j567_orientation_target(
        state,
        arm,
        candidate,
        target_quaternion,
        ori_tol_deg=RESET_BODY_KEEP_ORIENTATION_SOLVE_TOL_DEG,
        allow_global_search=False,
    )
    solve_calls = 1
    residual_deg = _reset_body_orientation_residual_deg(solve_report)
    if residual_deg > RESET_BODY_KEEP_ORIENTATION_FINAL_TOL_DEG:
        solved, solve_report = solve_j567_orientation_target(
            state,
            arm,
            candidate,
            target_quaternion,
            ori_tol_deg=RESET_BODY_KEEP_ORIENTATION_SOLVE_TOL_DEG,
            allow_global_search=True,
        )
        solve_calls += 1
        residual_deg = _reset_body_orientation_residual_deg(solve_report)

    lower, upper = _local_arm_joint_limits(state, arm)
    bounded_step = max(
        1e-6,
        min(
            float(max_step_rad),
            RESET_BODY_KEEP_J567_CATCHUP_MAX_STEP_RAD,
        ),
    )
    candidate[4:7] = np.clip(
        solved[4:7],
        measured[4:7] - bounded_step,
        measured[4:7] + bounded_step,
    )
    candidate[4:7] = np.clip(candidate[4:7], lower[4:7], upper[4:7])
    if ARM_DOF == 8:
        candidate[7] = 0.0
    _position, commanded_quaternion = _local_eef_pose(state, arm, candidate)
    fk_commanded_error_deg = orientation_error_deg(
        commanded_quaternion,
        target_quaternion,
    )
    solver_report_valid = math.isfinite(residual_deg)
    commanded_error_deg = (
        fk_commanded_error_deg if solver_report_valid else float("inf")
    )
    report = {
        **dict(solve_report),
        "solver_report_valid": bool(solver_report_valid),
        "unclipped_orientation_error_deg": float(residual_deg),
        "commanded_orientation_error_deg": float(commanded_error_deg),
        "fk_commanded_orientation_error_deg": float(fk_commanded_error_deg),
        "commanded_within_final_tolerance": bool(
            commanded_error_deg <= RESET_BODY_KEEP_ORIENTATION_FINAL_TOL_DEG
        ),
        "j567_clipped_to_action_step": bool(
            np.linalg.norm(candidate[4:7] - solved[4:7], ord=np.inf) > 1e-9
        ),
        "j567_action_step_limit_rad": float(bounded_step),
    }
    return candidate, report, solve_calls


def _reset_body_feedback_orientation_target(
    ctx,
    arm: str,
    keeper: _ResetBodyKeepOriState,
) -> tuple[np.ndarray, dict[str, Any]]:
    """Map evaluator EEF error onto the local-FK orientation target.

    The local URDF is used for J5-J7 IK, but evaluator EEF quaternion is the
    authoritative measurement.  Applying the measured raw-frame correction
    to the current local pose closes the model-offset loop instead of repeatedly
    issuing an already-satisfied local target.
    """
    raw_pose = _reset_body_raw_eef_pose(ctx, arm)
    if (
        raw_pose is None
        or keeper.raw_reference_quaternion is None
    ):
        return keeper.reference_quaternion.copy(), {
            "source": "fixed_local_entry_orientation",
            "raw_feedback_available": False,
        }

    actual_state = _reset_body_local_state(ctx, ctx.world.trunk_qpos())
    measured = (
        actual_state.arm_left_q
        if arm == "left"
        else actual_state.arm_right_q
    )
    _position, local_quaternion = _local_eef_pose(
        actual_state,
        arm,
        measured,
    )
    raw_current_rotation = _quat_to_mat_xyzw(raw_pose["quaternion"])
    raw_reference_rotation = _quat_to_mat_xyzw(
        keeper.raw_reference_quaternion
    )
    local_current_rotation = _quat_to_mat_xyzw(local_quaternion)
    correction = raw_reference_rotation @ raw_current_rotation.T
    correction_vector = _rotation_vector(correction)
    correction_angle = float(np.linalg.norm(correction_vector))
    raw_error_deg = math.degrees(correction_angle)
    gain_fraction = np.clip(
        (
            raw_error_deg - RESET_BODY_KEEP_ORIENTATION_FINAL_TOL_DEG
        )
        / (
            RESET_BODY_KEEP_RAW_FEEDBACK_FULL_GAIN_DEG
            - RESET_BODY_KEEP_ORIENTATION_FINAL_TOL_DEG
        ),
        0.0,
        1.0,
    )
    feedback_gain = 1.0 + float(gain_fraction) * (
        RESET_BODY_KEEP_RAW_FEEDBACK_MAX_GAIN - 1.0
    )
    if correction_angle > 1e-9:
        correction = _axis_rotation(
            correction_vector / correction_angle,
            correction_angle * feedback_gain,
        )
    target_rotation = correction @ local_current_rotation
    target_quaternion = _mat_to_quat_xyzw(target_rotation)
    return np.asarray(target_quaternion, dtype=np.float64).reshape(4), {
        "source": "evaluator_eef_delta_mapped_to_local_fk",
        "raw_feedback_available": True,
        "raw_orientation_error_deg": float(raw_error_deg),
        "raw_orientation_feedback_gain": float(feedback_gain),
        "local_target_offset_from_entry_deg": orientation_error_deg(
            target_quaternion,
            keeper.reference_quaternion,
        ),
    }


def _reset_body_soft_position_step(
    state: LocalRobotState,
    arm: str,
    q_current: np.ndarray,
    measured_q: np.ndarray,
    reference_position: np.ndarray,
) -> tuple[np.ndarray, dict[str, Any]]:
    command = np.asarray(q_current, dtype=np.float64).reshape(ARM_DOF).copy()
    measured = np.asarray(measured_q, dtype=np.float64).reshape(ARM_DOF)
    jacobian, position, _quaternion = numerical_eef_jacobian(
        state,
        arm,
        command,
        joint_indices=(0, 1, 2, 3),
    )
    error = np.asarray(reference_position, dtype=np.float64).reshape(3) - position
    error_norm = float(np.linalg.norm(error))
    applied_error = np.zeros(3, dtype=np.float64)
    delta = np.zeros(4, dtype=np.float64)
    if error_norm > RESET_BODY_KEEP_POSITION_DEADBAND_M:
        applied_error = error * (
            (error_norm - RESET_BODY_KEEP_POSITION_DEADBAND_M)
            / max(error_norm, 1e-12)
        )
        translation_jacobian = jacobian[:3, :]
        lhs = (
            translation_jacobian @ translation_jacobian.T
            + RESET_BODY_KEEP_POSITION_DAMPING**2 * np.eye(3)
        )
        try:
            delta = translation_jacobian.T @ np.linalg.solve(lhs, applied_error)
        except np.linalg.LinAlgError:
            delta = np.linalg.lstsq(
                translation_jacobian,
                applied_error,
                rcond=None,
            )[0]
        delta_norm = float(np.linalg.norm(delta, ord=np.inf))
        if delta_norm > RESET_BODY_KEEP_Q1234_MAX_STEP_RAD:
            delta *= RESET_BODY_KEEP_Q1234_MAX_STEP_RAD / (
                delta_norm + 1e-12
            )

    lower, upper = _local_arm_joint_limits(state, arm)
    best_command = command.copy()
    best_position = np.asarray(position, dtype=np.float64).copy()
    best_error_norm = error_norm
    accepted_scale = 0.0
    for scale in RESET_BODY_KEEP_POSITION_LINE_SEARCH_SCALES:
        candidate = command.copy()
        proposed_q1234 = command[:4] + float(scale) * delta
        proposed_q1234 = np.clip(
            proposed_q1234,
            measured[:4] - RESET_BODY_KEEP_Q1234_MAX_STEP_RAD,
            measured[:4] + RESET_BODY_KEEP_Q1234_MAX_STEP_RAD,
        )
        candidate[:4] = np.clip(proposed_q1234, lower[:4], upper[:4])
        candidate_position, _candidate_quaternion = _local_eef_pose(
            state,
            arm,
            candidate,
        )
        candidate_error_norm = float(
            np.linalg.norm(candidate_position - reference_position)
        )
        if candidate_error_norm < best_error_norm - 1e-6:
            best_command = candidate
            best_position = np.asarray(
                candidate_position,
                dtype=np.float64,
            ).copy()
            best_error_norm = candidate_error_norm
            accepted_scale = float(scale)
    command = best_command
    if ARM_DOF == 8:
        command[7] = 0.0
    return command, {
        "position_before_m": np.asarray(position, dtype=np.float64).tolist(),
        "position_error_before_m": error_norm,
        "deadband_m": RESET_BODY_KEEP_POSITION_DEADBAND_M,
        "applied_translation_error_m": applied_error.tolist(),
        "accepted_line_search_scale": accepted_scale,
        "position_after_m": best_position.tolist(),
        "position_error_after_m": best_error_norm,
        "q1234_delta_from_measured_rad": (
            command[:4] - measured[:4]
        ).tolist(),
    }


def _reset_body_plan_keep_overrides(
    ctx,
    trunk_command: Any,
    keep_states: dict[str, _ResetBodyKeepOriState],
    *,
    orientation_limit_deg: float = RESET_BODY_KEEP_ORIENTATION_PLAN_LIMIT_DEG,
    j567_max_step_rad: float = RESET_BODY_KEEP_J567_MAX_STEP_RAD,
) -> tuple[dict[str, list[float]], dict[str, Any]]:
    state = _reset_body_local_state(ctx, trunk_command)
    measured_by_arm = {
        "left": state.arm_left_q.copy(),
        "right": state.arm_right_q.copy(),
    }
    overrides: dict[str, list[float]] = {}
    reports: dict[str, Any] = {}
    for arm, keeper in keep_states.items():
        measured = measured_by_arm[arm]
        target_quaternion, target_report = (
            _reset_body_feedback_orientation_target(ctx, arm, keeper)
        )
        tracking_error = float(
            np.linalg.norm(keeper.last_command - measured, ord=np.inf)
        )
        candidate = measured.copy()
        position_reports: list[dict[str, Any]] = []
        solve_report: dict[str, Any] | None = None
        for _ in range(RESET_BODY_KEEP_ALTERNATING_PASSES):
            position_candidate, position_report = _reset_body_soft_position_step(
                state,
                arm,
                candidate,
                measured,
                keeper.reference_position,
            )
            position_reports.append(position_report)
            candidate, solve_report, solve_calls = _reset_body_solve_bounded_j567(
                state,
                arm,
                position_candidate,
                measured,
                target_quaternion,
                max_step_rad=j567_max_step_rad,
            )
            keeper.solve_calls += solve_calls
            commanded_error_deg = float(
                solve_report["commanded_orientation_error_deg"]
            )
            if commanded_error_deg > RESET_BODY_KEEP_ORIENTATION_FINAL_TOL_DEG:
                orientation_candidate, orientation_report, fallback_calls = (
                    _reset_body_solve_bounded_j567(
                        state,
                        arm,
                        measured,
                        measured,
                        target_quaternion,
                        max_step_rad=j567_max_step_rad,
                    )
                )
                keeper.solve_calls += fallback_calls
                fallback_error_deg = float(
                    orientation_report["commanded_orientation_error_deg"]
                )
                if fallback_error_deg < commanded_error_deg:
                    candidate = orientation_candidate
                    solve_report = orientation_report
                    commanded_error_deg = fallback_error_deg
                    position_report["discarded_for_orientation"] = True
                    position_report["orientation_only_fallback"] = True
            if commanded_error_deg > float(orientation_limit_deg):
                reports[arm] = {
                    "ok": False,
                    "error": "J5-J7 cannot preserve the entry orientation",
                    "orientation_acceptance_limit_deg": float(
                        orientation_limit_deg
                    ),
                    "orientation_target": target_report,
                    "orientation_solve": dict(solve_report),
                    "position_passes": position_reports,
                }
                return {}, {"ok": False, "arms": reports}
            if bool(position_report.get("orientation_only_fallback", False)):
                break

        final_position, final_quaternion = _local_eef_pose(
            state,
            arm,
            candidate,
        )
        position_error = float(
            np.linalg.norm(final_position - keeper.reference_position)
        )
        orientation_target_error = orientation_error_deg(
            final_quaternion,
            target_quaternion,
        )
        local_entry_orientation_error = orientation_error_deg(
            final_quaternion,
            keeper.reference_quaternion,
        )
        q1234_delta = float(
            np.linalg.norm(candidate[:4] - measured[:4], ord=np.inf)
        )
        j567_delta = float(
            np.linalg.norm(candidate[4:7] - measured[4:7], ord=np.inf)
        )
        keeper.last_command = candidate.copy()
        keeper.last_solver_report = None if solve_report is None else dict(solve_report)
        keeper.max_command_tracking_error_rad = max(
            keeper.max_command_tracking_error_rad,
            tracking_error,
        )
        keeper.max_command_q1234_delta_rad = max(
            keeper.max_command_q1234_delta_rad,
            q1234_delta,
        )
        keeper.max_command_j567_delta_rad = max(
            keeper.max_command_j567_delta_rad,
            j567_delta,
        )
        overrides[f"arm_{arm}"] = candidate.astype(float).tolist()
        reports[arm] = {
            "ok": True,
            "measured_q_rad": measured.astype(float).tolist(),
            "command_q_rad": candidate.astype(float).tolist(),
            "command_tracking_error_rad": tracking_error,
            "q1234_delta_from_measured_rad": q1234_delta,
            "j567_delta_from_measured_rad": j567_delta,
            "predicted_position_error_m": position_error,
            "predicted_orientation_error_deg": orientation_target_error,
            "predicted_local_entry_orientation_error_deg": (
                local_entry_orientation_error
            ),
            "orientation_acceptance_limit_deg": float(orientation_limit_deg),
            "orientation_target": target_report,
            "accepted_best_effort_orientation": bool(
                orientation_target_error
                > RESET_BODY_KEEP_ORIENTATION_SOLVE_TOL_DEG
            ),
            "position_passes": position_reports,
            "orientation_solve": dict(solve_report or {}),
        }
    return overrides, {"ok": True, "arms": reports}


def _reset_body_keep_trunk_command(
    current_trunk: np.ndarray,
    target_trunk: np.ndarray,
    requested_max_step: float,
    progress_steps: int,
    max_position_error_m: float,
) -> tuple[np.ndarray, float, float]:
    """Choose one bounded body step while treating EEF position as secondary.

    The command is relative to the latest observed trunk state.  This avoids
    accumulating an open-loop smoothstep trajectory while the evaluator is
    rendering and stepping the robot.  Position drift only reduces the speed
    near the emergency limit; it does not freeze the body at the soft leash.
    """
    max_step = min(
        float(requested_max_step),
        RESET_BODY_KEEP_TRUNK_MAX_STEP_RAD,
    )
    ramp_scale = min(
        1.0,
        float(progress_steps + 1) / RESET_BODY_KEEP_TRUNK_RAMP_STEPS,
    )
    # Position is best-effort.  Slowing or reversing the trunk cannot recover
    # an EEF target that becomes unreachable at the requested upright pose.
    # Keep the body step independent while J1-J4 use bounded local correction.
    _ = max_position_error_m
    slowdown_scale = 1.0
    step_cap = max_step * ramp_scale * slowdown_scale
    current = np.asarray(current_trunk, dtype=np.float64).reshape(4)
    target = np.asarray(target_trunk, dtype=np.float64).reshape(4)
    command = current + np.clip(target - current, -step_cap, step_cap)
    return command, float(step_cap), float(slowdown_scale)


def _reset_body_measured_follow_overrides(
    ctx,
    keep_states: dict[str, _ResetBodyKeepOriState],
) -> tuple[dict[str, list[float]], dict[str, Any]]:
    """Fall back to zero-delta arm targets without affecting the trunk command."""
    overrides: dict[str, list[float]] = {}
    reports: dict[str, Any] = {}
    for arm, keeper in keep_states.items():
        source = "measured_qpos"
        try:
            command = locked_arm_vector(
                ctx.world.arm_qpos_list(arm),
                label=f"{arm} arm proprioception",
            )
        except Exception:  # keep-arm faults are isolated from body control
            command = keeper.last_command.copy()
            source = "last_valid_command"
        tracking_error = float(
            np.linalg.norm(keeper.last_command - command, ord=np.inf)
        )
        keeper.max_command_tracking_error_rad = max(
            keeper.max_command_tracking_error_rad,
            tracking_error,
        )
        keeper.last_command = command.copy()
        overrides[f"arm_{arm}"] = command.astype(float).tolist()
        reports[arm] = {
            "ok": False,
            "fallback": "software_compliant_measured_follow",
            "fallback_source": source,
            "command_q_rad": command.astype(float).tolist(),
            "command_tracking_error_rad": tracking_error,
            "q1234_delta_from_measured_rad": 0.0,
            "j567_delta_from_measured_rad": 0.0,
        }
    return overrides, reports


def _reset_body_best_effort_keep_overrides(
    ctx,
    trunk_command: Any,
    keep_states: dict[str, _ResetBodyKeepOriState],
    *,
    j567_max_step_rad: float = RESET_BODY_KEEP_J567_MAX_STEP_RAD,
) -> tuple[dict[str, list[float]], dict[str, Any], bool, bool]:
    """Plan the arm at the full trunk step and degrade without changing that step."""
    try:
        overrides, report = _reset_body_plan_keep_overrides(
            ctx,
            trunk_command,
            keep_states,
            orientation_limit_deg=(
                RESET_BODY_KEEP_ORIENTATION_BEST_EFFORT_LIMIT_DEG
            ),
            j567_max_step_rad=j567_max_step_rad,
        )
    except Exception as exc:  # keep-arm faults are isolated from body control
        overrides = {}
        report = {"ok": False, "error": str(exc), "arms": {}}

    if bool(report.get("ok", False)):
        nominal = all(
            float(item.get("predicted_orientation_error_deg", float("inf")))
            <= RESET_BODY_KEEP_ORIENTATION_PLAN_LIMIT_DEG
            for item in (report.get("arms") or {}).values()
        )
        report = dict(report)
        report["mode"] = "nominal" if nominal else "best_effort"
        report["trunk_command_reduced_for_arm"] = False
        return overrides, report, not nominal, False

    fallback_overrides, fallback_reports = _reset_body_measured_follow_overrides(
        ctx,
        keep_states,
    )
    return (
        fallback_overrides,
        {
            "ok": False,
            "mode": "measured_follow_fallback",
            "error": "keep-orientation planning unavailable; trunk continued",
            "planning_failure": report,
            "arms": fallback_reports,
            "trunk_command_reduced_for_arm": False,
        },
        True,
        True,
    )


def _reset_body_safe_observed_keep_report(
    ctx,
    keep_states: dict[str, _ResetBodyKeepOriState],
) -> dict[str, Any]:
    """Make arm observation failures diagnostic-only for body reset."""
    try:
        return _reset_body_observed_keep_report(ctx, keep_states)
    except Exception as exc:  # keep-arm faults are isolated from body control
        return {
            "ok": False,
            "within_hard_limits": False,
            "within_position_hard_limits": False,
            "within_orientation_hard_limits": False,
            "within_orientation_tracking_guard": False,
            "within_position_final_tolerances": False,
            "within_orientation_final_tolerances": False,
            "within_final_tolerances": False,
            "arms": {},
            "observation_error": str(exc),
        }


def _reset_body_body_priority_action(
    ctx,
    trunk_command: Any,
    arm_overrides: dict[str, list[float]],
) -> tuple[np.ndarray, str | None]:
    """Drop invalid best-effort arm overrides before allowing them to block body."""
    trunk = np.asarray(trunk_command, dtype=np.float64).reshape(4).tolist()
    try:
        return ctx.world.make_action(trunk=trunk, **arm_overrides), None
    except Exception as exc:  # retry without optional arm fields
        if not arm_overrides:
            raise
        return ctx.world.make_action(trunk=trunk), str(exc)


def _reset_body_observed_keep_report(
    ctx,
    keep_states: dict[str, _ResetBodyKeepOriState],
) -> dict[str, Any]:
    if not keep_states:
        return {
            "ok": True,
            "within_hard_limits": True,
            "within_position_hard_limits": True,
            "within_orientation_hard_limits": True,
            "within_orientation_tracking_guard": True,
            "within_position_final_tolerances": True,
            "within_orientation_final_tolerances": True,
            "within_final_tolerances": True,
            "arms": {},
        }
    state = _reset_body_local_state(ctx, ctx.world.trunk_qpos())
    measured_by_arm = {
        "left": state.arm_left_q,
        "right": state.arm_right_q,
    }
    reports: dict[str, Any] = {}
    within_hard_limits = True
    within_orientation_hard_limits = True
    within_orientation_tracking_guard = True
    within_position_hard_limits = True
    within_position_final_tolerances = True
    within_orientation_final_tolerances = True
    within_final_tolerances = True
    for arm, keeper in keep_states.items():
        measured = measured_by_arm[arm]
        position, quaternion = _local_eef_pose(state, arm, measured)
        local_position_error = float(
            np.linalg.norm(position - keeper.reference_position)
        )
        local_orientation_error = orientation_error_deg(
            quaternion,
            keeper.reference_quaternion,
        )
        raw_pose = _reset_body_raw_eef_pose(ctx, arm)
        raw_position_error: float | None = None
        raw_orientation_error: float | None = None
        if (
            raw_pose is not None
            and keeper.raw_reference_position is not None
            and keeper.raw_reference_quaternion is not None
        ):
            raw_position_error = float(
                np.linalg.norm(
                    raw_pose["position"] - keeper.raw_reference_position
                )
            )
            raw_orientation_error = orientation_error_deg(
                raw_pose["quaternion"],
                keeper.raw_reference_quaternion,
            )
        # Evaluator EEF pose is the physical observation and therefore wins
        # when present.  Local FK remains the deterministic IK model and audit
        # fallback; taking max(raw, local) can create an error that no single
        # target can satisfy when the two models have a small fixed offset.
        position_error = (
            local_position_error
            if raw_position_error is None
            else raw_position_error
        )
        orientation_error = (
            local_orientation_error
            if raw_orientation_error is None
            else raw_orientation_error
        )
        keeper.max_observed_position_error_m = max(
            keeper.max_observed_position_error_m,
            position_error,
        )
        keeper.max_observed_orientation_error_deg = max(
            keeper.max_observed_orientation_error_deg,
            orientation_error,
        )
        arm_within_position_hard = bool(
            position_error <= RESET_BODY_KEEP_POSITION_HARD_LIMIT_M
        )
        arm_within_orientation_hard = bool(
            orientation_error <= RESET_BODY_KEEP_ORIENTATION_HARD_LIMIT_DEG
        )
        arm_within_orientation_tracking_guard = bool(
            orientation_error
            <= RESET_BODY_KEEP_ORIENTATION_TRACKING_GUARD_DEG
        )
        arm_within_hard = bool(
            arm_within_position_hard and arm_within_orientation_hard
        )
        arm_within_position_final = bool(
            position_error <= RESET_BODY_KEEP_POSITION_FINAL_TOL_M
        )
        arm_within_orientation_final = bool(
            orientation_error <= RESET_BODY_KEEP_ORIENTATION_FINAL_TOL_DEG
        )
        arm_within_final = bool(
            arm_within_position_final and arm_within_orientation_final
        )
        within_hard_limits = within_hard_limits and arm_within_hard
        within_position_hard_limits = (
            within_position_hard_limits and arm_within_position_hard
        )
        within_orientation_hard_limits = (
            within_orientation_hard_limits and arm_within_orientation_hard
        )
        within_orientation_tracking_guard = (
            within_orientation_tracking_guard
            and arm_within_orientation_tracking_guard
        )
        within_position_final_tolerances = (
            within_position_final_tolerances and arm_within_position_final
        )
        within_orientation_final_tolerances = (
            within_orientation_final_tolerances and arm_within_orientation_final
        )
        within_final_tolerances = within_final_tolerances and arm_within_final
        raw_q = np.asarray(
            ctx.world.arm_qpos_list(arm),
            dtype=np.float64,
        ).reshape(-1)
        reports[arm] = {
            "within_hard_limits": arm_within_hard,
            "within_position_hard_limits": arm_within_position_hard,
            "within_orientation_hard_limits": arm_within_orientation_hard,
            "within_orientation_tracking_guard": (
                arm_within_orientation_tracking_guard
            ),
            "within_position_final_tolerance": arm_within_position_final,
            "within_orientation_final_tolerance": arm_within_orientation_final,
            "within_final_tolerances": arm_within_final,
            "measured_q_rad": raw_q.astype(float).tolist(),
            "local_position_robot_m": np.asarray(position, dtype=np.float64).tolist(),
            "local_quaternion_xyzw": np.asarray(quaternion, dtype=np.float64).tolist(),
            "local_position_error_m": local_position_error,
            "local_orientation_error_deg": local_orientation_error,
            "raw_evaluator_position_error_m": raw_position_error,
            "raw_evaluator_orientation_error_deg": raw_orientation_error,
            "effective_position_error_m": position_error,
            "effective_orientation_error_deg": orientation_error,
            "effective_pose_source": (
                "local_fk"
                if raw_orientation_error is None
                else "evaluator_eef_pose"
            ),
            "observed_j8_rad": (
                float(raw_q[7]) if ARM_DOF == 8 and raw_q.size >= 8 else None
            ),
        }
    return {
        "ok": bool(within_final_tolerances),
        "within_hard_limits": bool(within_hard_limits),
        "within_position_hard_limits": bool(within_position_hard_limits),
        "within_orientation_hard_limits": bool(within_orientation_hard_limits),
        "within_orientation_tracking_guard": bool(
            within_orientation_tracking_guard
        ),
        "within_position_final_tolerances": bool(
            within_position_final_tolerances
        ),
        "within_orientation_final_tolerances": bool(
            within_orientation_final_tolerances
        ),
        "within_final_tolerances": bool(within_final_tolerances),
        "arms": reports,
    }


def _reset_body_keep_result(
    keep_states: dict[str, _ResetBodyKeepOriState],
    observed_report: dict[str, Any],
) -> dict[str, Any]:
    arms: dict[str, Any] = {}
    observed_arms = dict(observed_report.get("arms") or {})
    for arm, keeper in keep_states.items():
        raw_reference = None
        if (
            keeper.raw_reference_position is not None
            and keeper.raw_reference_quaternion is not None
        ):
            raw_reference = {
                "position": keeper.raw_reference_position.astype(float).tolist(),
                "quaternion_xyzw": (
                    keeper.raw_reference_quaternion.astype(float).tolist()
                ),
            }
        arms[arm] = {
            "reference_local_position_robot_m": (
                keeper.reference_position.astype(float).tolist()
            ),
            "reference_local_quaternion_xyzw": (
                keeper.reference_quaternion.astype(float).tolist()
            ),
            "reference_raw_evaluator_pose": raw_reference,
            "initial_q_rad": keeper.initial_q.astype(float).tolist(),
            "last_command_q_rad": keeper.last_command.astype(float).tolist(),
            "solve_calls": int(keeper.solve_calls),
            "max_observed_position_error_m": float(
                keeper.max_observed_position_error_m
            ),
            "max_observed_orientation_error_deg": float(
                keeper.max_observed_orientation_error_deg
            ),
            "max_command_tracking_error_rad": float(
                keeper.max_command_tracking_error_rad
            ),
            "max_command_q1234_delta_rad": float(
                keeper.max_command_q1234_delta_rad
            ),
            "max_command_j567_delta_rad": float(
                keeper.max_command_j567_delta_rad
            ),
            "last_orientation_solve": keeper.last_solver_report,
            "final_observation": observed_arms.get(arm),
            "j1234_policy": "measured_follow_with_best_effort_position_correction",
            "j567_policy": "fixed_candidate_j1234_local_urdf_orientation_tracking",
            "j8_policy": "locked_zero" if ARM_DOF == 8 else "not_present",
        }
    return {
        "enabled": bool(keep_states),
        "arms": arms,
        "controller": "body_first_nonblocking_keep_ori",
        "position_priority": "best_effort_advisory",
        "position_affects_body_speed": False,
        "position_deadband_m": RESET_BODY_KEEP_POSITION_DEADBAND_M,
        "position_warning_m": RESET_BODY_KEEP_POSITION_WARNING_M,
        "position_final_tolerance_m": RESET_BODY_KEEP_POSITION_FINAL_TOL_M,
        "position_hard_limit_m": RESET_BODY_KEEP_POSITION_HARD_LIMIT_M,
        "orientation_final_tolerance_deg": (
            RESET_BODY_KEEP_ORIENTATION_FINAL_TOL_DEG
        ),
        "orientation_planning_limit_deg": (
            RESET_BODY_KEEP_ORIENTATION_PLAN_LIMIT_DEG
        ),
        "orientation_tracking_guard_deg": (
            RESET_BODY_KEEP_ORIENTATION_TRACKING_GUARD_DEG
        ),
        "orientation_hard_limit_deg": RESET_BODY_KEEP_ORIENTATION_HARD_LIMIT_DEG,
        "orientation_hard_limit_behavior": "warning_only",
        "q1234_max_delta_from_measured_per_action_rad": (
            RESET_BODY_KEEP_Q1234_MAX_STEP_RAD
        ),
        "j567_max_delta_from_measured_per_action_rad": (
            RESET_BODY_KEEP_J567_CATCHUP_MAX_STEP_RAD
        ),
        "j567_nominal_max_delta_from_measured_per_action_rad": (
            RESET_BODY_KEEP_J567_MAX_STEP_RAD
        ),
        "j567_catchup_max_delta_from_measured_per_action_rad": (
            RESET_BODY_KEEP_J567_CATCHUP_MAX_STEP_RAD
        ),
        "stationary_recovery_actions_during_body_motion": 0,
        "software_compliance": bool(keep_states),
        "physical_impedance_available": False,
        "arm_quality_affects_trunk_motion": False,
        "arm_quality_affects_success": False,
        "trunk_step_backoff_for_arm": False,
        "reference_frame": "robot_base_from_evaluator_proprio_and_local_fk",
    }


def reset_body(
    ctx,
    keep_ori_arm: str = "none",
    timeout_s: float = 45.0,
    trunk_max_step: float | None = None,
    shoulder_iters: int = 4,
    pitch_deg: float = 0.0,
    **kwargs,
):
    # Retained only for compatibility with the old simulator-backed signature.
    del shoulder_iters
    try:
        keep_arms = _reset_body_keep_arms(keep_ori_arm)
    except ValueError as exc:
        _set_result(ctx, "reset_body", {"ok": False, "error": str(exc)})
        yield ctx.world.hold_action()
        return
    tolerance = max(1e-4, float(kwargs.get("tolerance_rad", 0.035)))
    timeout = float(timeout_s)
    if not math.isfinite(timeout) or timeout <= 0.0:
        _set_result(
            ctx,
            "reset_body",
            {"ok": False, "error": "timeout_s must be a positive finite value"},
        )
        yield ctx.world.hold_action()
        return
    start = np.asarray(ctx.world.trunk_qpos(), dtype=np.float64).reshape(4)
    target = R1PRO_UPRIGHT_TRUNK_Q.copy()
    target[2] = -math.radians(float(pitch_deg))
    target = np.clip(target, TRUNK_LIMITS[:, 0], TRUNK_LIMITS[:, 1])
    defaulted_max_step = trunk_max_step is None
    requested_max_step = (
        RESET_BODY_KEEP_DEFAULT_TRUNK_MAX_STEP_RAD
        if keep_arms and defaulted_max_step
        else RESET_BODY_DEFAULT_TRUNK_MAX_STEP_RAD
        if defaulted_max_step
        else float(trunk_max_step)
    )
    if not math.isfinite(requested_max_step) or requested_max_step <= 0.0:
        _set_result(
            ctx,
            "reset_body",
            {
                "ok": False,
                "error": "trunk_max_step must be a positive finite value",
            },
        )
        yield ctx.world.hold_action()
        return
    keep_initialization_error: str | None = None
    try:
        keep_states = _reset_body_init_keep_states(ctx, keep_arms)
    except Exception as exc:  # keep-arm initialization is advisory
        # keep_ori_arm is advisory. Missing arm kinematics must never prevent
        # the independently controlled trunk from returning upright.
        keep_states = {}
        keep_initialization_error = str(exc)
    keep_requested = bool(keep_arms)
    max_step = (
        min(requested_max_step, RESET_BODY_KEEP_TRUNK_MAX_STEP_RAD)
        if keep_requested
        else requested_max_step
    )
    steps = max(
        2,
        int(
            math.ceil(
                (
                    float(np.linalg.norm(target - start, ord=np.inf))
                    / max_step
                )
                if keep_requested
                else (
                    SMOOTHSTEP_MAX_SLOPE
                    * float(np.linalg.norm(target - start, ord=np.inf))
                    / max_step
                )
            )
        ),
    )
    deadline = time.monotonic() + timeout
    action_steps = 0
    timed_out = False
    body_failure: str | None = None
    # Compatibility metric: these are now concurrent catch-up actions.  The
    # body is never pinned for an orientation-only recovery during motion.
    keep_recovery_steps = 0
    keep_tracking_guard_steps = 0
    keep_relaxed_plan_steps = 0
    keep_fallback_steps = 0
    keep_action_fallback_steps = 0
    keep_observation_failure_steps = 0
    keep_hard_limit_observation_steps = 0
    keep_settle_steps_after_trunk = 0
    keep_plan_backoff_steps = 0
    last_keep_plan: dict[str, Any] = {"ok": True, "arms": {}}
    body_progress_steps = 0
    stalled = False
    stall_steps = 0
    if keep_requested:
        body_step_limit = steps + RESET_BODY_TRACKING_STALL_STEPS
        body_best_error = float("inf")
        body_stall_steps = 0
        while body_progress_steps < body_step_limit:
            _check_cancelled(ctx, "reset body interpolation")
            current_trunk = np.asarray(
                ctx.world.trunk_qpos(),
                dtype=np.float64,
            ).reshape(4)
            observed_error = float(np.max(np.abs(target - current_trunk)))
            if observed_error <= tolerance:
                break
            if time.monotonic() >= deadline:
                timed_out = True
                break
            observed_keep = _reset_body_safe_observed_keep_report(
                ctx,
                keep_states,
            )
            if observed_keep.get("observation_error"):
                keep_observation_failure_steps += 1
            orientation_error = max(
                (
                    float(item["effective_orientation_error_deg"])
                    for item in observed_keep["arms"].values()
                ),
                default=0.0,
            )
            if not observed_keep.get("within_orientation_hard_limits", True):
                keep_hard_limit_observation_steps += 1
            position_error = max(
                (
                    float(item["effective_position_error_m"])
                    for item in observed_keep["arms"].values()
                ),
                default=0.0,
            )
            tracking_guard_exceeded = bool(
                not observed_keep.get(
                    "within_orientation_tracking_guard",
                    orientation_error
                    <= RESET_BODY_KEEP_ORIENTATION_TRACKING_GUARD_DEG,
                )
            )
            if tracking_guard_exceeded:
                keep_tracking_guard_steps += 1
                keep_recovery_steps += 1
            if observed_error + 1e-4 < body_best_error:
                body_best_error = observed_error
                body_stall_steps = 0
            else:
                body_stall_steps += 1
            stall_steps = body_stall_steps
            if body_stall_steps >= RESET_BODY_TRACKING_STALL_STEPS:
                stalled = True
                break
            command, _step_cap, _slowdown_scale = (
                _reset_body_keep_trunk_command(
                    current_trunk,
                    target,
                    requested_max_step,
                    body_progress_steps,
                    position_error,
                )
            )
            wrist_step = (
                RESET_BODY_KEEP_J567_CATCHUP_MAX_STEP_RAD
                if tracking_guard_exceeded
                else RESET_BODY_KEEP_J567_MAX_STEP_RAD
            )
            arm_overrides: dict[str, list[float]] = {}
            if keep_states:
                (
                    arm_overrides,
                    last_keep_plan,
                    used_best_effort,
                    used_fallback,
                ) = _reset_body_best_effort_keep_overrides(
                    ctx,
                    command,
                    keep_states,
                    j567_max_step_rad=wrist_step,
                )
                if used_best_effort:
                    keep_relaxed_plan_steps += 1
                if used_fallback:
                    keep_fallback_steps += 1
            action, arm_action_error = _reset_body_body_priority_action(
                ctx,
                command,
                arm_overrides,
            )
            if arm_action_error is not None:
                keep_action_fallback_steps += 1
                last_keep_plan = {
                    **last_keep_plan,
                    "arm_action_error": arm_action_error,
                    "arm_action_fallback": "trunk_with_existing_arm_pins",
                }
            yield action
            action_steps += 1
            body_progress_steps += 1
        if (
            body_progress_steps >= body_step_limit
            and not timed_out
            and body_failure is None
            and not stalled
        ):
            achieved_now = np.asarray(
                ctx.world.trunk_qpos(),
                dtype=np.float64,
            ).reshape(4)
            if float(np.max(np.abs(target - achieved_now))) > tolerance:
                body_failure = "reset_body body-step budget exhausted"
    else:
        for index in range(1, steps + 1):
            if time.monotonic() >= deadline:
                timed_out = True
                break
            _check_cancelled(ctx, "reset body interpolation")
            alpha = _smoothstep(index / steps)
            command = start + alpha * (target - start)
            yield ctx.world.make_action(trunk=command.tolist())
            action_steps += 1
        body_progress_steps = steps

    required_stable = (
        RESET_BODY_KEEP_SETTLE_STABLE_STEPS if keep_requested else 3
    )
    settle_stall_limit = (
        RESET_BODY_KEEP_SETTLE_STALL_STEPS
        if keep_requested
        else RESET_BODY_TRACKING_STALL_STEPS
    )
    max_settle_steps = max(
        required_stable,
        min(
            int(math.ceil(timeout * CONTROL_HZ)),
            RESET_BODY_KEEP_SETTLE_MAX_STEPS if keep_requested else 90,
        ),
    )
    stable = 0
    settle_steps = 0
    if not stalled:
        stall_steps = 0
    best_error = float("inf")
    if not timed_out and body_failure is None and not stalled:
        for _ in range(max_settle_steps):
            if time.monotonic() >= deadline:
                current_error = float(
                    np.max(
                        np.abs(
                            target
                            - np.asarray(
                                ctx.world.trunk_qpos(),
                                dtype=np.float64,
                            ).reshape(4)
                        )
                    )
                )
                timed_out = current_error > tolerance
                break
            _check_cancelled(ctx, "reset body settle")
            arm_overrides: dict[str, list[float]] = {}
            if keep_states:
                pre_action_keep = _reset_body_safe_observed_keep_report(
                    ctx,
                    keep_states,
                )
                if pre_action_keep.get("observation_error"):
                    keep_observation_failure_steps += 1
                pre_action_orientation_error = max(
                    (
                        float(item["effective_orientation_error_deg"])
                        for item in pre_action_keep["arms"].values()
                    ),
                    default=0.0,
                )
                if not pre_action_keep.get(
                    "within_orientation_hard_limits",
                    True,
                ):
                    keep_hard_limit_observation_steps += 1
                catchup = bool(
                    not pre_action_keep.get(
                        "within_orientation_tracking_guard",
                        pre_action_orientation_error
                        <= RESET_BODY_KEEP_ORIENTATION_TRACKING_GUARD_DEG,
                    )
                )
                if catchup:
                    keep_tracking_guard_steps += 1
                    keep_recovery_steps += 1
                (
                    arm_overrides,
                    last_keep_plan,
                    used_best_effort,
                    used_fallback,
                ) = _reset_body_best_effort_keep_overrides(
                    ctx,
                    target,
                    keep_states,
                    j567_max_step_rad=(
                        RESET_BODY_KEEP_J567_CATCHUP_MAX_STEP_RAD
                        if catchup
                        else RESET_BODY_KEEP_J567_MAX_STEP_RAD
                    ),
                )
                if used_best_effort:
                    keep_relaxed_plan_steps += 1
                if used_fallback:
                    keep_fallback_steps += 1
            action, arm_action_error = _reset_body_body_priority_action(
                ctx,
                target,
                arm_overrides,
            )
            if arm_action_error is not None:
                keep_action_fallback_steps += 1
                last_keep_plan = {
                    **last_keep_plan,
                    "arm_action_error": arm_action_error,
                    "arm_action_fallback": "trunk_with_existing_arm_pins",
                }
            yield action
            action_steps += 1
            settle_steps += 1
            observed = np.asarray(
                ctx.world.trunk_qpos(),
                dtype=np.float64,
            ).reshape(4)
            observed_error = float(np.max(np.abs(target - observed)))
            observed_keep = _reset_body_safe_observed_keep_report(
                ctx,
                keep_states,
            )
            if observed_keep.get("observation_error"):
                keep_observation_failure_steps += 1
            if not observed_keep.get("within_orientation_hard_limits", True):
                keep_hard_limit_observation_steps += 1
            body_metric = observed_error / tolerance
            if observed_error <= tolerance:
                stable += 1
            else:
                stable = 0
            trunk_is_stable = stable >= required_stable
            if trunk_is_stable:
                if (
                    not keep_states
                    or observed_keep["within_orientation_final_tolerances"]
                ):
                    break
                keep_settle_steps_after_trunk += 1
                # The trunk is already stable. Any remaining actions are a
                # bounded wrist-only quality pass and cannot mark body stall.
                continue
            if body_metric + 1e-4 < best_error:
                best_error = body_metric
                stall_steps = 0
            else:
                stall_steps += 1
            if stall_steps >= settle_stall_limit:
                stalled = True
                break
    achieved = np.asarray(
        ctx.world.trunk_qpos(),
        dtype=np.float64,
    ).reshape(4)
    error = target - achieved
    max_error = float(np.max(np.abs(error)))
    final_keep = _reset_body_safe_observed_keep_report(ctx, keep_states)
    if final_keep.get("observation_error"):
        keep_observation_failure_steps += 1
    if not final_keep.get("within_orientation_hard_limits", True):
        keep_hard_limit_observation_steps += 1
    keep_ok = bool(
        keep_initialization_error is None
        and final_keep["within_orientation_final_tolerances"]
    )
    position_drift_warning = any(
        float(item.get("effective_position_error_m") or 0.0)
        > RESET_BODY_KEEP_POSITION_WARNING_M
        for item in (final_keep.get("arms") or {}).values()
    )
    ok = bool(
        max_error <= tolerance
        and not timed_out
        and not stalled
        and body_failure is None
    )
    keep_value = (
        "both"
        if len(keep_arms) == 2
        else (keep_arms[0] if keep_arms else "none")
    )
    keep_report = _reset_body_keep_result(keep_states, final_keep)
    keep_report.update(
        {
            "requested": keep_requested,
            "requested_arms": list(keep_arms),
            "initialized_arms": list(keep_states),
            "initialization_error": keep_initialization_error,
            "orientation_satisfied": bool(keep_ok),
            "affects_trunk_motion": False,
            "affects_reset_success": False,
            "trunk_priority": "absolute",
        }
    )
    keep_degraded = bool(
        keep_requested
        and (
            not keep_ok
            or keep_initialization_error is not None
            or keep_fallback_steps > 0
            or keep_action_fallback_steps > 0
            or keep_observation_failure_steps > 0
            or keep_hard_limit_observation_steps > 0
        )
    )
    warnings: list[str] = []
    if keep_initialization_error is not None:
        warnings.append(
            "keep-orientation initialization failed; trunk reset continued"
        )
    if keep_observation_failure_steps:
        warnings.append(
            "keep-orientation observation failed; trunk reset continued"
        )
    if keep_hard_limit_observation_steps:
        warnings.append(
            "kept EEF exceeded the 25 deg diagnostic threshold; trunk reset continued"
        )
    if keep_fallback_steps:
        warnings.append(
            "keep-orientation IK degraded to measured-follow; trunk reset continued"
        )
    if keep_action_fallback_steps:
        warnings.append(
            "kept-arm action override was rejected; trunk-only command was used"
        )
    if keep_requested and not keep_ok:
        warnings.append(
            "kept EEF orientation did not reach the advisory final tolerance"
        )
    result = {
        "ok": bool(ok),
        "implementation_version": RESET_BODY_IMPLEMENTATION_VERSION,
        "target_trunk_q": target.astype(float).tolist(),
        "achieved_qpos": achieved.astype(float).tolist(),
        "error_rad": error.astype(float).tolist(),
        "max_abs_error_rad": max_error,
        "tolerance_rad": tolerance,
        "settle_steps": int(settle_steps),
        "action_steps": int(action_steps),
        "interpolation_steps": int(steps),
        "body_progress_steps": int(body_progress_steps),
        "planned_interpolation_steps": int(steps),
        "requested_max_step_rad": requested_max_step,
        "defaulted_max_step": bool(defaulted_max_step),
        "effective_max_step_rad": max_step,
        "keep_ori_arm": keep_value,
        "trunk_priority": "absolute",
        "keep_orientation_affects_trunk": False,
        "keep_orientation_affects_success": False,
        "keep_orientation_satisfied": bool(keep_ok),
        "keep_orientation_degraded": bool(keep_degraded),
        "keep_orientation": keep_report,
        "position_drift_warning": bool(position_drift_warning),
        "keep_recovery_steps": int(keep_recovery_steps),
        "keep_tracking_guard_steps": int(keep_tracking_guard_steps),
        "keep_relaxed_plan_steps": int(keep_relaxed_plan_steps),
        "keep_fallback_steps": int(keep_fallback_steps),
        "keep_action_fallback_steps": int(keep_action_fallback_steps),
        "keep_observation_failure_steps": int(keep_observation_failure_steps),
        "keep_hard_limit_observation_steps": int(
            keep_hard_limit_observation_steps
        ),
        "keep_settle_steps_after_trunk": int(keep_settle_steps_after_trunk),
        "stationary_recovery_steps_during_body_motion": 0,
        "keep_plan_backoff_steps": int(keep_plan_backoff_steps),
        "last_keep_plan": last_keep_plan,
        "warnings": warnings,
        "stall_steps": int(stall_steps),
        "tracking_stalled": bool(stalled),
        "timed_out": bool(timed_out),
        "timeout_s": timeout,
        "arms_grippers": (
            "selected arms software-compliant; other limbs action-pinned"
            if keep_states
            else (
                "keep-orientation unavailable; limbs action-pinned"
                if keep_requested
                else "pinned through action targets"
            )
        ),
        "direct_simulator_mutation": False,
    }
    if not ok:
        result["error"] = (
            body_failure
            if body_failure is not None
            else (
                "reset_body timed out before trunk reached target"
                if timed_out
                else (
                    "reset_body trunk tracking stalled before reaching target"
                    if stalled
                    else "trunk did not converge using evaluator-proprio action control"
                )
            )
        )
    _set_result(ctx, "reset_body", result)
    if ok:
        arm_overrides: dict[str, list[float]] = {}
        if keep_states:
            arm_overrides, _final_plan, _best_effort, _fallback = (
                _reset_body_best_effort_keep_overrides(
                    ctx,
                    target,
                    keep_states,
                )
            )
        final_action, _arm_action_error = _reset_body_body_priority_action(
            ctx,
            target,
            arm_overrides,
        )
        yield final_action
    else:
        yield ctx.world.hold_action()


