if WRIST_ROLL_TEST_TOOL_ENABLED:
    PUBLIC_TOOL_FUNCTIONS["control_wrist_roll"] = control_wrist_roll

if tuple(PUBLIC_TOOL_FUNCTIONS) != PUBLIC_TOOLS:
    raise RuntimeError("official_v2 public tool implementation order mismatch")

# Official policy-interface processes advertise their evaluator port in the
# environment before importing this module.  Install the monitor scheduler at
# import time as well as on the first capture, so motion-only requests also do
# not pay the synchronous thumbnail/NAS finalization cost.
if os.environ.get("BEHAVIOR_EVAL_TEST_POLICY_PORT", "").strip():
    _install_async_agent_monitor_finish()


__all__ = ["PUBLIC_TOOL_FUNCTIONS", *PUBLIC_TOOLS]
